  log(`[TestV3] Initial LLMClient in deps: ${!!LLMClient}`);

  if (!LLMClient) {
    if (typeof window !== 'undefined' && window.REPLOID) {
       log(`[TestV3] Found window.REPLOID. Keys: ${Object.keys(window.REPLOID).join(', ')}`);
