          warning: limits.warning,
          limit: limits.hard,
          exceeded: hardCheck.exceeded,
          percentage: Math.round((tokens / limits.hard) * 100)
        });
      }

      return tokens;
    };

    // ─────────────────────────────────────────────────────────────────────────
    // Exports
    // ─────────────────────────────────────────────────────────────────────────

    return {
      // Core functions
      countTokens,
      invalidateTokenCache,

      // Threshold checks
      shouldCompact,
      isAtWarningLevel,
      exceedsHardLimit,

      // Compaction
      compact,

      // Main entry point (recommended)
      manage,

      // Configuration
      getLimitsForModel,
      setLimits,
      clearLimitOverrides,

      // Token events
      emitTokens,

      // Expose defaults for reference
      DEFAULT_LIMITS,
      MODEL_LIMITS
    };
  }
