     */
    const terminate = (workerId) => {
      const worker = _activeWorkers.get(workerId);
      if (worker) {
        logger.info(`[WorkerManager] Terminating worker: ${workerId}`);
        // TODO: Actually terminate the Web Worker in Phase 3
        _activeWorkers.delete(workerId);
        const terminatedRecord = {
          workerId,
          type: worker.type,
          task: worker.task,
          startTime: worker.startTime,
          status: 'terminated',
          logs: worker.logs || [],
          completedTime: Date.now(),
          duration: Date.now() - worker.startTime
        };
        _completedWorkers.set(workerId, terminatedRecord);
        _persistWorker(workerId, terminatedRecord);
        if (EventBus) {
          EventBus.emit('worker:terminated', { workerId });
        }
        return true;
      }
      return false;
    };

    /**
     * Get completed worker results
     * @param {string} [workerId] - Specific worker or all if not provided
     */
    const getResults = (workerId) => {
      if (workerId) {
        return _completedWorkers.get(workerId);
      }
      return Array.from(_completedWorkers.entries()).map(([id, data]) => ({
        workerId: id,
        ...data
      }));
    };

    /**
     * Clear completed worker history (also deletes from VFS)
     */
    const clearHistory = async () => {
      // Delete files from VFS
      if (VFS) {
        for (const workerId of _completedWorkers.keys()) {
          try {
            await VFS.delete(`${WORKERS_DIR}/${workerId}.json`);
          } catch (e) {
            // Ignore deletion errors
          }
        }
      }
      _completedWorkers.clear();
    };

    // Create API object so we can reference it in init for circular dependency fix
    const api = {
      init,
      setModelConfig,
      setModelRoles,
      spawn,
      list,
      awaitWorkers,
      terminate,
      addLog,
      getResults,
      clearHistory,
      getToolsForType,
      isToolAllowed
    };

    return api;
  }
};

export default WorkerManager;
","/infrastructure/audit-logger.js":"/**
 * @fileoverview Audit Logger
 * Security tracking. Writes to /.logs/audit/YYYY-MM-DD.jsonl
 * Supports structured export (JSON/CSV) for compliance and debugging.
 */

const AuditLogger = {
  metadata: {
    id: 'AuditLogger',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'VFS', 'TelemetryTimeline?'],
    async: true,
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { Utils, VFS, TelemetryTimeline } = deps;
    const { logger, generateId } = Utils;
    const LOG_DIR = '/.logs/audit';

    const init = async () => {
      // Directory check implied by VFS structure
      return true;
    };

    const logEvent = async (type, data, severity = 'INFO') => {
      const entry = {
        id: generateId('log'),
        ts: new Date().toISOString(),
        type,
        severity,
        data
      };

      // Echo security warnings to console
      if (severity === 'ERROR' || severity === 'WARN') {
        logger.warn(`[Audit] ${type}`, data);
      }

      const date = new Date().toISOString().split('T')[0];
      const path = `${LOG_DIR}/${date}.jsonl`;

      // Retry once on failure to ensure audit trail integrity
      for (let attempt = 0; attempt < 2; attempt++) {
        try {
          let content = '';
          if (await VFS.exists(path)) {
            content = await VFS.read(path);
          }
          content += JSON.stringify(entry) + '\n';
          await VFS.write(path, content);
          if (TelemetryTimeline) {
            await TelemetryTimeline.record(`audit:${type}`, entry.data, { severity, tags: ['audit'] });
          }
          return; // Success
        } catch (e) {
          if (attempt === 0) {
            logger.warn('[AuditLogger] Write failed, retrying...', e.message);
            await new Promise(r => setTimeout(r, 50));
          } else {
            logger.error('[AuditLogger] Write failed after retry - audit event lost', {
              error: e.message,
              entry: { type, severity, id: entry.id }
            });
          }
        }
      }
    };

    /**
     * Get all log entries for a date range
     * @param {string} [startDate] - YYYY-MM-DD (default: today)
     * @param {string} [endDate] - YYYY-MM-DD (default: startDate)
     * @returns {Promise<Array>} Array of log entries
     */
    const getEntries = async (startDate = null, endDate = null) => {
      const today = new Date().toISOString().split('T')[0];
      const start = startDate || today;
      const end = endDate || start;

      const entries = [];
      const current = new Date(start);
      const endDt = new Date(end);

      while (current <= endDt) {
        const dateStr = current.toISOString().split('T')[0];
        const path = `${LOG_DIR}/${dateStr}.jsonl`;

        try {
          if (await VFS.exists(path)) {
            const content = await VFS.read(path);
            const lines = content.split('\n').filter(l => l.trim());
            for (const line of lines) {
              try {
                entries.push(JSON.parse(line));
              } catch (e) {
                // Skip malformed lines
              }
            }
          }
        } catch (e) {
          logger.warn(`[AuditLogger] Failed to read ${path}:`, e.message);
        }

        current.setDate(current.getDate() + 1);
      }

      return entries;
    };

    /**
     * Export audit log as JSON
     * @param {string} [startDate] - YYYY-MM-DD
     * @param {string} [endDate] - YYYY-MM-DD
     * @returns {Promise<string>} JSON string
     */
    const exportJSON = async (startDate = null, endDate = null) => {
      const entries = await getEntries(startDate, endDate);
      return JSON.stringify({
        exported: new Date().toISOString(),
        startDate: startDate || new Date().toISOString().split('T')[0],
        endDate: endDate || startDate || new Date().toISOString().split('T')[0],
        count: entries.length,
        entries
      }, null, 2);
    };

    /**
     * Export audit log as CSV
     * @param {string} [startDate] - YYYY-MM-DD
     * @param {string} [endDate] - YYYY-MM-DD
     * @returns {Promise<string>} CSV string
     */
    const exportCSV = async (startDate = null, endDate = null) => {
      const entries = await getEntries(startDate, endDate);

      // CSV header
      const headers = ['id', 'timestamp', 'type', 'severity', 'data'];
      const rows = [headers.join(',')];

      for (const entry of entries) {
        const row = [
          entry.id || '',
          entry.ts || '',
          entry.type || '',
          entry.severity || 'INFO',
          JSON.stringify(entry.data || {}).replace(/"/g, '""')
        ];
        rows.push(row.map(v => `"${v}"`).join(','));
      }

      return rows.join('\n');
    };

    /**
     * Download audit log (browser only)
     * @param {string} format - 'json' or 'csv'
     * @param {string} [startDate] - YYYY-MM-DD
     * @param {string} [endDate] - YYYY-MM-DD
     */
    const download = async (format = 'json', startDate = null, endDate = null) => {
      const content = format === 'csv'
        ? await exportCSV(startDate, endDate)
        : await exportJSON(startDate, endDate);

      const mimeType = format === 'csv' ? 'text/csv' : 'application/json';
      const ext = format === 'csv' ? 'csv' : 'json';
      const filename = `audit-${startDate || 'today'}-${endDate || startDate || 'today'}.${ext}`;

      const blob = new Blob([content], { type: mimeType });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      logger.info(`[AuditLogger] Downloaded ${filename}`);
    };

    /**
     * Get summary statistics for a date range
     * @param {string} [startDate] - YYYY-MM-DD
     * @param {string} [endDate] - YYYY-MM-DD
     * @returns {Promise<Object>} Statistics
     */
    const getStats = async (startDate = null, endDate = null) => {
      const entries = await getEntries(startDate, endDate);

      const stats = {
        total: entries.length,
        byType: {},
        bySeverity: { INFO: 0, WARN: 0, ERROR: 0 },
        timeRange: {
          start: entries[0]?.ts || null,
          end: entries[entries.length - 1]?.ts || null
        }
      };

      for (const entry of entries) {
        stats.byType[entry.type] = (stats.byType[entry.type] || 0) + 1;
        stats.bySeverity[entry.severity || 'INFO']++;
      }

      return stats;
    };

    return {
      init,
      logEvent,
      getEntries,
      exportJSON,
      exportCSV,
      download,
      getStats,
      // Convenience aliases
      logAgentAction: (action, tool, args) => logEvent('AGENT_ACTION', { action, tool, args }),
      logSecurity: (type, details) => logEvent('SECURITY', { type, ...details }, 'ERROR')
    };
  }
};

export default AuditLogger;
","/infrastructure/circuit-breaker.js":"/**
 * @fileoverview Circuit Breaker - Failure tracking utility
 * Prevents repeated calls to failing services/tools.
 * Implements three states: CLOSED (normal), OPEN (failing), HALF_OPEN (testing recovery).
 */

const CircuitBreaker = {
  metadata: {
    id: 'CircuitBreaker',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'EventBus?'],
    async: false,
    type: 'utility'
  },

  factory: (deps) => {
    const { Utils, EventBus } = deps;
    const { logger } = Utils;

    /** Circuit states */
    const State = {
      CLOSED: 'closed',     // Normal operation
      OPEN: 'open',         // Failing, reject calls
      HALF_OPEN: 'half_open' // Testing recovery
    };

    /**
     * Create a circuit breaker instance
     * @param {Object} options
     * @param {number} options.threshold - Failures before circuit opens (default: 3)
     * @param {number} options.resetMs - Cooldown before testing recovery (default: 60000)
     * @param {number} options.successThreshold - Successes needed to close (default: 2)
     * @param {string} options.name - Name for logging (default: 'CircuitBreaker')
     * @param {boolean} options.emitEvents - Emit EventBus events (default: true)
     */
    const create = (options = {}) => {
      const {
        threshold = 3,
        resetMs = 60000,
        successThreshold = 2,
        name = 'CircuitBreaker',
        emitEvents = true
      } = options;

      const circuits = new Map();

      const emit = (event, data) => {
        if (emitEvents && EventBus) {
          EventBus.emit(event, { breaker: name, ...data });
        }
      };

      /**
       * Check if circuit is open for a key
       * @param {string} key - Identifier (tool name, service name, etc.)
       * @returns {boolean} True if circuit is open (should skip execution)
       */
      const isOpen = (key) => {
        const record = circuits.get(key);
        if (!record) return false;

        const now = Date.now();

        // OPEN state: check if cooldown has passed
        if (record.state === State.OPEN) {
          const elapsed = now - record.tripTime;
          if (elapsed >= resetMs) {
            // Transition to HALF_OPEN (test recovery)
            record.state = State.HALF_OPEN;
            record.testSuccesses = 0;
            logger.info(`[${name}] Circuit half-open for: ${key} (testing recovery)`);
            emit('circuit:half_open', { key });
            return false; // Allow test call
          }
          return true; // Still in cooldown
        }

        // HALF_OPEN state: allow calls (testing recovery)
        if (record.state === State.HALF_OPEN) {
          return false;
        }

        // CLOSED state or counting failures
        if (record.failures >= threshold) {
          // Should have transitioned to OPEN, but just in case
          record.state = State.OPEN;
          record.tripTime = now;
          return true;
        }

        return false;
      };

      /**
       * Record a failure for a key
       * @param {string} key - Identifier
       * @param {Error} error - The error that occurred
       */
      const recordFailure = (key, error) => {
        const now = Date.now();
        let record = circuits.get(key);

        if (!record) {
          record = {
            state: State.CLOSED,
            failures: 0,
            lastError: null,
            tripTime: 0,
            testSuccesses: 0
          };
        }

        record.lastError = error;

        if (record.state === State.HALF_OPEN) {
          // Recovery test failed - back to OPEN
          record.state = State.OPEN;
          record.tripTime = now;
          record.testSuccesses = 0;
          logger.warn(`[${name}] Recovery failed for: ${key}, circuit re-opened`);
          emit('circuit:reopen', { key, error: error?.message });
        } else {
          // Normal failure counting
          record.failures++;

          if (record.failures >= threshold && record.state !== State.OPEN) {
            record.state = State.OPEN;
            record.tripTime = now;
            logger.warn(`[${name}] Circuit TRIPPED for: ${key} after ${record.failures} failures`);
            emit('circuit:open', { key, failures: record.failures, error: error?.message });
          }
        }

        circuits.set(key, record);
      };

      /**
       * Record a success for a key
       * @param {string} key - Identifier
       */
      const recordSuccess = (key) => {
        const record = circuits.get(key);
        if (!record) return;

        if (record.state === State.HALF_OPEN) {
          // Count successful test calls
          record.testSuccesses++;

          if (record.testSuccesses >= successThreshold) {
            // Fully recovered - close circuit
            circuits.delete(key);
            logger.info(`[${name}] Circuit CLOSED for: ${key} (recovered after ${successThreshold} successes)`);
            emit('circuit:closed', { key });
          }
        } else {
          // Normal success - clear failure record
          circuits.delete(key);
        }
      };

      /**
       * Get current state for a key
       * @param {string} key - Identifier
       * @returns {Object|null} Circuit state or null if no record
       */
      const getState = (key) => {
        const record = circuits.get(key);
        if (!record) return { state: State.CLOSED, failures: 0, isOpen: false };

        const now = Date.now();
        const isCurrentlyOpen = record.state === State.OPEN &&
          (now - record.tripTime) < resetMs;

        return {
          state: record.state,
          failures: record.failures,
          lastError: record.lastError?.message,
          isOpen: isCurrentlyOpen,
          tripTime: record.tripTime,
          testSuccesses: record.testSuccesses || 0
        };
      };

      /**
       * Reset all circuits
       */
      const reset = () => {
        circuits.clear();
        logger.info(`[${name}] All circuits reset`);
      };

      /**
       * Get all tracked keys
       * @returns {string[]} List of keys with records
       */
      const getTrackedKeys = () => [...circuits.keys()];

      return {
        isOpen,
        recordFailure,
        recordSuccess,
        getState,
        reset,
        getTrackedKeys,
        State,
        get size() { return circuits.size; }
      };
    };

    return { create, State };
  }
};

export default CircuitBreaker;
","/infrastructure/event-bus.js":"/**
 * @fileoverview Event Bus
 * Pub/Sub system with subscription tracking.
 */

const EventBus = {
  metadata: {
    id: 'EventBus',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils'],
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { logger, createSubscriptionTracker } = deps.Utils;
    const _listeners = new Map();
    const _tracker = createSubscriptionTracker();

    const on = (event, fn, ownerId = null) => {
      if (!_listeners.has(event)) _listeners.set(event, new Set());
      _listeners.get(event).add(fn);

      const unsub = () => {
        const set = _listeners.get(event);
        if (set) {
          set.delete(fn);
          // Clean up empty Sets to prevent memory leak
          if (set.size === 0) {
            _listeners.delete(event);
          }
        }
      };

      if (ownerId) _tracker.track(ownerId, unsub);
      return unsub;
    };

    const emit = (event, data) => {
      // logger.debug(`[Event] ${event}`, data); // Uncomment for verbose debugging
      const set = _listeners.get(event);
      if (set) {
        for (const fn of set) {
          try { fn(data); } catch (e) { logger.error(`[EventBus] Error in ${event}`, e); }
        }
      }
    };

    const unsubscribeModule = (moduleId) => {
      _tracker.unsubscribeAll(moduleId);
      logger.debug(`[EventBus] Unsubscribed module: ${moduleId}`);
    };

    return { on, emit, unsubscribeModule };
  }
};

export default EventBus;
","/infrastructure/genesis-snapshot.js":"/**
 * @fileoverview Genesis Snapshot - Immutable kernel backups and rollback
 * Provides "Lifeboat" snapshots for recovery from bad mutations.
 */

const GenesisSnapshot = {
  metadata: {
    id: 'GenesisSnapshot',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'VFS', 'EventBus'],
    async: true,
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { Utils, VFS, EventBus } = deps;
    const { logger, generateId } = Utils;

    const SNAPSHOT_DIR = '/.genesis/snapshots';
    const LIFEBOAT_KEY = 'REPLOID_LIFEBOAT';
    const MAX_SNAPSHOTS = 10;

    /**
     * Create a full VFS snapshot
     * @param {string} [name] - Optional snapshot name
     * @param {Object} [options] - Options
     * @param {boolean} [options.includeApps] - Include /apps/ (default: false)
     * @param {boolean} [options.includeLogs] - Include /.logs/ (default: false)
     * @returns {Promise<Object>} Snapshot metadata
     */
    const createSnapshot = async (name = null, options = {}) => {
      const { includeApps = false, includeLogs = false } = options;

      const snapshotId = generateId('snap');
      const timestamp = Date.now();
      const snapshotName = name || `snapshot-${new Date(timestamp).toISOString().split('T')[0]}`;

      logger.info(`[Genesis] Creating snapshot: ${snapshotName}`);

      // Collect all files
      const files = {};
      const collectFiles = async (dir) => {
        try {
          const entries = await VFS.list(dir);
          for (const entry of entries) {
            // Skip based on options
            if (!includeLogs && entry.startsWith('/.logs/')) continue;
            if (!includeApps && entry.startsWith('/apps/')) continue;
            if (entry.startsWith('/.genesis/')) continue; // Never include snapshots

            try {
              const stat = await VFS.stat(entry);
              if (stat.isDirectory) {
                await collectFiles(entry);
              } else {
                files[entry] = await VFS.read(entry);
              }
            } catch (e) {
              logger.debug(`[Genesis] Skip ${entry}: ${e.message}`);
            }
          }
        } catch (e) {
          logger.debug(`[Genesis] Cannot list ${dir}: ${e.message}`);
        }
      };

      await collectFiles('/');

      const snapshot = {
        id: snapshotId,
        name: snapshotName,
        timestamp,
        fileCount: Object.keys(files).length,
        isBootable: true, // This snapshot contains a complete runnable system
        version: '2.0', // Self-hosting VFS architecture version
        files
      };

      // Save snapshot to VFS
      const snapshotPath = `${SNAPSHOT_DIR}/${snapshotId}.json`;
      await VFS.write(snapshotPath, JSON.stringify(snapshot));

      // Update index
      await updateIndex(snapshotId, snapshotName, timestamp, Object.keys(files).length);

      // Prune old snapshots
      await pruneSnapshots();

      EventBus.emit('genesis:snapshot_created', {
        id: snapshotId,
        name: snapshotName,
        fileCount: Object.keys(files).length
      });

      logger.info(`[Genesis] Snapshot created: ${snapshotId} (${Object.keys(files).length} files)`);

      return {
        id: snapshotId,
        name: snapshotName,
        timestamp,
        fileCount: Object.keys(files).length,
        isBootable: true,
        version: '2.0'
      };
    };

    /**
     * Create a "Lifeboat" - immutable kernel backup stored in localStorage
     * This survives VFS corruption and can restore the system from scratch.
     */
    const createLifeboat = async () => {
      logger.info('[Genesis] Creating Lifeboat backup...');

      const coreFiles = {};
      const corePaths = ['/core/', '/infrastructure/'];

      for (const prefix of corePaths) {
        try {
          const entries = await VFS.list(prefix);
          for (const entry of entries) {
            if (entry.endsWith('.js')) {
              try {
                coreFiles[entry] = await VFS.read(entry);
              } catch (e) {
                logger.warn(`[Genesis] Cannot backup ${entry}`);
              }
            }
          }
        } catch (e) {
          logger.debug(`[Genesis] Cannot list ${prefix}`);
        }
      }

      const lifeboat = {
        version: '1.0',
        timestamp: Date.now(),
        files: coreFiles
      };

      try {
        // Compress for localStorage (simple approach)
        const json = JSON.stringify(lifeboat);
        localStorage.setItem(LIFEBOAT_KEY, json);

        EventBus.emit('genesis:lifeboat_created', {
          timestamp: lifeboat.timestamp,
          fileCount: Object.keys(coreFiles).length,
          sizeBytes: json.length
        });

        logger.info(`[Genesis] Lifeboat created: ${Object.keys(coreFiles).length} core files`);
        return { success: true, fileCount: Object.keys(coreFiles).length };
      } catch (e) {
        logger.error('[Genesis] Lifeboat creation failed:', e.message);
        return { success: false, error: e.message };
      }
    };

    /**
     * Restore from Lifeboat (emergency recovery)
     */
    const restoreFromLifeboat = async () => {
      logger.warn('[Genesis] EMERGENCY: Restoring from Lifeboat...');

      try {
        const json = localStorage.getItem(LIFEBOAT_KEY);
        if (!json) {
          throw new Error('No Lifeboat backup found');
        }

        const lifeboat = JSON.parse(json);

        for (const [path, content] of Object.entries(lifeboat.files)) {
          await VFS.write(path, content);
          logger.info(`[Genesis] Restored: ${path}`);
        }

        EventBus.emit('genesis:lifeboat_restored', {
          timestamp: lifeboat.timestamp,
          fileCount: Object.keys(lifeboat.files).length
        });

        logger.info(`[Genesis] Lifeboat restore complete: ${Object.keys(lifeboat.files).length} files`);
        return { success: true, fileCount: Object.keys(lifeboat.files).length };
      } catch (e) {
        logger.error('[Genesis] Lifeboat restore failed:', e.message);
        return { success: false, error: e.message };
      }
    };

    /**
     * Restore from a snapshot
     * @param {string} snapshotId - Snapshot ID to restore
     * @param {Object} [options] - Options
     * @param {boolean} [options.deleteExtra] - Delete files not in snapshot (default: false)
     */
    const restoreSnapshot = async (snapshotId, options = {}) => {
      const { deleteExtra = false } = options;

      logger.warn(`[Genesis] Restoring snapshot: ${snapshotId}`);

      const snapshotPath = `${SNAPSHOT_DIR}/${snapshotId}.json`;
      const snapshotJson = await VFS.read(snapshotPath);
      const snapshot = JSON.parse(snapshotJson);

      let restored = 0;
      let deleted = 0;

      // Restore all files from snapshot
      for (const [path, content] of Object.entries(snapshot.files)) {
        try {
          await VFS.write(path, content);
          restored++;
        } catch (e) {
          logger.warn(`[Genesis] Failed to restore ${path}: ${e.message}`);
        }
      }

      // Optionally delete files not in snapshot
      if (deleteExtra) {
        const currentFiles = await getAllFiles('/');
        for (const path of currentFiles) {
          if (path.startsWith('/.genesis/')) continue;
          if (path.startsWith('/.logs/')) continue;
          if (!snapshot.files[path]) {
            try {
              await VFS.delete(path);
              deleted++;
            } catch (e) {
              logger.debug(`[Genesis] Could not delete ${path}`);
            }
          }
        }
      }

      EventBus.emit('genesis:snapshot_restored', {
        id: snapshotId,
        name: snapshot.name,
        restored,
        deleted
      });

      logger.info(`[Genesis] Restore complete: ${restored} restored, ${deleted} deleted`);
      return { success: true, restored, deleted };
    };

    /**
     * Get list of available snapshots
     */
    const listSnapshots = async () => {
      try {
        const indexPath = `${SNAPSHOT_DIR}/index.json`;
        if (await VFS.exists(indexPath)) {
          const indexJson = await VFS.read(indexPath);
          return JSON.parse(indexJson);
        }
      } catch (e) {
        logger.debug('[Genesis] No snapshot index');
      }
      return [];
    };

    /**
     * Delete a snapshot
     */
    const deleteSnapshot = async (snapshotId) => {
      const snapshotPath = `${SNAPSHOT_DIR}/${snapshotId}.json`;
      await VFS.delete(snapshotPath);

      // Update index
      const index = await listSnapshots();
      const newIndex = index.filter(s => s.id !== snapshotId);
      await VFS.write(`${SNAPSHOT_DIR}/index.json`, JSON.stringify(newIndex, null, 2));

      EventBus.emit('genesis:snapshot_deleted', { id: snapshotId });
      logger.info(`[Genesis] Deleted snapshot: ${snapshotId}`);
    };

    /**
     * Export snapshot as downloadable JSON
     */
    const exportSnapshot = async (snapshotId) => {
      const snapshotPath = `${SNAPSHOT_DIR}/${snapshotId}.json`;
      const snapshotJson = await VFS.read(snapshotPath);
      const snapshot = JSON.parse(snapshotJson);

      const blob = new Blob([JSON.stringify(snapshot, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `genesis-${snapshot.name}-${snapshotId}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      logger.info(`[Genesis] Exported: ${snapshot.name}`);
    };

    /**
     * Import snapshot from file
     */
    const importSnapshot = async (file) => {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = async (e) => {
          try {
            const snapshot = JSON.parse(e.target.result);

            // Validate snapshot structure
            if (!snapshot.id || !snapshot.files || !snapshot.timestamp) {
              throw new Error('Invalid snapshot format');
            }

            // Save to VFS
            const snapshotPath = `${SNAPSHOT_DIR}/${snapshot.id}.json`;
            await VFS.write(snapshotPath, JSON.stringify(snapshot));

            // Update index
            await updateIndex(snapshot.id, snapshot.name, snapshot.timestamp, snapshot.fileCount);

            EventBus.emit('genesis:snapshot_imported', { id: snapshot.id, name: snapshot.name });
            logger.info(`[Genesis] Imported: ${snapshot.name}`);

            resolve({ success: true, id: snapshot.id, name: snapshot.name });
          } catch (err) {
            reject(err);
          }
        };
        reader.onerror = () => reject(new Error('Failed to read file'));
        reader.readAsText(file);
      });
    };

    // --- Internal helpers ---

    const updateIndex = async (id, name, timestamp, fileCount) => {
      const index = await listSnapshots();
      index.push({ id, name, timestamp, fileCount });
      index.sort((a, b) => b.timestamp - a.timestamp);
      await VFS.write(`${SNAPSHOT_DIR}/index.json`, JSON.stringify(index, null, 2));
    };

    const pruneSnapshots = async () => {
      const index = await listSnapshots();
      if (index.length > MAX_SNAPSHOTS) {
        const toDelete = index.slice(MAX_SNAPSHOTS);
        for (const snap of toDelete) {
          try {
            await deleteSnapshot(snap.id);
          } catch (e) {
            logger.debug(`[Genesis] Could not prune ${snap.id}`);
          }
        }
      }
    };

    const getAllFiles = async (dir, acc = []) => {
      try {
        const entries = await VFS.list(dir);
        for (const entry of entries) {
          try {
            const stat = await VFS.stat(entry);
            if (stat.isDirectory) {
              await getAllFiles(entry, acc);
            } else {
              acc.push(entry);
            }
          } catch (e) {}
        }
      } catch (e) {}
      return acc;
    };

    /**
     * Check if Lifeboat exists
     */
    const hasLifeboat = () => {
      try {
        return !!localStorage.getItem(LIFEBOAT_KEY);
      } catch (e) {
        return false;
      }
    };

    /**
     * Get Lifeboat info
     */
    const getLifeboatInfo = () => {
      try {
        const json = localStorage.getItem(LIFEBOAT_KEY);
        if (!json) return null;
        const lifeboat = JSON.parse(json);
        return {
          timestamp: lifeboat.timestamp,
          fileCount: Object.keys(lifeboat.files).length,
          sizeBytes: json.length
        };
      } catch (e) {
        return null;
      }
    };

    return {
      createSnapshot,
      restoreSnapshot,
      listSnapshots,
      deleteSnapshot,
      exportSnapshot,
      importSnapshot,
      createLifeboat,
      restoreFromLifeboat,
      hasLifeboat,
      getLifeboatInfo
    };
  }
};

export default GenesisSnapshot;
","/infrastructure/hitl-controller.js":"/**
 * @fileoverview HITL Controller - Human-in-the-Loop approval system
 * Autonomous by default. Opt-in HITL for users who want approval gates.
 */

const HITLController = {
  metadata: {
    id: 'HITLController',
    version: '1.0.0',
    genesis: { introduced: 'reflection' },
    dependencies: ['Utils', 'EventBus'],
    async: false,
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { Utils, EventBus } = deps;
    const { logger, generateId } = Utils;

    const STORAGE_KEY = 'REPLOID_HITL_CONFIG';

    /** Approval capability types */
    const CAPABILITIES = {
      APPROVE_CODE_CHANGES: 'approve_code_changes',
      APPROVE_FILE_OPERATIONS: 'approve_file_operations',
      APPROVE_TOOL_EXECUTION: 'approve_tool_execution',
      APPROVE_SELF_MODIFICATION: 'approve_self_modification',
      APPROVE_CORE_WRITES: 'approve_core_writes'
    };

    /** Mode constants */
    const MODES = {
      AUTONOMOUS: 'autonomous',
      HITL: 'hitl',
      EVERY_N: 'every_n', // Approve every N steps
      INHERIT: 'inherit'
    };

    // Internal state
    const _moduleRegistry = new Map();
    const _approvalQueue = [];
    const _timeouts = new Map();

    let _config = {
      approvalMode: MODES.AUTONOMOUS, // Autonomous by default
      moduleOverrides: {},
      everyNSteps: 5, // Default: approve every 5 steps
      stepCounter: 0  // Track steps since last approval
    };

    const _stats = {
      total: 0,
      approved: 0,
      rejected: 0,
      timedOut: 0,
      autoApproved: 0,
      history: []
    };

    // --- Persistence ---

    const _saveConfig = () => {
      try {
        const toSave = {
          approvalMode: _config.approvalMode,
          moduleOverrides: _config.moduleOverrides,
          everyNSteps: _config.everyNSteps,
          stepCounter: _config.stepCounter
        };
        localStorage.setItem(STORAGE_KEY, JSON.stringify(toSave));
      } catch (e) {
        logger.warn('[HITL] Failed to save config:', e.message);
      }
    };

    const _loadConfig = () => {
      try {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
          const parsed = JSON.parse(saved);
          _config.approvalMode = parsed.approvalMode || MODES.AUTONOMOUS;
          _config.moduleOverrides = parsed.moduleOverrides || {};
          _config.everyNSteps = parsed.everyNSteps || 5;
          _config.stepCounter = parsed.stepCounter || 0;
          logger.info(`[HITL] Loaded config: ${_config.approvalMode} mode` +
            (_config.approvalMode === MODES.EVERY_N ? ` (every ${_config.everyNSteps} steps)` : ''));
        }
      } catch (e) {
        logger.warn('[HITL] Failed to load config, using defaults');
      }
    };

    // --- Module Registration ---

    /**
     * Register a module as HITL-capable
     * @param {string} moduleId - Module identifier
     * @param {string[]} capabilities - Array of CAPABILITIES
     * @param {string} [description] - Optional description
     */
    const registerModule = (moduleId, capabilities = [], description = '') => {
      if (!moduleId) {
        logger.warn('[HITL] registerModule called without moduleId');
        return;
      }

      const existing = _moduleRegistry.get(moduleId);
      const currentMode = _config.moduleOverrides[moduleId] || MODES.INHERIT;

      _moduleRegistry.set(moduleId, {
        id: moduleId,
        description,
        capabilities,
        currentMode,
        registeredAt: existing?.registeredAt || Date.now()
      });

      EventBus.emit('hitl:module-registered', { moduleId });
      logger.debug(`[HITL] Registered module: ${moduleId} with ${capabilities.length} capabilities`);
    };

    // --- Mode Management ---

    /**
     * Get effective mode for a module
     * @param {string} moduleId - Module identifier
     * @returns {string} 'autonomous' or 'hitl'
     */
    const getModuleMode = (moduleId) => {
      const override = _config.moduleOverrides[moduleId];
      if (override && override !== MODES.INHERIT) {
        return override;
      }
      return _config.approvalMode;
    };

    /**
     * Set master mode (affects all modules using 'inherit')
     * @param {string} mode - 'autonomous' or 'hitl'
     */
    const setApprovalMode = (mode) => {
      if (mode !== MODES.AUTONOMOUS && mode !== MODES.HITL && mode !== MODES.EVERY_N) {
        logger.warn(`[HITL] Invalid mode: ${mode}`);
        return;
      }

      const oldMode = _config.approvalMode;
      _config.approvalMode = mode;

      // Reset step counter when changing to/from EVERY_N mode
      if (mode === MODES.EVERY_N || oldMode === MODES.EVERY_N) {
        _config.stepCounter = 0;
      }

      _saveConfig();

      const affectedModules = [..._moduleRegistry.keys()].filter(
        id => !_config.moduleOverrides[id] || _config.moduleOverrides[id] === MODES.INHERIT
      );

      EventBus.emit('hitl:approval-mode-changed', { oldMode, newMode: mode, affectedModules });
      logger.info(`[HITL] Approval mode changed: ${oldMode} -> ${mode}` +
        (mode === MODES.EVERY_N ? ` (every ${_config.everyNSteps} steps)` : ''));
    };

    /**
     * Set the step interval for EVERY_N mode
     * @param {number} steps - Number of steps between approvals (1-100)
     */
    const setEveryNSteps = (steps) => {
      const n = parseInt(steps, 10);
      if (isNaN(n) || n < 1 || n > 100) {
        logger.warn(`[HITL] Invalid step count: ${steps} (must be 1-100)`);
        return;
      }

      _config.everyNSteps = n;
      _config.stepCounter = 0; // Reset counter
      _saveConfig();

      EventBus.emit('hitl:every-n-changed', { steps: n });
      logger.info(`[HITL] Every-N interval set to: ${n} steps`);
    };

    /**
     * Set mode override for a specific module
     * @param {string} moduleId - Module identifier
     * @param {string} mode - 'autonomous', 'hitl', or 'inherit'
     */
    const setModuleMode = (moduleId, mode) => {
      if (!_moduleRegistry.has(moduleId)) {
        logger.warn(`[HITL] Module not registered: ${moduleId}`);
        return;
      }

      if (![MODES.AUTONOMOUS, MODES.HITL, MODES.EVERY_N, MODES.INHERIT].includes(mode)) {
        logger.warn(`[HITL] Invalid mode: ${mode}`);
        return;
      }

      const oldMode = _config.moduleOverrides[moduleId] || MODES.INHERIT;
      _config.moduleOverrides[moduleId] = mode;

      const entry = _moduleRegistry.get(moduleId);
      if (entry) {
        entry.currentMode = mode;
      }

      _saveConfig();

      EventBus.emit('hitl:module-mode-changed', {
        moduleId,
        oldMode,
        newMode: mode,
        effectiveMode: getModuleMode(moduleId)
      });
    };

    // --- Approval Logic ---

    /**
     * Check if approval is required for an action
     * @param {string} moduleId - Module identifier
     * @param {string} capability - Capability being checked
     * @returns {boolean} True if approval required
     */
    const requiresApproval = (moduleId, capability) => {
      const effectiveMode = getModuleMode(moduleId);
      if (effectiveMode === MODES.AUTONOMOUS) {
        return false;
      }

      // In EVERY_N mode, check step counter
      if (effectiveMode === MODES.EVERY_N) {
        _config.stepCounter++;
        const needsApproval = _config.stepCounter >= _config.everyNSteps;
        if (needsApproval) {
          _config.stepCounter = 0; // Reset counter
          _saveConfig();
        }
        return needsApproval;
      }

      // In HITL mode, check if module has this capability
      const entry = _moduleRegistry.get(moduleId);
      if (!entry) {
        return false; // Unregistered modules don't require approval
      }

      return entry.capabilities.includes(capability);
    };

    /**
     * Request approval for an action
     * @param {Object} request - Approval request
     * @param {string} request.moduleId - Module requesting approval
     * @param {string} request.capability - Capability being used
     * @param {string} request.action - Human-readable action description
     * @param {*} request.data - Data to pass to callback
     * @param {Function} request.onApprove - Called with data on approval
     * @param {Function} request.onReject - Called with reason on rejection
     * @param {number} [request.timeout] - Auto-reject after ms (optional)
     * @returns {string|null} Approval ID if queued, null if auto-approved
     */
    const requestApproval = (request) => {
      const { moduleId, capability, action, data, onApprove, onReject, timeout } = request;

      // Check if approval is actually required
      if (!requiresApproval(moduleId, capability)) {
        // Auto-approve in autonomous mode
        _stats.autoApproved++;
        logger.debug(`[HITL] Auto-approved: ${moduleId}/${capability}`);
        if (onApprove) onApprove(data);
        return null;
      }

      // Queue for approval
      const approvalId = generateId('approval');
      const item = {
        id: approvalId,
        moduleId,
        capability,
        action,
        data,
        onApprove,
        onReject,
        timestamp: Date.now(),
        status: 'pending'
      };

      _approvalQueue.push(item);

      // Set timeout if specified
      if (timeout && timeout > 0) {
        const timeoutId = setTimeout(() => {
          _handleTimeout(approvalId);
        }, timeout);
        _timeouts.set(approvalId, timeoutId);
      }

      EventBus.emit('hitl:approval-pending', item);
      logger.info(`[HITL] Approval required: ${action} (${approvalId})`);

      return approvalId;
    };

    /**
     * Approve a pending request
     * @param {string} approvalId - Approval ID
     * @param {*} [data] - Optional data override
     */
    const approve = (approvalId, data = null) => {
      const index = _approvalQueue.findIndex(item => item.id === approvalId);
      if (index === -1) {
        logger.warn(`[HITL] Approval not found: ${approvalId}`);
        return false;
      }

      const item = _approvalQueue[index];
      _approvalQueue.splice(index, 1);

      // Clear timeout if set
      if (_timeouts.has(approvalId)) {
        clearTimeout(_timeouts.get(approvalId));
        _timeouts.delete(approvalId);
      }

      // Update stats
      _stats.total++;
      _stats.approved++;
      _addHistory('approved', item);

      // Execute callback
      if (item.onApprove) {
        item.onApprove(data !== null ? data : item.data);
      }

      EventBus.emit('hitl:approval-granted', { approvalId, item });
      logger.info(`[HITL] Approved: ${item.action}`);

      return true;
    };

    /**
     * Reject a pending request
     * @param {string} approvalId - Approval ID
     * @param {string} [reason] - Rejection reason
     */
    const reject = (approvalId, reason = 'Rejected by user') => {
      const index = _approvalQueue.findIndex(item => item.id === approvalId);
      if (index === -1) {
        logger.warn(`[HITL] Approval not found: ${approvalId}`);
        return false;
      }

      const item = _approvalQueue[index];
      _approvalQueue.splice(index, 1);

      // Clear timeout if set
      if (_timeouts.has(approvalId)) {
        clearTimeout(_timeouts.get(approvalId));
        _timeouts.delete(approvalId);
      }

      // Update stats
      _stats.total++;
      _stats.rejected++;
      _addHistory('rejected', item, reason);

      // Execute callback
      if (item.onReject) {
        item.onReject(reason);
      }

      EventBus.emit('hitl:approval-rejected', { approvalId, item, reason });
      logger.info(`[HITL] Rejected: ${item.action} - ${reason}`);

      return true;
    };

    const _handleTimeout = (approvalId) => {
      const index = _approvalQueue.findIndex(item => item.id === approvalId);
      if (index === -1) return; // Already processed

      const item = _approvalQueue[index];
      _approvalQueue.splice(index, 1);
      _timeouts.delete(approvalId);

      // Update stats
      _stats.total++;
      _stats.timedOut++;
      _addHistory('timeout', item, 'Timed out');

      // Execute rejection callback
      if (item.onReject) {
        item.onReject('Approval timed out');
      }

      EventBus.emit('hitl:approval-timeout', { approvalId, item });
      logger.warn(`[HITL] Approval timed out: ${item.action}`);
    };

    const _addHistory = (outcome, item, reason = null) => {
      _stats.history.unshift({
        outcome,
        moduleId: item.moduleId,
        action: item.action,
        reason,
        timestamp: Date.now()
      });

      // Keep only last 50 entries
      if (_stats.history.length > 50) {
        _stats.history.pop();
      }
    };

    // --- Query APIs ---

    const getState = () => ({
      config: {
        approvalMode: _config.approvalMode,
        moduleOverrides: { ..._config.moduleOverrides }
      },
      approvalQueue: [..._approvalQueue],
      approvalStats: { ..._stats, history: [..._stats.history] },
      registeredModules: [..._moduleRegistry.values()].map(m => ({
        ...m,
        effectiveMode: getModuleMode(m.id)
      }))
    });

    const getApprovalQueue = () => [..._approvalQueue];

    const getStats = () => ({ ..._stats, history: [..._stats.history] });

    const isHITLEnabled = () => _config.approvalMode === MODES.HITL;

    const resetToDefaults = () => {
      _config.approvalMode = MODES.AUTONOMOUS;
      _config.moduleOverrides = {};
      _approvalQueue.length = 0;

      // Clear all timeouts
      for (const timeoutId of _timeouts.values()) {
        clearTimeout(timeoutId);
      }
      _timeouts.clear();

      _saveConfig();
      EventBus.emit('hitl:config-reset', {});
      logger.info('[HITL] Reset to defaults (autonomous mode)');
    };

    // --- EventBus Integration ---

    const init = () => {
      _loadConfig();

      EventBus.on('hitl:set-approval-mode', ({ mode }) => setApprovalMode(mode), 'HITLController');
      EventBus.on('hitl:set-module-mode', ({ moduleId, mode }) => setModuleMode(moduleId, mode), 'HITLController');
      EventBus.on('hitl:approve', ({ approvalId, data }) => approve(approvalId, data), 'HITLController');
      EventBus.on('hitl:reject', ({ approvalId, reason }) => reject(approvalId, reason), 'HITLController');

      logger.info(`[HITL] Initialized in ${_config.approvalMode} mode`);
      return true;
    };

    return {
      init,
      CAPABILITIES,
      MODES,
      registerModule,
      getModuleMode,
      setApprovalMode,
      setModuleMode,
      setEveryNSteps,
      requiresApproval,
      requestApproval,
      approve,
      reject,
      getState,
      getApprovalQueue,
      getStats,
      isHITLEnabled,
      resetToDefaults
    };
  }
};

export default HITLController;
","/infrastructure/indexed-db-helper.js":"/**
 * @fileoverview IndexedDB Helper - Database initialization utility
 * Provides standardized IndexedDB setup with store/index configuration.
 *
 * NOTE: Cannot be used by bootstrap modules (vfs.js, event-bus.js, utils.js)
 * which must remain self-contained.
 */

const IndexedDBHelper = {
  metadata: {
    id: 'IndexedDBHelper',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils'],
    async: false,
    type: 'utility'
  },

  factory: (deps) => {
    const { Utils } = deps;
    const { logger } = Utils;

    /**
     * Create a database helper for a specific database
     * @param {string} dbName - Database name
     * @param {number} version - Database version
     * @param {Array<Object>} storeConfigs - Store configurations
     * @param {string} storeConfigs[].name - Object store name
     * @param {string} storeConfigs[].keyPath - Key path for objects
     * @param {boolean} storeConfigs[].autoIncrement - Auto-increment keys
     * @param {Array<Object>} storeConfigs[].indexes - Index definitions
     * @param {string} storeConfigs[].indexes[].name - Index name
     * @param {string} storeConfigs[].indexes[].keyPath - Index key path
     * @param {boolean} storeConfigs[].indexes[].unique - Unique constraint
     * @returns {Object} Database helper with openDB, close methods
     */
    const createDBHelper = (dbName, version, storeConfigs) => {
      let db = null;
      let openPromise = null;

      const openDB = () => {
        // Return existing connection if open
        if (db) return Promise.resolve(db);

        // Return pending connection if opening
        if (openPromise) return openPromise;

        openPromise = new Promise((resolve, reject) => {
          const request = indexedDB.open(dbName, version);

          request.onupgradeneeded = (event) => {
            const database = event.target.result;

            for (const config of storeConfigs) {
              if (!database.objectStoreNames.contains(config.name)) {
                const storeOptions = { keyPath: config.keyPath };
                if (config.autoIncrement) {
                  storeOptions.autoIncrement = true;
                }

                const store = database.createObjectStore(config.name, storeOptions);

                // Create indexes
                if (config.indexes) {
                  for (const idx of config.indexes) {
                    store.createIndex(
                      idx.name,
                      idx.keyPath || idx.name,
                      { unique: !!idx.unique }
                    );
                  }
                }
              }
            }
          };

          request.onsuccess = (e) => {
            db = e.target.result;
            logger.info(`[IndexedDBHelper] Database '${dbName}' connected`);
            resolve(db);
          };

          request.onerror = () => {
            openPromise = null;
            reject(new Error(`Failed to open database: ${dbName}`));
          };
        });

        return openPromise;
      };

      const close = () => {
        if (db) {
          db.close();
          db = null;
          openPromise = null;
          logger.info(`[IndexedDBHelper] Database '${dbName}' closed`);
        }
      };

      /**
       * Run a transaction on specified stores
       * @param {string|string[]} storeNames - Store name(s)
       * @param {'readonly'|'readwrite'} mode - Transaction mode
       * @param {Function} callback - (stores) => result
       * @returns {Promise<any>} Transaction result
       */
      const transaction = async (storeNames, mode, callback) => {
        await openDB();
        const stores = Array.isArray(storeNames) ? storeNames : [storeNames];
        const tx = db.transaction(stores, mode);

        // Get store objects
        const storeObjects = stores.length === 1
          ? tx.objectStore(stores[0])
          : stores.reduce((acc, name) => {
              acc[name] = tx.objectStore(name);
              return acc;
            }, {});

        return callback(storeObjects, tx);
      };

      /**
       * Get all records from a store
       * @param {string} storeName - Store name
       * @returns {Promise<Array>} All records
       */
      const getAll = async (storeName) => {
        return transaction(storeName, 'readonly', (store) => {
          return new Promise((resolve) => {
            const req = store.getAll();
            req.onsuccess = () => resolve(req.result || []);
            req.onerror = () => resolve([]);
          });
        });
      };

      /**
       * Get a record by key
       * @param {string} storeName - Store name
       * @param {any} key - Record key
       * @returns {Promise<any>} Record or undefined
       */
      const get = async (storeName, key) => {
        return transaction(storeName, 'readonly', (store) => {
          return new Promise((resolve) => {
            const req = store.get(key);
            req.onsuccess = () => resolve(req.result);
            req.onerror = () => resolve(undefined);
          });
        });
      };

      /**
       * Put a record (add or update)
       * @param {string} storeName - Store name
       * @param {any} value - Record value
       * @returns {Promise<any>} Record key
       */
      const put = async (storeName, value) => {
        return transaction(storeName, 'readwrite', (store) => {
          return new Promise((resolve, reject) => {
            const req = store.put(value);
            req.onsuccess = () => resolve(req.result);
            req.onerror = () => reject(new Error('Put failed'));
          });
        });
      };

      /**
       * Delete a record by key
       * @param {string} storeName - Store name
       * @param {any} key - Record key
       * @returns {Promise<void>}
       */
      const remove = async (storeName, key) => {
        return transaction(storeName, 'readwrite', (store) => {
          return new Promise((resolve) => {
            const req = store.delete(key);
            req.onsuccess = () => resolve();
            req.onerror = () => resolve();
          });
        });
      };

      /**
       * Clear all records from a store
       * @param {string} storeName - Store name
       * @returns {Promise<void>}
       */
      const clear = async (storeName) => {
        return transaction(storeName, 'readwrite', (store) => {
          return new Promise((resolve) => {
            const req = store.clear();
            req.onsuccess = () => resolve();
            req.onerror = () => resolve();
          });
        });
      };

      return {
        openDB,
        close,
        transaction,
        getAll,
        get,
        put,
        remove,
        clear,
        get isOpen() { return !!db; }
      };
    };

    return { createDBHelper };
  }
};

export default IndexedDBHelper;
","/infrastructure/observability.js":"/**
 * @fileoverview Observability - Token tracking, mutation stream, and metrics
 * Real-time visibility into agent behavior and resource usage.
 */

const Observability = {
  metadata: {
    id: 'Observability',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'EventBus', 'StateManager?'],
    async: false,
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { Utils, EventBus, StateManager } = deps;
    const { logger } = Utils;

    // --- Token Tracking ---
    const _tokenUsage = {
      session: { input: 0, output: 0, total: 0 },
      daily: { input: 0, output: 0, total: 0, date: null },
      byModel: {},
      history: [] // Last 100 requests
    };

    const COST_PER_1K = {
      'gpt-4': { input: 0.03, output: 0.06 },
      'gpt-4-turbo': { input: 0.01, output: 0.03 },
      'gpt-3.5-turbo': { input: 0.0005, output: 0.0015 },
      'claude-3-opus': { input: 0.015, output: 0.075 },
      'claude-3-sonnet': { input: 0.003, output: 0.015 },
      'claude-3-haiku': { input: 0.00025, output: 0.00125 },
      'gemini-pro': { input: 0.00025, output: 0.0005 },
      'gemini-1.5-pro': { input: 0.00125, output: 0.005 },
      default: { input: 0.001, output: 0.002 }
    };

    /**
     * Record token usage from an LLM call
     * @param {Object} usage - { inputTokens, outputTokens, model, provider }
     */
    const recordTokens = (usage) => {
      const { inputTokens = 0, outputTokens = 0, model = 'unknown', provider = 'unknown' } = usage;
      const total = inputTokens + outputTokens;

      // Update session totals
      _tokenUsage.session.input += inputTokens;
      _tokenUsage.session.output += outputTokens;
      _tokenUsage.session.total += total;

      // Update daily totals
      const today = new Date().toISOString().split('T')[0];
      if (_tokenUsage.daily.date !== today) {
        _tokenUsage.daily = { input: 0, output: 0, total: 0, date: today };
      }
      _tokenUsage.daily.input += inputTokens;
      _tokenUsage.daily.output += outputTokens;
      _tokenUsage.daily.total += total;

      // Track by model
      if (!_tokenUsage.byModel[model]) {
        _tokenUsage.byModel[model] = { input: 0, output: 0, total: 0, calls: 0 };
      }
      _tokenUsage.byModel[model].input += inputTokens;
      _tokenUsage.byModel[model].output += outputTokens;
      _tokenUsage.byModel[model].total += total;
      _tokenUsage.byModel[model].calls++;

      // Add to history
      _tokenUsage.history.push({
        timestamp: Date.now(),
        model,
        provider,
        inputTokens,
        outputTokens,
        total
      });
      if (_tokenUsage.history.length > 100) {
        _tokenUsage.history.shift();
      }

      // Emit event for UI
      EventBus.emit('observability:tokens', {
        session: { ..._tokenUsage.session },
        daily: { ..._tokenUsage.daily },
        latest: { model, inputTokens, outputTokens, total }
      });
    };

    /**
     * Estimate cost for token usage
     * @param {string} model - Model name
     * @param {number} inputTokens
     * @param {number} outputTokens
     * @returns {number} Estimated cost in USD
     */
    const estimateCost = (model, inputTokens, outputTokens) => {
      const rates = COST_PER_1K[model] || COST_PER_1K.default;
      return (inputTokens / 1000) * rates.input + (outputTokens / 1000) * rates.output;
    };

    /**
     * Get token usage summary
     */
    const getTokenUsage = () => {
      const sessionCost = Object.entries(_tokenUsage.byModel).reduce((sum, [model, usage]) => {
        return sum + estimateCost(model, usage.input, usage.output);
      }, 0);

      return {
        session: { ..._tokenUsage.session, estimatedCost: sessionCost },
        daily: { ..._tokenUsage.daily },
        byModel: { ..._tokenUsage.byModel },
        history: [..._tokenUsage.history]
      };
    };

    // --- Mutation Stream ---
    const _mutations = [];
    const MAX_MUTATIONS = 500;

    /**
     * Record a VFS mutation
     * @param {Object} mutation - { type, path, bytesBefore, bytesAfter, source }
     */
    const recordMutation = (mutation) => {
      const entry = {
        id: Utils.generateId('mut'),
        timestamp: Date.now(),
        ...mutation
      };

      _mutations.push(entry);
      if (_mutations.length > MAX_MUTATIONS) {
        _mutations.shift();
      }

      EventBus.emit('observability:mutation', entry);
    };

    /**
     * Get mutation history
     * @param {Object} [filter] - { type, path, since }
     */
    const getMutations = (filter = {}) => {
      let result = [..._mutations];

      if (filter.type) {
        result = result.filter(m => m.type === filter.type);
      }
      if (filter.path) {
        result = result.filter(m => m.path.includes(filter.path));
      }
      if (filter.since) {
        result = result.filter(m => m.timestamp >= filter.since);
      }

      return result;
    };

    // --- Agent Decision Trace ---
    const _decisionTrace = [];
    const MAX_DECISIONS = 200;

    /**
     * Record an agent decision point
     * @param {Object} decision - { cycle, type, input, output, reasoning }
     */
    const recordDecision = (decision) => {
      const entry = {
        id: Utils.generateId('dec'),
        timestamp: Date.now(),
        ...decision
      };

      _decisionTrace.push(entry);
      if (_decisionTrace.length > MAX_DECISIONS) {
        _decisionTrace.shift();
      }

      EventBus.emit('observability:decision', entry);
    };

    /**
     * Get decision trace
     * @param {number} [limit] - Max entries to return
     */
    const getDecisionTrace = (limit = 50) => {
      return _decisionTrace.slice(-limit);
    };

    // --- Performance Metrics ---
    const _metrics = {
      llmLatency: [], // Last 50 LLM call latencies
      toolLatency: {}, // By tool name
      errorRate: { total: 0, errors: 0 }
    };

    /**
     * Record LLM latency
     */
    const recordLLMLatency = (ms, model) => {
      _metrics.llmLatency.push({ ms, model, timestamp: Date.now() });
      if (_metrics.llmLatency.length > 50) {
        _metrics.llmLatency.shift();
      }
    };

    /**
     * Record tool execution latency
     */
    const recordToolLatency = (tool, ms, success) => {
      if (!_metrics.toolLatency[tool]) {
        _metrics.toolLatency[tool] = { calls: 0, totalMs: 0, errors: 0 };
      }
      _metrics.toolLatency[tool].calls++;
      _metrics.toolLatency[tool].totalMs += ms;
      if (!success) _metrics.toolLatency[tool].errors++;

      _metrics.errorRate.total++;
      if (!success) _metrics.errorRate.errors++;
    };

    /**
     * Get performance metrics summary
     */
    const getMetrics = () => {
      const avgLLMLatency = _metrics.llmLatency.length > 0
        ? _metrics.llmLatency.reduce((sum, l) => sum + l.ms, 0) / _metrics.llmLatency.length
        : 0;

      const toolMetrics = {};
      for (const [tool, data] of Object.entries(_metrics.toolLatency)) {
        toolMetrics[tool] = {
          calls: data.calls,
          avgMs: data.calls > 0 ? Math.round(data.totalMs / data.calls) : 0,
          errorRate: data.calls > 0 ? (data.errors / data.calls * 100).toFixed(1) + '%' : '0%'
        };
      }

      return {
        llm: {
          avgLatencyMs: Math.round(avgLLMLatency),
          recentCalls: _metrics.llmLatency.length
        },
        tools: toolMetrics,
        errorRate: _metrics.errorRate.total > 0
          ? (_metrics.errorRate.errors / _metrics.errorRate.total * 100).toFixed(1) + '%'
          : '0%'
      };
    };

    // --- Event Subscriptions ---
    const init = () => {
      // Subscribe to relevant events
      EventBus.on('agent:history', (data) => {
        if (data.type === 'llm_response') {
          recordDecision({
            cycle: data.cycle,
            type: 'llm_response',
            outputLength: data.content?.length || 0
          });
        } else if (data.type === 'tool_result') {
          recordDecision({
            cycle: data.cycle,
            type: 'tool_call',
            tool: data.tool,
            success: !data.result?.startsWith('Error:')
          });
        }
      }, 'Observability');

      EventBus.on('vfs:write', (data) => {
        recordMutation({ type: 'write', path: data.path, source: 'tool' });
      }, 'Observability');

      EventBus.on('artifact:created', (data) => {
        recordMutation({ type: 'create', path: data.path, source: 'tool' });
      }, 'Observability');

      EventBus.on('artifact:deleted', (data) => {
        recordMutation({ type: 'delete', path: data.path, source: 'tool' });
      }, 'Observability');

      logger.info('[Observability] Initialized');
      return true;
    };

    /**
     * Reset all metrics (for new session)
     */
    const reset = () => {
      _tokenUsage.session = { input: 0, output: 0, total: 0 };
      _tokenUsage.byModel = {};
      _tokenUsage.history = [];
      _mutations.length = 0;
      _decisionTrace.length = 0;
      _metrics.llmLatency = [];
      _metrics.toolLatency = {};
      _metrics.errorRate = { total: 0, errors: 0 };

      EventBus.emit('observability:reset', {});
      logger.info('[Observability] Metrics reset');
    };

    /**
     * Get full observability dashboard data
     */
    const getDashboard = () => {
      return {
        tokens: getTokenUsage(),
        mutations: {
          recent: _mutations.slice(-20),
          total: _mutations.length
        },
        decisions: {
          recent: _decisionTrace.slice(-20),
          total: _decisionTrace.length
        },
        metrics: getMetrics()
      };
    };

    return {
      init,
      reset,
      // Token tracking
      recordTokens,
      getTokenUsage,
      estimateCost,
      // Mutation stream
      recordMutation,
      getMutations,
      // Decision trace
      recordDecision,
      getDecisionTrace,
      // Performance
      recordLLMLatency,
      recordToolLatency,
      getMetrics,
      // Dashboard
      getDashboard
    };
  }
};

export default Observability;
","/infrastructure/rate-limiter.js":"/**
 * @fileoverview Token Bucket Rate Limiter
 */

const RateLimiter = {
  metadata: {
    id: 'RateLimiter',
    version: '1.0.0',
    genesis: { introduced: 'reflection' },
    dependencies: ['Utils'],
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { logger } = deps.Utils;

    class TokenBucket {
      constructor(capacity, refillRate) {
        this.capacity = capacity;
        this.tokens = capacity;
        this.refillRate = refillRate; // tokens per second
        this.lastRefill = Date.now();
        this._pendingWait = null;  // Lock for concurrent access
      }

      _refill() {
        const now = Date.now();
        const elapsed = (now - this.lastRefill) / 1000;
        if (elapsed > 0) {
          const added = elapsed * this.refillRate;
          this.tokens = Math.min(this.capacity, this.tokens + added);
          this.lastRefill = now;
        }
      }

      async waitForToken() {
        // If already waiting, chain onto existing wait to prevent race condition
        if (this._pendingWait) {
          await this._pendingWait;
          return this.waitForToken();
        }

        this._refill();
        if (this.tokens >= 1) {
          this.tokens -= 1;
          return true;
        }

        const needed = 1 - this.tokens;
        const waitMs = (needed / this.refillRate) * 1000;
        logger.debug(`[RateLimiter] Throttling for ${Math.ceil(waitMs)}ms`);

        // Create wait promise that concurrent calls can chain onto
        this._pendingWait = new Promise(r => setTimeout(r, waitMs));
        await this._pendingWait;
        this._pendingWait = null;

        this._refill();  // Refill after wait instead of hard reset
        if (this.tokens >= 1) {
          this.tokens -= 1;
        }
        return true;
      }
    }

    const createLimiter = (tpm = 60) => new TokenBucket(10, tpm / 60);

    return { createLimiter };
  }
};

export default RateLimiter;
","/infrastructure/stream-parser.js":"/**
 * @fileoverview Stream Parser - SSE stream parsing utility
 * Extracts text content from Server-Sent Events streams.
 * Used by LLM providers (Gemini, OpenAI, Anthropic) for streaming responses.
 */

const StreamParser = {
  metadata: {
    id: 'StreamParser',
    version: '1.0.0',
    genesis: { introduced: 'reflection' },
    dependencies: [],
    async: false,
    type: 'utility'
  },

  factory: () => {
    /** Default timeout between stream chunks (30 seconds) */
    const DEFAULT_STREAM_TIMEOUT_MS = 30000;

    /**
     * Wrap a reader with timeout handling
     * Aborts if no data received within timeoutMs
     * @param {ReadableStreamDefaultReader} reader - The stream reader
     * @param {number} timeoutMs - Timeout in milliseconds
     * @param {AbortController} [abortController] - Optional controller to abort fetch
     * @returns {Object} Wrapped reader with timeout
     */
    const withStreamTimeout = (reader, timeoutMs = DEFAULT_STREAM_TIMEOUT_MS, abortController = null) => {
      let timeoutId = null;

      const resetTimeout = () => {
        if (timeoutId) clearTimeout(timeoutId);
        timeoutId = setTimeout(() => {
          if (abortController) {
            abortController.abort();
          }
          reader.cancel('Stream timeout - no data received');
        }, timeoutMs);
      };

      const clearStreamTimeout = () => {
        if (timeoutId) {
          clearTimeout(timeoutId);
          timeoutId = null;
        }
      };

      return {
        async read() {
          resetTimeout();
          try {
            const result = await reader.read();
            if (result.done) clearStreamTimeout();
            return result;
          } catch (err) {
            clearStreamTimeout();
            throw err;
          }
        },
        cancel(reason) {
          clearStreamTimeout();
          return reader.cancel(reason);
        },
        releaseLock() {
          clearStreamTimeout();
          return reader.releaseLock();
        }
      };
    };
    /**
     * Parse SSE stream and extract text using provider-specific extractor
     * @param {Response} response - Fetch response with readable body
     * @param {Function} textExtractor - (data: object) => string - extracts text from parsed JSON
     * @param {Function} onUpdate - Called with each text chunk
     * @param {Object} [options] - Optional settings
     * @param {AbortController} [options.abortController] - Controller to abort on timeout
     * @param {number} [options.timeoutMs] - Timeout between chunks (default: 30s)
     * @returns {Promise<string>} Full accumulated content
     */
    const parseSSEStream = async (response, textExtractor, onUpdate, options = {}) => {
      if (!response.body) {
        throw new Error('Response body is not readable');
      }

      const { abortController, timeoutMs = DEFAULT_STREAM_TIMEOUT_MS } = options;
      const rawReader = response.body.getReader();
      const reader = withStreamTimeout(rawReader, timeoutMs, abortController);
      const decoder = new TextDecoder();
      let buffer = '';
      let fullContent = '';

      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';

          for (const line of lines) {
            if (line.startsWith('data: ') && line !== 'data: [DONE]') {
              try {
                const data = JSON.parse(line.slice(6));
                const text = textExtractor(data);
                if (text) {
                  fullContent += text;
                  onUpdate?.(text);
                }
              } catch {
                // Skip malformed JSON chunks
              }
            }
          }
        }

        // Process any remaining buffer content
        if (buffer.startsWith('data: ') && buffer !== 'data: [DONE]') {
          try {
            const data = JSON.parse(buffer.slice(6));
            const text = textExtractor(data);
            if (text) {
              fullContent += text;
              onUpdate?.(text);
            }
          } catch {
            // Skip malformed JSON
          }
        }
      } finally {
        reader.releaseLock();
      }

      return fullContent;
    };

    /**
     * Pre-built text extractors for common LLM providers
     */
    const extractors = {
      gemini: (data) => data.candidates?.[0]?.content?.parts?.[0]?.text || '',
      openai: (data) => data.choices?.[0]?.delta?.content || '',
      anthropic: (data) => {
        if (data.type === 'content_block_delta') {
          return data.delta?.text || '';
        }
        return '';
      }
    };

    /**
     * Convenience method to parse stream for a specific provider
     * @param {Response} response - Fetch response
     * @param {string} provider - 'gemini' | 'openai' | 'anthropic'
     * @param {Function} onUpdate - Called with each text chunk
     * @param {Object} [options] - Optional settings (abortController, timeoutMs)
     * @returns {Promise<string>} Full content
     */
    const parseForProvider = async (response, provider, onUpdate, options = {}) => {
      const extractor = extractors[provider];
      if (!extractor) {
        throw new Error(`Unknown provider: ${provider}`);
      }
      return parseSSEStream(response, extractor, onUpdate, options);
    };

    /**
     * Parse OpenAI stream with tool call support
     * OpenAI streams tool_calls in chunks with index-based accumulation
     * @param {Response} response - Fetch response
     * @param {Function} onUpdate - Called with each text chunk
     * @param {Object} [options] - Optional settings
     * @returns {Promise<{content: string, toolCalls: Array|null}>} Content and tool calls
     */
    const parseOpenAIStreamWithTools = async (response, onUpdate, options = {}) => {
      if (!response.body) {
        throw new Error('Response body is not readable');
      }

      const { abortController, timeoutMs = DEFAULT_STREAM_TIMEOUT_MS } = options;
      const rawReader = response.body.getReader();
      const reader = withStreamTimeout(rawReader, timeoutMs, abortController);
      const decoder = new TextDecoder();
      let buffer = '';
      let fullContent = '';

      // Accumulate tool calls by index
      const toolCallsMap = new Map(); // index -> { id, name, arguments }

      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';

          for (const line of lines) {
            if (line.startsWith('data: ') && line !== 'data: [DONE]') {
              try {
                const data = JSON.parse(line.slice(6));
                const delta = data.choices?.[0]?.delta;

                // Handle text content
                if (delta?.content) {
                  fullContent += delta.content;
                  onUpdate?.(delta.content);
                }

                // Handle tool calls (accumulate by index)
                if (delta?.tool_calls) {
                  for (const tc of delta.tool_calls) {
                    const idx = tc.index ?? 0;
                    if (!toolCallsMap.has(idx)) {
                      toolCallsMap.set(idx, { id: '', name: '', arguments: '' });
                    }
                    const entry = toolCallsMap.get(idx);
                    if (tc.id) entry.id = tc.id;
                    if (tc.function?.name) entry.name = tc.function.name;
                    if (tc.function?.arguments) entry.arguments += tc.function.arguments;
                  }
                }
              } catch {
                // Skip malformed JSON chunks
              }
            }
          }
        }
      } finally {
        reader.releaseLock();
      }

      // Convert tool calls map to array
      let toolCalls = null;
      if (toolCallsMap.size > 0) {
        toolCalls = [];
        for (const [, entry] of toolCallsMap) {
          if (entry.name) {
            let args = {};
            try {
              args = JSON.parse(entry.arguments || '{}');
            } catch {
              // Invalid JSON in arguments
            }
            toolCalls.push({
              id: entry.id,
              name: entry.name,
              args
            });
          }
        }
      }

      return { content: fullContent, toolCalls };
    };

    /**
     * Parse Anthropic stream with tool call support
     * Anthropic uses content_block events with type='tool_use'
     * @param {Response} response - Fetch response
     * @param {Function} onUpdate - Called with each text chunk
     * @param {Object} [options] - Optional settings
     * @returns {Promise<{content: string, toolCalls: Array|null}>}
     */
    const parseAnthropicStreamWithTools = async (response, onUpdate, options = {}) => {
      if (!response.body) {
        throw new Error('Response body is not readable');
      }

      const { abortController, timeoutMs = DEFAULT_STREAM_TIMEOUT_MS } = options;
      const rawReader = response.body.getReader();
      const reader = withStreamTimeout(rawReader, timeoutMs, abortController);
      const decoder = new TextDecoder();
      let buffer = '';
      let fullContent = '';
      const toolCalls = [];
      let currentToolUse = null;

      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';

          for (const line of lines) {
            if (line.startsWith('data: ')) {
              try {
                const data = JSON.parse(line.slice(6));

                // Handle text content
                if (data.type === 'content_block_delta' && data.delta?.type === 'text_delta') {
                  const text = data.delta.text || '';
                  if (text) {
                    fullContent += text;
                    onUpdate?.(text);
                  }
                }

                // Handle tool use start
                if (data.type === 'content_block_start' && data.content_block?.type === 'tool_use') {
                  currentToolUse = {
                    id: data.content_block.id,
                    name: data.content_block.name,
                    arguments: ''
                  };
                }

                // Handle tool use input delta
                if (data.type === 'content_block_delta' && data.delta?.type === 'input_json_delta') {
                  if (currentToolUse) {
                    currentToolUse.arguments += data.delta.partial_json || '';
                  }
                }

                // Handle tool use end
                if (data.type === 'content_block_stop' && currentToolUse) {
                  let args = {};
                  try {
                    args = JSON.parse(currentToolUse.arguments || '{}');
                  } catch { /* Invalid JSON */ }
                  toolCalls.push({
                    id: currentToolUse.id,
                    name: currentToolUse.name,
                    args
                  });
                  currentToolUse = null;
                }
              } catch {
                // Skip malformed JSON chunks
              }
            }
          }
        }
      } finally {
        reader.releaseLock();
      }

      return { content: fullContent, toolCalls: toolCalls.length > 0 ? toolCalls : null };
    };

    /**
     * Parse Gemini stream with tool call support
     * Gemini uses functionCall in candidates
     * @param {Response} response - Fetch response
     * @param {Function} onUpdate - Called with each text chunk
     * @param {Object} [options] - Optional settings
     * @returns {Promise<{content: string, toolCalls: Array|null}>}
     */
    const parseGeminiStreamWithTools = async (response, onUpdate, options = {}) => {
      if (!response.body) {
        throw new Error('Response body is not readable');
      }

      const { abortController, timeoutMs = DEFAULT_STREAM_TIMEOUT_MS } = options;
      const rawReader = response.body.getReader();
      const reader = withStreamTimeout(rawReader, timeoutMs, abortController);
      const decoder = new TextDecoder();
      let buffer = '';
      let fullContent = '';
      const toolCalls = [];

      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';

          for (const line of lines) {
            if (line.startsWith('data: ') && line !== 'data: [DONE]') {
              try {
                const data = JSON.parse(line.slice(6));
                const candidate = data.candidates?.[0];

                // Handle text content
                const text = candidate?.content?.parts?.[0]?.text || '';
                if (text) {
                  fullContent += text;
                  onUpdate?.(text);
                }

                // Handle function calls
                const functionCall = candidate?.content?.parts?.[0]?.functionCall;
                if (functionCall) {
                  toolCalls.push({
                    id: `gemini_${Date.now()}_${toolCalls.length}`,
                    name: functionCall.name,
                    args: functionCall.args || {}
                  });
                }
              } catch {
                // Skip malformed JSON chunks
              }
            }
          }
        }
      } finally {
        reader.releaseLock();
      }

      return { content: fullContent, toolCalls: toolCalls.length > 0 ? toolCalls : null };
    };

    return {
      parseSSEStream,
      parseForProvider,
      parseOpenAIStreamWithTools,
      parseAnthropicStreamWithTools,
      parseGeminiStreamWithTools,
      extractors,
      withStreamTimeout,
      DEFAULT_STREAM_TIMEOUT_MS
    };
  }
};

export default StreamParser;
","/infrastructure/telemetry-timeline.js":"/**
 * @fileoverview Telemetry Timeline
 * Unified append-only event log for audit, performance, and agent state changes.
 */

const TelemetryTimeline = {
  metadata: {
    id: 'TelemetryTimeline',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'VFS', 'EventBus?'],
    async: true,
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { Utils, VFS, EventBus } = deps;
    const { logger, generateId } = Utils;

    const LOG_DIR = '/.logs/timeline';
    const MAX_RECENT = 500;
    const _recent = [];

    const _appendEntry = async (entry) => {
      const date = new Date(entry.ts).toISOString().split('T')[0];
      const path = `${LOG_DIR}/${date}.jsonl`;
      let content = '';

      try {
        if (await VFS.exists(path)) {
          content = await VFS.read(path);
        }
      } catch (err) {
        logger.warn('[Telemetry] Failed to read timeline file', { path, error: err.message });
      }

      try {
        await VFS.write(path, content + JSON.stringify(entry) + '\n');
      } catch (err) {
        logger.error('[Telemetry] Failed to write timeline entry', { error: err.message });
      }
    };

    const _loadRecent = async () => {
      const today = new Date().toISOString().split('T')[0];
      const path = `${LOG_DIR}/${today}.jsonl`;

      try {
        if (await VFS.exists(path)) {
          const content = await VFS.read(path);
          const lines = content.split('\n').filter(Boolean);
          const start = Math.max(0, lines.length - MAX_RECENT);
          for (let i = start; i < lines.length; i++) {
            try {
              _recent.push(JSON.parse(lines[i]));
            } catch {
              // skip malformed line
            }
          }
        }
      } catch (err) {
        logger.warn('[Telemetry] Failed to load recent timeline entries', err.message);
      }
    };

    const record = async (type, payload = {}, options = {}) => {
      const entry = {
        id: generateId('evt'),
        ts: Date.now(),
        type,
        severity: options.severity || 'info',
        tags: options.tags || [],
        payload
      };
      _recent.push(entry);
      if (_recent.length > MAX_RECENT) _recent.shift();

      await _appendEntry(entry);
      if (EventBus) {
        EventBus.emit('telemetry:event', entry);
      }
      return entry.id;
    };

    const getRecent = (limit = 100) => {
      if (limit <= 0) return [];
      const start = Math.max(0, _recent.length - limit);
      return _recent.slice(start);
    };

    const getEntries = async (startDate, endDate = startDate) => {
      if (!startDate) throw new Error('startDate required');
      let start = new Date(startDate);
      let end = new Date(endDate || startDate);
      const entries = [];

      // Guard against infinite loop if dates are inverted
      if (start > end) {
        logger.warn('[Telemetry] startDate > endDate, swapping');
        [start, end] = [end, start];
      }

      // Use separate loop variable to avoid mutating comparison target
      const current = new Date(start);
      while (current <= end) {
        const dateStr = current.toISOString().split('T')[0];
        const path = `${LOG_DIR}/${dateStr}.jsonl`;
        try {
          if (await VFS.exists(path)) {
            const content = await VFS.read(path);
            for (const line of content.split('\n').filter(Boolean)) {
              try { entries.push(JSON.parse(line)); } catch { /* ignore */ }
            }
          }
        } catch (err) {
          logger.warn('[Telemetry] Failed to read timeline entries', { path, error: err.message });
        }
        current.setDate(current.getDate() + 1);
      }

      return entries;
    };

    const _wireEventBus = () => {
      if (!EventBus) return;
      const safeRecord = (type, payload, options) => {
        record(type, payload, options).catch((err) => {
          logger.warn('[Telemetry] Failed to record event', { type, error: err?.message || err });
        });
      };

      EventBus.on('agent:status', (data = {}) => safeRecord('agent:status', data, { tags: ['agent'] }));
      EventBus.on('agent:warning', (data = {}) => safeRecord('agent:warning', data, { severity: 'warn', tags: ['agent'] }));
      EventBus.on('tool:slow', (data = {}) => safeRecord('tool:slow', data, { severity: 'warn', tags: ['tool'] }));
      EventBus.on('tool:timeout', (data = {}) => safeRecord('tool:timeout', data, { severity: 'error', tags: ['tool'] }));
      EventBus.on('tool:error', (data = {}) => safeRecord('tool:error', data, { severity: 'error', tags: ['tool'] }));
      EventBus.on('tool:circuit_skip', (data = {}) => safeRecord('tool:circuit_skip', data, { severity: 'warn', tags: ['tool'] }));
    };

    return {
      init: async () => {
        await _loadRecent();
        _wireEventBus();
        logger.info('[Telemetry] Timeline initialized');
        return true;
      },
      record,
      getRecent,
      getEntries
    };
  }
};

export default TelemetryTimeline;
","/infrastructure/tool-executor.js":"/**
 * @fileoverview Tool Executor - Shared tool execution with retry, timeout, and batching
 * Used by AgentLoop and WorkerManager for consistent tool execution behavior.
 */

const ToolExecutor = {
  metadata: {
    id: 'ToolExecutor',
    version: '1.0.0',
    genesis: { introduced: 'reflection' },
    dependencies: ['Utils', 'ToolRunner', 'EventBus?'],
    async: false,
    type: 'utility'
  },

  factory: (deps) => {
    const { Utils, ToolRunner, EventBus } = deps;
    const { logger } = Utils;

    // Default configuration
    const DEFAULT_TIMEOUT_MS = 30000;  // 30s per tool
    const DEFAULT_MAX_RETRIES = 2;
    const DEFAULT_RETRY_DELAY_MS = 100;

    /**
     * Execute a single tool with timeout
     * @param {string} name - Tool name
     * @param {Object} args - Tool arguments
     * @param {Object} [options] - Execution options
     * @param {number} [options.timeoutMs] - Timeout in ms
     * @returns {Promise<any>} Tool result
     */
    const executeWithTimeout = async (name, args, options = {}) => {
      const { timeoutMs = DEFAULT_TIMEOUT_MS } = options;

      let timeoutId;
      const timeoutPromise = new Promise((_, reject) => {
        timeoutId = setTimeout(() => reject(new Error(`Tool timeout after ${timeoutMs}ms`)), timeoutMs);
      });

      try {
        const result = await Promise.race([
          ToolRunner.execute(name, args, options),
          timeoutPromise
        ]);
        return result;
      } finally {
        clearTimeout(timeoutId);  // Always clear timeout to prevent memory leak
      }
    };

    /**
     * Execute a tool with retry logic and timeout
     * @param {Object} call - Tool call { name, args }
     * @param {Object} [options] - Execution options
     * @param {number} [options.timeoutMs] - Timeout per attempt
     * @param {number} [options.maxRetries] - Max retry attempts
     * @param {number} [options.retryDelayMs] - Base delay between retries
     * @param {number} [options.iteration] - Current agent iteration (for events)
     * @param {string} [options.workerId] - Worker ID (for worker context)
     * @param {string[]|'*'} [options.allowedTools] - Allowed tools filter
     * @returns {Promise<{result: string, error: Error|null, duration: number}>}
     */
    const executeWithRetry = async (call, options = {}) => {
      const {
        timeoutMs = DEFAULT_TIMEOUT_MS,
        maxRetries = DEFAULT_MAX_RETRIES,
        retryDelayMs = DEFAULT_RETRY_DELAY_MS,
        iteration = 0,
        workerId = null,
        allowedTools = '*'
      } = options;

      let result = null;
      let lastError = null;
      const startTime = Date.now();

      for (let attempt = 0; attempt <= maxRetries; attempt++) {
        try {
          const toolStartTime = Date.now();
          const rawResult = await executeWithTimeout(call.name, call.args, {
            timeoutMs,
            workerId,
            allowedTools
          });
          const toolDuration = Date.now() - toolStartTime;

          // Warn on slow tools
          if (toolDuration > timeoutMs * 0.7) {
            logger.warn(`[ToolExecutor] Slow tool: ${call.name} took ${toolDuration}ms`);
            if (EventBus) {
              EventBus.emit('tool:slow', { tool: call.name, ms: toolDuration, cycle: iteration, workerId });
            }
          }

          // Stringify result
          result = typeof rawResult === 'string' ? rawResult : JSON.stringify(rawResult, null, 2);
          if (result === 'undefined' || result === undefined) {
            result = '(Tool returned no output)';
          }
          lastError = null;
          break;
        } catch (err) {
          lastError = err;
          const isTimeout = err.message?.includes('timeout');

          if (isTimeout) {
            logger.error(`[ToolExecutor] Tool ${call.name} TIMEOUT - exceeded ${timeoutMs}ms`);
            result = `Error: Tool execution timed out after ${timeoutMs / 1000}s. The operation may still be running.`;
            if (EventBus) {
              EventBus.emit('tool:timeout', { tool: call.name, timeout: timeoutMs, cycle: iteration, workerId });
            }
            break;
          }

          if (attempt < maxRetries) {
            logger.warn(`[ToolExecutor] Tool ${call.name} failed (attempt ${attempt + 1}/${maxRetries + 1}), retrying...`);
            await new Promise(r => setTimeout(r, retryDelayMs * (attempt + 1)));
          }
        }
      }

      return {
        result,
        error: lastError,
        duration: Date.now() - startTime
      };
    };

    /**
     * Execute multiple tools in parallel
     * @param {Object[]} calls - Array of { name, args } tool calls
     * @param {Object} [options] - Execution options (same as executeWithRetry)
     * @returns {Promise<Array<{call: Object, result: string, error: Error|null, duration: number}>>}
     */
    const executeBatch = async (calls, options = {}) => {
      const results = await Promise.all(
        calls.map(async (call) => {
          const { result, error, duration } = await executeWithRetry(call, options);
          return { call, result, error, duration };
        })
      );
      return results;
    };

    /**
     * Execute tools with readOnly/mutating split
     * ReadOnly tools run in parallel, mutating tools run sequentially after
     * @param {Object[]} calls - Tool calls
     * @param {Set<string>} readOnlyTools - Set of tool names that are read-only
     * @param {Object} [options] - Execution options
     * @returns {Promise<{results: Array, readOnlyResults: Array, mutatingResults: Array, telemetry: string[]}>}
     */
    const executeWithParallelization = async (calls, readOnlyTools, options = {}) => {
      const readOnlyCalls = calls.filter(c => readOnlyTools.has(c.name));
      const mutatingCalls = calls.filter(c => !readOnlyTools.has(c.name));

      const telemetry = [];
      const results = [];

      // Execute read-only tools in parallel
      if (readOnlyCalls.length > 0) {
        const batchResults = await executeBatch(readOnlyCalls, options);
        results.push(...batchResults);
        if (readOnlyCalls.length > 1) {
          telemetry.push(`${readOnlyCalls.length} read-only tools in parallel`);
        }
      }

      // Execute mutating tools sequentially
      for (const call of mutatingCalls) {
        const { result, error, duration } = await executeWithRetry(call, options);
        results.push({ call, result, error, duration });
      }

      if (mutatingCalls.length > 0) {
        telemetry.push(`${mutatingCalls.length} mutating tool${mutatingCalls.length > 1 ? 's' : ''} sequential`);
      }

      return {
        results,
        readOnlyResults: results.filter(r => readOnlyTools.has(r.call.name)),
        mutatingResults: results.filter(r => !readOnlyTools.has(r.call.name)),
        telemetry
      };
    };

    /**
     * Format tool result for context message
     * @param {string} toolName - Tool name
     * @param {string} result - Tool result
     * @param {Error|null} error - Error if any
     * @returns {string} Formatted message
     */
    const formatResultForContext = (toolName, result, error) => {
      if (error) {
        return `Error executing ${toolName}: ${error.message}`;
      }
      return `Result of ${toolName}:\n${result}`;
    };

    return {
      executeWithTimeout,
      executeWithRetry,
      executeBatch,
      executeWithParallelization,
      formatResultForContext,
      DEFAULT_TIMEOUT_MS,
      DEFAULT_MAX_RETRIES
    };
  }
};

export default ToolExecutor;
","/infrastructure/vfs-hmr.js":"/**
 * @fileoverview VFS Hot Module Replacement
 * Enables live reloading of modules when agent modifies code in VFS.
 * Works in conjunction with Service Worker to serve updated modules.
 */

const VFSHMR = {
  metadata: {
    id: 'VFSHMR',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'EventBus', 'VFS'],
    async: true,
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { Utils, EventBus, VFS } = deps;
    const { logger } = Utils;

    let _isEnabled = true;
    let _moduleCache = new Map(); // path -> module reference
    let _dependencyGraph = new Map(); // path -> Set of dependent paths
    let _reloadCallbacks = new Map(); // path -> callback

    const init = async () => {
      logger.info('[VFS-HMR] Initializing Hot Module Replacement...');

      // Listen for VFS file changes
      EventBus.on('vfs:file_changed', handleFileChange);

      // Check if Service Worker is active
      if ('serviceWorker' in navigator && navigator.serviceWorker.controller) {
        logger.info('[VFS-HMR] Service Worker active, HMR enabled');
      } else {
        logger.warn('[VFS-HMR] Service Worker not active, HMR disabled');
        _isEnabled = false;
      }

      return true;
    };

    /**
     * Handle VFS file changes
     */
    const handleFileChange = async (event) => {
      if (!_isEnabled) return;

      const { path, operation } = event;

      // Only handle JavaScript modules
      if (!path.endsWith('.js')) return;

      logger.info(`[VFS-HMR] File changed: ${path} (${operation})`);

      try {
        if (operation === 'write' || operation === 'update') {
          await reloadModule(path);
        } else if (operation === 'delete') {
          await unloadModule(path);
        }
      } catch (error) {
        logger.error(`[VFS-HMR] Failed to reload ${path}:`, error);
        EventBus.emit('hmr:error', { path, error: error.message });
      }
    };

    /**
     * Reload a module and all its dependents
     */
    const reloadModule = async (path) => {
      logger.info(`[VFS-HMR] Reloading module: ${path}`);

      // Invalidate Service Worker cache for this module
      await invalidateServiceWorkerCache(path);

      // Get all dependent modules
      const dependents = _dependencyGraph.get(path) || new Set();

      // Execute reload callback if registered
      const callback = _reloadCallbacks.get(path);
      if (callback) {
        try {
          await callback();
          logger.info(`[VFS-HMR] Executed reload callback for ${path}`);
        } catch (error) {
          logger.error(`[VFS-HMR] Reload callback failed for ${path}:`, error);
        }
      }

      // Re-import the module with cache busting
      try {
        const timestamp = Date.now();
        const moduleUrl = path + '?hmr=' + timestamp;

        // Dynamic import with cache busting
        const newModule = await import(moduleUrl);

        // Store in cache
        _moduleCache.set(path, newModule);

        EventBus.emit('hmr:module_reloaded', { path, timestamp });
        logger.info(`[VFS-HMR] Module reloaded: ${path}`);

        // Reload dependents recursively
        for (const dependentPath of dependents) {
          logger.info(`[VFS-HMR] Reloading dependent: ${dependentPath}`);
          await reloadModule(dependentPath);
        }
      } catch (error) {
        logger.error(`[VFS-HMR] Failed to import ${path}:`, error);
        throw error;
      }
    };

    /**
     * Unload a module
     */
    const unloadModule = async (path) => {
      logger.info(`[VFS-HMR] Unloading module: ${path}`);

      _moduleCache.delete(path);
      _reloadCallbacks.delete(path);
      _dependencyGraph.delete(path);

      await invalidateServiceWorkerCache(path);

      EventBus.emit('hmr:module_unloaded', { path });
    };

    /**
     * Invalidate Service Worker cache for a module
     */
    const invalidateServiceWorkerCache = async (path) => {
      if (!navigator.serviceWorker.controller) return;

      try {
        // Send message to Service Worker to invalidate cache
        const messageChannel = new MessageChannel();

        const response = await new Promise((resolve, reject) => {
          messageChannel.port1.onmessage = (event) => {
            if (event.data.success) {
              resolve(event.data);
            } else {
              reject(new Error('Cache invalidation failed'));
            }
          };

          navigator.serviceWorker.controller.postMessage({
            type: 'INVALIDATE_MODULE',
            data: { path }
          }, [messageChannel.port2]);

          // Timeout after 1 second
          setTimeout(() => reject(new Error('Timeout')), 1000);
        });

        logger.debug(`[VFS-HMR] Cache invalidated for ${path}`);
      } catch (error) {
        logger.warn(`[VFS-HMR] Failed to invalidate SW cache for ${path}:`, error.message);
      }
    };

    /**
     * Register a reload callback for a module
     * Useful for modules that need custom cleanup/reinitialization
     */
    const onReload = (path, callback) => {
      _reloadCallbacks.set(path, callback);
      logger.debug(`[VFS-HMR] Registered reload callback for ${path}`);
    };

    /**
     * Register module dependency
     * @param {string} modulePath - The module that imports
     * @param {string} dependencyPath - The module being imported
     */
    const registerDependency = (modulePath, dependencyPath) => {
      if (!_dependencyGraph.has(dependencyPath)) {
        _dependencyGraph.set(dependencyPath, new Set());
      }
      _dependencyGraph.get(dependencyPath).add(modulePath);

      logger.debug(`[VFS-HMR] Registered dependency: ${dependencyPath} -> ${modulePath}`);
    };

    /**
     * Clear all HMR state
     */
    const clear = () => {
      _moduleCache.clear();
      _dependencyGraph.clear();
      _reloadCallbacks.clear();
      logger.info('[VFS-HMR] Cache cleared');
    };

    /**
     * Get HMR statistics
     */
    const getStats = () => {
      return {
        enabled: _isEnabled,
        cachedModules: _moduleCache.size,
        dependencies: _dependencyGraph.size,
        callbacks: _reloadCallbacks.size,
        serviceWorkerActive: navigator.serviceWorker?.controller ? true : false
      };
    };

    /**
     * Enable/disable HMR
     */
    const setEnabled = (enabled) => {
      _isEnabled = enabled;
      logger.info(`[VFS-HMR] ${enabled ? 'Enabled' : 'Disabled'}`);
    };

    /**
     * Force reload all modules
     */
    const reloadAll = async () => {
      logger.info('[VFS-HMR] Reloading all modules...');

      const paths = Array.from(_moduleCache.keys());

      for (const path of paths) {
        try {
          await reloadModule(path);
        } catch (error) {
          logger.error(`[VFS-HMR] Failed to reload ${path}:`, error);
        }
      }

      logger.info(`[VFS-HMR] Reloaded ${paths.length} modules`);
    };

    return {
      init,
      onReload,
      registerDependency,
      reloadModule,
      reloadAll,
      clear,
      getStats,
      setEnabled
    };
  }
};

export default VFSHMR;
","/styles/proto/components.css":"/* Proto Components - Cards, badges, modals, diff viewer, buttons */

/* Button variants */
.btn-small {
