}

.modal-content {
    background: var(--bg-panel);
    border: 2px solid var(--primary-dim);
    border-radius: var(--radius-lg);
    min-width: 360px;
    max-width: 560px;
    max-height: 80vh;
    overflow: auto;
    box-shadow: var(--shadow-lg);
