    background: var(--success-dim);
    color: var(--bg-app);
}

.diff-operation.modify {
    background: var(--warning-dim);
    color: var(--bg-app);
}

.diff-operation.delete {
    background: var(--danger-dim);
    color: var(--bg-app);
}

.diff-file-actions {
    display: flex;
    gap: var(--space-sm);
    align-items: center;
    flex-wrap: wrap;
}

.side-by-side-diff {
    display: flex;
    gap: 2px;
}

.diff-pane {
    flex: 1;
    overflow-x: auto;
}

.diff-line {
    display: flex;
    min-height: 20px;
}

.diff-line.added {
    background: rgba(16, 185, 129, 0.15);
}

.diff-line.removed {
    background: rgba(239, 68, 68, 0.15);
}

.diff-line.changed {
    background: rgba(245, 158, 11, 0.15);
}

.line-number {
    width: 40px;
    color: var(--text-muted);
    text-align: right;
    padding-right: var(--space-sm);
    user-select: none;
}

.code-block {
    background: var(--bg-panel);
    padding: var(--space-md);
    overflow-x: auto;
    border-radius: var(--radius-md);
    font-size: var(--font-xs);
}

/* Genesis diff color coding */
.diff-added {
    background: rgba(173, 252, 65, 0.1);
    border-left: 3px solid #adfc41;
}

.diff-deleted {
    background: rgba(127, 127, 127, 0.1);
    border-left: 3px solid #7f7f7f;
    text-decoration: line-through;
}

.diff-modified {
    background: rgba(173, 252, 65, 0.05);
    border-left: 3px solid #adfc41;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

::-webkit-scrollbar-track {
    background: var(--scrollbar-bg);
}

::-webkit-scrollbar-thumb {
    background: var(--scrollbar-thumb);
    border-radius: var(--radius-md);
}

::-webkit-scrollbar-thumb:hover {
    background: var(--scrollbar-thumb-hover);
}

/* Legacy - deprecated */
.utility-panel {
    display: none;
}

.utility-header {
    display: none;
}
","/styles/proto/history.css":"/* Proto History - History stream, reflections, arena results */

/* History/Reflections Streams */
.history-stream, .reflections-stream {
    font-size: var(--font-xs);
    line-height: 1.6;
    flex: 1;
    min-height: 0;
    overflow-y: auto;
}

.history-stream {
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
}

.reflections-stream {
    display: flex;
    flex-direction: column;
    gap: var(--space-xs);
}

/* History Entries */
.history-entry {
    margin-bottom: var(--space-md);
    border: 1px solid var(--border-secondary);
    border-radius: var(--radius-sm);
    overflow: hidden;
}

.history-header {
    background: var(--bg-tertiary);
    padding: var(--space-sm) var(--space-md);
    font-size: var(--font-sm);
    font-weight: 600;
    color: var(--primary);
    border-bottom: 1px solid var(--border-secondary);
}

.history-content {
    margin: 0;
    padding: var(--space-md);
    font-size: var(--font-xs);
    overflow-x: auto;
    white-space: pre-wrap;
    word-break: break-word;
    max-height: 300px;
    overflow-y: auto;
}

/* Streaming animation */
.history-entry.streaming .history-header {
    color: var(--warning);
}

.history-entry.streaming .history-header::after {
    content: '';
    animation: pulse 1s ease-in-out infinite;
}

@keyframes pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.5; }
}

/* History Actions */
.history-actions {
    margin-top: var(--space-sm);
    padding-top: var(--space-sm);
    border-top: 1px solid var(--border-subtle);
}

.history-error {
    color: var(--danger);
}

/* Error Badge */
.error-badge {
    background: var(--danger);
    color: var(--bg-app);
    font-size: var(--font-xs);
    padding: 2px 6px;
    margin-left: 8px;
    text-transform: uppercase;
    font-weight: bold;
}

/* Reflection Entries */
.reflection-entry {
    padding: var(--space-sm);
    margin-bottom: var(--space-xs);
    border-radius: var(--radius-sm);
    border-left: 3px solid transparent;
}

.reflection-success {
    background: var(--success-bg);
    border-left-color: var(--success);
}

.reflection-error {
    background: var(--error-bg);
    border-left-color: var(--error);
}

.reflection-header {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    font-size: var(--font-sm);
}

.reflection-icon {
    font-weight: bold;
}

.reflection-success .reflection-icon {
    color: var(--success);
}

.reflection-error .reflection-icon {
    color: var(--error);
}

.reflection-tool {
    color: var(--text-primary);
    font-weight: 600;
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.reflection-cycle {
    color: var(--text-muted);
    font-size: var(--font-xs);
}

.reflection-detail {
    margin-top: var(--space-xs);
    font-size: var(--font-xs);
    color: var(--text-secondary);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* Arena Results */
.arena-result {
    border-left: 3px solid var(--primary);
}

.arena-header {
    background: var(--bg-tertiary);
    color: var(--primary);
}

.arena-solutions {
    padding: var(--space-md);
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
}

.arena-solution {
    padding: var(--space-sm);
    border: 1px solid var(--border-secondary);
    border-radius: var(--radius-sm);
    background: var(--bg-secondary);
}

.arena-solution.arena-winner {
    border-color: var(--primary);
    background: rgba(173, 252, 65, 0.05);
}

.arena-solution-header {
    font-size: var(--font-sm);
    color: var(--text-primary);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.winner-badge {
    display: inline-block;
    padding: 2px 6px;
    background: var(--primary);
    color: var(--bg-primary);
    font-size: var(--font-xs);
    font-weight: 700;
    border-radius: 3px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

/* Log Container */
.log-container {
    height: calc(100% - 30px);
    overflow-y: auto;
    font-family: monospace;
    font-size: var(--font-sm);
    background: var(--bg-tertiary);
    padding: var(--space-md);
    border-radius: var(--radius-md);
}

.log-entry {
    padding: var(--space-xs) 0;
    border-bottom: 1px solid var(--border-secondary);
}

.log-info { color: var(--text-primary); }
.log-warn { color: var(--warning); }
.log-error { color: var(--error); }
.log-debug { color: var(--text-muted); }

/* Agent Status */
#agent-status-container {
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
    margin-bottom: var(--space-md);
}
","/styles/proto/hitl.css":"/* HITL Widget - Human-in-the-loop approval UI */

.hitl-widget {
  background: rgba(0, 0, 0, 0.3);
  border-radius: 8px;
  padding: 12px;
  font-size: var(--font-xs);
}

.hitl-widget.hitl-active {
  border-left: 3px solid var(--warning, #ffa500);
}

.hitl-widget.hitl-auto {
  border-left: 3px solid var(--success, #66bb6a);
}

.hitl-widget.hitl-every-n {
  border-left: 3px solid var(--info, #42a5f5);
}

.hitl-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.hitl-icon {
  font-size: 16px;
}

.hitl-title {
  flex: 1;
  font-weight: 500;
}

.hitl-toggle {
  background: rgba(255, 255, 255, 0.1);
  border: none;
  padding: 4px 8px;
  border-radius: 4px;
  cursor: pointer;
  font-size: var(--font-xs);
  color: var(--text-primary, #fff);
}

.hitl-toggle:hover {
  background: rgba(255, 255, 255, 0.2);
}

.hitl-mode-select {
  flex: 1;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  padding: 4px 8px;
  border-radius: 4px;
  color: var(--text-primary, #fff);
  font-size: var(--font-xs);
  cursor: pointer;
}

.hitl-mode-select:hover {
  background: rgba(255, 255, 255, 0.15);
}

.hitl-config {
  margin: 8px 0;
  background: rgba(66, 165, 245, 0.1);
  border-radius: 4px;
  padding: 8px;
}

.hitl-config-label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: var(--font-xs);
}

.hitl-steps-input {
  width: 50px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  padding: 2px 6px;
  border-radius: 3px;
  color: var(--text-primary, #fff);
  font-size: var(--font-xs);
}

.hitl-step-counter {
  color: var(--text-muted, rgba(255, 255, 255, 0.5));
  font-size: var(--font-xs);
}

.hitl-queue {
  margin: 8px 0;
  background: rgba(255, 165, 0, 0.1);
  border-radius: 4px;
  padding: 8px;
}

.hitl-queue-header {
  font-weight: 500;
  margin-bottom: 8px;
  color: var(--warning, #ffa500);
}

.hitl-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.hitl-item:last-child {
  border-bottom: none;
}

.hitl-item-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.hitl-item-module {
  font-weight: 500;
  font-size: var(--font-xs);
}

.hitl-item-action {
  color: var(--text-secondary, rgba(255, 255, 255, 0.6));
  font-size: var(--font-xs);
}

.hitl-item-actions {
  display: flex;
  gap: 4px;
}

.hitl-approve,
.hitl-reject {
  width: 24px;
  height: 24px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: var(--font-xs);
}

.hitl-approve {
  background: rgba(102, 187, 106, 0.2);
  color: var(--success, #66bb6a);
}

.hitl-approve:hover {
  background: rgba(102, 187, 106, 0.4);
}

.hitl-reject {
  background: rgba(244, 135, 113, 0.2);
  color: var(--danger, #f48771);
}

.hitl-reject:hover {
  background: rgba(244, 135, 113, 0.4);
}

.hitl-more {
  text-align: center;
  color: var(--text-muted, rgba(255, 255, 255, 0.5));
  font-size: var(--font-xs);
  padding-top: 4px;
}

.hitl-stats {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.hitl-stat {
  padding: 2px 8px;
  border-radius: 10px;
  font-size: var(--font-xs);
}

.hitl-stat.approved {
  background: rgba(102, 187, 106, 0.2);
  color: var(--success, #66bb6a);
}

.hitl-stat.rejected {
  background: rgba(244, 135, 113, 0.2);
  color: var(--danger, #f48771);
}

.hitl-stat.auto {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text-secondary, rgba(255, 255, 255, 0.6));
}

.hitl-disabled {
  color: var(--text-muted, rgba(255, 255, 255, 0.4));
  text-align: center;
  padding: 20px;
}

/* Mobile responsive styles for HITL widget */
@media (max-width: 768px) {
  .hitl-widget {
    padding: 10px;
  }

  .hitl-header {
    flex-wrap: wrap;
    gap: 6px;
  }

  .hitl-item {
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
  }

  .hitl-item-actions {
    width: 100%;
    justify-content: flex-end;
  }

  .hitl-stats {
    flex-wrap: wrap;
    gap: 8px;
  }
}

@media (max-width: 480px) {
  .hitl-widget {
    padding: 8px;
    font-size: 11px;
  }

  .hitl-icon {
    font-size: 14px;
  }

  .hitl-title {
    font-size: 12px;
  }

  .hitl-mode-select {
    padding: 6px;
    font-size: 11px;
  }

  .hitl-approve,
  .hitl-reject {
    width: 32px;
    height: 32px;
  }

  .hitl-stat {
    font-size: 10px;
    padding: 2px 6px;
  }

  .hitl-config {
    padding: 6px;
  }

  .hitl-queue {
    padding: 6px;
  }
}

/* Touch optimization for HITL */
@media (pointer: coarse) {
  .hitl-approve,
  .hitl-reject {
    min-width: 44px;
    min-height: 44px;
  }

  .hitl-toggle {
    min-height: 36px;
    padding: 6px 12px;
  }

  .hitl-mode-select {
    min-height: 40px;
  }
}
