","/styles/proto/inline-chat.css":"/* Inline Chat - Human-in-the-loop message input */

.inline-chat {
  background: rgba(0, 0, 0, 0.4);
  border-top: 1px solid var(--primary-dim, rgba(173, 252, 65, 0.2));
  padding: 8px 12px;
}

.inline-chat-input-row {
  display: flex;
  gap: 8px;
}

.inline-chat-input {
  flex: 1;
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid var(--primary-dim, rgba(173, 252, 65, 0.3));
  border-radius: 4px;
  padding: 8px 12px;
  color: var(--text-primary, #fff);
  font-size: var(--font-sm);
  font-family: inherit;
  outline: none;
  transition: border-color 0.15s ease;
}

.inline-chat-input:focus {
  border-color: var(--primary, rgba(173, 252, 65, 0.6));
}

.inline-chat-input::placeholder {
  color: var(--text-muted, rgba(255, 255, 255, 0.3));
}

.inline-chat-send {
  background: var(--primary-dim, rgba(173, 252, 65, 0.15));
  border: 1px solid rgba(173, 252, 65, 0.4);
  color: var(--primary, #adfc41);
  padding: 8px 14px;
  border-radius: 4px;
  font-size: var(--font-sm);
  cursor: pointer;
  transition: all 0.15s ease;
  pointer-events: auto;
  user-select: none;
}

.inline-chat-send:hover {
  background: rgba(173, 252, 65, 0.25);
  border-color: rgba(173, 252, 65, 0.6);
}

.inline-chat-send:active {
  transform: scale(0.95);
}

.inline-chat-send.sent {
  background: rgba(173, 252, 65, 0.3);
  border-color: rgba(173, 252, 65, 0.6);
  color: var(--primary, #adfc41);
}

/* Human message display in history */
.history-entry.human-message {
  background: rgba(173, 252, 65, 0.1);
  border-left: 3px solid var(--primary, #adfc41);
}

.history-entry.human-message .entry-label {
  color: var(--primary, #adfc41);
}

/* Approval prompt in history */
.history-entry.approval-pending {
  background: rgba(255, 165, 0, 0.15);
  border-left: 3px solid var(--warning, #ffa500);
  padding: 12px;
}

.approval-header {
  font-weight: 600;
  color: var(--warning, #ffa500);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.approval-action {
  font-size: var(--font-xs);
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: 8px;
}

.approval-data {
  background: rgba(0, 0, 0, 0.3);
  border-radius: 4px;
  padding: 8px;
  font-size: var(--font-xs);
  max-height: 150px;
  overflow-y: auto;
  margin-bottom: 10px;
  white-space: pre-wrap;
  word-break: break-all;
}

.approval-buttons {
  display: flex;
  gap: 8px;
}

.approval-buttons button {
  flex: 1;
  padding: 8px 16px;
  border-radius: 4px;
  border: none;
  cursor: pointer;
  font-size: var(--font-xs);
  font-weight: 500;
  transition: all 0.15s ease;
}

.approval-buttons .approve-btn {
  background: rgba(102, 187, 106, 0.2);
  color: var(--success, #66bb6a);
  border: 1px solid rgba(102, 187, 106, 0.3);
}

.approval-buttons .approve-btn:hover {
  background: rgba(102, 187, 106, 0.3);
}

.approval-buttons .reject-btn {
  background: rgba(244, 135, 113, 0.2);
  color: var(--danger, #f48771);
  border: 1px solid rgba(244, 135, 113, 0.3);
}

.approval-buttons .reject-btn:hover {
  background: rgba(244, 135, 113, 0.3);
}

.approval-resolved {
  opacity: 0.5;
  pointer-events: none;
}

.approval-resolved .approval-buttons {
  display: none;
}

.approval-resolved::after {
  content: attr(data-resolution);
  display: block;
  margin-top: 8px;
  font-size: var(--font-xs);
  color: rgba(255, 255, 255, 0.5);
}

/* Mobile responsive styles for inline chat */
@media (max-width: 768px) {
  .inline-chat {
    padding: 6px 10px;
  }

  .inline-chat-input-row {
    gap: 6px;
  }

  .inline-chat-input {
    padding: 10px;
    font-size: 14px;
  }

  .inline-chat-send {
    padding: 10px 12px;
    font-size: 14px;
  }

  .approval-data {
    max-height: 100px;
    font-size: 11px;
  }

  .approval-buttons {
    flex-direction: column;
    gap: 6px;
  }

  .approval-buttons button {
    padding: 10px 16px;
  }
}

@media (max-width: 480px) {
  .inline-chat {
    padding: 6px 8px;
  }

  .inline-chat-input {
    padding: 8px 10px;
    font-size: 14px;
    min-height: 40px;
  }

  .inline-chat-send {
    padding: 8px 10px;
    font-size: 13px;
    min-width: 60px;
  }

  .history-entry.approval-pending {
    padding: 10px;
  }

  .approval-header {
    font-size: var(--font-xs);
  }

  .approval-data {
    max-height: 80px;
    padding: 6px;
  }
}

/* Touch optimization for inline chat */
@media (pointer: coarse) {
  .inline-chat-input,
  .inline-chat-send {
    min-height: 44px;
  }

  .approval-buttons button {
    min-height: 44px;
  }
}
","/styles/proto/layout.css":"/* Proto Layout - App shell, grid, sidebar, workspace */

:root {
    --bg-primary: var(--bg-app);
    --bg-secondary: var(--bg-panel);
    --bg-tertiary: var(--bg-element);
    --border-primary: var(--primary);
    --border-secondary: var(--border-subtle);
    --border-color: var(--border-subtle);
}

#app {
    display: none;
}

#app.active {
    display: block;
    width: 100%;
    height: 100vh;
    overflow: hidden;
}

.app-shell {
    display: grid;
    grid-template-columns: 50px 240px 1fr;
    height: 100vh;
    background: var(--bg-primary);
    color: var(--text-primary);
    font-family: 'Courier New', monospace;
    overflow: hidden;
}

/* Sidebar Navigation */
.sidebar {
    display: flex;
    flex-direction: column;
    background: var(--bg-secondary);
    border-right: 1px solid var(--border-default);
    padding: 8px 0;
    overflow-y: auto;
    overflow-x: hidden;
}

.sidebar-btn {
    position: relative;
    width: 100%;
    height: 40px;
    background: transparent;
    border: none;
    color: var(--text-muted);
    font-size: 16px;
    cursor: pointer;
    transition: 0.2s;
}

.sidebar-btn:hover {
    color: var(--primary);
    background: rgba(173, 252, 65, 0.1);
}

.sidebar-btn.active {
    color: var(--primary);
    background: rgba(173, 252, 65, 0.15);
    border-left: 2px solid var(--primary);
}

.sidebar-spacer {
    flex: 1;
}

/* Main Workspace */
.workspace {
    display: flex;
    flex-direction: column;
    overflow: hidden;
    min-height: 0;
    position: relative;
}

.workspace-header {
    padding: 12px 16px;
    border-bottom: 1px solid var(--border-default);
    background: var(--bg-secondary);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-shrink: 0;
}

.workspace-content {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
    min-height: 0;
}

.workspace-title {
    display: flex;
    align-items: flex-start;
    gap: var(--space-sm);
    font-size: var(--font-md);
    overflow: hidden;
    flex: 1;
    min-width: 0;
}

.workspace-title .goal-text {
    flex: 1;
    max-height: 2.8em;
    line-height: 1.4;
    overflow-y: auto;
    scrollbar-width: none;
    -ms-overflow-style: none;
}

.workspace-title .goal-text::-webkit-scrollbar {
    display: none;
}

.workspace-status {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    font-size: var(--font-md);
    color: var(--text-primary);
}

/* Proto Container (legacy) */
.proto-container {
    display: flex;
    flex-direction: column;
    width: 100%;
    height: 100vh;
    background: var(--bg-primary);
    color: var(--text-primary);
    font-family: 'Courier New', monospace;
    overflow: hidden;
}

/* Dashboard Layout */
.dashboard-header {
    padding: var(--space-lg);
    border-bottom: 1px solid var(--border-primary);
    background: var(--bg-secondary);
}

.dashboard-header h1 {
    margin: 0 0 var(--space-sm) 0;
    color: var(--primary);
    font-size: var(--font-xl);
}

.dashboard-main {
    display: flex;
    flex: 1;
    overflow: hidden;
    min-height: 0;
}

.panel {
    flex: 1;
    padding: var(--space-lg);
    overflow-y: auto;
    overflow-x: hidden;
    display: flex;
    flex-direction: column;
    min-height: 0;
}

.left-panel {
    border-right: 1px solid var(--border-secondary);
}

.right-panel {
    background: var(--bg-panel);
}

/* Controls */
.status-bar {
    font-size: var(--font-sm);
    color: var(--text-secondary);
    margin-bottom: var(--space-md);
}

.controls {
    display: flex;
    gap: var(--space-md);
    align-items: center;
}

.controls input {
    flex: 1;
    padding: var(--space-sm) var(--space-md);
    background: var(--bg-tertiary);
    border: 1px solid var(--border-primary);
    border-radius: var(--radius-md);
    color: var(--text-primary);
    font-size: var(--font-base);
    font-family: inherit;
}

.controls input:focus {
    outline: none;
    border-color: var(--primary);
}

.controls button {
    padding: var(--space-sm) var(--space-lg);
    background: var(--primary-dim);
    border: 1px solid var(--primary);
    border-radius: var(--radius-md);
    color: var(--primary);
    cursor: pointer;
    font-weight: 600;
    font-family: inherit;
    transition: all var(--transition-normal);
}

.controls button:hover:not(:disabled) {
    background: rgba(173, 252, 65, 0.3);
}

.controls button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}
","/styles/proto/panels.css":"/* Proto Panels - Telemetry, Schema, Workers, Debug, Status */

/* Telemetry Panel */
.telemetry-panel {
    display: flex;
    flex-direction: column;
    gap: 12px;
    height: 100%;
}

.telemetry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
}

.telemetry-controls {
    display: flex;
    gap: 8px;
    align-items: center;
    font-size: var(--font-xs);
}

.telemetry-controls select {
    background: var(--bg-element);
    color: var(--text-primary);
    border: 1px solid var(--border-default);
    padding: 2px 6px;
    font-family: inherit;
}

.telemetry-status {
    font-size: var(--font-xs);
}

.telemetry-list {
    flex: 1;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.telemetry-entry {
    border: 1px solid var(--border-default);
    background: var(--bg-secondary);
    padding: 12px;
    border-radius: 4px;
    font-size: var(--font-xs);
}

.telemetry-entry header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 6px;
}

.telemetry-time {
    font-size: var(--font-xs);
    color: var(--text-muted);
    margin-left: 6px;
}

.telemetry-severity {
    font-size: var(--font-xs);
    letter-spacing: 0.1em;
}

.telemetry-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    font-size: var(--font-xs);
    color: var(--text-muted);
    margin-bottom: 6px;
}

.telemetry-tag {
    background: rgba(173, 252, 65, 0.08);
    padding: 0 6px;
    border-radius: 3px;
}

.telemetry-entry pre {
    margin: 0;
    background: var(--bg-tertiary);
    padding: 8px;
    border-radius: 4px;
    max-height: 200px;
    overflow: auto;
}

.telemetry-entry.telemetry-warn {
    border-color: #adfc41;
}

.telemetry-entry.telemetry-error {
    border-color: #adfc41;
}

/* Schema Registry Panel */
.schema-panel {
    display: flex;
    flex-direction: column;
    gap: 16px;
    height: 100%;
}

.schema-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
}

.schema-controls {
    display: flex;
    gap: 8px;
    align-items: center;
}

.schema-search {
    width: 240px;
    padding: 6px 8px;
    background: var(--bg-element);
    color: var(--text-primary);
    border: 1px solid var(--border-default);
    font-family: inherit;
    font-size: var(--font-xs);
}

.schema-columns {
    flex: 1;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 16px;
    overflow-y: auto;
}

.schema-card {
    background: var(--bg-secondary);
    border: 1px solid var(--border-default);
    border-radius: 4px;
    padding: 12px;
    font-size: var(--font-xs);
}

.schema-card header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 8px;
}

.schema-card pre {
    margin: 0;
    background: var(--bg-tertiary);
    border-radius: 4px;
    padding: 8px;
    max-height: 200px;
    overflow: auto;
    font-size: var(--font-xs);
}

.schema-badge {
    font-size: var(--font-xs);
    border: 1px solid var(--border-default);
    padding: 1px 6px;
    border-radius: 999px;
    text-transform: uppercase;
}

.schema-worker-meta {
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
    font-size: var(--font-xs);
    margin-bottom: 6px;
}

.schema-meta-label {
    color: var(--text-muted);
    margin-right: 4px;
}

.schema-tools {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    font-size: var(--font-xs);
}

.schema-tools code {
    background: var(--bg-tertiary);
    padding: 2px 4px;
    border-radius: 3px;
}

/* Status Panel */
.status-panel {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.status-item {
    display: flex;
    justify-content: space-between;
    padding: 8px 12px;
    background: var(--bg-element);
    border: 1px solid var(--border-default);
}

.status-label {
    color: var(--text-muted);
    font-size: var(--font-xs);
}

.status-value {
    color: var(--primary);
    font-size: var(--font-xs);
}

/* Models list in Status panel */
.status-item-models {
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
}

.status-models-list {
    display: flex;
    flex-direction: column;
    gap: 4px;
    width: 100%;
}

.model-entry {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 4px 8px;
    background: var(--bg-secondary);
    border-radius: 3px;
}

.model-name {
    color: var(--primary);
    font-size: var(--font-xs);
}

.model-provider {
    font-size: var(--font-xs);
    padding: 1px 6px;
    border-radius: 2px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.model-provider-openai {
    background: rgba(16, 163, 127, 0.2);
    color: #10a37f;
}

.model-provider-anthropic {
    background: rgba(204, 149, 92, 0.2);
    color: #cc955c;
}

.model-provider-google {
    background: rgba(66, 133, 244, 0.2);
    color: #4285f4;
}

.model-provider-ollama,
.model-provider-local {
    background: rgba(173, 252, 65, 0.15);
    color: var(--primary);
}

.model-provider-unknown {
    background: rgba(127, 127, 127, 0.2);
    color: var(--text-muted);
}

/* Workers Panel */
.workers-panel {
    display: flex;
    flex-direction: column;
    gap: var(--space-lg);
}

.workers-summary {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-md);
}

.workers-summary-item {
    background: var(--bg-secondary);
    border: 1px solid var(--border-default);
    border-radius: 6px;
    padding: 8px 12px;
    min-width: 140px;
}

.workers-summary-item span {
    display: block;
    font-size: var(--font-xs);
    color: var(--text-muted);
}

.workers-summary-item strong {
    font-size: var(--font-md);
}

.workers-sections {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--space-lg);
}

@media (max-width: 1200px) {
    .workers-sections {
        grid-template-columns: 1fr;
    }
}

.workers-section {
    background: var(--bg-secondary);
    border: 1px solid var(--border-default);
    border-radius: 6px;
    padding: 12px;
}

.workers-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: var(--font-sm);
    margin-bottom: var(--space-sm);
}

.workers-list {
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
}

.worker-card {
    border: 1px solid var(--border-default);
    border-left: 3px solid var(--border-default);
    background: var(--bg-element);
    padding: 12px;
    border-radius: 4px;
    font-size: var(--font-xs);
}

.worker-card.worker-running {
    border-left-color: var(--primary);
}

.worker-card.worker-completed {
    border-left-color: var(--success, #adfc41);
}

.worker-card.worker-error {
    border-left-color: var(--danger, #adfc41);
}

.worker-card.worker-terminated {
    border-left-color: #adfc41;
}

.worker-card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 6px;
    font-size: var(--font-xs);
}

.worker-type {
    font-size: var(--font-xs);
    letter-spacing: 0.1em;
    color: var(--text-muted);
    margin-right: 8px;
}

.worker-task {
    font-family: 'Courier New', monospace;
    margin-bottom: 6px;
    white-space: pre-wrap;
}

.worker-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    color: var(--text-muted);
    margin-bottom: 4px;
}

.worker-progress {
    font-size: var(--font-xs);
    color: var(--primary);
}

.worker-log {
    margin-top: 8px;
    font-size: var(--font-xs);
}

.worker-log ul {
    list-style: none;
    padding: 0;
    margin: 4px 0 0;
    border-top: 1px solid var(--border-default);
    max-height: 140px;
    overflow-y: auto;
}

.worker-log li {
    display: flex;
    gap: 8px;
    padding: 4px 0;
    border-bottom: 1px solid var(--border-default);
}

.worker-log-time {
    color: var(--text-muted);
    width: 70px;
    flex-shrink: 0;
}

.worker-log-text {
    flex: 1;
}

.worker-output {
    margin-top: 8px;
    padding: 8px;
    border: 1px dashed var(--border-default);
    background: var(--bg-secondary);
    white-space: pre-wrap;
    max-height: 120px;
    overflow-y: auto;
}

.worker-output-error {
    color: var(--danger, #adfc41);
    border-color: var(--danger, #adfc41);
}

.worker-indicator {
    font-size: var(--font-xs);
    color: var(--text-muted);
    border: 1px solid transparent;
    border-radius: 4px;
    padding: 2px 6px;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 4px;
    transition: 0.2s;
}

.worker-indicator:hover {
    border-color: var(--primary);
    color: var(--primary);
}

.worker-indicator.has-workers {
    border-color: var(--primary);
    color: var(--primary);
    background: rgba(173, 252, 65, 0.1);
}

#worker-indicator-count {
    font-weight: bold;
}

.empty-state {
    font-size: var(--font-xs);
    color: var(--text-muted);
    padding: 12px;
    border: 1px dashed var(--border-default);
    border-radius: 4px;
    text-align: center;
}

/* Debug Panel */
.debug-panel {
    display: flex;
    flex-direction: column;
    gap: var(--space-lg);
    padding: var(--space-lg);
    height: 100%;
    overflow-y: auto;
}

.debug-section {
    background: var(--bg-secondary);
    border: 1px solid var(--border-default);
    border-radius: var(--radius-md);
    overflow: hidden;
}

.debug-section-header {
    padding: var(--space-md);
    background: var(--bg-element);
    border-bottom: 1px solid var(--border-default);
    font-size: var(--font-sm);
    font-weight: bold;
    color: var(--primary);
}

.debug-content {
    padding: var(--space-md);
    margin: 0;
    font-family: 'Courier New', monospace;
    font-size: var(--font-xs);
    line-height: 1.5;
    color: var(--text-primary);
    background: var(--bg-app);
    max-height: 400px;
    overflow-y: auto;
    white-space: pre-wrap;
    word-wrap: break-word;
}

.debug-content::-webkit-scrollbar {
    width: 8px;
}

.debug-content::-webkit-scrollbar-track {
    background: var(--bg-secondary);
}

.debug-content::-webkit-scrollbar-thumb {
    background: var(--border-primary);
    border-radius: 4px;
}

.debug-content::-webkit-scrollbar-thumb:hover {
    background: var(--primary);
}

/* Status Section */
.status-section {
    margin-top: 20px;
    border-top: 1px solid var(--border-default);
    padding-top: 16px;
}

.status-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 12px;
    font-weight: bold;
    color: var(--text-primary);
}

/* Status Badge on Sidebar Tab */
.status-badge {
    position: absolute;
    top: 4px;
    right: 4px;
    background: var(--error);
    color: var(--text-primary);
    font-size: var(--font-xs);
    font-weight: bold;
    padding: 2px 5px;
    border-radius: 10px;
    min-width: 16px;
    text-align: center;
}

.status-badge.warning {
    background: var(--warning);
}

.status-badge.error {
    background: var(--error);
}

/* Errors List */
.btn-link {
    background: none;
    border: none;
    color: var(--primary);
    cursor: pointer;
    font-size: var(--font-xs);
    text-decoration: underline;
}

.btn-link:hover {
    color: var(--text-primary);
}

.errors-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.error-item {
    border: 1px solid var(--border-default);
    border-radius: 4px;
    overflow: hidden;
}

.error-item.error {
    border-left: 3px solid var(--error);
}

.error-item.warning {
    border-left: 3px solid var(--warning);
}

.error-summary {
    padding: 10px 12px;
    cursor: pointer;
    background: var(--bg-element);
    display: flex;
    align-items: center;
    gap: 8px;
    list-style: none;
}

.error-summary:hover {
    background: var(--bg-hover);
}

.error-icon {
    font-size: 14px;
    flex-shrink: 0;
}

.error-item.error .error-icon {
    color: var(--error);
}

.error-item.warning .error-icon {
    color: var(--warning);
}

.error-title {
    flex: 1;
    font-size: var(--font-sm);
    color: var(--text-primary);
}

.error-time {
    font-size: var(--font-xs);
    color: var(--text-muted);
    flex-shrink: 0;
}

.error-details {
    padding: 12px;
    background: var(--bg-panel);
    border-top: 1px solid var(--border-default);
}

.error-details pre {
    margin: 0;
    font-size: var(--font-xs);
    color: var(--text-muted);
    white-space: pre-wrap;
    word-break: break-word;
}

/* Replay Panel */
.replay-panel {
    display: flex;
    flex-direction: column;
    gap: 16px;
    height: 100%;
    padding: 8px 0;
}

.replay-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.replay-loader {
    display: flex;
    align-items: center;
    gap: 12px;
}

.replay-file-label {
    cursor: pointer;
}

.replay-file-label input[type="file"] {
    display: none;
}

.replay-metadata {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
    gap: 8px;
    padding: 12px;
    background: var(--bg-secondary);
    border-radius: 4px;
}

.replay-meta-item {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.replay-controls {
    display: flex;
    flex-direction: column;
    gap: 12px;
    padding: 12px;
    background: var(--bg-secondary);
    border-radius: 4px;
}

.replay-progress {
    display: flex;
    align-items: center;
    gap: 12px;
}

.replay-progress-bar {
    flex: 1;
    height: 8px;
    background: var(--bg-element);
    border-radius: 4px;
    overflow: hidden;
}

.replay-progress-fill {
    height: 100%;
    background: var(--text-link);
    transition: width 0.1s ease-out;
}

.replay-buttons {
    display: flex;
    gap: 8px;
}

.replay-buttons button {
    min-width: 40px;
}

.replay-speed {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: var(--font-xs);
}

.replay-speed select {
    background: var(--bg-element);
    color: var(--text-primary);
    border: 1px solid var(--border-default);
    padding: 4px 8px;
    font-family: inherit;
    border-radius: 4px;
}

.replay-event-log {
    flex: 1;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 4px;
    padding: 8px;
    background: var(--bg-secondary);
    border-radius: 4px;
    font-family: var(--font-mono);
    font-size: var(--font-xs);
}

.replay-event {
    padding: 4px 8px;
    border-radius: 2px;
    display: flex;
    gap: 8px;
}

.replay-event.agent {
    background: rgba(99, 179, 237, 0.1);
}

.replay-event.tool {
    background: rgba(154, 230, 180, 0.1);
}

.replay-event.error {
    background: rgba(252, 129, 129, 0.1);
}

.replay-event-time {
    color: var(--text-muted);
    flex-shrink: 0;
}

.replay-event-type {
    color: var(--text-secondary);
    flex-shrink: 0;
    min-width: 100px;
}

.replay-event-content {
    color: var(--text-primary);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
","/styles/proto/responsive.css":"/* Proto Responsive - All media queries and mobile styles */

/* Tablet breakpoint */
@media (max-width: 1024px) {
    .app-shell {
        grid-template-columns: 50px 200px 1fr;
    }

    .vfs-browser-header {
        padding: var(--space-sm) var(--space-md);
    }
}

/* Mobile breakpoint */
@media (max-width: 768px) {
    .app-shell {
        grid-template-columns: 1fr;
        grid-template-rows: auto 1fr auto;
    }

    .sidebar {
        order: 3;
        flex-direction: row;
        border-right: none;
        border-top: 1px solid var(--border-default);
        padding: 0 8px;
        justify-content: space-around;
    }

    .sidebar-btn {
        width: auto;
        height: 48px;
        padding: 0 12px;
        min-width: 48px;
    }

    .sidebar-spacer {
        display: none;
    }

    .workspace {
        order: 1;
    }

    .workspace-header {
        padding: 10px 12px;
        flex-wrap: wrap;
        gap: 8px;
    }

    .workspace-title {
        font-size: var(--font-sm);
    }

    .workspace-status {
        font-size: var(--font-sm);
    }

    .workspace-content {
        padding: 12px;
    }

    .vfs-browser-panel {
        order: 2;
        border-right: none;
        border-bottom: 1px solid var(--border-default);
        max-height: 200px;
        overflow: hidden;
        display: none;
    }

    .vfs-browser-panel.expanded {
        display: flex;
        max-height: 40vh;
    }

    .vfs-browser-header {
        padding: 8px 12px;
        font-size: var(--font-xs);
    }

    .vfs-tree {
        max-height: 100px;
        font-size: var(--font-xs);
    }

    .vfs-content {
        max-height: 80px;
        font-size: var(--font-xs);
    }

    .dashboard-main {
        flex-direction: column;
    }

    .left-panel {
        border-right: none;
        border-bottom: 1px solid var(--border-secondary);
    }

    .panel {
        max-height: 50vh;
        padding: var(--space-md);
    }

    .history-entry {
        margin-bottom: var(--space-sm);
    }

    .history-header {
        padding: var(--space-xs) var(--space-sm);
        font-size: var(--font-xs);
    }

    .history-content {
        padding: var(--space-sm);
        font-size: var(--font-xs);
        max-height: 200px;
    }

    .status-item {
        padding: var(--space-xs) var(--space-sm);
    }

    .status-label,
    .status-value {
        font-size: var(--font-xs);
    }

    .controls {
        flex-direction: column;
        gap: var(--space-sm);
    }

    .controls input {
        width: 100%;
    }

    .controls button {
        width: 100%;
    }

    .modal-content {
        width: 92%;
        min-width: auto;
    }

    .modal-actions {
        flex-direction: column-reverse;
    }

    .modal-actions .btn {
        width: 100%;
    }

    .vfs-browser-panel::before {
        content: '';
        display: block;
        width: 40px;
        height: 4px;
        background: var(--border-default);
        border-radius: 2px;
        margin: 8px auto;
        cursor: grab;
    }

    .vfs-browser-panel.collapsed .vfs-browser-header span,
    .vfs-browser-panel.collapsed .vfs-search-container,
    .vfs-browser-panel.collapsed .vfs-tree {
        display: none;
    }

    .workspace-content {
        scroll-snap-type: x mandatory;
        overflow-x: auto;
    }

    .token-budget-text {
        display: none;
    }

    .token-budget-bar {
        width: 40px;
    }

    #progress-container {
        padding: 0 var(--space-sm);
    }

    .vfs-editor {
        min-height: 150px;
        font-size: var(--font-sm);
    }
}

/* Small mobile */
@media (max-width: 480px) {
    .app-shell {
        grid-template-rows: auto 1fr 52px;
    }

    .sidebar {
        padding: 0 4px;
    }

    .sidebar-btn {
        height: 42px;
        min-width: 42px;
        padding: 0 8px;
        font-size: var(--font-sm);
    }

    .workspace-header {
        padding: 6px 8px;
        min-height: 40px;
    }

    .workspace-title {
        font-size: var(--font-sm);
    }

    .workspace-title span:last-child {
        max-width: 120px;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .workspace-status {
        font-size: var(--font-xs);
    }

    .workspace-content {
        padding: 8px;
    }

    .vfs-browser-panel {
        max-height: 120px;
    }

    .vfs-browser-panel.expanded {
        max-height: 35vh;
    }

    .vfs-browser-header {
        padding: 6px 8px;
        font-size: var(--font-xs);
    }

    .vfs-tree {
        max-height: 60px;
        padding: 4px;
    }

    .vfs-content {
        max-height: 50px;
        padding: 4px;
    }

    .history-stream,
    .reflections-stream {
        font-size: var(--font-xs);
    }

    .history-entry {
        margin-bottom: var(--space-xs);
    }

    .history-header {
        padding: var(--space-xs);
        font-size: 10px;
    }

    .history-content {
        padding: var(--space-xs);
        max-height: 120px;
        font-size: 11px;
    }

    .reflection-entry {
        padding: var(--space-xs);
    }

    .reflection-header {
        font-size: var(--font-xs);
    }

    .reflection-detail {
        font-size: var(--font-xs);
    }

    .log-container {
        padding: var(--space-sm);
        font-size: var(--font-xs);
    }

    .card {
        padding: var(--space-sm);
    }

    .card-header {
        font-size: var(--font-sm);
        margin-bottom: var(--space-xs);
    }

    .diff-viewer {
        padding: var(--space-sm);
    }

    .diff-file-header {
        flex-direction: column;
        align-items: flex-start;
        gap: var(--space-xs);
        padding: var(--space-sm);
    }

    .diff-file-actions {
        width: 100%;
    }

    .side-by-side-diff {
        flex-direction: column;
    }

    .line-number {
        width: 28px;
        font-size: 10px;
    }

    /* Panel adjustments */
    .panel {
        padding: var(--space-sm);
    }

    .status-item {
        padding: var(--space-xs);
        flex-direction: column;
        align-items: flex-start;
        gap: 2px;
    }

    /* Schema panel */
    .schema-columns {
        grid-template-columns: 1fr;
    }

    .schema-search {
        width: 100%;
    }

    /* Telemetry panel */
    .telemetry-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 6px;
    }

    /* Workers panel */
    .workers-sections {
        grid-template-columns: 1fr;
        gap: var(--space-sm);
    }

    .workers-summary {
        gap: var(--space-xs);
    }

    .workers-summary-item {
        min-width: 100px;
        padding: 6px 8px;
    }
}

/* Touch optimization */
@media (pointer: coarse) {
    .sidebar-btn {
        min-height: 56px;
        min-width: 56px;
    }

    .vfs-tree .vfs-file {
        min-height: 44px;
        display: flex;
        align-items: center;
    }

    .vfs-tree .vfs-dir {
        min-height: 44px;
        display: flex;
        align-items: center;
    }

    .btn-small {
        min-height: 44px;
        padding: var(--space-sm) var(--space-md);
    }

    .btn, .btn-sm {
        min-height: 44px;
    }

    .workspace-content,
    .vfs-tree,
    .vfs-content,
    .log-container,
    .history-content {
        -webkit-overflow-scrolling: touch;
        scroll-behavior: smooth;
    }

    .controls button {
        min-height: 48px;
    }

    .controls input {
        min-height: 44px;
    }

    .toast-container {
        top: auto;
        bottom: 70px;
        left: 10px;
        right: 10px;
        max-width: none;
    }

    .toast {
        width: 100%;
    }

    .toast-btn {
        min-height: 36px;
        padding: 8px 16px;
    }

    .history-actions .toast-btn {
        min-height: 36px;
    }
}
","/styles/proto/vfs.css":"/* Proto VFS - Browser, Tree, Content, Editor */

/* VFS Browser Panel (middle column) */
.vfs-browser-panel {
    display: flex;
    flex-direction: column;
    background: var(--bg-secondary);
    border-right: 1px solid var(--border-default);
    min-height: 0;
    overflow: hidden;
}

.vfs-browser-panel.collapsed {
    width: 40px;
    min-width: 40px;
}

.vfs-browser-header {
    padding: 12px;
    border-bottom: 1px solid var(--border-default);
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: var(--font-xs);
    color: var(--text-muted);
    flex-shrink: 0;
}

.vfs-tree {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 8px;
    font-size: var(--font-sm);
}

.vfs-tree .vfs-dir {
    color: var(--warning);
    font-weight: 600;
    margin-top: var(--space-xs);
    cursor: pointer;
    padding: 2px var(--space-sm);
    display: flex;
    align-items: center;
    gap: 4px;
}

.vfs-tree .vfs-dir:hover {
    background: var(--bg-hover);
}

.vfs-tree .vfs-file {
    padding: 2px var(--space-sm);
    cursor: pointer;
    color: var(--text-primary);
    border-radius: var(--radius-sm);
    font-size: var(--font-sm);
}

.vfs-tree .vfs-file:hover {
    background: var(--bg-hover);
    color: var(--primary);
}

/* VFS File selected state */
.vfs-tree .vfs-file.selected,
.vfs-item.vfs-file.selected {
    background: rgba(173, 252, 65, 0.15);
    color: var(--primary);
    border-left: 2px solid var(--primary);
    font-weight: 500;
}

.vfs-tree .vfs-file.selected:hover,
.vfs-item.vfs-file.selected:hover {
    background: rgba(173, 252, 65, 0.2);
}

/* VFS Search highlight */
.vfs-tree .vfs-file.highlight,
.vfs-item.vfs-file.highlight {
    background: rgba(255, 200, 0, 0.15);
    border-left: 2px solid var(--warning);
}

.vfs-tree .vfs-file.highlight.selected,
.vfs-item.vfs-file.highlight.selected {
    background: rgba(173, 252, 65, 0.2);
    border-left: 2px solid var(--primary);
}

/* VFS File state icon */
.vfs-state-icon {
    font-size: 10px;
    font-weight: 700;
    margin-left: 4px;
    padding: 0 3px;
    border-radius: 2px;
    line-height: 1;
}

/* VFS File modification indicators */
.vfs-tree .vfs-file-created,
.vfs-item.vfs-file-created {
    color: var(--success, #66bb6a);
    font-weight: 500;
}

.vfs-file-created .vfs-state-icon {
    background: rgba(102, 187, 106, 0.25);
    color: var(--success, #66bb6a);
}

.vfs-tree .vfs-file-modified,
.vfs-item.vfs-file-modified {
    color: var(--warning, #ffa500);
    font-weight: 500;
}

.vfs-file-modified .vfs-state-icon {
    background: rgba(255, 165, 0, 0.25);
    color: var(--warning, #ffa500);
}

.vfs-tree .vfs-file-deleted,
.vfs-item.vfs-file-deleted {
    color: var(--error, #f48771);
    text-decoration: line-through;
    opacity: 0.6;
}

.vfs-file-deleted .vfs-state-icon {
    background: rgba(244, 135, 113, 0.25);
    color: var(--error, #f48771);
}

@keyframes vfs-pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.6; }
}

@keyframes vfs-fade-out {
    0% { opacity: 0.7; }
    70% { opacity: 0.7; }
    100% { opacity: 0; }
}

.vfs-dir-icon {
    font-size: var(--font-xs);
    color: var(--text-muted);
    width: 12px;
}

/* VFS Search */
.vfs-search-container {
    padding: 8px;
    border-bottom: 1px solid var(--border-default);
    flex-shrink: 0;
}

.vfs-search-input {
    width: 100%;
    padding: 6px 8px;
    background: var(--bg-element);
    border: 1px solid var(--border-default);
    color: var(--text-primary);
    font-size: var(--font-sm);
    font-family: 'Courier New', monospace;
}

.vfs-search-input:focus {
    outline: none;
    border-color: var(--primary);
}

/* VFS Content (in workspace) */
.vfs-content {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: var(--bg-app);
    font-size: var(--font-sm);
    overflow: hidden;
    padding: 16px;
    min-height: 0;
}

.vfs-content.hidden {
    display: none;
}

.vfs-file-path {
    color: var(--primary);
    font-weight: 600;
    margin-bottom: var(--space-sm);
    padding-bottom: var(--space-xs);
    border-bottom: 1px solid var(--border-subtle);
}

/* VFS Content Header with Actions */
.vfs-content-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-bottom: var(--space-sm);
    margin-bottom: var(--space-sm);
    border-bottom: 1px solid var(--border-subtle);
}

.vfs-content-actions {
    display: flex;
    gap: 4px;
}

.vfs-content-body {
    overflow: auto;
    flex: 1;
}

.vfs-content-body pre {
    margin: 0;
    white-space: pre-wrap;
    word-break: break-all;
}

/* VFS Editor */
.vfs-editor {
    width: 100%;
    min-height: 200px;
    flex: 1;
    background: var(--bg-element);
    border: 1px solid var(--border-default);
    color: var(--text-primary);
    font-family: var(--font-mono);
    font-size: var(--font-md);
    padding: var(--space-sm);
    resize: vertical;
}

.vfs-editor:focus {
    border-color: var(--primary);
    outline: none;
}

/* VFS Browser Collapsed State (desktop) */
.vfs-browser-panel.collapsed .vfs-browser-header {
    justify-content: center;
    padding: var(--space-sm);
}

/* VFS Preview, Diff, and Snapshot Panels */
.vfs-preview-panel,
.vfs-diff-panel,
.vfs-snapshot-panel {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: var(--bg-panel);
    display: flex;
    flex-direction: column;
    z-index: 10;
}

.vfs-preview-header,
.vfs-diff-header,
.vfs-snapshot-header {
    padding: 8px 12px;
    background: var(--bg-element);
    border-bottom: 1px solid var(--border-default);
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: var(--font-sm);
    font-weight: 500;
}

#vfs-preview-iframe {
    flex: 1;
    border: none;
    width: 100%;
    background: white;
}

#vfs-diff-content,
#vfs-snapshot-timeline {
    flex: 1;
    overflow: auto;
    padding: 12px;
}

#vfs-snapshot-viewer {
    flex: 1;
    overflow: auto;
    border-top: 1px solid var(--border-default);
    padding: 12px;
}

/* Snapshot timeline */
.snapshot-item {
    padding: 10px;
    margin-bottom: 8px;
    background: var(--bg-element);
    border: 1px solid var(--border-default);
    border-radius: 4px;
    cursor: pointer;
    transition: background 0.2s;
}

.snapshot-item:hover {
    background: var(--bg-hover);
}

.snapshot-item.active {
    border-color: var(--primary);
    background: var(--bg-hover);
}

.snapshot-timestamp {
    font-size: var(--font-xs);
    color: var(--text-muted);
}

.snapshot-stats {
    font-size: var(--font-xs);
    color: var(--text-muted);
    margin-top: 4px;
}

.snapshot-actions {
    margin-top: 8px;
    display: flex;
    gap: 8px;
}

.snapshot-actions .btn {
    font-size: var(--font-xs);
    padding: 4px 8px;
}

/* Diff Content Styles */
.diff-header {
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 8px;
    padding-bottom: 8px;
    border-bottom: 1px solid var(--border-default);
}

.diff-stats {
    font-size: var(--font-xs);
    color: var(--text-muted);
    margin-bottom: 12px;
}

.diff-content {
    font-family: var(--font-mono);
    font-size: var(--font-xs);
    line-height: 1.5;
    background: var(--bg-element);
    padding: 12px;
    border-radius: 4px;
    overflow: auto;
}

.diff-same {
    color: var(--text-secondary);
}

.diff-add {
    color: var(--success);
    background: rgba(0, 255, 0, 0.1);
    display: block;
}

.diff-del {
    color: var(--error);
    background: rgba(255, 0, 0, 0.1);
    display: block;
}

/* Snapshot List Styles */
.snapshot-name {
    font-weight: 500;
    display: block;
    margin-bottom: 4px;
}

.snapshot-date {
    font-size: var(--font-xs);
    color: var(--text-muted);
    margin-right: 12px;
}

.snapshot-files {
    font-size: var(--font-xs);
    color: var(--primary);
}
","/styles/theme.css":"/* ========================================
   REPLOID Design System - NEON CORE
   styles/theme.css
   ======================================== */

:root {
  /* ---- Core Palette (Monochrome + Green) ---- */
  --bg-app: #000000;       /* Pure Black */
  --bg-panel: #000000;     /* Pure Black */
  --bg-element: #000000;   /* Pure Black */
  --bg-hover: #000000;     /* Pure Black */
  --bg-active: rgba(173, 252, 65, 0.1);

  /* ---- Borders ---- */
  --border-subtle: #7f7f7f;
  --border-default: #999999;
  --border-active: #adfc41;

  /* ---- Text ---- */
  --text-primary: #ffffff;
  --text-secondary: #b8b8b8;
  --text-muted: #a0a0a0;
  --text-inverse: #000000;

  /* ---- Accents (Green) ---- */
  --primary: #adfc41;
  --primary-dim: rgba(173, 252, 65, 0.15);
  --primary-glow: 0 0 10px rgba(173, 252, 65, 0.4);

  --secondary: #adfc41;
  --secondary-dim: rgba(173, 252, 65, 0.15);

  --success: #adfc41;
  --warning: #adfc41;
  --danger: #adfc41;

  /* ---- Typography ---- */
  --font-mono: 'Courier New', 'Consolas', monospace;
  --font-sans: 'Inter', system-ui, sans-serif;
  --font-base: 15px;
  --font-xs: 13px;
  --font-sm: 14px;
  --font-md: var(--font-base);
  --font-lg: 16px;
  --font-xl: 18px;

  /* ---- Spacing & Radius ---- */
  --space-sm: 8px;
  --space-md: 12px;
  --space-lg: 20px;
  --radius-none: 0px;
  --radius-sm: 2px;
}

/* ========================================
   RESET & BASE
   ======================================== */
* { box-sizing: border-box; }

body {
  margin: 0; padding: 0;
  background: var(--bg-app);
  color: var(--text-primary);
  font-family: var(--font-mono); /* Default to code font */
  font-size: var(--font-base);
  overflow-x: hidden;
}

/* Scanline Overlay (Optional - adds CRT feel) */
body::before {
  content: " ";
  display: block;
  position: fixed; top: 0; left: 0; bottom: 0; right: 0;
  background: linear-gradient(rgba(0, 0, 0, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(173, 252, 65, 0.02), rgba(173, 252, 65, 0.02), rgba(173, 252, 65, 0.02));
  z-index: 2;
  background-size: 100% 2px, 3px 100%;
  pointer-events: none;
}

/* ========================================
   COMPONENTS
   ======================================== */

/* 1. Buttons (Holographic) */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 10px 20px;
  font-family: var(--font-mono);
  font-size: 12px; text-transform: uppercase; letter-spacing: 1px;
  background: transparent;
  border: 1px solid var(--border-default);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn:hover:not(:disabled) {
  border-color: var(--text-primary);
  color: var(--text-primary);
  background: var(--bg-hover);
}

.btn.primary {
  border-color: var(--primary);
  color: var(--primary);
  box-shadow: 0 0 5px rgba(173,252,65,0.1);
}

.btn.primary:hover:not(:disabled) {
  background: var(--primary-dim);
  box-shadow: var(--primary-glow);
}

.btn.secondary {
  border-color: var(--border-default);
  color: var(--text-muted);
}

.btn:disabled { opacity: 0.5; cursor: not-allowed; }

/* 2. Cards (HUD Panels) */
.card, .panel, .advanced-panel {
  background: var(--bg-panel);
  border: 1px solid var(--border-default);
  padding: var(--space-lg);
  position: relative;
}

/* Corner accents for panels */
.card::after, .panel::after {
  content: ''; position: absolute;
  top: -1px; right: -1px;
  width: 10px; height: 10px;
  border-top: 2px solid var(--primary);
  border-right: 2px solid var(--primary);
}

/* 3. Inputs (Terminal Entry) */
input, select, textarea {
  background: var(--bg-element);
  border: 1px solid var(--border-default);
  color: var(--text-primary);
  font-family: var(--font-mono);
  padding: 10px;
  width: 100%;
}

input:focus, select:focus, textarea:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: inset 0 0 10px rgba(173, 252, 65, 0.1);
}

/* ========================================
   UTILITIES
   ======================================== */
.hidden { display: none !important; }
.text-cyan { color: var(--primary); }
.text-magenta { color: var(--secondary); }
.text-muted { color: var(--text-muted); }

/* ========================================
   PROGRESS BAR
   ======================================== */
.progress-bar {
  width: 100%;
  height: 4px;
  background: var(--bg-element);
  border: 1px solid var(--border-default);
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--primary), var(--secondary));
  transition: width 0.3s ease;
  box-shadow: 0 0 10px var(--primary);
}

.progress-bar-indeterminate .progress-bar-fill {
  width: 30%;
  animation: indeterminate 1.5s ease-in-out infinite;
}

@keyframes indeterminate {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(400%); }
}

/* ========================================
   TOAST NOTIFICATIONS
   ======================================== */
.toast-container {
  position: fixed;
  top: 20px;
  right: 20px;
  z-index: 10000;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-width: 400px;
}

.toast {
  background: var(--bg-panel);
  border: 1px solid var(--border-default);
  padding: 12px 16px;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  animation: slideIn 0.3s ease;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
}

.toast-icon {
  font-size: 16px;
  flex-shrink: 0;
}

.toast-content {
  flex: 1;
  min-width: 0;
}

.toast-title {
  font-weight: bold;
  margin-bottom: 4px;
  font-size: 12px;
}

.toast-message {
  font-size: 11px;
  color: var(--text-secondary);
  word-break: break-word;
}

.toast-actions {
  display: flex;
  gap: 8px;
  margin-top: 8px;
}

.toast-btn {
  padding: 4px 10px;
  font-size: 10px;
  background: transparent;
  border: 1px solid var(--border-default);
  color: var(--text-secondary);
  cursor: pointer;
  transition: 0.2s;
}

.toast-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.toast-btn.primary {
  border-color: var(--primary);
  color: var(--primary);
}

.toast-close {
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 0;
  font-size: 16px;
  line-height: 1;
}

.toast-close:hover {
  color: var(--text-primary);
}

.toast.toast-error {
  border-color: var(--danger);
}

.toast.toast-error .toast-icon {
  color: var(--danger);
}

.toast.toast-success {
  border-color: var(--success);
}

.toast.toast-success .toast-icon {
  color: var(--success);
}

.toast.toast-warning {
  border-color: var(--warning);
}

.toast.toast-warning .toast-icon {
  color: var(--warning);
}

.toast.toast-info {
  border-color: var(--primary);
}

.toast.toast-info .toast-icon {
  color: var(--primary);
}

/* ========================================
   TOKEN BUDGET INDICATOR
   ======================================== */
.token-budget {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--text-primary);
}

.token-budget-bar {
  width: 60px;
  height: 6px;
  background: var(--bg-element);
  border: 1px solid var(--border-subtle);
  overflow: hidden;
}

.token-budget-fill {
  height: 100%;
  transition: width 0.3s ease, background 0.3s ease;
}

.token-budget-fill.low {
  background: var(--success);
}

.token-budget-fill.medium {
  background: var(--warning);
}

.token-budget-fill.high {
  background: var(--danger);
}

.token-budget-text {
  min-width: 80px;
}

/* ========================================
   GOAL HISTORY DROPDOWN
   ======================================== */
.goal-history-container {
  position: relative;
  width: 100%;
}

.goal-history-dropdown {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--bg-panel);
  border: 1px solid var(--border-default);
  border-top: none;
