 * @fileoverview SwarmListPeers - List connected swarm peers and connection status
 */

async function call(args = {}, deps = {}) {
  const { SwarmTransport, SwarmSync } = deps;

  if (!SwarmTransport) {
    return `SwarmTransport not available. Swarm may be disabled. Enable with localStorage.setItem('REPLOID_SWARM_ENABLED', 'true') and reload.`;
  }

  const stats = SwarmTransport.getStats();
  const syncStats = SwarmSync?.getStats?.() || {};

  // Check if swarm is enabled
  if (stats.connectionState === 'disconnected' || !stats.transport) {
    return `Swarm not connected.

To enable swarm mode:
1. Run: localStorage.setItem('REPLOID_SWARM_ENABLED', 'true')
2. Reload the page
3. Open another tab with the same room (use ?swarm=<room> parameter)

Current state: ${stats.connectionState || 'disconnected'}`;
  }

  const peers = SwarmTransport.getConnectedPeers();

  let result = `Swarm Status:
- Transport: ${stats.transport}
- Connection: ${stats.connectionState}
- Room: ${stats.roomId || 'unknown'}
- My Peer ID: ${stats.peerId || 'unknown'}
- Synced entries: ${syncStats.syncedEntries || 0}
- Active transfers: ${syncStats.activeTransfers || 0}

`;

  if (peers.length === 0) {
    result += `No peers connected yet.

To connect another tab:
1. Open a new browser tab
2. Navigate to the same URL with ?swarm=<same-room>
3. Or use the default local room for same-browser tabs`;
  } else {
    result += `Connected Peers (${peers.length}):\n`;
    for (const peer of peers) {
      const lastSeen = peer.lastSeen ? new Date(peer.lastSeen).toISOString() : 'unknown';
      result += `- ${peer.id} (last seen: ${lastSeen})\n`;
    }
    result += `\nUse SwarmShareFile to share files with these peers.`;
  }

  return result;
}

export const tool = {
  name: "SwarmListPeers",
  description: "List all connected swarm peers and show connection status. Use this before SwarmShareFile or SwarmRequestFile to see available peers.",
  inputSchema: {
    type: 'object',
    properties: {}
  },
  call
};

export default call;
","/tools/SwarmRequestFile.js":"/**
 * @fileoverview SwarmRequestFile - Request a file from a connected peer
 */

async function call(args = {}, deps = {}) {
  const { SwarmSync, SwarmTransport } = deps;

  if (!SwarmSync) throw new Error('SwarmSync not available - swarm may be disabled');
  if (!SwarmTransport) throw new Error('SwarmTransport not available');

  const { peerId, path } = args;

  if (!peerId) throw new Error('Missing peerId argument - use SwarmListPeers to find peer IDs');
  if (!path) throw new Error('Missing path argument - the VFS path as announced by the peer');

  // Check swarm connection
  const stats = SwarmTransport.getStats();
  if (stats.connectionState === 'disconnected' || !stats.transport) {
    return `Swarm not connected. Enable with localStorage.setItem('REPLOID_SWARM_ENABLED', 'true') and reload.`;
  }

  // Verify peer exists
  const peers = SwarmTransport.getConnectedPeers();
  const peerExists = peers.some(p => p.id === peerId);
  if (!peerExists) {
    const peerList = peers.map(p => p.id).join(', ') || 'none';
    return `Peer ${peerId} not found. Connected peers: ${peerList}`;
  }

  // Request the file
  const requested = SwarmSync.requestArtifact(peerId, path);

  if (!requested) {
    return `Request failed - transfer may already be in progress or max concurrent transfers reached.`;
  }

  // Build the target path where file will be saved
  const targetPath = `/shared${path.startsWith('/') ? '' : '/'}${path}`;

  return `Requested ${path} from peer ${peerId}. File will be saved to ${targetPath} when transfer completes.`;
}

export const tool = {
  name: "SwarmRequestFile",
  description: "Request a file from a connected swarm peer. Use SwarmListPeers to find peer IDs. The file will be automatically saved to /shared/ when received.",
  inputSchema: {
    type: 'object',
    required: ['peerId', 'path'],
    properties: {
      peerId: {
        type: 'string',
        description: 'ID of the peer to request from (get from SwarmListPeers)'
      },
      path: {
        type: 'string',
        description: 'Path of the file to request (as announced by peer, e.g. /test/myfile.txt)'
      }
    }
  },
  call
};

export default call;
","/tools/SwarmShareFile.js":"/**
 * @fileoverview SwarmShareFile - Share a VFS file with connected swarm peers
 */

async function call(args = {}, deps = {}) {
  const { SwarmSync, VFS, SwarmTransport } = deps;

  if (!SwarmSync) throw new Error('SwarmSync not available - swarm may be disabled');
  if (!VFS) throw new Error('VFS not available');

  const path = args.path;

  if (!path) throw new Error('Missing path argument');

  // Check if file exists
  const exists = await VFS.exists(path);
  if (!exists) {
    throw new Error(`File not found: ${path}`);
  }

  // Check swarm connection
  const stats = SwarmTransport?.getStats?.() || {};
  if (stats.connectionState === 'disconnected' || !stats.transport) {
    return `Swarm not connected. Enable with localStorage.setItem('REPLOID_SWARM_ENABLED', 'true') and reload.`;
  }

  // Announce the file to peers
  const count = await SwarmSync.announceArtifact(path);

  if (count === 0) {
    return `Announced ${path} but no peers connected. Other tabs will see this file when they join.`;
  }

  return `Announced ${path} to ${count} peer(s). Peers can now request this file.`;
}

export const tool = {
  name: "SwarmShareFile",
  description: "Share a VFS file with connected swarm peers. Peers will receive an announcement and can request the file. Use SwarmListPeers to see connected peers first.",
  inputSchema: {
    type: 'object',
    required: ['path'],
    properties: {
      path: {
        type: 'string',
        description: 'VFS path to share (e.g. /data/report.json, /test/myfile.txt)'
      }
    }
  },
  call
};

export default call;
","/tools/Tail.js":"/**
 * @fileoverview Tail - View the last N lines of a file
 */

async function call(args = {}, deps = {}) {
  const { VFS } = deps;
  if (!VFS) throw new Error('VFS not available');

  const { path, lines = 10 } = args;
  if (!path) throw new Error('Missing "path" argument');

  const content = await VFS.read(path);
  const allLines = content.split('\n');
  const n = parseInt(lines, 10);
  return allLines.slice(-n).join('\n');
}

export const tool = {
  name: "Tail",
  description: "Show the last N lines of a file (tail)",
  readOnly: true,
  call
};

export default call;
","/tools/Touch.js":"/**
 * @fileoverview Touch - Create empty files or update timestamps
 */

async function call(args = {}, deps = {}) {
  const { VFS } = deps;
  if (!VFS) throw new Error('VFS not available');

  const { path } = args;
  if (!path) throw new Error('Missing "path" argument');

  const exists = await VFS.exists(path);
  if (exists) {
    // Read and rewrite to update timestamp
    const content = await VFS.read(path);
    await VFS.write(path, content);
    return `Updated: ${path}`;
  }

  // Create empty file
  await VFS.write(path, '');
  return `Created: ${path}`;
}

export const tool = {
  name: "Touch",
  description: "Create empty files or update timestamps (touch)",
  call
};

export default call;
","/tools/WriteFile.js":"/**
 * @fileoverview WriteFile - Write content to VFS with audit logging and arena verification
 */

async function call(args = {}, deps = {}) {
  const { VFS, EventBus, AuditLogger, VFSSandbox, VerificationManager, SubstrateLoader } = deps;
  if (!VFS) throw new Error('VFS not available');

  const path = args.path || args.file;
  const content = args.content;
  const autoLoad = args.autoLoad === true;

  if (!path) throw new Error('Missing path argument');
  if (content === undefined) throw new Error('Missing content argument');

  const isCore = path.startsWith('/core/');
  const existed = await VFS.exists(path);
  const beforeContent = existed ? await VFS.read(path).catch(() => null) : null;

  // Arena verification for core file changes (when enabled)
  let arenaGatingEnabled = false;
  try {
    arenaGatingEnabled = localStorage.getItem('REPLOID_ARENA_GATING') === 'true';
  } catch (e) { /* ignore */ }

  if (isCore && arenaGatingEnabled && VFSSandbox && VerificationManager) {
    try {
      const snapshot = await VFSSandbox.createSnapshot();
      try {
        await VFSSandbox.applyChanges({ [path]: content });
        const result = await VerificationManager.verifyProposal({ [path]: content });

        if (!result.passed) {
          const errorMsg = `Core modification blocked: ${result.errors?.join(', ') || 'verification failed'}`;
          if (AuditLogger) {
            await AuditLogger.logEvent('CORE_WRITE_BLOCKED', { path, errors: result.errors }, 'WARN');
          }
          if (EventBus) {
            EventBus.emit('tool:core_blocked', { path, errors: result.errors });
          }
          throw new Error(errorMsg);
        }
      } finally {
        await VFSSandbox.restoreSnapshot(snapshot);
      }
    } catch (err) {
      if (err.message.startsWith('Core modification blocked')) throw err;
      // Verification system error - log but proceed
      console.warn('[WriteFile] Arena verification error:', err.message);
    }
  }

  await VFS.write(path, content);

  // Emit event for UI
  if (EventBus) {
    EventBus.emit(existed ? 'vfs:write' : 'artifact:created', { path });
  }

  // Audit log
  if (AuditLogger) {
    await AuditLogger.logEvent('FILE_WRITE', {
      path,
      existed,
      bytesWritten: content.length,
      bytesBefore: beforeContent?.length || 0,
      isCore,
      arenaVerified: isCore && arenaGatingEnabled
    }, isCore ? 'WARN' : 'INFO');
  }

  // Auto-load module if requested and file is .js
  let loadResult = '';
  if (autoLoad && path.endsWith('.js') && SubstrateLoader) {
    try {
      await SubstrateLoader.loadModule(path);
      loadResult = ' + hot-reloaded';
    } catch (err) {
      loadResult = ` (autoLoad failed: ${err.message})`;
    }
  } else if (autoLoad && !SubstrateLoader) {
    loadResult = ' (autoLoad skipped: SubstrateLoader not available)';
  }

  return `Wrote ${path} (${content.length} bytes)${loadResult}`;
}

export const tool = {
  name: "WriteFile",
  description: "Write content to a file in the virtual filesystem",
  inputSchema: {
    type: 'object',
    required: ['path', 'content'],
    properties: {
      path: { type: 'string', description: 'VFS path to write (e.g. /tools/my-tool.js)' },
      content: { type: 'string', description: 'Content to write' },
      autoLoad: { type: 'boolean', description: 'If true and path is .js, hot-reload the module after writing', default: false }
    }
  },
  call
};

export default call;
","/ui/components/confirmation-modal.js":"// Confirmation Modal Component for REPLOID

const ConfirmationModal = {
  metadata: {
    id: 'ConfirmationModal',
    version: '1.0.0',
    dependencies: ['Utils'],
    async: false,
    type: 'ui'
  },

  factory: (deps) => {
    const { Utils } = deps;
    const { logger, escapeHtml } = Utils;

    let activeModal = null;

    const attachHandlers = (overlay, handlers) => {
      overlay.querySelector('.modal-btn-confirm').addEventListener('click', handlers.confirm);
      overlay.querySelector('.modal-btn-cancel').addEventListener('click', handlers.cancel);
      overlay.querySelector('.modal-close').addEventListener('click', handlers.cancel);
      document.addEventListener('keydown', handlers.escape);
      overlay.addEventListener('click', handlers.overlayClick);
    };

    const confirm = (options = {}) => {
      const {
        title = 'Confirm Action',
        message = 'Are you sure you want to proceed?',
        confirmText = 'Confirm',
        cancelText = 'Cancel',
        danger = false,
        details = null
      } = options;

      return new Promise((resolve) => {
        closeModal();

        const overlay = document.createElement('div');
        overlay.className = 'modal-overlay';
        overlay.innerHTML = `
          <div class="modal-content ${danger ? 'modal-danger' : ''}">
            <div class="modal-header">
              <h3 class="modal-title">${escapeHtml(title)}</h3>
              <button class="modal-close" aria-label="Close">&times;</button>
            </div>
            <div class="modal-body">
              <p class="modal-message">${escapeHtml(message)}</p>
              ${details ? `<div class="modal-details">${escapeHtml(details)}</div>` : ''}
            </div>
            <div class="modal-actions">
              <button class="btn btn-secondary modal-btn-cancel">${escapeHtml(cancelText)}</button>
              <button class="btn ${danger ? 'btn-danger' : 'btn-primary'} modal-btn-confirm">${escapeHtml(confirmText)}</button>
            </div>
          </div>
        `;

        const handlers = {
          confirm: () => {
            closeModal();
            resolve(true);
          },
          cancel: () => {
            closeModal();
            resolve(false);
          },
          escape: (event) => {
            if (event.key === 'Escape') handlers.cancel();
          },
          overlayClick: (event) => {
            if (event.target === overlay) handlers.cancel();
          }
        };

        document.body.appendChild(overlay);
        attachHandlers(overlay, handlers);

        activeModal = { overlay, handlers };
        logger.info('[ConfirmationModal] Modal shown:', title);
      });
    };

    const closeModal = () => {
      if (!activeModal) return;
      const { overlay, handlers } = activeModal;

      document.removeEventListener('keydown', handlers.escape);
      overlay.removeEventListener('click', handlers.overlayClick);

      if (overlay.parentNode) {
        overlay.parentNode.removeChild(overlay);
      }

      activeModal = null;
      logger.info('[ConfirmationModal] Modal closed');
    };

    return { confirm, closeModal };
  }
};

export default ConfirmationModal;
","/ui/components/diff-viewer-ui.js":"// Interactive Diff Viewer UI Component for REPLOID Sentinel
// Provides rich diff visualization and interactive approval controls
// PX-3 Enhanced: Prism.js syntax highlighting + detailed statistics
// PHASE 3 UPDATE: Added Event-Driven Rollback capability

// Removed direct import - using injected Utils
// import ParserUtils from '../../core/parser-utils.js';

const DiffViewerUI = {
  metadata: {
    id: 'DiffViewerUI',
    version: '1.0.0', // Updated for DIUtils
    description: 'Enhanced diff viewer with Prism.js highlighting, stats, and rollback events',
    features: [
      'Prism.js syntax highlighting for 10+ languages',
      'Side-by-side diff with color-coded changes',
      'Detailed per-file statistics (added/removed/modified lines)',
      'Language detection from file extensions',
      'Export to markdown, clipboard, and Web Share API',
      'Event-driven Rollback trigger'
    ],
    dependencies: ['Utils', 'StateManager', 'EventBus', 'ConfirmationModal?'],
    externalDeps: ['Prism'],
    async: false,
    type: 'ui'
  },

  factory: (deps) => {
    const { Utils, StateManager, EventBus, ConfirmationModal } = deps;
    const { logger, escapeHtml } = Utils;

    let container = null;
    let currentDiff = null;

    // Track event listeners for cleanup
    const eventListeners = {
      showDiff: null,
      clearDiff: null
    };

    // Cleanup function to remove event listeners
    const cleanup = () => {
      if (eventListeners.showDiff) {
        EventBus.off('diff:show', eventListeners.showDiff);
        eventListeners.showDiff = null;
      }
      if (eventListeners.clearDiff) {
        EventBus.off('diff:clear', eventListeners.clearDiff);
        eventListeners.clearDiff = null;
      }
    };

    // Initialize the diff viewer
    const init = (containerId) => {
      // Clean up any existing listeners first
      cleanup();

      container = document.getElementById(containerId);
      if (!container) {
        logger.error('[DiffViewerUI] Container not found:', containerId);
        return;
      }

      // Register event listeners and store references
      eventListeners.showDiff = handleShowDiff;
      eventListeners.clearDiff = clearDiff;
      EventBus.on('diff:show', eventListeners.showDiff);
      EventBus.on('diff:clear', eventListeners.clearDiff);

      logger.info('[DiffViewerUI] Initialized');
    };

    // Handle showing a diff
    const handleShowDiff = async (data) => {
      const { dogs_path, session_id, turn } = data;

      try {
        // Load and parse the dogs bundle
        const dogsContent = await StateManager.getArtifactContent(dogs_path);
        if (!dogsContent) {
          showError('Dogs bundle not found');
          return;
        }

        const changes = await parseDogsBundle(dogsContent);
        currentDiff = { changes, dogs_path, session_id, turn };

        renderDiff(changes);

      } catch (error) {
        logger.error('[DiffViewerUI] Error showing diff:', error);
        showError('Failed to load diff');
      }
    };

    // Parse dogs bundle using injected Utils parser
    const parseDogsBundle = async (content) => {
      // Use canonical parser from Utils
      const baseChanges = Utils.parseDogsBundle(content);

      // Enrich with old content and UI state
      const enrichedChanges = [];
      for (const change of baseChanges) {
        let oldContent = '';

        // For MODIFY and DELETE operations, fetch current content
        if (change.operation === 'MODIFY' || change.operation === 'DELETE') {
          try {
            oldContent = await StateManager.getArtifactContent(change.file_path) || '';
          } catch (err) {
            console.error(`Failed to fetch old content for ${change.file_path}:`, err);
            oldContent = '// Error loading original content';
          }
        }

        enrichedChanges.push({
          ...change,
          old_content: oldContent,
          approved: true // Default to approved for smoother workflow
        });
      }

      return enrichedChanges;
    };

    let actionClickHandler = null;

    // Render the diff viewer
    const renderDiff = (changes) => {
      if (!container) return;

      const html = `
        <div class="diff-viewer">
          <div class="diff-header">
            <h3>Review Proposed Changes</h3>
            <div class="diff-stats">
              ${getChangeStats(changes)}
            </div>
          </div>

          <div class="diff-actions" role="toolbar" aria-label="Diff actions">
            <button class="btn-approve-all" data-action="approve-all" aria-label="Approve all changes">
              ✓ Approve All
            </button>
            <button class="btn-reject-all" data-action="reject-all" aria-label="Reject all changes">
              ✗ Reject All
            </button>
            <button class="btn-edit" data-action="edit" aria-label="edit proposal">
              ✎ edit Proposal
            </button>
            <button class="btn-export" data-action="copy" title="Copy diff to clipboard">
              ☷ Copy
            </button>
            <button class="btn-export" data-action="export" title="Export as Markdown">
              ⚿ Export
            </button>
          </div>

          <div class="diff-files">
            ${changes.map((change, index) => renderFileChange(change, index)).join('')}
          </div>

          <div class="diff-footer" role="group" aria-label="Apply or cancel changes">
             <button class="btn-rollback" data-action="rollback" aria-label="Emergency Rollback" title="Revert file system to pre-proposal state">
              ☈ Emergency Rollback
            </button>
            <div class="spacer" style="flex: 1;"></div>
            <button class="btn-cancel" data-action="cancel" aria-label="Cancel and close">
              Cancel
            </button>
            <button class="btn-apply" data-action="apply" aria-label="Apply approved changes">
              Apply Approved Changes
            </button>
          </div>
      </div>
    `;

      container.innerHTML = html;
      bindDiffEvents();

      // Initialize diff rendering for each file
      changes.forEach((change, index) => {
        if (change.operation === 'MODIFY') {
          renderFileDiff(change, index);
        }
      });
    };

    const bindDiffEvents = () => {
      if (!container) return;

      if (actionClickHandler) {
        container.removeEventListener('click', actionClickHandler);
      }

      actionClickHandler = handleActionClick;
      container.addEventListener('click', actionClickHandler);

      const diffFiles = container.querySelector('.diff-files');
      if (diffFiles) {
        diffFiles.addEventListener('click', handleDiffFileClick);
        diffFiles.addEventListener('change', handleApprovalChangeEvent);
      }
    };

    const handleActionClick = (event) => {
      const target = event.target.closest('[data-action]');
      if (!target) return;
      const actionMap = {
        'approve-all': approveAll,
        'reject-all': rejectAll,
        'edit': editProposal,
        'copy': () => copyToClipboard(target),
        'export': exportMarkdown,
        'rollback': rollback,
        'cancel': cancel,
        'apply': applyApproved
      };
      const handler = actionMap[target.dataset.action];
      if (handler) {
        handler();
      }
    };

    const handleDiffFileClick = (event) => {
      const expandBtn = event.target.closest('[data-expand]');
      if (!expandBtn) return;
      const index = parseInt(expandBtn.dataset.expand, 10);
      if (!Number.isNaN(index)) {
        toggleExpand(index);
      }
    };

    const handleApprovalChangeEvent = (event) => {
      if (!event.target.classList.contains('approve-checkbox')) return;
      const index = parseInt(event.target.dataset.index, 10);
      if (!Number.isNaN(index)) {
        toggleApproval(index, event.target.checked);
      }
    };

    // Get change statistics
    const getChangeStats = (changes) => {
      const stats = { CREATE: 0, MODIFY: 0, DELETE: 0 };
      changes.forEach(c => stats[c.operation]++);

      return `
        <span class="stat-create">+${stats.CREATE} new</span>
        <span class="stat-modify">~${stats.MODIFY} modified</span>
        <span class="stat-delete">-${stats.DELETE} deleted</span>
      `;
    };

    // Render a single file change
    const renderFileChange = (change, index) => {
      const icon = {
        CREATE: '☩',
        MODIFY: '✎',
        DELETE: '✄'
      }[change.operation];

      return `
        <div class="diff-file" data-index="${index}" role="article">
          <div class="diff-file-header" id="diff-header-${index}">
            <div class="diff-file-info">
              <span class="diff-icon" aria-hidden="true">${icon}</span>
              <span class="diff-path">${change.file_path}</span>
              <span class="diff-operation ${change.operation.toLowerCase()}">${change.operation}</span>
            </div>
            <div class="diff-file-actions">
              <label class="checkbox-wrapper">
                <input type="checkbox"
                       class="approve-checkbox"
                       data-index="${index}"
                       ${change.approved ? 'checked' : ''}>
                <span>Approve</span>
              </label>
              <button class="btn-expand" data-expand="${index}">
                ${change.operation === 'DELETE' ? 'View' : 'Expand'}
              </button>
            </div>
          </div>
          <div class="diff-file-content" id="diff-content-${index}" style="display: none;">
            ${renderChangeContent(change, index)}
          </div>
        </div>
      `;
    };

    // Render the content of a change
    const renderChangeContent = (change, index) => {
      const language = detectLanguage(change.file_path);

      if (change.operation === 'CREATE') {
        const highlightedCode = highlightCode(change.new_content, language);
        const lines = change.new_content.split('\n').length;
        return `
          <div class="diff-create">
            <div class="diff-stats-summary">
              <span class="diff-stat-item added">+${lines} lines</span>
            </div>
            <pre class="code-block language-${language}"><code>${highlightedCode}</code></pre>
          </div>
        `;
      } else if (change.operation === 'DELETE') {
        const content = change.old_content || 'File will be deleted';
        const highlightedCode = change.old_content ? highlightCode(content, language) : content;
        const lines = change.old_content ? change.old_content.split('\n').length : 0;
        return `
          <div class="diff-delete">
            <div class="diff-stats-summary">
              <span class="diff-stat-item removed">-${lines} lines</span>
            </div>
            <pre class="code-block language-${language}"><code>${highlightedCode}</code></pre>
          </div>
        `;
      } else if (change.operation === 'MODIFY') {
        return `<div class="diff-modify" id="diff-modify-${index}">Loading diff...</div>`;
      }
    };

    // Render a file diff for MODIFY operations
    const renderFileDiff = async (change, index) => {
      const container = document.getElementById(`diff-modify-${index}`);
      if (!container) return;

      try {
        const oldContent = await StateManager.getArtifactContent(change.file_path) || '';
        const newContent = change.new_content;
        const diffHtml = generateSideBySideDiff(oldContent, newContent, change.file_path);
        container.innerHTML = diffHtml;
      } catch (error) {
        container.innerHTML = '<div class="error">Failed to load diff</div>';
      }
    };

    // Detect language from file path
    const detectLanguage = (filePath) => {
      const ext = filePath.split('.').pop().toLowerCase();
      const langMap = {
        'js': 'javascript', 'ts': 'typescript', 'json': 'json', 'css': 'css', 'html': 'markup', 'py': 'python', 'md': 'markdown'
      };
      return langMap[ext] || 'javascript';
    };

    // Apply syntax highlighting
    const highlightCode = (code, language) => {
      if (typeof Prism === 'undefined' || !Prism.languages[language]) {
        return escapeHtml(code);
      }
      try {
        return Prism.highlight(code, Prism.languages[language], language);
      } catch (err) {
        return escapeHtml(code);
      }
