}","/capabilities/cognition/cognition-api.js":"/**
 * @fileoverview Cognition API
 * Unified entry point for the neurosymbolic cognition system.
 * Orchestrates semantic memory, symbolic reasoning, and learning.
 */

const CognitionAPI = {
  metadata: {
    id: 'CognitionAPI',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: [
      'Utils',
      'EventBus',
      'SemanticMemory',
      'KnowledgeGraph',
      'RuleEngine',
      'SymbolGrounder'
    ],
    async: true,
    type: 'capability'
  },

  factory: (deps) => {
    const {
      Utils,
      EventBus,
      SemanticMemory,
      KnowledgeGraph,
      RuleEngine,
      SymbolGrounder
    } = deps;
    const { logger, generateId } = Utils;

    // State
    let _isInitialized = false;
    let _config = {
      semantic: { enabled: true },
      symbolic: { enabled: true },
      learning: { enabled: true, autoLearn: true, minConfidence: 0.8 }
    };

    // Circuit breakers for graceful degradation
    const _circuits = {
      semantic: { failures: 0, lastFailure: 0, open: false },
      symbolic: { failures: 0, lastFailure: 0, open: false },
      learning: { failures: 0, lastFailure: 0, open: false }
    };

    const CIRCUIT_THRESHOLD = 3;
    const CIRCUIT_RESET_MS = 60000;

    // --- Lifecycle ---

    const init = async () => {
      if (_isInitialized) return true;

      logger.info('[CognitionAPI] Initializing...');

      try {
        // Initialize subsystems in parallel where possible
        await Promise.all([
          KnowledgeGraph.init(),
          RuleEngine.init()
        ]);

        // SemanticMemory loads model lazily
        await SemanticMemory.init();

        _isInitialized = true;
        logger.info('[CognitionAPI] Initialized successfully');

        EventBus.emit('cognition:status', {
          subsystem: 'all',
          state: 'ready'
        });

        return true;
      } catch (err) {
        logger.error('[CognitionAPI] Initialization failed', err);
        throw err;
      }
    };

    // --- Circuit Breaker Logic ---

    const isCircuitOpen = (subsystem) => {
      const circuit = _circuits[subsystem];
      if (!circuit?.open) return false;

      // Check if circuit should reset
      if (Date.now() - circuit.lastFailure > CIRCUIT_RESET_MS) {
        circuit.open = false;
        circuit.failures = 0;
        logger.info(`[CognitionAPI] Circuit ${subsystem} reset`);
        return false;
      }

      return true;
    };

    const recordFailure = (subsystem) => {
      const circuit = _circuits[subsystem];
      if (!circuit) return;

      circuit.failures++;
      circuit.lastFailure = Date.now();

      if (circuit.failures >= CIRCUIT_THRESHOLD) {
        circuit.open = true;
        logger.warn(`[CognitionAPI] Circuit ${subsystem} opened after ${circuit.failures} failures`);
        EventBus.emit('cognition:degraded', {
          subsystem,
          reason: 'Circuit breaker opened'
        });
      }
    };

    const recordSuccess = (subsystem) => {
      const circuit = _circuits[subsystem];
      if (!circuit) return;

      if (circuit.failures > 0) {
        circuit.failures = Math.max(0, circuit.failures - 1);
      }
    };

    // --- Semantic Memory Interface ---

    const semantic = {
      async enrich(query, context = []) {
        if (!_config.semantic.enabled || isCircuitOpen('semantic')) {
          return context;
        }

        try {
          const result = await SemanticMemory.enrich(query, context);
          recordSuccess('semantic');
          return result;
        } catch (err) {
          logger.warn('[CognitionAPI] Semantic enrichment failed', err);
          recordFailure('semantic');
          return context;
        }
      },

      async search(query, options = {}) {
        if (!_config.semantic.enabled || isCircuitOpen('semantic')) {
          return [];
        }

        try {
          const result = await SemanticMemory.search(query, options);
          recordSuccess('semantic');
          return result;
        } catch (err) {
          logger.warn('[CognitionAPI] Semantic search failed', err);
          recordFailure('semantic');
          return [];
        }
      },

      async store(text, metadata = {}) {
        if (!_config.semantic.enabled || isCircuitOpen('semantic')) {
          return null;
        }

        try {
          const result = await SemanticMemory.store(text, metadata);
          recordSuccess('semantic');
          return result;
        } catch (err) {
          logger.warn('[CognitionAPI] Semantic store failed', err);
          recordFailure('semantic');
          return null;
        }
      },

      async embed(text) {
        if (!_config.semantic.enabled || isCircuitOpen('semantic')) {
          return null;
        }

        try {
          const result = await SemanticMemory.embed(text);
          recordSuccess('semantic');
          return result;
        } catch (err) {
          recordFailure('semantic');
          throw err;
        }
      },

      getStats: () => SemanticMemory.getStats()
    };

    // --- Symbolic Engine Interface ---

    const symbolic = {
      async validate(response, context = {}) {
        if (!_config.symbolic.enabled || isCircuitOpen('symbolic')) {
          return { valid: true, skipped: true, violations: [] };
        }

        try {
          // Ground the response to symbolic entities
          const grounding = await SymbolGrounder.ground(response, context);

          // Run validation
          const validation = await RuleEngine.validate();

          recordSuccess('symbolic');

          return {
            valid: validation.valid,
            violations: validation.violations,
            suggestions: validation.suggestions,
            grounding
          };
        } catch (err) {
          logger.warn('[CognitionAPI] Symbolic validation failed', err);
          recordFailure('symbolic');
          return { valid: true, skipped: true, violations: [] };
        }
      },

      async infer() {
        if (!_config.symbolic.enabled || isCircuitOpen('symbolic')) {
          return [];
        }

        try {
          const result = await RuleEngine.infer();
          recordSuccess('symbolic');
          return result;
        } catch (err) {
          logger.warn('[CognitionAPI] Symbolic inference failed', err);
          recordFailure('symbolic');
          return [];
        }
      },

      addEntity: (entity) => KnowledgeGraph.addEntity(entity),
      getEntity: (id) => KnowledgeGraph.getEntity(id),
      addTriple: (s, p, o, m) => KnowledgeGraph.addTriple(s, p, o, m),
      query: (pattern) => KnowledgeGraph.query(pattern),
      addRule: (rule) => RuleEngine.addRule(rule),
      addConstraint: (c) => RuleEngine.addConstraint(c),

      getStats: () => ({
        ...KnowledgeGraph.getStats(),
        ...RuleEngine.getStats()
      })
    };

    // --- Learning Interface ---

    const learning = {
      async extract(response, context = {}) {
        if (!_config.learning.enabled || isCircuitOpen('learning')) {
          return { learned: false, deferred: true };
        }

        try {
          // Ground the response
          const grounding = await SymbolGrounder.ground(response, context);

          // Filter by confidence threshold
          const highConfidenceEntities = grounding.newEntities.filter(
            e => e.score >= _config.learning.minConfidence
          );

          const highConfidenceRelations = grounding.relations.filter(
            r => r.confidence >= _config.learning.minConfidence
          );

          // Auto-learn if enabled
          if (_config.learning.autoLearn) {
            await SymbolGrounder.integrateGrounding({
              ...grounding,
              newEntities: highConfidenceEntities,
              relations: highConfidenceRelations
            });

            // Store in semantic memory
            if (response.length > 50) {
              await SemanticMemory.store(response, {
                domain: context.domain || 'conversation',
                source: 'assistant'
              });
            }
          }

          recordSuccess('learning');

          EventBus.emit('cognition:learning:extract', {
            entities: highConfidenceEntities.length,
            relations: highConfidenceRelations.length
          });

          return {
            learned: true,
            entities: highConfidenceEntities.length,
            relations: highConfidenceRelations.length,
            grounding
          };
        } catch (err) {
          logger.warn('[CognitionAPI] Learning extraction failed', err);
          recordFailure('learning');
          return { learned: false, error: err.message };
        }
      },

      async feedback(responseId, quality, corrections = {}) {
        // Future: Use feedback for reinforcement learning
        EventBus.emit('cognition:learning:feedback', {
          responseId,
          quality,
          corrections
        });
        return true;
      }
    };

    // --- Unified Query Interface ---

    const query = async (input, options = {}) => {
      const queryId = generateId('cog');
      const startTime = Date.now();

      EventBus.emit('cognition:query:start', { queryId, input: input.slice?.(0, 100) });

      try {
        const result = {
          queryId,
          enrichment: null,
          validation: null,
          learned: null,
          metadata: {
            subsystemsUsed: [],
            duration: 0
          }
        };

        // Phase 1: Semantic enrichment (pre-processing)
        if (options.useSemanticEnrichment !== false && _config.semantic.enabled) {
          result.enrichment = await semantic.enrich(
            input.query || input,
            input.context || []
          );
          result.metadata.subsystemsUsed.push('semantic');
        }

        // Phase 2: Neural inference is handled externally by LLMClient

        // Phase 3: Symbolic validation (post-processing)
        if (options.useSymbolicValidation !== false && _config.symbolic.enabled && input.response) {
          result.validation = await symbolic.validate(input.response, {
            cycle: input.cycle
          });
          result.metadata.subsystemsUsed.push('symbolic');
        }

        // Phase 4: Learning (post-response)
        if (options.enableLearning !== false && _config.learning.enabled && input.response) {
          result.learned = await learning.extract(input.response, {
            cycle: input.cycle,
            domain: input.domain
          });
          result.metadata.subsystemsUsed.push('learning');
        }

        result.metadata.duration = Date.now() - startTime;

        EventBus.emit('cognition:query:complete', {
          queryId,
          duration: result.metadata.duration
        });

        return result;
      } catch (err) {
        EventBus.emit('cognition:query:error', {
          queryId,
          error: err.message
        });
        throw err;
      }
    };

    // --- Configuration ---

    const configure = (newConfig) => {
      _config = {
        ..._config,
        ...newConfig,
        semantic: { ..._config.semantic, ...newConfig.semantic },
        symbolic: { ..._config.symbolic, ...newConfig.symbolic },
        learning: { ..._config.learning, ...newConfig.learning }
      };
      logger.info('[CognitionAPI] Configuration updated', _config);
    };

    const getConfig = () => ({ ..._config });

    // --- Status & Health ---

    const getStatus = () => ({
      initialized: _isInitialized,
      config: _config,
      circuits: {
        semantic: { ...(_circuits.semantic), open: isCircuitOpen('semantic') },
        symbolic: { ...(_circuits.symbolic), open: isCircuitOpen('symbolic') },
        learning: { ...(_circuits.learning), open: isCircuitOpen('learning') }
      }
    });

    const healthCheck = async () => {
      const status = {
        semantic: false,
        symbolic: false,
        learning: false
      };

      try {
        await SemanticMemory.getStats();
        status.semantic = true;
      } catch {}

      try {
        KnowledgeGraph.getStats();
        status.symbolic = true;
      } catch {}

      status.learning = status.semantic && status.symbolic;

      return status;
    };

    // --- Cleanup ---

    const dispose = async () => {
      await SemanticMemory.dispose();
      _isInitialized = false;
      logger.info('[CognitionAPI] Disposed');
    };

    return {
      init,
      query,
      semantic,
      symbolic,
      learning,
      configure,
      getConfig,
      getStatus,
      healthCheck,
      dispose
    };
  }
};

export default CognitionAPI;
","/capabilities/cognition/semantic/embedding-store.js":"/**
 * @fileoverview Embedding Store
 * IndexedDB-backed storage for semantic memory embeddings.
 * Provides vector storage, similarity search, and LRU pruning.
 */

const EmbeddingStore = {
  metadata: {
    id: 'EmbeddingStore',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils'],
    async: true,
    type: 'service'
  },

  factory: (deps) => {
    const { Utils } = deps;
    const { logger, generateId, Errors } = Utils;

    const DB_NAME = 'reploid-semantic-v1';
    const STORE_MEMORIES = 'memories';
    const STORE_VOCAB = 'vocabulary';
    const MAX_MEMORIES = 10000;

    let db = null;

    // --- Database Setup ---

    const openDB = () => {
      return new Promise((resolve, reject) => {
        if (db) return resolve(db);

        const request = indexedDB.open(DB_NAME, 1);

        request.onupgradeneeded = (event) => {
          const d = event.target.result;

          // Memories store
          if (!d.objectStoreNames.contains(STORE_MEMORIES)) {
            const memStore = d.createObjectStore(STORE_MEMORIES, { keyPath: 'id' });
            memStore.createIndex('timestamp', 'timestamp', { unique: false });
            memStore.createIndex('domain', 'domain', { unique: false });
            memStore.createIndex('accessCount', 'accessCount', { unique: false });
          }

          // Vocabulary store
          if (!d.objectStoreNames.contains(STORE_VOCAB)) {
            const vocabStore = d.createObjectStore(STORE_VOCAB, { keyPath: 'token' });
            vocabStore.createIndex('frequency', 'frequency', { unique: false });
            vocabStore.createIndex('lastSeen', 'lastSeen', { unique: false });
          }
        };

        request.onsuccess = (e) => {
          db = e.target.result;
          logger.info('[EmbeddingStore] Database connected');
          resolve(db);
        };

        request.onerror = () => {
          reject(new Errors.StateError('Failed to open EmbeddingStore DB'));
        };
      });
    };

    const init = async () => {
      await openDB();
      return true;
    };

    // --- Memory Operations ---

    const addMemory = async (memory) => {
      await openDB();
      const id = memory.id || generateId('mem');

      const entry = {
        id,
        content: memory.content,
        embedding: memory.embedding, // Float32Array or array
        domain: memory.domain || 'general',
        timestamp: Date.now(),
        accessCount: 0,
        source: memory.source || 'assistant',
        metadata: memory.metadata || {}
      };

      return new Promise((resolve, reject) => {
        const tx = db.transaction([STORE_MEMORIES], 'readwrite');
        const store = tx.objectStore(STORE_MEMORIES);
        store.put(entry).onsuccess = () => {
          logger.debug(`[EmbeddingStore] Added memory: ${id}`);
          resolve(id);
        };
        tx.onerror = () => reject(new Errors.ArtifactError(`Failed to add memory: ${id}`));
      });
    };

    const getMemory = async (id) => {
      await openDB();
      return new Promise((resolve, reject) => {
        const tx = db.transaction([STORE_MEMORIES], 'readonly');
        const req = tx.objectStore(STORE_MEMORIES).get(id);
        req.onsuccess = () => resolve(req.result || null);
        req.onerror = () => reject(new Errors.ArtifactError(`Failed to get memory: ${id}`));
      });
    };

    const getAllMemories = async () => {
      await openDB();
      return new Promise((resolve, reject) => {
        const tx = db.transaction([STORE_MEMORIES], 'readonly');
        const req = tx.objectStore(STORE_MEMORIES).getAll();
        req.onsuccess = () => resolve(req.result || []);
        req.onerror = () => reject(new Errors.ArtifactError('Failed to get all memories'));
      });
    };

    const updateAccessCount = async (id) => {
      await openDB();
      const memory = await getMemory(id);
      if (!memory) return;

      memory.accessCount = (memory.accessCount || 0) + 1;

      return new Promise((resolve, reject) => {
        const tx = db.transaction([STORE_MEMORIES], 'readwrite');
        const store = tx.objectStore(STORE_MEMORIES);
        store.put(memory).onsuccess = () => resolve(true);
        tx.onerror = () => reject(new Errors.ArtifactError(`Failed to update access count: ${id}`));
      });
    };

    const deleteMemory = async (id) => {
      await openDB();
      return new Promise((resolve, reject) => {
        const tx = db.transaction([STORE_MEMORIES], 'readwrite');
        const req = tx.objectStore(STORE_MEMORIES).delete(id);
        req.onsuccess = () => {
          logger.debug(`[EmbeddingStore] Deleted memory: ${id}`);
          resolve(true);
        };
        req.onerror = () => reject(new Errors.ArtifactError(`Failed to delete memory: ${id}`));
      });
    };

    // --- Similarity Search ---

    const cosineSimilarity = (a, b) => {
      if (!a || !b || a.length !== b.length) return 0;

      let dotProduct = 0;
      let normA = 0;
      let normB = 0;

      for (let i = 0; i < a.length; i++) {
        dotProduct += a[i] * b[i];
        normA += a[i] * a[i];
        normB += b[i] * b[i];
      }

      const magnitude = Math.sqrt(normA) * Math.sqrt(normB);
      return magnitude === 0 ? 0 : dotProduct / magnitude;
    };

    const searchSimilar = async (queryEmbedding, topK = 5, minSimilarity = 0.5) => {
      const memories = await getAllMemories();
      const queryArray = Array.isArray(queryEmbedding)
        ? queryEmbedding
        : Array.from(queryEmbedding);

      const scored = memories
        .filter(m => m.embedding && m.embedding.length > 0)
        .map(m => {
          const embArray = Array.isArray(m.embedding)
            ? m.embedding
            : Array.from(m.embedding);
          const similarity = cosineSimilarity(queryArray, embArray);
          return { memory: m, similarity };
        })
        .filter(item => item.similarity >= minSimilarity)
        .sort((a, b) => b.similarity - a.similarity)
        .slice(0, topK);

      // Update access counts for returned memories
      for (const item of scored) {
        await updateAccessCount(item.memory.id);
      }

      return scored;
    };

    // --- Vocabulary Operations ---

    const updateVocabulary = async (tokens) => {
      await openDB();
      const now = Date.now();

      return new Promise((resolve, reject) => {
        const tx = db.transaction([STORE_VOCAB], 'readwrite');
        const store = tx.objectStore(STORE_VOCAB);

        let completed = 0;
        const total = tokens.length;

        for (const token of tokens) {
          const getReq = store.get(token);
          getReq.onsuccess = () => {
            const existing = getReq.result;
            const entry = existing || { token, frequency: 0, domains: [] };
            entry.frequency += 1;
            entry.lastSeen = now;
            store.put(entry);
            completed++;
            if (completed === total) resolve(true);
          };
        }

        if (total === 0) resolve(true);
        tx.onerror = () => reject(new Errors.ArtifactError('Failed to update vocabulary'));
      });
    };

    const getVocabulary = async () => {
      await openDB();
      return new Promise((resolve, reject) => {
        const tx = db.transaction([STORE_VOCAB], 'readonly');
        const req = tx.objectStore(STORE_VOCAB).getAll();
        req.onsuccess = () => resolve(req.result || []);
        req.onerror = () => reject(new Errors.ArtifactError('Failed to get vocabulary'));
      });
    };

    // --- Maintenance ---

    const pruneOldMemories = async (maxAge = 7 * 24 * 60 * 60 * 1000) => {
      const memories = await getAllMemories();
      const now = Date.now();
      const cutoff = now - maxAge;

      // Sort by accessCount (LRU), then timestamp
      const candidates = memories
        .filter(m => m.timestamp < cutoff)
        .sort((a, b) => a.accessCount - b.accessCount || a.timestamp - b.timestamp);

      // Delete excess memories
      const toDelete = candidates.slice(0, Math.max(0, memories.length - MAX_MEMORIES));
      let deleted = 0;

      for (const memory of toDelete) {
        await deleteMemory(memory.id);
        deleted++;
      }

      if (deleted > 0) {
        logger.info(`[EmbeddingStore] Pruned ${deleted} old memories`);
      }

      return deleted;
    };

    const getStats = async () => {
      const memories = await getAllMemories();
      const vocab = await getVocabulary();

      return {
        memoryCount: memories.length,
        vocabularySize: vocab.length,
        maxMemories: MAX_MEMORIES,
        oldestMemory: memories.length > 0
          ? Math.min(...memories.map(m => m.timestamp))
          : null
      };
    };

    const clear = async () => {
      await openDB();
      return new Promise((resolve, reject) => {
        const tx = db.transaction([STORE_MEMORIES, STORE_VOCAB], 'readwrite');
        tx.objectStore(STORE_MEMORIES).clear();
        tx.objectStore(STORE_VOCAB).clear();
        tx.oncomplete = () => {
          logger.info('[EmbeddingStore] Cleared all data');
          resolve(true);
        };
        tx.onerror = () => reject(new Errors.ArtifactError('Failed to clear store'));
      });
    };

    return {
      init,
      addMemory,
      getMemory,
      getAllMemories,
      deleteMemory,
      searchSimilar,
      updateVocabulary,
      getVocabulary,
      pruneOldMemories,
      getStats,
      clear
    };
  }
};

export default EmbeddingStore;
","/capabilities/cognition/semantic/semantic-memory.js":"/**
 * @fileoverview Semantic Memory
 * Evolving word embeddings that learn from conversations.
 * Uses Transformers.js for browser-native embedding generation.
 */

const SemanticMemory = {
  metadata: {
    id: 'SemanticMemory',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'EventBus', 'EmbeddingStore'],
    async: true,
    type: 'capability'
  },

  factory: (deps) => {
    const { Utils, EventBus, EmbeddingStore } = deps;
    const { logger, generateId, Errors } = Utils;

    // State
    let _extractor = null;
    let _loaderPromise = null;
    let _isInitialized = false;

    // Configuration
    const CONFIG = {
      model: 'Xenova/all-MiniLM-L6-v2', // 384-dim, fast
      minSimilarity: 0.5,
      topK: 5,
      batchSize: 10,
      idleTrainingDelay: 2000
    };

    // Training queue for idle-time processing
    let _trainingQueue = [];
    let _idleCallbackId = null;

    // --- Transformers.js Setup ---

    const ensureTransformersReady = async () => {
      if (typeof window === 'undefined') {
        throw new Errors.ConfigError('SemanticMemory requires browser environment');
      }

      if (window.transformers?.pipeline) return window.transformers;
      if (_loaderPromise) return _loaderPromise;

      _loaderPromise = import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@3')
        .then(mod => {
          window.transformers = {
            pipeline: mod.pipeline,
            env: mod.env
          };
          mod.env.backends.onnx.wasm.proxy = false;
          return window.transformers;
        })
        .catch(err => {
          _loaderPromise = null;
          logger.error('[SemanticMemory] Failed to load Transformers.js', err);
          throw new Errors.ConfigError('Failed to load Transformers.js');
        });

      return _loaderPromise;
    };

    const loadEmbeddingModel = async () => {
      if (_extractor) return _extractor;

      const tf = await ensureTransformersReady();

      logger.info(`[SemanticMemory] Loading embedding model: ${CONFIG.model}`);

      EventBus.emit('cognition:status', {
        subsystem: 'semantic',
        state: 'loading',
        message: 'Loading embedding model...'
      });

      try {
        _extractor = await tf.pipeline('feature-extraction', CONFIG.model, {
          device: navigator.gpu ? 'webgpu' : 'wasm',
          dtype: 'fp32',
          progress_callback: (progress) => {
            if (progress.status === 'progress' && progress.total > 0) {
              const percent = Math.round((progress.loaded / progress.total) * 100);
              EventBus.emit('cognition:status', {
                subsystem: 'semantic',
                state: 'loading',
                progress: percent,
                message: `Loading model: ${percent}%`
              });
            }
          }
        });

        logger.info('[SemanticMemory] Embedding model loaded');
        EventBus.emit('cognition:status', {
          subsystem: 'semantic',
          state: 'ready',
          message: 'Embedding model ready'
        });

        return _extractor;
      } catch (err) {
        logger.error('[SemanticMemory] Failed to load embedding model', err);
        _extractor = null;
        throw new Errors.ApiError('Failed to load embedding model');
      }
    };

    // --- Core API ---

    const init = async () => {
      if (_isInitialized) return true;

      await EmbeddingStore.init();
      // Don't load model eagerly - load on first use
      _isInitialized = true;

      // Listen for conversation events for auto-learning
      EventBus.on('agent:history', handleAgentHistory);

      logger.info('[SemanticMemory] Initialized');
      return true;
    };

    const embed = async (text) => {
      if (!text || typeof text !== 'string') {
        throw new Errors.ValidationError('Text is required for embedding');
      }

      await loadEmbeddingModel();

      try {
        const output = await _extractor(text, {
          pooling: 'mean',
          normalize: true
        });

        // Convert to regular array for storage
        const embedding = Array.from(output.data);

        EventBus.emit('cognition:semantic:embed', {
          text: text.slice(0, 50) + '...',
          dimensions: embedding.length
        });

        return embedding;
      } catch (err) {
        logger.error('[SemanticMemory] Embedding failed', err);
        throw new Errors.ApiError('Failed to generate embedding');
      }
    };

    const embedBatch = async (texts) => {
      const embeddings = [];
      for (const text of texts) {
        const emb = await embed(text);
        embeddings.push(emb);
      }
      return embeddings;
    };

    const store = async (text, metadata = {}) => {
      const embedding = await embed(text);

      const id = await EmbeddingStore.addMemory({
        content: text,
        embedding,
        domain: metadata.domain || 'general',
        source: metadata.source || 'assistant',
        metadata
      });

      // Update vocabulary with tokens
      const tokens = tokenize(text);
      await EmbeddingStore.updateVocabulary(tokens);

      EventBus.emit('cognition:semantic:store', { id, text: text.slice(0, 50) });

      return id;
    };

    const search = async (query, options = {}) => {
      const { topK = CONFIG.topK, minSimilarity = CONFIG.minSimilarity } = options;

      const queryEmbedding = await embed(query);
      const results = await EmbeddingStore.searchSimilar(queryEmbedding, topK, minSimilarity);

      EventBus.emit('cognition:semantic:search', {
        query: query.slice(0, 50),
        results: results.length
      });

      return results.map(r => ({
        id: r.memory.id,
        content: r.memory.content,
        similarity: r.similarity,
        domain: r.memory.domain,
        timestamp: r.memory.timestamp
      }));
    };

    const enrich = async (query, context = []) => {
      try {
        const relevantMemories = await search(query, { topK: 3 });

        if (relevantMemories.length === 0) {
          return context;
        }

        // Build memory context string
        const memoryContext = relevantMemories
          .map(m => `[Memory ${m.domain}] ${m.content.slice(0, 200)}`)
          .join('\n');

        // find insertion point (after system messages)
        const enrichedContext = [...context];
        const insertIdx = enrichedContext.findIndex(m => m.role !== 'system');
        const idx = insertIdx === -1 ? enrichedContext.length : insertIdx;

        enrichedContext.splice(idx, 0, {
          role: 'system',
          content: `Relevant context from memory:\n${memoryContext}`
        });

        logger.debug(`[SemanticMemory] Enriched context with ${relevantMemories.length} memories`);

        return enrichedContext;
      } catch (err) {
        logger.warn('[SemanticMemory] Enrichment failed, using original context', err);
        return context;
      }
    };

    // --- Tokenization ---

    const tokenize = (text) => {
      if (!text) return [];
      return text
        .toLowerCase()
        .replace(/[^\w\s]/g, ' ')
        .split(/\s+/)
        .filter(t => t.length > 2);
    };

    // --- Idle-time Learning ---

    const handleAgentHistory = (event) => {
      if (event.type === 'llm_response' && event.content) {
        queueForLearning({
          content: event.content,
          source: 'assistant',
          domain: 'conversation'
        });
      } else if (event.type === 'tool_result' && event.result) {
        queueForLearning({
          content: typeof event.result === 'string' ? event.result : JSON.stringify(event.result),
          source: 'tool',
          domain: event.tool || 'tool'
        });
      }
    };

    const queueForLearning = (item) => {
      _trainingQueue.push(item);

      // Schedule idle-time processing
      if (!_idleCallbackId && _trainingQueue.length >= CONFIG.batchSize) {
        scheduleIdleLearning();
      }
    };

    const scheduleIdleLearning = () => {
      if ('requestIdleCallback' in window) {
        _idleCallbackId = requestIdleCallback(processLearningQueue, {
          timeout: 60000 // Max 1 minute wait
        });
      } else {
        // Fallback for Safari
        _idleCallbackId = setTimeout(processLearningQueue, CONFIG.idleTrainingDelay);
      }
    };

    const processLearningQueue = async (deadline) => {
      _idleCallbackId = null;

      const hasTimeRemaining = deadline?.timeRemaining
        ? () => deadline.timeRemaining() > 10
        : () => true;

      let processed = 0;

      while (_trainingQueue.length > 0 && hasTimeRemaining() && processed < CONFIG.batchSize) {
        const item = _trainingQueue.shift();

        try {
          // Only store substantial content
          if (item.content && item.content.length > 50) {
            await store(item.content, {
              source: item.source,
              domain: item.domain
            });
            processed++;
          }
        } catch (err) {
          logger.warn('[SemanticMemory] Failed to process learning item', err);
        }
      }

      if (processed > 0) {
        logger.debug(`[SemanticMemory] Processed ${processed} items from learning queue`);
        EventBus.emit('cognition:learning:semantic', { processed });
      }

      // Reschedule if more items pending
      if (_trainingQueue.length > 0) {
        scheduleIdleLearning();
      }
    };

    // --- Maintenance ---

    const prune = async () => {
      return EmbeddingStore.pruneOldMemories();
    };

    const getStats = async () => {
      const storeStats = await EmbeddingStore.getStats();
      return {
        ...storeStats,
        modelLoaded: !!_extractor,
        model: CONFIG.model,
        queueSize: _trainingQueue.length
      };
    };

    const clear = async () => {
      _trainingQueue = [];
      if (_idleCallbackId) {
        if ('cancelIdleCallback' in window) {
          cancelIdleCallback(_idleCallbackId);
        } else {
          clearTimeout(_idleCallbackId);
        }
        _idleCallbackId = null;
      }
      return EmbeddingStore.clear();
    };

    const dispose = async () => {
      await clear();
      EventBus.off('agent:history', handleAgentHistory);
      if (_extractor?.dispose) {
        await _extractor.dispose();
      }
      _extractor = null;
      _isInitialized = false;
      logger.info('[SemanticMemory] Disposed');
    };

    return {
      init,
      embed,
      embedBatch,
      store,
      search,
      enrich,
      prune,
      getStats,
      clear,
      dispose
    };
  }
};

export default SemanticMemory;
","/capabilities/cognition/symbolic/knowledge-graph.js":"/**
 * @fileoverview Knowledge Graph
 * Entity-relationship store for symbolic reasoning.
 * Provides RDF-like triple storage with confidence tracking.
 */

const KnowledgeGraph = {
  metadata: {
    id: 'KnowledgeGraph',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'VFS', 'EventBus'],
    async: true,
    type: 'service'
  },

  factory: (deps) => {
    const { Utils, VFS, EventBus } = deps;
    const { logger, generateId } = Utils;

    const STORE_PATH = '/.memory/knowledge-graph.json';
    const MAX_ENTITIES = 10000;
    const MAX_TRIPLES = 50000;
    const CONFIDENCE_DECAY_RATE = 0.999; // Per hour

    // In-memory graph structure
    let _entities = new Map();
    let _triples = [];
    let _predicateIndex = new Map(); // predicate -> triple indices
    let _subjectIndex = new Map();   // subject -> triple indices
    let _objectIndex = new Map();    // object -> triple indices

    // --- Persistence ---

    const init = async () => {
      if (await VFS.exists(STORE_PATH)) {
        try {
          const content = await VFS.read(STORE_PATH);
          const data = JSON.parse(content);
          deserialize(data);
          logger.info(`[KnowledgeGraph] Loaded ${_entities.size} entities, ${_triples.length} triples`);
        } catch (e) {
          logger.error('[KnowledgeGraph] Corrupt store, starting fresh', e);
          _entities = new Map();
          _triples = [];
        }
      }
      rebuildIndices();
      return true;
    };

    const save = async () => {
      if (!await VFS.exists('/.memory')) {
        await VFS.mkdir('/.memory');
      }
      const data = serialize();
      await VFS.write(STORE_PATH, JSON.stringify(data, null, 2));
    };

    const serialize = () => ({
      entities: Array.from(_entities.entries()),
      triples: _triples,
      version: 1
    });

    const deserialize = (data) => {
      _entities = new Map(data.entities || []);
      _triples = data.triples || [];
    };

    const rebuildIndices = () => {
      _predicateIndex = new Map();
      _subjectIndex = new Map();
      _objectIndex = new Map();

      _triples.forEach((triple, idx) => {
        addToIndex(_predicateIndex, triple.predicate, idx);
        addToIndex(_subjectIndex, triple.subject, idx);
        if (typeof triple.object === 'string') {
          addToIndex(_objectIndex, triple.object, idx);
        }
      });
    };

    const addToIndex = (index, key, value) => {
      if (!index.has(key)) {
        index.set(key, []);
      }
      index.get(key).push(value);
    };

    // --- Entity Operations ---

    const addEntity = async (entity) => {
      const id = entity.id || generateId('ent');

      const entry = {
        id,
        types: entity.types || ['Entity'],
        labels: entity.labels || { en: id },
        properties: entity.properties || {},
        metadata: {
          confidence: entity.confidence ?? 1.0,
          source: entity.source || 'system',
          timestamp: Date.now(),
          ...entity.metadata
        }
      };

      _entities.set(id, entry);
      await save();

      EventBus.emit('cognition:symbolic:add', { type: 'entity', id });
      logger.debug(`[KnowledgeGraph] Added entity: ${id}`);

      return id;
    };

    const getEntity = (id) => {
      return _entities.get(id) || null;
    };

    const updateEntity = async (id, updates) => {
      const entity = _entities.get(id);
      if (!entity) return null;

      Object.assign(entity, updates);
      entity.metadata.timestamp = Date.now();
      _entities.set(id, entity);
      await save();

      return entity;
    };

    const deleteEntity = async (id) => {
      if (!_entities.has(id)) return false;

      _entities.delete(id);

      // Remove all triples involving this entity
      _triples = _triples.filter(t => t.subject !== id && t.object !== id);
      rebuildIndices();
      await save();

      logger.debug(`[KnowledgeGraph] Deleted entity: ${id}`);
      return true;
    };

    const getAllEntities = () => {
      return Array.from(_entities.values());
    };

    // --- Triple Operations ---

    const addTriple = async (subject, predicate, object, metadata = {}) => {
      // Validate subject exists or is a literal
      if (!_entities.has(subject) && typeof subject === 'string') {
        // Auto-create entity for unknown subjects
        await addEntity({ id: subject, labels: { en: subject } });
      }

      const triple = {
        id: generateId('trp'),
        subject,
        predicate,
        object,
        metadata: {
          confidence: metadata.confidence ?? 0.8,
          source: metadata.source || 'llm',
          timestamp: Date.now(),
          provenance: metadata.provenance || []
        }
      };

      // Check for duplicate
      const existing = _triples.find(t =>
        t.subject === subject &&
        t.predicate === predicate &&
        t.object === object
      );

      if (existing) {
        // Update confidence if higher
        if (triple.metadata.confidence > existing.metadata.confidence) {
          existing.metadata.confidence = triple.metadata.confidence;
          existing.metadata.timestamp = Date.now();
        }
        await save();
        return existing.id;
      }

      const idx = _triples.length;
      _triples.push(triple);

      // Update indices
      addToIndex(_predicateIndex, predicate, idx);
      addToIndex(_subjectIndex, subject, idx);
      if (typeof object === 'string') {
        addToIndex(_objectIndex, object, idx);
      }

      await save();

      EventBus.emit('cognition:symbolic:add', { type: 'triple', id: triple.id });
      logger.debug(`[KnowledgeGraph] Added triple: ${subject} -[${predicate}]-> ${object}`);

      return triple.id;
    };

    const getTriple = (id) => {
      return _triples.find(t => t.id === id) || null;
    };

    const deleteTriple = async (id) => {
      const idx = _triples.findIndex(t => t.id === id);
      if (idx === -1) return false;

      _triples.splice(idx, 1);
      rebuildIndices();
      await save();

      return true;
    };

    // --- Query Operations ---

    const query = (pattern) => {
      let results = [..._triples];

      if (pattern.subject) {
        const indices = _subjectIndex.get(pattern.subject) || [];
        results = indices.map(i => _triples[i]).filter(Boolean);
      }

      if (pattern.predicate) {
        if (pattern.subject) {
          results = results.filter(t => t.predicate === pattern.predicate);
        } else {
          const indices = _predicateIndex.get(pattern.predicate) || [];
          results = indices.map(i => _triples[i]).filter(Boolean);
        }
      }

      if (pattern.object) {
        results = results.filter(t => t.object === pattern.object);
      }

      if (pattern.minConfidence) {
        results = results.filter(t => t.metadata.confidence >= pattern.minConfidence);
      }

      return results;
    };

    const queryEntities = (pattern) => {
      let results = getAllEntities();

      if (pattern.type) {
        results = results.filter(e => e.types.includes(pattern.type));
      }

      if (pattern.hasProperty) {
        results = results.filter(e => pattern.hasProperty in e.properties);
      }

      if (pattern.label) {
        const labelLower = pattern.label.toLowerCase();
        results = results.filter(e =>
          Object.values(e.labels).some(l => l.toLowerCase().includes(labelLower))
        );
      }

      return results;
    };

    const getRelatedEntities = (entityId, predicate = null) => {
      const outgoing = query({ subject: entityId, predicate });
      const incoming = query({ object: entityId, predicate });

      const related = new Set();

      outgoing.forEach(t => {
        if (typeof t.object === 'string' && _entities.has(t.object)) {
          related.add(t.object);
        }
      });

      incoming.forEach(t => {
        if (_entities.has(t.subject)) {
          related.add(t.subject);
        }
      });

      return Array.from(related).map(id => _entities.get(id));
    };

    // --- Confidence Management ---

    const decayConfidence = async () => {
      const now = Date.now();
      const hourMs = 3600000;
      let updated = 0;

      for (const triple of _triples) {
        if (triple.metadata.source === 'llm') {
          const hoursOld = (now - triple.metadata.timestamp) / hourMs;
          const decayedConfidence = triple.metadata.confidence * Math.pow(CONFIDENCE_DECAY_RATE, hoursOld);

          if (decayedConfidence < 0.3) {
            // Mark for deletion
            triple.metadata.confidence = 0;
            updated++;
          } else if (Math.abs(triple.metadata.confidence - decayedConfidence) > 0.01) {
            triple.metadata.confidence = decayedConfidence;
            updated++;
          }
        }
      }

      // Remove low-confidence triples
      const before = _triples.length;
      _triples = _triples.filter(t => t.metadata.confidence > 0);
      const removed = before - _triples.length;

      if (removed > 0) {
        rebuildIndices();
        await save();
        logger.info(`[KnowledgeGraph] Decayed ${updated} triples, removed ${removed}`);
      }

      return { updated, removed };
    };

    // --- Maintenance ---

    const prune = async () => {
      // Remove entities with no triples
      const usedEntities = new Set();
      for (const triple of _triples) {
        usedEntities.add(triple.subject);
        if (typeof triple.object === 'string') {
          usedEntities.add(triple.object);
        }
      }

      let removed = 0;
      for (const [id, entity] of _entities) {
        if (!usedEntities.has(id) && entity.metadata.source !== 'system') {
          _entities.delete(id);
          removed++;
        }
      }

      if (removed > 0) {
        await save();
        logger.info(`[KnowledgeGraph] Pruned ${removed} orphan entities`);
      }

      return removed;
    };

    const getStats = () => ({
      entityCount: _entities.size,
      tripleCount: _triples.length,
      predicates: Array.from(_predicateIndex.keys()),
      maxEntities: MAX_ENTITIES,
      maxTriples: MAX_TRIPLES
    });

    const clear = async () => {
      _entities = new Map();
      _triples = [];
      _predicateIndex = new Map();
      _subjectIndex = new Map();
      _objectIndex = new Map();
      await save();
      logger.info('[KnowledgeGraph] Cleared all data');
    };

    const exportGraph = () => serialize();

    const importGraph = async (data) => {
      deserialize(data);
      rebuildIndices();
      await save();
      logger.info(`[KnowledgeGraph] Imported ${_entities.size} entities, ${_triples.length} triples`);
    };

    return {
      init,
      addEntity,
      getEntity,
      updateEntity,
      deleteEntity,
      getAllEntities,
      addTriple,
      getTriple,
      deleteTriple,
      query,
      queryEntities,
      getRelatedEntities,
      decayConfidence,
      prune,
      getStats,
      clear,
      exportGraph,
      importGraph
    };
  }
};

export default KnowledgeGraph;
","/capabilities/cognition/symbolic/rule-engine.js":"/**
 * @fileoverview Rule Engine
 * Stratified Datalog-like inference engine for symbolic reasoning.
 * Supports forward chaining, constraint validation, and defeasible rules.
 */

const RuleEngine = {
  metadata: {
    id: 'RuleEngine',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'VFS', 'EventBus', 'KnowledgeGraph'],
    async: true,
    type: 'service'
  },

  factory: (deps) => {
    const { Utils, VFS, EventBus, KnowledgeGraph } = deps;
    const { logger, generateId } = Utils;

    const STORE_PATH = '/.memory/rules.json';

    // Rule storage
    let _rules = [];
    let _constraints = [];
    let _inducedRules = []; // Auto-learned rules

    // --- Persistence ---

    const init = async () => {
      if (await VFS.exists(STORE_PATH)) {
        try {
          const content = await VFS.read(STORE_PATH);
          const data = JSON.parse(content);
          _rules = data.rules || [];
          _constraints = data.constraints || [];
          _inducedRules = data.inducedRules || [];
          logger.info(`[RuleEngine] Loaded ${_rules.length} rules, ${_constraints.length} constraints`);
        } catch (e) {
          logger.error('[RuleEngine] Corrupt store, starting fresh', e);
        }
      }

      // Add built-in rules
      addBuiltinRules();

      return true;
    };

    const save = async () => {
      if (!await VFS.exists('/.memory')) {
        await VFS.mkdir('/.memory');
      }
      await VFS.write(STORE_PATH, JSON.stringify({
        rules: _rules,
        constraints: _constraints,
        inducedRules: _inducedRules
      }, null, 2));
    };

    const addBuiltinRules = () => {
      // Transitivity rule for 'isA'
      if (!_rules.find(r => r.id === 'builtin-isa-transitive')) {
        _rules.push({
          id: 'builtin-isa-transitive',
          head: { predicate: 'isA', args: ['?x', '?z'] },
          body: [
            { predicate: 'isA', args: ['?x', '?y'] },
            { predicate: 'subClassOf', args: ['?y', '?z'] }
          ],
          priority: 100,
          builtin: true
        });
      }

      // Tool failure avoidance rule
      if (!_rules.find(r => r.id === 'builtin-avoid-failing-tool')) {
        _rules.push({
          id: 'builtin-avoid-failing-tool',
          head: { predicate: 'shouldAvoid', args: ['?tool'] },
          body: [
            { predicate: 'failedExecution', args: ['?tool', '?c1'] },
            { predicate: 'failedExecution', args: ['?tool', '?c2'] },
            { predicate: 'failedExecution', args: ['?tool', '?c3'] },
            { predicate: '!=', args: ['?c1', '?c2'] },
            { predicate: '!=', args: ['?c2', '?c3'] },
            { predicate: '!=', args: ['?c1', '?c3'] }
          ],
          priority: 80,
          builtin: true
        });
      }
    };

    // --- Rule Management ---

    const addRule = async (rule) => {
      const id = rule.id || generateId('rule');

      const entry = {
        id,
        head: rule.head,
        body: rule.body || [],
        priority: rule.priority || 50,
        confidence: rule.confidence || 1.0,
        source: rule.source || 'user',
        enabled: rule.enabled !== false
      };

      // Check for duplicate
      const existing = _rules.findIndex(r => r.id === id);
      if (existing >= 0) {
        _rules[existing] = entry;
      } else {
        _rules.push(entry);
      }

      await save();
      EventBus.emit('cognition:symbolic:add', { type: 'rule', id });
      logger.debug(`[RuleEngine] Added rule: ${id}`);

      return id;
    };

    const removeRule = async (id) => {
      const idx = _rules.findIndex(r => r.id === id);
      if (idx === -1) return false;

      if (_rules[idx].builtin) {
        logger.warn(`[RuleEngine] Cannot remove builtin rule: ${id}`);
        return false;
      }

      _rules.splice(idx, 1);
      await save();
      return true;
    };

    const getRules = () => _rules.filter(r => r.enabled);

    // --- Constraint Management ---

    const addConstraint = async (constraint) => {
      const id = constraint.id || generateId('cstr');

      const entry = {
        id,
        body: constraint.body,
        message: constraint.message || 'Constraint violated',
        severity: constraint.severity || 'error',
        enabled: constraint.enabled !== false
      };

      const existing = _constraints.findIndex(c => c.id === id);
      if (existing >= 0) {
        _constraints[existing] = entry;
      } else {
        _constraints.push(entry);
      }

      await save();
      return id;
    };

    const getConstraints = () => _constraints.filter(c => c.enabled);

    // --- Inference Engine ---

    const infer = async (maxIterations = 10) => {
      const allTriples = KnowledgeGraph.query({});
      let facts = allTriples.map(t => ({
        predicate: t.predicate,
        args: [t.subject, t.object],
        source: 'kb',
        confidence: t.metadata.confidence
      }));

      let newFacts = [...facts];
      let iteration = 0;

      while (iteration < maxIterations) {
        const derived = [];
        const rules = getRules().sort((a, b) => b.priority - a.priority);

        for (const rule of rules) {
          const bindings = matchRule(rule, newFacts);

          for (const binding of bindings) {
            const head = instantiate(rule.head, binding);

            // Check if fact already exists
            const exists = facts.some(f =>
              f.predicate === head.predicate &&
              arraysEqual(f.args, head.args)
            );

            if (!exists) {
              derived.push({
                ...head,
                source: 'inferred',
                rule: rule.id,
                confidence: rule.confidence * 0.9, // Slight decay for inferred facts
                bindings: binding
              });
            }
          }
        }

        if (derived.length === 0) break;

        // Add derived facts to KB
        for (const fact of derived) {
          if (fact.args.length === 2 && typeof fact.args[0] === 'string') {
            await KnowledgeGraph.addTriple(
              fact.args[0],
              fact.predicate,
              fact.args[1],
              {
                confidence: fact.confidence,
                source: 'inferred',
                provenance: [`Rule: ${fact.rule}`]
              }
            );
          }
        }

        facts = [...facts, ...derived];
        newFacts = derived;
        iteration++;
      }

      const inferredCount = facts.length - allTriples.length;
      if (inferredCount > 0) {
        logger.info(`[RuleEngine] Inferred ${inferredCount} new facts in ${iteration} iterations`);
        EventBus.emit('cognition:symbolic:infer', {
          inputFacts: allTriples.length,
          inferredFacts: inferredCount
        });
      }

      return facts;
    };

    const matchRule = (rule, facts) => {
      if (!rule.body || rule.body.length === 0) {
        return [{}]; // Empty body matches with empty binding
      }

      let bindings = [{}];

      for (const bodyAtom of rule.body) {
        const newBindings = [];

        for (const binding of bindings) {
          const matches = matchAtom(bodyAtom, facts, binding);
          newBindings.push(...matches);
        }

        bindings = newBindings;
        if (bindings.length === 0) break;
      }

      return bindings;
    };

    const matchAtom = (atom, facts, existingBinding) => {
      const bindings = [];

      // Handle built-in predicates
      if (atom.predicate === '!=') {
        const [a, b] = atom.args.map(arg => resolveArg(arg, existingBinding));
        if (a !== undefined && b !== undefined && a !== b) {
          bindings.push({ ...existingBinding });
        }
        return bindings;
      }

      if (atom.predicate === '=') {
        const [a, b] = atom.args.map(arg => resolveArg(arg, existingBinding));
        if (a !== undefined && b !== undefined && a === b) {
          bindings.push({ ...existingBinding });
        }
        return bindings;
      }

      // Match against facts
      for (const fact of facts) {
        if (fact.predicate !== atom.predicate) continue;
        if (atom.negated && fact) continue; // Simple negation-as-failure

        const newBinding = tryUnify(atom.args, fact.args, existingBinding);
        if (newBinding) {
          bindings.push(newBinding);
        }
      }

      // Handle negation-as-failure
      if (atom.negated && bindings.length === 0) {
        bindings.push({ ...existingBinding });
      }

      return bindings;
    };

    const tryUnify = (pattern, values, binding) => {
      if (pattern.length !== values.length) return null;

      const newBinding = { ...binding };

      for (let i = 0; i < pattern.length; i++) {
        const p = pattern[i];
        const v = values[i];

        if (isVariable(p)) {
          if (p in newBinding) {
            if (newBinding[p] !== v) return null;
          } else {
            newBinding[p] = v;
          }
        } else {
          if (p !== v) return null;
        }
      }

      return newBinding;
    };

    const isVariable = (term) => typeof term === 'string' && term.startsWith('?');

    const resolveArg = (arg, binding) => {
      if (isVariable(arg)) {
        return binding[arg];
      }
      return arg;
    };

    const instantiate = (template, binding) => ({
      predicate: template.predicate,
      args: template.args.map(arg => resolveArg(arg, binding) || arg)
    });

    const arraysEqual = (a, b) => {
      if (a.length !== b.length) return false;
      for (let i = 0; i < a.length; i++) {
        if (a[i] !== b[i]) return false;
      }
      return true;
    };

    // --- Validation ---

    const validate = async (facts = null) => {
      if (!facts) {
        facts = KnowledgeGraph.query({}).map(t => ({
          predicate: t.predicate,
          args: [t.subject, t.object]
        }));
      }

      const violations = [];

      for (const constraint of getConstraints()) {
        const bindings = matchRule({ body: constraint.body }, facts);

        if (bindings.length > 0) {
          violations.push({
            constraint: constraint.id,
            message: constraint.message,
            severity: constraint.severity,
            bindings: bindings.slice(0, 5) // Limit examples
          });
        }
      }

      EventBus.emit('cognition:symbolic:validate', {
        valid: violations.filter(v => v.severity === 'error').length === 0,
        violations: violations.length
      });

      return {
        valid: violations.filter(v => v.severity === 'error').length === 0,
        violations,
        suggestions: generateSuggestions(violations)
      };
    };

    const generateSuggestions = (violations) => {
      return violations.map(v => ({
        constraint: v.constraint,
        action: 'review',
        message: `Review: ${v.message}`
      }));
    };

    // --- Rule Induction ---

    const induceRule = async (pattern) => {
      const id = generateId('induced');

      const rule = {
        id,
        head: pattern.head,
        body: pattern.body,
        priority: 30, // Lower priority than explicit rules
        confidence: pattern.confidence || 0.7,
        source: 'induced',
        support: pattern.support || 1,
        enabled: true
      };

      _inducedRules.push(rule);
      _rules.push(rule);

      await save();
      logger.info(`[RuleEngine] Induced new rule: ${id}`);
      EventBus.emit('cognition:learning:rule', { id, rule });

      return id;
    };

    const getInducedRules = () => _inducedRules;

    // --- Utilities ---

    const getStats = () => ({
      ruleCount: _rules.length,
      constraintCount: _constraints.length,
      inducedRuleCount: _inducedRules.length,
      enabledRules: _rules.filter(r => r.enabled).length
    });

    const clear = async () => {
      _rules = [];
      _constraints = [];
      _inducedRules = [];
      addBuiltinRules();
      await save();
      logger.info('[RuleEngine] Cleared all rules');
    };

    return {
      init,
      addRule,
      removeRule,
      getRules,
      addConstraint,
      getConstraints,
      infer,
      validate,
      induceRule,
      getInducedRules,
      getStats,
      clear
    };
  }
};

export default RuleEngine;
","/capabilities/cognition/symbolic/symbol-grounder.js":"/**
 * @fileoverview Symbol Grounder
 * Maps LLM text output to symbolic entities in the knowledge graph.
 * Performs entity recognition, linking, and fact extraction.
 */

const SymbolGrounder = {
  metadata: {
    id: 'SymbolGrounder',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'EventBus', 'KnowledgeGraph', 'SemanticMemory'],
    async: true,
    type: 'service'
  },

  factory: (deps) => {
    const { Utils, EventBus, KnowledgeGraph, SemanticMemory } = deps;
    const { logger, generateId } = Utils;

    // Patterns for extracting structured information
    const PATTERNS = {
      toolCall: /TOOL_CALL:\s*(\w+)/g,
      filePath: /(?:\/[\w\-./]+\.\w+)/g,
      codeRef: /`([^`]+)`/g,
      error: /(?:Error|Exception|Failed):\s*([^\n.]+)/gi,
      url: /https?:\/\/[^\s<>"{}|\\^`[\]]+/g,
      number: /\b\d+(?:\.\d+)?\b/g
    };

    // Type mapping for extracted mentions
    const TYPE_MAP = {
      toolCall: 'Tool',
      filePath: 'File',
      codeRef: 'CodeElement',
      error: 'Error',
      url: 'URL'
    };

    // --- Grounding Pipeline ---

    const ground = async (text, context = {}) => {
      if (!text || typeof text !== 'string') {
        return { entities: [], relations: [], facts: [] };
      }

      // Step 1: Extract mentions using patterns
      const mentions = extractMentions(text);

      // Step 2: Link mentions to existing entities or create new ones
      const groundedEntities = [];
      const newEntities = [];

      for (const mention of mentions) {
        const linked = await linkMention(mention, context);

        if (linked.isNew) {
          newEntities.push(linked);
        }
        groundedEntities.push(linked);
      }

      // Step 3: Extract relations from text
      const relations = extractRelations(text, groundedEntities);

      // Step 4: Create facts from structured data
      const facts = extractFacts(text, context);

      logger.debug(`[SymbolGrounder] Grounded ${groundedEntities.length} entities, ${relations.length} relations`);

      return {
        entities: groundedEntities,
        newEntities,
        relations,
        facts
      };
    };

    // --- Mention Extraction ---

    const extractMentions = (text) => {
      const mentions = [];
      const seen = new Set();

      for (const [patternName, regex] of Object.entries(PATTERNS)) {
        // Reset regex state
        regex.lastIndex = 0;
        let match;

        while ((match = regex.exec(text)) !== null) {
          const value = match[1] || match[0];
          const key = `${patternName}:${value}`;

          if (!seen.has(key)) {
            seen.add(key);
            mentions.push({
              text: value,
              type: TYPE_MAP[patternName] || 'Entity',
              patternType: patternName,
              start: match.index,
              end: match.index + match[0].length,
              confidence: 0.9
            });
          }
        }
      }

      // Extract noun phrases (simple heuristic)
      const nounPhrases = extractNounPhrases(text);
      for (const np of nounPhrases) {
        const key = `np:${np.text}`;
        if (!seen.has(key) && np.text.length > 3) {
          seen.add(key);
          mentions.push({
            ...np,
            type: 'Entity',
            patternType: 'nounPhrase',
            confidence: 0.6
          });
        }
      }

      return mentions;
    };

    const extractNounPhrases = (text) => {
      // Simple noun phrase extraction using capitalization
      const phrases = [];
      const capitalizedPattern = /\b([A-Z][a-z]+(?:\s+[A-Z][a-z]+)*)\b/g;
      let match;

      while ((match = capitalizedPattern.exec(text)) !== null) {
        // Filter out common sentence starters
        const skipWords = ['The', 'This', 'That', 'These', 'Those', 'It', 'I', 'You', 'We', 'They'];
        if (!skipWords.includes(match[1])) {
          phrases.push({
            text: match[1],
            start: match.index,
            end: match.index + match[0].length
          });
        }
      }

      return phrases;
    };

    // --- Entity Linking ---

    const linkMention = async (mention, context) => {
      const entities = KnowledgeGraph.getAllEntities();

      // Try exact match first
      let bestMatch = null;
      let bestScore = 0;

      for (const entity of entities) {
        const score = computeMatchScore(mention, entity);
        if (score > bestScore) {
          bestScore = score;
          bestMatch = entity;
        }
      }

      // If good match found, return linked entity
      if (bestMatch && bestScore > 0.8) {
        return {
          mention,
          entity: bestMatch,
          entityId: bestMatch.id,
          score: bestScore,
          isNew: false
        };
      }

      // Try semantic similarity if available
      if (SemanticMemory && bestScore < 0.6) {
        try {
          const similar = await SemanticMemory.search(mention.text, { topK: 1 });
          if (similar.length > 0 && similar[0].similarity > 0.7) {
            // Found semantically similar memory, check for linked entity
            const memoryEntity = findEntityByLabel(similar[0].content, entities);
            if (memoryEntity) {
              return {
                mention,
                entity: memoryEntity,
                entityId: memoryEntity.id,
                score: similar[0].similarity,
                isNew: false,
                matchType: 'semantic'
              };
            }
          }
        } catch (e) {
          // SemanticMemory not ready, continue without it
        }
      }

      // Create new entity if high-confidence novel mention
      if (mention.confidence > 0.7) {
        const newId = await KnowledgeGraph.addEntity({
          types: [mention.type],
          labels: { en: mention.text },
          properties: {
            extractedFrom: 'llm-output',
            patternType: mention.patternType
          },
          source: 'grounding',
          confidence: mention.confidence
        });

        const newEntity = KnowledgeGraph.getEntity(newId);

        return {
          mention,
          entity: newEntity,
          entityId: newId,
          score: mention.confidence,
          isNew: true
        };
      }

      // Low confidence, return unlinked
      return {
        mention,
        entity: null,
        entityId: null,
        score: 0,
        isNew: false,
        unlinked: true
      };
    };

    const computeMatchScore = (mention, entity) => {
      const mentionLower = mention.text.toLowerCase();
      let maxScore = 0;

      // Check labels
      for (const label of Object.values(entity.labels || {})) {
        const labelLower = label.toLowerCase();

        // Exact match
        if (labelLower === mentionLower) {
          return 1.0;
        }

        // Partial match
        if (labelLower.includes(mentionLower) || mentionLower.includes(labelLower)) {
          const score = Math.min(mentionLower.length, labelLower.length) /
                       Math.max(mentionLower.length, labelLower.length);
          maxScore = Math.max(maxScore, score * 0.8);
        }
      }

      // Check entity ID
      if (entity.id.toLowerCase() === mentionLower) {
        maxScore = Math.max(maxScore, 0.9);
      }

      // Type match bonus
      if (entity.types.includes(mention.type)) {
        maxScore = Math.min(1.0, maxScore + 0.1);
      }

      return maxScore;
    };

    const findEntityByLabel = (label, entities) => {
      const labelLower = label.toLowerCase();
      return entities.find(e =>
        Object.values(e.labels || {}).some(l => l.toLowerCase() === labelLower)
      );
    };

    // --- Relation Extraction ---

    const extractRelations = (text, groundedEntities) => {
      const relations = [];
      const entityMap = new Map(groundedEntities.map(g => [g.mention.text, g]));

      // Pattern-based relation extraction
      const relationPatterns = [
        {
          pattern: /(\w+)\s+(?:is|are)\s+(?:a|an)\s+(\w+)/gi,
          predicate: 'isA'
        },
        {
          pattern: /(\w+)\s+(?:uses?|using)\s+(\w+)/gi,
          predicate: 'uses'
        },
        {
          pattern: /(\w+)\s+(?:depends?\s+on|requires?)\s+(\w+)/gi,
          predicate: 'dependsOn'
        },
        {
          pattern: /(\w+)\s+(?:created?|generates?|produces?)\s+(\w+)/gi,
          predicate: 'produces'
        },
        {
          pattern: /(\w+)\s+(?:failed?|errored?)\s+(?:with|due\s+to)\s+(.+?)(?:\.|$)/gi,
          predicate: 'failedWith'
        }
      ];

      for (const { pattern, predicate } of relationPatterns) {
        pattern.lastIndex = 0;
        let match;

        while ((match = pattern.exec(text)) !== null) {
          const subjectText = match[1];
          const objectText = match[2];

          const subject = entityMap.get(subjectText);
          const object = entityMap.get(objectText);

          if (subject?.entityId && object?.entityId) {
            relations.push({
              subject: subject.entityId,
              predicate,
              object: object.entityId,
              confidence: 0.7,
              source: 'pattern-extraction'
            });
          }
        }
      }

      return relations;
    };

    // --- Fact Extraction ---

    const extractFacts = (text, context) => {
      const facts = [];

      // Extract tool execution facts
      const toolCalls = text.match(/TOOL_CALL:\s*(\w+)/g) || [];
      for (const call of toolCalls) {
        const toolName = call.replace('TOOL_CALL:', '').trim();
        facts.push({
          predicate: 'toolExecuted',
          args: [toolName, context.cycle || 'unknown'],
          confidence: 1.0,
          source: 'structured'
        });
      }

      // Extract success/failure facts
      if (text.includes('Error:') || text.includes('Failed')) {
        const toolMatch = text.match(/TOOL_CALL:\s*(\w+)/);
        if (toolMatch) {
          facts.push({
            predicate: 'failedExecution',
            args: [toolMatch[1], context.cycle || 'unknown'],
            confidence: 0.9,
            source: 'structured'
          });
        }
      }

      // Extract file modification facts
      const fileWrites = text.match(/(?:wrote|created|modified)\s+(\/[\w\-./]+\.\w+)/gi) || [];
      for (const write of fileWrites) {
        const path = write.match(/(\/[\w\-./]+\.\w+)/)?.[1];
        if (path) {
          facts.push({
            predicate: 'fileModified',
            args: [path, context.cycle || 'unknown'],
            confidence: 0.8,
            source: 'pattern'
          });
        }
      }

      return facts;
    };

    // --- Batch Processing ---

    const groundBatch = async (texts, context = {}) => {
      const results = [];
      for (const text of texts) {
        const result = await ground(text, context);
        results.push(result);
      }
      return results;
    };

    // --- Integration ---

    const integrateGrounding = async (grounding) => {
      // Add extracted relations to knowledge graph
      for (const relation of grounding.relations) {
        await KnowledgeGraph.addTriple(
          relation.subject,
          relation.predicate,
          relation.object,
          {
            confidence: relation.confidence,
            source: relation.source
          }
        );
      }

      // Add extracted facts to knowledge graph
      for (const fact of grounding.facts) {
        if (fact.args.length === 2) {
          await KnowledgeGraph.addTriple(
            fact.args[0],
            fact.predicate,
            fact.args[1],
            {
              confidence: fact.confidence,
              source: fact.source
            }
          );
        }
      }

      logger.debug(`[SymbolGrounder] Integrated ${grounding.relations.length} relations, ${grounding.facts.length} facts`);
    };

    return {
      ground,
      groundBatch,
      extractMentions,
      extractRelations,
      extractFacts,
      integrateGrounding
    };
  }
};

export default SymbolGrounder;
","/capabilities/communication/swarm-sync.js":"/**
 * @fileoverview Swarm State Synchronization
 * Last-Writer-Wins merge with Lamport timestamps for goals, reflections, and artifacts.
 * Supports artifact chunking and pull-based transfer.
 */

const MAX_ARTIFACT_SIZE = 256 * 1024; // 256KB
const CHUNK_SIZE = 32 * 1024; // 32KB
const MAX_CONCURRENT_TRANSFERS = 3;
const TRANSFER_TIMEOUT = 30000; // 30s

const SwarmSync = {
  metadata: {
    id: 'SwarmSync',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'EventBus', 'SwarmTransport', 'VFS', 'ReflectionStore'],
    async: true,
    type: 'capability'
  },

  factory: (deps) => {
    const { Utils, EventBus, SwarmTransport, VFS, ReflectionStore } = deps;
    const { logger, generateId } = Utils;

    // LWW State Store: id -> { value, clock, peerId, updatedAt }
    const _syncedState = new Map();

    // Artifact transfer tracking
    const _pendingTransfers = new Map(); // transferId -> { chunks, received, timeout }
    const _activeTransfers = new Set(); // peerId:artifactId

    /**
     * LWW Merge - returns winner
     */
    const merge = (local, remote) => {
      // Remote has higher clock - remote wins
      if (remote.clock > local.clock) {
        return { winner: 'remote', value: remote };
      }
      // Local has higher clock - local wins
      if (remote.clock < local.clock) {
        return { winner: 'local', value: local };
      }
      // Same clock - lexicographic tiebreak on peerId
      if (remote.peerId > local.peerId) {
        return { winner: 'remote', value: remote };
      }
      return { winner: 'local', value: local };
    };

    /**
     * Create LWW entry with incremented clock
     */
    const createEntry = (id, value) => {
      return {
        id,
        value,
        clock: SwarmTransport.tick(), // Increment clock on local write
        peerId: SwarmTransport._getPeerId(),
        updatedAt: Date.now(),
        sharedFrom: null
      };
    };

    /**
     * Set local state (increments clock)
     */
    const setLocal = (id, value) => {
      const entry = createEntry(id, value);
      _syncedState.set(id, entry);

      // Broadcast update
      SwarmTransport.broadcast('goal-update', {
        id,
        value,
        clock: entry.clock,
        peerId: entry.peerId,
        updatedAt: entry.updatedAt
      });

      EventBus.emit('swarm:state-updated', { id, entry, source: 'local' });
      return entry;
    };

    /**
     * Apply remote state with LWW merge
     */
    const applyRemote = (id, remoteEntry) => {
      const local = _syncedState.get(id);

      if (!local) {
        // No local entry - accept remote
        const entry = {
          ...remoteEntry,
          sharedFrom: remoteEntry.peerId
        };
        _syncedState.set(id, entry);
        EventBus.emit('swarm:state-updated', { id, entry, source: 'remote' });
        return { accepted: true, entry };
      }

      // Merge with existing
      const { winner, value } = merge(local, remoteEntry);

      if (winner === 'remote') {
        const entry = {
          ...remoteEntry,
          sharedFrom: remoteEntry.peerId
        };
        _syncedState.set(id, entry);
        EventBus.emit('swarm:state-updated', { id, entry, source: 'remote' });
        return { accepted: true, entry };
      }

      return { accepted: false, entry: local };
    };

    /**
     * Get synced state
     */
    const get = (id) => {
      return _syncedState.get(id);
    };

    /**
     * Get all synced state
     */
    const getAll = () => {
      return Array.from(_syncedState.values());
    };

    /**
     * Initialize sync handlers
     */
    const init = async () => {
      // Register WebRTC message handlers
      SwarmTransport.onMessage('sync-request', handleSyncRequest);
      SwarmTransport.onMessage('sync-response', handleSyncResponse);
      SwarmTransport.onMessage('goal-update', handleGoalUpdate);
      SwarmTransport.onMessage('reflection-share', handleReflectionShare);
      SwarmTransport.onMessage('artifact-announce', handleArtifactAnnounce);
      SwarmTransport.onMessage('artifact-request', handleArtifactRequest);
      SwarmTransport.onMessage('artifact-chunk', handleArtifactChunk);
      SwarmTransport.onMessage('artifact-ack', handleArtifactAck);

      // Subscribe to local state changes to auto-sync
      EventBus.on('goal:set', (data) => {
        logger.debug('[SwarmSync] Goal set, syncing to swarm');
        setLocal(data.id, { type: 'goal', goal: data.goal, timestamp: data.timestamp });
      }, 'SwarmSync');

      EventBus.on('reflection:added', (reflection) => {
        // Avoid re-broadcasting reflections that were already shared from a peer
        const fromPeer = reflection?.context?.sharedFrom ||
          (reflection?.tags || []).find(tag => tag.startsWith('shared_from_'));
        if (fromPeer) {
          logger.debug(`[SwarmSync] Skipping shared reflection from ${fromPeer}`);
          return;
        }
        logger.debug('[SwarmSync] Reflection added, sharing with swarm');
        shareReflection(reflection);
      }, 'SwarmSync');

      // Auto-save received artifacts to VFS
      EventBus.on('swarm:artifact-received', async ({ artifactId, content, peerId }) => {
        try {
          // Save to /shared/ directory, preserving path structure
          const targetPath = `/shared${artifactId.startsWith('/') ? '' : '/'}${artifactId}`;
          await VFS.write(targetPath, content);
          logger.info(`[SwarmSync] Saved shared file from ${peerId} to ${targetPath}`);
        } catch (e) {
          logger.error(`[SwarmSync] Failed to save shared file:`, e);
        }
      }, 'SwarmSync');

      logger.info('[SwarmSync] Initialized with auto-sync for goals, reflections, and files');
      return true;
    };

    /**
     * Handle sync request - send full state snapshot
     */
    const handleSyncRequest = (peerId, payload) => {
      logger.info(`[SwarmSync] Sync request from ${peerId}`);

      const snapshot = {
        state: Array.from(_syncedState.entries()),
        timestamp: Date.now()
      };

      SwarmTransport.sendToPeer(peerId, 'sync-response', snapshot);
    };

    /**
     * Handle sync response - merge incoming state
     */
    const handleSyncResponse = (peerId, payload) => {
      logger.info(`[SwarmSync] Sync response from ${peerId}: ${payload.state?.length || 0} entries`);

      for (const [id, entry] of (payload.state || [])) {
        applyRemote(id, entry);
      }

      EventBus.emit('swarm:sync-complete', { peerId, count: payload.state?.length || 0 });
    };

    /**
     * Handle goal update
     */
    const handleGoalUpdate = (peerId, payload) => {
      const { id, value, clock, updatedAt } = payload;

      logger.debug(`[SwarmSync] Goal update from ${peerId}: ${id}`);

      applyRemote(id, {
        id,
        value,
        clock,
        peerId,
        updatedAt
      });
    };

    /**
     * Handle reflection share
     */
    const handleReflectionShare = async (peerId, payload) => {
      const { reflection } = payload;

      if (!reflection || !reflection.content) {
        logger.warn(`[SwarmSync] Invalid reflection from ${peerId}`);
        return;
      }

