      EventBus.emit(`swarm:message:${data.type}`, {
        peerId: data.peerId,
        payload: data.payload,
        timestamp: data.timestamp
      });
    };

    // =========================================
    // WebRTC Transport (delegates to WebRTCSwarm)
    // =========================================

    /**
     * Initialize WebRTC transport via existing WebRTCSwarm
     */
    const initWebRTC = async () => {
      _transport = 'webrtc';

