     */
    const init = async () => {
      if (!isEnabled()) {
        logger.info('[SwarmTransport] Disabled (add ?swarm=true or ?swarm=<room> to URL)');
        return false;
      }

      _peerId = generateId('peer');
      _roomId = getRoomId();

