     * Get stats
     */
    const getStats = () => {
      if (_transport === 'webrtc' && _webrtcSwarm) {
        return {
          ..._webrtcSwarm.getStats(),
          transport: 'webrtc'
        };
      }

      return {
        peerId: _peerId,
        roomId: _roomId,
        transport: _transport,
        connectionState: _connectionState,
        connectedPeers: _peers.size,
        clock: _logicalClock
      };
    };

