      init,
      disconnect,
      sendToPeer,
      broadcast,
      onMessage,
      getConnectionState,
      getConnectedPeers,
      getTransportType,
      getStats,
      getClock,
      tick,
      _getPeerId: () => _peerId,
      _getSessionId: () => _roomId
    };
  }
};

