      return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
        const r = Math.random() * 16 | 0;
        return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
      });
    };

    /**
     * Increment logical clock (Lamport timestamp)
     */
    const tick = () => ++_logicalClock;

    /**
     * Update logical clock on receive
     */
    const updateClock = (remoteClock) => {
      _logicalClock = Math.max(_logicalClock, remoteClock) + 1;
    };

    /**
     * Validate message envelope
     */
    const validateEnvelope = (envelope) => {
      if (!envelope || typeof envelope !== 'object') {
        return { valid: false, reason: 'Invalid envelope format' };
      }
      if (envelope.protocolVersion !== PROTOCOL_VERSION) {
        return { valid: false, reason: `Protocol version mismatch: ${envelope.protocolVersion}` };
      }
      if (!MESSAGE_TYPES.has(envelope.type)) {
        return { valid: false, reason: `Unknown message type: ${envelope.type}` };
      }
      if (!envelope.peerId || typeof envelope.peerId !== 'string') {
        return { valid: false, reason: 'Missing or invalid peerId' };
      }
      if (typeof envelope.timestamp !== 'number') {
        return { valid: false, reason: 'Missing or invalid timestamp' };
      }
      if (envelope.payloadSize > MAX_PAYLOAD_SIZE) {
        return { valid: false, reason: `Payload too large: ${envelope.payloadSize}` };
      }
      return { valid: true };
    };

    /**
     * Wrap message in protocol envelope
     */
    const wrapMessage = (type, payload) => {
      const payloadStr = JSON.stringify(payload || {});
      if (payloadStr.length > MAX_PAYLOAD_SIZE) {
        throw new Error(`Payload exceeds max size: ${payloadStr.length} > ${MAX_PAYLOAD_SIZE}`);
      }
      return {
        protocolVersion: PROTOCOL_VERSION,
        type,
        peerId: _peerId,
        timestamp: tick(),
        payload: payload || {},
        payloadSize: payloadStr.length
      };
    };

    /**
     * Check if swarm is enabled via URL param or localStorage
     */
    const isEnabled = () => {
      if (typeof window === 'undefined') return false;

      // URL param takes priority: ?swarm=true or ?swarm=<roomId>
      const urlParams = new URLSearchParams(window.location.search);
      const swarmParam = urlParams.get('swarm');
      if (swarmParam) return true;

      // Fall back to localStorage
      return localStorage.getItem('REPLOID_SWARM_ENABLED') === 'true';
    };

    /**
     * Get room token from URL param or session
     */
    const getRoomToken = () => {
      if (typeof window === 'undefined') return null;

      const urlParams = new URLSearchParams(window.location.search);
      const swarmParam = urlParams.get('swarm');

      // If swarm param is a custom string, use it as token
      if (swarmParam && swarmParam !== 'true') {
        return swarmParam;
      }

      // Otherwise use session-based token
      return _sessionId;
    };

    /**
     * Get room ID from token
     */
    const getRoomId = (token) => {
      return `reploid-swarm-${token}`;
    };

    /**
     * Initialize the swarm transport
     */
    const init = async () => {
      // Check if enabled via URL param or feature flag
      if (!isEnabled()) {
        logger.info('[WebRTCSwarm] Disabled (add ?swarm=true to URL or set REPLOID_SWARM_ENABLED=true)');
        return false;
      }

      // Generate or restore IDs
      _peerId = generateId('peer');
      _sessionId = localStorage.getItem('REPLOID_SESSION_ID') || uuid();
      localStorage.setItem('REPLOID_SESSION_ID', _sessionId);

      // Get room token (from URL param or session)
      const roomToken = getRoomToken();
      _roomId = getRoomId(roomToken);

      CONFIG.signalingServer = getSignalingUrl();

      logger.info(`[WebRTCSwarm] Initializing - peerId: ${_peerId}, room: ${_roomId}`);

      // Connect to signaling server
      await connectToSignaling();

      return true;
    };

    /**
     * Connect to signaling server with retry
     */
    const connectToSignaling = () => {
      return new Promise((resolve, reject) => {
        if (!CONFIG.signalingServer) {
          reject(new Error('No signaling server configured'));
          return;
        }

        if (_signalingWs) {
          _signalingWs.close();
        }

        _connectionState = 'connecting';
        EventBus.emit('swarm:state-change', { state: _connectionState });
        logger.info(`[WebRTCSwarm] Connecting to ${CONFIG.signalingServer}`);

        try {
          _signalingWs = new WebSocket(CONFIG.signalingServer);

          _signalingWs.onopen = () => {
            logger.info('[WebRTCSwarm] Connected to signaling server');
            _connectionState = 'connected';
            _reconnectAttempt = 0;
            EventBus.emit('swarm:state-change', { state: _connectionState });

            // Clear any pending reconnect
            if (_reconnectTimer) {
              clearTimeout(_reconnectTimer);
              _reconnectTimer = null;
            }

            // Join room (token must match room suffix for auth)
            const token = _roomId.replace('reploid-swarm-', '');
            sendSignaling({
              type: 'join',
              peerId: _peerId,
              roomId: _roomId,
              token,
              metadata: { capabilities: [] }
            });

            // Start heartbeat
            startHeartbeat();

            resolve(true);
          };

          _signalingWs.onmessage = (event) => {
            try {
              const message = JSON.parse(event.data);
              handleSignalingMessage(message);
            } catch (e) {
              logger.error('[WebRTCSwarm] Failed to parse signaling message:', e);
            }
          };

          _signalingWs.onerror = (error) => {
            logger.error('[WebRTCSwarm] WebSocket error:', error);
          };

          _signalingWs.onclose = () => {
            logger.warn('[WebRTCSwarm] Disconnected from signaling server');
            _connectionState = 'disconnected';
            stopHeartbeat();
            EventBus.emit('swarm:state-change', { state: _connectionState });

            // Clear peers so reconnect will re-dial
            clearPeers();

            // Schedule reconnect
            scheduleReconnect();
          };
        } catch (e) {
          logger.error('[WebRTCSwarm] Failed to create WebSocket:', e);
          _connectionState = 'disconnected';
          scheduleReconnect();
          reject(e);
        }
      });
    };

    /**
     * Schedule reconnection with exponential backoff
     */
    const scheduleReconnect = () => {
      if (_reconnectTimer) return;

      _reconnectAttempt++;
      const backoff = Math.min(
        CONFIG.reconnectBaseMs * Math.pow(2, _reconnectAttempt - 1),
        MAX_BACKOFF_MS
      );

      logger.info(`[WebRTCSwarm] Reconnecting in ${backoff}ms (attempt ${_reconnectAttempt})`);
      _connectionState = 'reconnecting';
      EventBus.emit('swarm:state-change', { state: _connectionState, attempt: _reconnectAttempt });

      _reconnectTimer = setTimeout(() => {
        _reconnectTimer = null;
        connectToSignaling().catch(e => {
          logger.error('[WebRTCSwarm] Reconnect failed:', e);
        });
      }, backoff);
    };

    /**
     * Send message to signaling server
     */
    const sendSignaling = (message) => {
      if (!_signalingWs || _signalingWs.readyState !== WebSocket.OPEN) {
        logger.warn('[WebRTCSwarm] Cannot send signaling: not connected');
        return false;
      }
      try {
        _signalingWs.send(JSON.stringify(message));
        return true;
      } catch (e) {
        logger.error('[WebRTCSwarm] Failed to send signaling:', e);
        return false;
      }
    };

    /**
     * Handle incoming signaling messages
     */
    const handleSignalingMessage = async (message) => {
      const { type } = message;

      switch (type) {
        case 'welcome':
          logger.debug('[WebRTCSwarm] Received welcome from signaling server');
          break;

        case 'joined':
          logger.info(`[WebRTCSwarm] Joined room ${message.roomId}, existing peers: ${message.peers?.length || 0}`);
          // Connect to existing peers
          for (const remotePeerId of (message.peers || [])) {
            await connectToPeer(remotePeerId);
          }
          break;

        case 'peer-joined':
          logger.info(`[WebRTCSwarm] Peer joined: ${message.peerId}`);
          EventBus.emit('swarm:peer-joined', { peerId: message.peerId });
          break;

        case 'peer-left':
          logger.info(`[WebRTCSwarm] Peer left: ${message.peerId}`);
          removePeer(message.peerId);
          EventBus.emit('swarm:peer-left', { peerId: message.peerId });
          break;

        case 'offer':
          await handleOffer(message.peerId, message.offer);
          break;

        case 'answer':
          await handleAnswer(message.peerId, message.answer);
          break;

        case 'ice-candidate':
          await handleIceCandidate(message.peerId, message.candidate);
          break;

        case 'error':
          logger.error('[WebRTCSwarm] Signaling error:', message.error);
          break;

        default:
          logger.debug(`[WebRTCSwarm] Unknown signaling message: ${type}`);
      }
    };

    /**
     * Connect to a remote peer
     */
    const connectToPeer = async (remotePeerId) => {
      // Skip if already connected or connecting
      const existingPeer = _peers.get(remotePeerId);
      if (existingPeer) {
        if (existingPeer.status === 'connected') {
          logger.debug(`[WebRTCSwarm] Already connected to ${remotePeerId}, skipping`);
          return;
        }
        // Close stale connection before reconnecting
        logger.info(`[WebRTCSwarm] Closing stale connection to ${remotePeerId}`);
        removePeer(remotePeerId);
      }

      logger.info(`[WebRTCSwarm] Connecting to peer: ${remotePeerId}`);

      const connection = new RTCPeerConnection({ iceServers: CONFIG.iceServers });
      const dataChannel = connection.createDataChannel('reploid', CONFIG.channelOptions);

      const peer = {
        id: remotePeerId,
        connection,
        dataChannel,
        metadata: {},
        status: 'connecting',
        lastSeen: Date.now()
      };

      _peers.set(remotePeerId, peer);

      // ICE candidate handler
      connection.onicecandidate = (event) => {
        if (event.candidate) {
          sendSignaling({
            type: 'ice-candidate',
            peerId: _peerId,
            targetPeer: remotePeerId,
            candidate: event.candidate
          });
        }
      };

      // Connection state monitoring
      connection.onconnectionstatechange = () => {
        logger.debug(`[WebRTCSwarm] Connection state with ${remotePeerId}: ${connection.connectionState}`);
        if (connection.connectionState === 'failed' || connection.connectionState === 'disconnected') {
          removePeer(remotePeerId);
        }
      };

      // Data channel handlers
      setupDataChannel(dataChannel, remotePeerId, peer);

      // Create and send offer
      const offer = await connection.createOffer();
      await connection.setLocalDescription(offer);

      sendSignaling({
        type: 'offer',
        peerId: _peerId,
        targetPeer: remotePeerId,
        offer
      });
    };

    /**
     * Handle incoming WebRTC offer
     */
    const handleOffer = async (remotePeerId, offer) => {
      logger.info(`[WebRTCSwarm] Received offer from: ${remotePeerId}`);

      const connection = new RTCPeerConnection({ iceServers: CONFIG.iceServers });

      const peer = {
        id: remotePeerId,
        connection,
        dataChannel: null,
        metadata: {},
        status: 'connecting',
        lastSeen: Date.now()
      };

      _peers.set(remotePeerId, peer);

      // ICE candidate handler
      connection.onicecandidate = (event) => {
        if (event.candidate) {
          sendSignaling({
            type: 'ice-candidate',
            peerId: _peerId,
            targetPeer: remotePeerId,
            candidate: event.candidate
          });
        }
      };

      // Wait for incoming data channel
      connection.ondatachannel = (event) => {
        peer.dataChannel = event.channel;
        setupDataChannel(event.channel, remotePeerId, peer);
      };

      // Set remote description and create answer
      await connection.setRemoteDescription(offer);
      const answer = await connection.createAnswer();
      await connection.setLocalDescription(answer);

      sendSignaling({
        type: 'answer',
        peerId: _peerId,
        targetPeer: remotePeerId,
        answer
      });
    };

    /**
     * Handle incoming WebRTC answer
     */
    const handleAnswer = async (remotePeerId, answer) => {
      const peer = _peers.get(remotePeerId);
      if (peer) {
        await peer.connection.setRemoteDescription(answer);
      }
    };

    /**
     * Handle incoming ICE candidate
     */
    const handleIceCandidate = async (remotePeerId, candidate) => {
      const peer = _peers.get(remotePeerId);
      if (peer && candidate) {
        try {
          await peer.connection.addIceCandidate(candidate);
        } catch (e) {
          logger.error(`[WebRTCSwarm] Failed to add ICE candidate for ${remotePeerId}:`, e);
        }
      }
    };

    /**
     * Setup data channel handlers
     */
    const setupDataChannel = (dataChannel, remotePeerId, peer) => {
      dataChannel.onopen = () => {
        logger.info(`[WebRTCSwarm] Data channel opened with ${remotePeerId}`);
        peer.status = 'connected';
        EventBus.emit('swarm:peer-connected', { peerId: remotePeerId });

        // Request initial sync
        sendToPeer(remotePeerId, 'sync-request', {});
      };

      dataChannel.onmessage = (event) => {
        handlePeerMessage(remotePeerId, event.data);
      };

      dataChannel.onerror = (error) => {
        logger.error(`[WebRTCSwarm] Data channel error with ${remotePeerId}:`, error);
      };

      dataChannel.onclose = () => {
        logger.info(`[WebRTCSwarm] Data channel closed with ${remotePeerId}`);
        peer.status = 'disconnected';
      };
    };

    /**
     * Remove peer and cleanup
     */
    const removePeer = (remotePeerId) => {
      const peer = _peers.get(remotePeerId);
      if (peer) {
        try {
          if (peer.dataChannel) peer.dataChannel.close();
          if (peer.connection) peer.connection.close();
        } catch (e) {
          // Ignore cleanup errors
        }
        _peers.delete(remotePeerId);
      }
    };

    /**
     * Remove all peers
     */
    const clearPeers = () => {
      for (const [peerId] of _peers) {
        removePeer(peerId);
      }
    };

    /**
     * Handle incoming peer message
     */
    const handlePeerMessage = (remotePeerId, data) => {
      let envelope;
      try {
        // Size check before parse
        if (data.length > MAX_PAYLOAD_SIZE * 2) {
          logger.warn(`[WebRTCSwarm] Message too large from ${remotePeerId}: ${data.length}`);
          _stats.rejected++;
          return;
        }

        envelope = JSON.parse(data);
      } catch (e) {
        logger.warn(`[WebRTCSwarm] Failed to parse message from ${remotePeerId}`);
        _stats.rejected++;
        return;
      }

      // Validate envelope
      const validation = validateEnvelope(envelope);
      if (!validation.valid) {
        logger.warn(`[WebRTCSwarm] Invalid message from ${remotePeerId}: ${validation.reason}`);
        _stats.rejected++;
        return;
      }

      // Update logical clock
      updateClock(envelope.timestamp);

      // Update peer last seen
      const peer = _peers.get(remotePeerId);
      if (peer) {
        peer.lastSeen = Date.now();
      }

      // Track stats
      _stats.messagesReceived++;
      _stats.bytesReceived += data.length;

      // Route to handler
      const handler = _messageHandlers.get(envelope.type);
      if (handler) {
        try {
          handler(remotePeerId, envelope.payload, envelope);
        } catch (e) {
          logger.error(`[WebRTCSwarm] Handler error for ${envelope.type}:`, e);
        }
      }

      // Emit event for external listeners
      EventBus.emit(`swarm:message:${envelope.type}`, {
        peerId: remotePeerId,
        payload: envelope.payload,
        timestamp: envelope.timestamp
      });
    };

    /**
     * Send message to specific peer
     */
    const sendToPeer = (remotePeerId, type, payload) => {
      const peer = _peers.get(remotePeerId);
      if (!peer || !peer.dataChannel || peer.dataChannel.readyState !== 'open') {
        logger.warn(`[WebRTCSwarm] Cannot send to ${remotePeerId}: not connected`);
        return false;
      }

      try {
        const envelope = wrapMessage(type, payload);
        const data = JSON.stringify(envelope);

        peer.dataChannel.send(data);

        _stats.messagesSent++;
        _stats.bytesSent += data.length;

        return true;
      } catch (e) {
        logger.error(`[WebRTCSwarm] Failed to send to ${remotePeerId}:`, e);
        return false;
      }
    };

    /**
     * Broadcast message to all connected peers
     */
    const broadcast = (type, payload) => {
      let sent = 0;
      for (const [peerId] of _peers) {
        if (sendToPeer(peerId, type, payload)) {
          sent++;
        }
      }
      return sent;
    };

    /**
     * Register message handler
     */
    const onMessage = (type, handler) => {
      if (!MESSAGE_TYPES.has(type)) {
        logger.warn(`[WebRTCSwarm] Registering handler for unknown type: ${type}`);
      }
      _messageHandlers.set(type, handler);
    };

    /**
     * Start heartbeat timer
     */
    const startHeartbeat = () => {
      stopHeartbeat();
      _heartbeatTimer = setInterval(() => {
        // Send heartbeat to signaling
        sendSignaling({
          type: 'heartbeat',
          peerId: _peerId,
          roomId: _roomId
        });

        // Ping all peers
        broadcast('ping', { ts: Date.now() });

        // Check for stale peers
        const now = Date.now();
        for (const [peerId, peer] of _peers) {
          if (now - peer.lastSeen > PEER_TIMEOUT) {
            logger.warn(`[WebRTCSwarm] Peer ${peerId} is stale, removing`);
            removePeer(peerId);
            EventBus.emit('swarm:peer-timeout', { peerId });
          }
        }
      }, HEARTBEAT_INTERVAL);
    };

    /**
     * Stop heartbeat timer
     */
    const stopHeartbeat = () => {
      if (_heartbeatTimer) {
        clearInterval(_heartbeatTimer);
        _heartbeatTimer = null;
      }
    };

    /**
     * Disconnect from swarm
     */
    const disconnect = () => {
      stopHeartbeat();

      // Close all peer connections
      for (const [peerId] of _peers) {
        removePeer(peerId);
      }

      // Close signaling
      if (_signalingWs) {
        sendSignaling({ type: 'leave', peerId: _peerId, roomId: _roomId });
        _signalingWs.close();
        _signalingWs = null;
      }

      _connectionState = 'disconnected';
      EventBus.emit('swarm:state-change', { state: _connectionState });
    };

    /**
     * Get current connection state
     */
    const getConnectionState = () => _connectionState;

    /**
     * Get connected peers
     */
    const getConnectedPeers = () => {
      return Array.from(_peers.entries())
        .filter(([_, peer]) => peer.status === 'connected')
        .map(([id, peer]) => ({
          id,
          metadata: peer.metadata,
          lastSeen: peer.lastSeen
        }));
    };

    /**
     * Get stats
     */
    const getStats = () => ({
      peerId: _peerId,
      sessionId: _sessionId,
      roomId: _roomId,
      connectionState: _connectionState,
      connectedPeers: getConnectedPeers().length,
      totalPeers: _peers.size,
      ..._stats,
      uptime: Date.now() - _stats.startTime
    });

    /**
     * Get logical clock value
     */
    const getClock = () => _logicalClock;

    // Register default handlers
    onMessage('ping', (peerId, payload) => {
      sendToPeer(peerId, 'pong', { ts: payload.ts, received: Date.now() });
    });

    onMessage('pong', (peerId, payload) => {
      const latency = Date.now() - payload.ts;
      logger.debug(`[WebRTCSwarm] Latency to ${peerId}: ${latency}ms`);
    });

    return {
      init,
      disconnect,
      sendToPeer,
      broadcast,
      onMessage,
      getConnectionState,
      getConnectedPeers,
      getStats,
      getClock,
      tick, // Expose for SwarmSync to increment clock on local writes
      // Expose for SwarmSync
      _getPeerId: () => _peerId,
      _getSessionId: () => _sessionId
    };
  }
};

export default WebRTCSwarm;
","/capabilities/performance/performance-monitor.js":"/**
 * @fileoverview Performance Monitor
 * Tracks system metrics and tool execution stats.
 */

const PerformanceMonitor = {
  metadata: {
    id: 'PerformanceMonitor',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'EventBus', 'TelemetryTimeline?'],
    type: 'capability'
  },

  factory: (deps) => {
    const { Utils, EventBus, TelemetryTimeline } = deps;
    const { logger } = Utils;

    const metrics = {
      toolCalls: 0,
      apiTokens: 0,
      apiLatency: [],
      errors: 0,
      startTime: Date.now()
    };

    const logTimeline = (type, payload, options = {}) => {
      if (!TelemetryTimeline) return;
      TelemetryTimeline.record(type, payload, options).catch((err) => {
        logger.warn('[PerfMon] Failed to record timeline entry', err?.message || err);
      });
    };

    const init = () => {
      // Listen to system events
      EventBus.on('agent:tool:start', (data = {}) => {
        metrics.toolCalls++;
        logTimeline('tool:start', { tool: data.tool, workerId: data.workerId }, { tags: ['tool'] });
      });
      EventBus.on('agent:error', (data = {}) => {
        metrics.errors++;
        logTimeline('agent:error', data, { severity: 'error', tags: ['agent'] });
      });

      // Listen for LLM stats (emitted by LLMClient if configured)
      EventBus.on('llm:complete', (data) => {
        if (data.tokens) metrics.apiTokens += data.tokens;
        if (data.latency) metrics.apiLatency.push(data.latency);
        logTimeline('llm:complete', {
          provider: data.provider,
          model: data.model,
          tokens: data.tokens,
          latency: data.latency
        }, { tags: ['llm'] });
      });

      logger.info('[PerfMon] Monitoring started');
    };

    const getReport = () => {
      const uptime = (Date.now() - metrics.startTime) / 1000;
      const avgLatency = metrics.apiLatency.reduce((a, b) => a + b, 0) / (metrics.apiLatency.length || 1);

      return {
        uptime: `${uptime.toFixed(0)}s`,
        toolsUsed: metrics.toolCalls,
        tokens: metrics.apiTokens,
        errors: metrics.errors,
        avgLatency: `${avgLatency.toFixed(0)}ms`
      };
    };

    return { init, getReport };
  }
};

export default PerformanceMonitor;
","/capabilities/reflection/reflection-analyzer.js":"/**
 * @fileoverview Reflection Analyzer
 * Analyzes patterns in reflections to enable learning from past experiences.
 */

const ReflectionAnalyzer = {
  metadata: {
    id: 'ReflectionAnalyzer',
    version: '1.0.0',
    genesis: { introduced: 'reflection' },
    dependencies: ['ReflectionStore', 'Utils'],
    async: true,
    type: 'intelligence'
  },

  factory: (deps) => {
    const { ReflectionStore, Utils } = deps;
    const { logger } = Utils;

    const getKeywords = (text) => {
      if (!text) return [];
      return text.toLowerCase()
        .split(/\W+/)
        .filter(w => w.length > 3)
        .slice(0, 10);
    };

    // Simple failure pattern detection
    const detectFailurePatterns = async () => {
      const failed = await ReflectionStore.getReflections({
        outcome: 'failed',
        limit: 50
      });

      const counts = {};
      const examples = {};

      for (const r of failed) {
          // Heuristic: Error message is usually in content or context
          const msg = r.content || "Unknown error";
          const errorType = msg.split(':')[0] || "GenericError";

          counts[errorType] = (counts[errorType] || 0) + 1;
          if (!examples[errorType]) examples[errorType] = msg;
      }

      // Convert to array
      return Object.entries(counts)
          .filter(([_, count]) => count >= 2) // Threshold
          .map(([indicator, count]) => ({
              indicator: indicator,
              count: count,
              example: examples[indicator]
          }))
          .sort((a, b) => b.count - a.count);
    };

    return {
      init: async () => {
        logger.info('[ReflectionAnalyzer] Initialized');
        return true;
      },
      api: {
        detectFailurePatterns
      }
    };
  }
};

export default ReflectionAnalyzer;
","/capabilities/reflection/reflection-store.js":"/**
 * @fileoverview Reflection Store
 * Persists insights, errors, and success patterns to VFS.
 */

const ReflectionStore = {
  metadata: {
    id: 'ReflectionStore',
    version: '1.0.0',
    genesis: { introduced: 'reflection' },
    dependencies: ['Utils', 'VFS', 'EventBus'],
    async: true,
    type: 'capability'
  },

  factory: (deps) => {
    const { Utils, VFS, EventBus } = deps;
    const { logger, generateId } = Utils;

    const STORE_PATH = '/.memory/reflections.json';
    let _cache = [];

    const init = async () => {
      if (await VFS.exists(STORE_PATH)) {
        try {
          const content = await VFS.read(STORE_PATH);
          _cache = JSON.parse(content);
        } catch (e) {
          logger.error('[Reflection] Corrupt store, resetting.', e);
          _cache = [];
        }
      }
      return true;
    };

    const add = async (entry) => {
      const reflection = {
        id: generateId('ref'),
        ts: Date.now(),
        type: entry.type || 'insight', // 'insight', 'error', 'success'
        content: entry.content,
        context: entry.context || {},
        // Enriched fields for Analyzer
        tags: entry.tags || [],
        description: entry.description || entry.content
      };

      _cache.push(reflection);

      // Simple persistence (no debouncing in core to avoid async complexity)
      await _save();

      EventBus.emit('reflection:added', reflection);
      logger.info(`[Reflection] Added: ${entry.type}`);
      return reflection.id;
    };

    const query = (filterFn) => {
      return _cache.filter(filterFn);
    };

    const getReflections = async (options = {}) => {
      let results = [..._cache];

      if (options.outcome) {
        results = results.filter(r => r.context?.outcome === options.outcome);
      }

      results.sort((a, b) => b.ts - a.ts);

      if (options.limit) {
        results = results.slice(0, options.limit);
      }

      return results;
    };

    const _save = async () => {
      // Ensure directory exists
      if (!await VFS.exists('/.memory')) {
          await VFS.mkdir('/.memory');
      }
      await VFS.write(STORE_PATH, JSON.stringify(_cache, null, 2));
    };

    return { init, add, query, getReflections };
  }
};

export default ReflectionStore;
","/capabilities/system/substrate-loader.js":"/**
 * @fileoverview Substrate Loader - Dynamically loads modules and widgets from VFS.
 */

const SubstrateLoader = {
  metadata: {
    id: 'SubstrateLoader',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'VFS'],
    type: 'capability'
  },

  factory: (deps) => {
    const { Utils, VFS } = deps;
    const { logger } = Utils;

    const loadModule = async (path) => {
      if (!(await VFS.exists(path))) throw new Error(`Module not found: ${path}`);

      const code = await VFS.read(path);
      const blob = new Blob([code], { type: 'text/javascript' });
      const url = URL.createObjectURL(blob);

      try {
        const module = await import(url);
        logger.info(`[Substrate] Loaded module: ${path}`);
        return module;
      } finally {
        URL.revokeObjectURL(url);
      }
    };

    const loadWidget = async (path, containerId) => {
      const module = await loadModule(path);
      if (!module.default || !module.default.render) {
        throw new Error('Invalid widget: missing render()');
      }

      const container = document.getElementById(containerId);
      if (container) {
        container.innerHTML = ''; // Clear previous
        const element = module.default.render();
        container.appendChild(element);
        logger.info(`[Substrate] Rendered widget ${path} to ${containerId}`);
      }
    };

    return { loadModule, loadWidget };
  }
};

export default SubstrateLoader;
","/core/agent-loop.js":"/**
 * @fileoverview Agent Loop
 * The main cognitive cycle: Think -> Act -> Observe.
 */

const AgentLoop = {
  metadata: {
    id: 'AgentLoop',
    version: '1.1.0', // Parallel read-only tool execution
    genesis: { introduced: 'tabula' },
    dependencies: [
      'Utils', 'EventBus', 'LLMClient', 'ToolRunner', 'ContextManager',
      'ResponseParser', 'StateManager', 'PersonaManager', 'CircuitBreaker', 'SchemaRegistry',
      'ReflectionStore?', 'ReflectionAnalyzer?', 'CognitionAPI?', 'MultiModelCoordinator?'
    ],
    type: 'core'
  },

  factory: (deps) => {
    const {
      Utils, EventBus, LLMClient, ToolRunner, ContextManager,
      ResponseParser, StateManager, PersonaManager, CircuitBreaker, SchemaRegistry,
      ReflectionStore, ReflectionAnalyzer, CognitionAPI, MultiModelCoordinator
    } = deps;

    const { logger, Errors } = Utils;

    const MAX_ITERATIONS = 50;
    const DEFAULT_MAX_TOOL_CALLS = 5;

    // Configurable limits - can be overridden via StateManager config
    const getMaxToolCalls = () => {
      try {
        const config = StateManager?.getState()?.config || {};
        return config.maxToolCallsPerIteration || DEFAULT_MAX_TOOL_CALLS;
      } catch {
        return DEFAULT_MAX_TOOL_CALLS;
      }
    };

    // Use SchemaRegistry for read-only tool detection (no longer hardcoded)
    const isReadOnlyTool = (name) => {
      if (SchemaRegistry?.isToolReadOnly) {
        return SchemaRegistry.isToolReadOnly(name);
      }
      // Fallback if SchemaRegistry not available
      const FALLBACK_READ_ONLY = ['ReadFile', 'ListFiles', 'Grep', 'Find', 'Cat', 'Head', 'Tail', 'Ls', 'Pwd', 'ListTools', 'ListMemories', 'ListKnowledge'];
      return FALLBACK_READ_ONLY.includes(name);
    };

    const MAX_NO_PROGRESS_ITERATIONS = 5; // Max consecutive iterations without tool calls
    const TOOL_EXECUTION_TIMEOUT_MS = 30000; // 30 second timeout per tool

    // Track single-tool usage for batching nudges
    let _consecutiveSingleToolCalls = 0;
    const SINGLE_TOOL_NUDGE_THRESHOLD = 3; // Nudge after 3 consecutive single-tool iterations
    let _isRunning = false;
    let _abortController = null;
    let _modelConfig = null;
    let _modelConfigs = []; // Array of models for multi-model mode
    let _consensusStrategy = 'arena'; // arena, peer-review, swarm
    const MAX_ACTIVITY_LOG = 200;
    const _activityLog = [];

    // Debug visibility - track current context and system prompt
    let _currentContext = [];
    let _currentSystemPrompt = '';

    // Human-in-the-loop message queue
    let _humanMessageQueue = [];

    // Helper to update tracked context whenever it changes
    const _syncContext = (context) => {
      _currentContext = [...context];
    };

    // Inject a human message into the agent's context
    const injectHumanMessage = (content, type = 'context') => {
      _humanMessageQueue.push({ content, type, timestamp: Date.now() });
      EventBus.emit('human:message-queued', { content, type });
      logger.info(`[Agent] Human message queued (${type}): ${content.substring(0, 50)}...`);
    };

    // Listen for human messages from UI
    EventBus.on('human:message', ({ content, type }) => {
      injectHumanMessage(content, type);
    }, 'AgentLoop');

    // Stuck loop detection state
    let _loopHealth = {
      consecutiveNoToolCalls: 0,
      lastResponseLength: 0,
      repeatedShortResponses: 0
    };

    const _resetLoopHealth = () => {
      _loopHealth = {
        consecutiveNoToolCalls: 0,
        lastResponseLength: 0,
        repeatedShortResponses: 0
      };
    };

    // Circuit breaker for failing tools - use shared utility
    const _toolCircuitBreaker = CircuitBreaker.create({
      threshold: 3,
      resetMs: 60000,
      name: 'AgentToolCircuit',
      emitEvents: true
    });

    const _checkLoopHealth = (iteration, toolCallCount, responseLength) => {
      // Check 1: No tool calls for too many iterations
      if (toolCallCount === 0) {
        _loopHealth.consecutiveNoToolCalls++;
        if (_loopHealth.consecutiveNoToolCalls >= MAX_NO_PROGRESS_ITERATIONS) {
          return {
            stuck: true,
            reason: `No tool calls for ${MAX_NO_PROGRESS_ITERATIONS} consecutive iterations`,
            action: 'request_summary'
          };
        }
      } else {
        _loopHealth.consecutiveNoToolCalls = 0;
      }

      // Check 2: Response getting very short (model degradation)
      if (responseLength < 50 && iteration > 3) {
        _loopHealth.repeatedShortResponses++;
        if (_loopHealth.repeatedShortResponses >= 3) {
          return {
            stuck: true,
            reason: 'Model producing very short responses repeatedly',
            action: 'force_stop'
          };
        }
      } else {
        _loopHealth.repeatedShortResponses = 0;
      }

      _loopHealth.lastResponseLength = responseLength;
      return { stuck: false };
    };

    const _pushActivity = (entry) => {
      _activityLog.push({ ts: Date.now(), ...entry });
      if (_activityLog.length > MAX_ACTIVITY_LOG) {
        _activityLog.shift();
      }
    };

    /**
     * Execute a tool with retry logic and timeout
     * @param {Object} call - Tool call object { name, args }
     * @param {number} iteration - Current iteration number
     * @returns {Promise<{result: string, error: Error|null}>}
     */
    const _executeToolWithRetry = async (call, iteration) => {
      const MAX_RETRIES = 2;
      let result = null;
      let lastError = null;

      const executeWithTimeout = () => Promise.race([
        ToolRunner.execute(call.name, call.args),
        new Promise((_, reject) =>
          setTimeout(() => reject(new Error(`Tool timeout after ${TOOL_EXECUTION_TIMEOUT_MS}ms`)), TOOL_EXECUTION_TIMEOUT_MS)
        )
      ]);

      for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
        try {
          const toolStartTime = Date.now();
          const rawResult = await executeWithTimeout();
          const toolDuration = Date.now() - toolStartTime;

          // Warn on slow tools
          if (toolDuration > TOOL_EXECUTION_TIMEOUT_MS * 0.7) {
            logger.warn(`[Agent] Slow tool: ${call.name} took ${toolDuration}ms`);
            EventBus.emit('tool:slow', { tool: call.name, ms: toolDuration, cycle: iteration });
          }

          result = typeof rawResult === 'string' ? rawResult : JSON.stringify(rawResult, null, 2);
          if (result === 'undefined' || result === undefined) {
            result = '(Tool returned no output)';
          }
          lastError = null;
          break;
        } catch (err) {
          lastError = err;
          const isTimeout = err.message?.includes('timeout');

          if (isTimeout) {
            logger.error(`[Agent] Tool ${call.name} TIMEOUT - exceeded ${TOOL_EXECUTION_TIMEOUT_MS}ms`);
            result = `Error: Tool execution timed out after ${TOOL_EXECUTION_TIMEOUT_MS / 1000}s. The operation may still be running.`;
            EventBus.emit('tool:timeout', { tool: call.name, timeout: TOOL_EXECUTION_TIMEOUT_MS, cycle: iteration });
            break;
          }

          if (attempt < MAX_RETRIES) {
            logger.warn(`[Agent] Tool ${call.name} failed (attempt ${attempt + 1}/${MAX_RETRIES + 1}), retrying...`);
            await new Promise(r => setTimeout(r, 100 * (attempt + 1)));
          }
        }
      }

      return { result, error: lastError };
    };

    /**
     * Handle stuck loop detection and recovery
     * @param {Object} healthCheck - Health check result
     * @param {Array} context - Current context array
     * @param {number} iteration - Current iteration
     * @returns {Promise<boolean>} True if should break the loop
     */
    const _handleStuckLoop = async (healthCheck, context, iteration) => {
      logger.warn(`[Agent] STUCK LOOP DETECTED: ${healthCheck.reason}`);
      EventBus.emit('agent:warning', {
        type: 'stuck_loop',
        reason: healthCheck.reason,
        cycle: iteration
      });

      if (healthCheck.action === 'request_summary') {
        context.push({
          role: 'user',
          content: 'SYSTEM: You appear to be stuck without making progress. Please summarize what you have accomplished so far and what remains to be done, then stop.'
        });
        try {
          const summaryResponse = await LLMClient.chat(context, _modelConfig);
          _pushActivity({ kind: 'stuck_summary', cycle: iteration, content: summaryResponse.content });
          EventBus.emit('agent:history', { type: 'llm_response', cycle: iteration, content: summaryResponse.content });
        } catch (e) {
          logger.error('[Agent] Failed to get summary response', e);
        }
        return true;
      }
      return healthCheck.action === 'force_stop';
    };

    /**
     * Process and log tool result
     * @param {Object} call - Tool call object
     * @param {string} result - Tool result string
     * @param {number} iteration - Current iteration
     * @param {Array} context - Context array to push result to
     */
    const _processToolResult = (call, result, iteration, context) => {
      // Smart truncation
      let processedResult = result;
      if (result.length > 5000 && call.name !== 'ReadFile') {
        processedResult = result.substring(0, 5000) + "\n... [OUTPUT TRUNCATED. USE FileOutline OR ReadFile FOR DETAILS] ...";
      }

      context.push({
        role: 'user',
        content: `TOOL_RESULT (${call.name}):\n${processedResult}`
      });

      EventBus.emit('agent:history', {
        type: 'tool_result',
        cycle: iteration,
        tool: call.name,
        args: call.args,
        result: processedResult
      });
      _pushActivity({ kind: 'tool_result', cycle: iteration, tool: call.name, args: call.args, result: processedResult });
      _logReflection(call, processedResult, iteration);
    };

    const run = async (goal) => {
      if (_isRunning) throw new Errors.StateError('Agent already running');
      if (!_modelConfig) throw new Errors.ConfigError('No model configured');

      _isRunning = true;
      _abortController = new AbortController();
      _resetLoopHealth();
      _toolCircuitBreaker.reset();

      logger.info(`[Agent] Starting cycle. Goal: "${goal}"`);
      EventBus.emit('agent:status', { state: 'STARTING', activity: 'Initializing...' });

      await StateManager.setGoal(goal);
      let context = await _buildInitialContext(goal);
      let iteration = 0;

      // Update tracked context after initialization
      _currentContext = [...context];

      try {
        while (_isRunning && iteration < MAX_ITERATIONS) {
          if (_abortController.signal.aborted) break;

          iteration++;
          await StateManager.incrementCycle();
          logger.info(`[Agent] Iteration ${iteration}`);

          // 2. Insights / Reflection Injection
          let insights = null;
          try {
            if (ReflectionAnalyzer && ReflectionAnalyzer.api) {
              const failurePatterns = await ReflectionAnalyzer.api.detectFailurePatterns();
              if (failurePatterns.length > 0) {
                insights = failurePatterns.slice(0, 2).map(p => p.indicator);
              }
            }
          } catch (e) {
            logger.debug('[Agent] Failed to get reflection insights:', e.message);
          }

          if (insights && insights.length > 0) {
            // Append memory as user message to maintain proper message ordering
            context.push({ role: 'user', content: `[MEMORY] Watch out for these past failure patterns: ${insights.join(', ')}` });
          }

          EventBus.emit('agent:status', { state: 'THINKING', activity: `Cycle ${iteration} - Calling LLM...`, cycle: iteration });

          // Context management: compaction, warnings, and hard limit enforcement
          const contextResult = await ContextManager.manage(context, _modelConfig);
          context = contextResult.context;
          _syncContext(context);

          // Check if context manager halted the agent (hard limit exceeded after aggressive compaction)
          if (contextResult.halted) {
            logger.error(`[Agent] STOPPING: ${contextResult.error}`);
            EventBus.emit('agent:error', {
              error: contextResult.error,
              cycle: iteration
            });
            throw new Error(contextResult.error);
          }

          // Drain human message queue before LLM call
          while (_humanMessageQueue.length > 0) {
            const msg = _humanMessageQueue.shift();
            const prefix = msg.type === 'goal' ? '[GOAL REFINEMENT]' : '[USER]';
            context.push({ role: 'user', content: `${prefix} ${msg.content}` });
            _syncContext(context);

            // Emit for history display
            EventBus.emit('agent:history', {
              type: 'human',
              cycle: iteration,
              content: msg.content,
              messageType: msg.type
            });
            _pushActivity({ kind: 'human_message', cycle: iteration, content: msg.content, messageType: msg.type });
            logger.info(`[Agent] Injected human ${msg.type} message into context`);
          }

          // Cognition: Semantic enrichment (pre-LLM)
          if (CognitionAPI) {
            try {
              const lastUserMsg = context.filter(m => m.role === 'user').pop();
              if (lastUserMsg?.content) {
                context = await CognitionAPI.semantic.enrich(lastUserMsg.content, context);
                _syncContext(context);
              }
            } catch (e) {
              logger.debug('[Agent] Cognition enrichment skipped:', e.message);
            }
          }

          let llmResponseText = '';
          const streamCallback = (text) => {
            EventBus.emit('agent:stream', text);
            llmResponseText += text;
          };

          // Get tool schemas for native tool calling (if supported)
          const toolSchemas = ToolRunner.getToolSchemas ? ToolRunner.getToolSchemas() : [];

          // Multi-model execution if multiple models configured
          let response;
          let arenaResult = null;

          if (_modelConfigs.length >= 2 && MultiModelCoordinator) {
            logger.info(`[Agent] Multi-model mode: ${_modelConfigs.length} models, strategy: ${_consensusStrategy}`);

            const multiModelConfig = {
              mode: _consensusStrategy === 'peer-review' ? 'consensus' : _consensusStrategy,
              models: _modelConfigs
            };

            const onUpdate = (update) => {
              EventBus.emit('agent:multimodel-update', update);
            };

            try {
              arenaResult = await MultiModelCoordinator.execute(context, multiModelConfig, onUpdate);
              response = arenaResult.result;

              // Emit arena results for UI
              EventBus.emit('agent:arena-result', {
                cycle: iteration,
                mode: arenaResult.mode,
                winner: arenaResult.winner,
                solutions: arenaResult.solutions
              });

              logger.info(`[Agent] Arena winner: ${arenaResult.winner?.model || 'unknown'}`);
            } catch (error) {
              logger.error('[Agent] Multi-model execution failed, falling back to single model:', error);
              response = await LLMClient.chat(context, _modelConfig || _modelConfigs[0], streamCallback, { tools: toolSchemas });
            }
          } else {
            // Single model execution (with native tools if supported)
            response = await LLMClient.chat(context, _modelConfig, streamCallback, { tools: toolSchemas });
          }

          const llmEvent = {
            type: 'llm_response',
            cycle: iteration,
            content: response.content
          };
          EventBus.emit('agent:history', llmEvent);
          _pushActivity({ kind: 'llm_response', cycle: iteration, content: response.content });

          const responseContent = response?.content || '';

          // Cognition: Validation and Learning (post-LLM)
          if (CognitionAPI) {
            try {
              // Validate response with symbolic engine
              const validation = await CognitionAPI.symbolic.validate(responseContent, { cycle: iteration });
              if (!validation.valid && !validation.skipped) {
                logger.debug(`[Agent] Cognition validation: ${validation.violations.length} issues`);
              }

              // Auto-learn from response
              await CognitionAPI.learning.extract(responseContent, { cycle: iteration });
            } catch (e) {
              logger.debug('[Agent] Cognition post-processing skipped:', e.message);
            }
          }

          // Use native tool calls if available, otherwise fall back to text parsing
          const toolCalls = response.toolCalls?.length > 0
            ? response.toolCalls
            : ResponseParser.parseToolCalls(responseContent);

          if (response.toolCalls?.length > 0) {
            logger.info(`[Agent] Using ${response.toolCalls.length} native tool call(s)`);
          }

          context.push({ role: 'assistant', content: responseContent });
          _syncContext(context);

          // Check for stuck loop
          const healthCheck = _checkLoopHealth(iteration, toolCalls.length, responseContent.length);
          if (healthCheck.stuck) {
            const shouldBreak = await _handleStuckLoop(healthCheck, context, iteration);
            if (shouldBreak) break;
          }

          if (toolCalls.length > 0) {
            // Limit and partition tools
            const maxTools = getMaxToolCalls();
            const callsToExecute = toolCalls.slice(0, maxTools);
            if (toolCalls.length > maxTools) {
              const limitMsg = `Tool call limit (${maxTools}) reached. Executing first ${maxTools}.`;
              logger.warn('[Agent] ' + limitMsg);
              context.push({ role: 'user', content: limitMsg });
            }

            // Track single-tool usage for batching nudges
            if (callsToExecute.length === 1) {
              _consecutiveSingleToolCalls++;
              if (_consecutiveSingleToolCalls >= SINGLE_TOOL_NUDGE_THRESHOLD) {
                const nudgeMsg = `TIP: You can batch multiple independent tool calls in one response. Read-only tools (ReadFile, ListFiles, Grep, etc.) run in parallel for speed.`;
                context.push({ role: 'user', content: nudgeMsg });
                logger.info('[Agent] Nudging model to batch tool calls');
                _consecutiveSingleToolCalls = 0; // Reset after nudge
              }
            } else {
              _consecutiveSingleToolCalls = 0; // Reset on multi-tool usage
            }

            // Pre-filter: handle parse errors and circuit breaker before execution
            const preResults = []; // Store results for tools that can't execute
            const executableCalls = [];
            for (const call of callsToExecute) {
              if (call.error) {
                logger.warn(`[Agent] Tool ${call.name} has parse error: ${call.error}`);
                preResults.push({ call, finalResult: `Error: ${call.error}`, skipped: true });
                continue;
              }
              if (_toolCircuitBreaker.isOpen(call.name)) {
                const circuitState = _toolCircuitBreaker.getState(call.name);
                const remainingMs = 60000 - (Date.now() - circuitState.tripTime);
                const remainingSec = Math.ceil(remainingMs / 1000);
                logger.warn(`[Agent] Circuit breaker OPEN for ${call.name} - skipping`);
                const skipMsg = `Tool ${call.name} is temporarily disabled. Retry in ${remainingSec}s.`;
                preResults.push({ call, finalResult: `Error: ${skipMsg}`, skipped: true });
                EventBus.emit('tool:circuit_skip', { tool: call.name, remainingMs });
                continue;
              }
              executableCalls.push(call);
            }

            // Partition into read-only (parallel) and mutating (sequential)
            const readOnlyCalls = executableCalls.filter(c => isReadOnlyTool(c.name));
            const mutatingCalls = executableCalls.filter(c => !isReadOnlyTool(c.name));

            const allResults = [...preResults]; // Start with pre-filtered results

            // Execute read-only tools in PARALLEL
            if (readOnlyCalls.length > 0) {
              logger.info(`[Agent] Executing ${readOnlyCalls.length} read-only tools in parallel`);
              EventBus.emit('agent:status', { state: 'ACTING', activity: `Parallel: ${readOnlyCalls.map(c => c.name).join(', ')}` });

              const parallelResults = await Promise.all(readOnlyCalls.map(async (call) => {
                if (_abortController.signal.aborted) return { call, finalResult: 'Aborted', aborted: true };
                const { result, error } = await _executeToolWithRetry(call, iteration);
                let finalResult = result;
                if (error && !result) {
                  logger.error(`[Agent] Tool Error: ${call.name}`, error);
                  finalResult = `Error: ${error.message}`;
                  EventBus.emit('tool:error', { tool: call.name, error: error.message, cycle: iteration });
                  _toolCircuitBreaker.recordFailure(call.name, error);
                } else if (!error) {
                  _toolCircuitBreaker.recordSuccess(call.name);
                }
                return { call, finalResult, result };
              }));
              allResults.push(...parallelResults);
            }

            // Execute mutating tools SEQUENTIALLY
            for (const call of mutatingCalls) {
              if (_abortController.signal.aborted) break;
              logger.info(`[Agent] Tool Call: ${call.name}`);
              EventBus.emit('agent:status', { state: 'ACTING', activity: `Executing: ${call.name}` });

              const { result, error } = await _executeToolWithRetry(call, iteration);
              let finalResult = result;
              if (error && !result) {
                logger.error(`[Agent] Tool Error: ${call.name}`, error);
                finalResult = `Error: ${error.message}`;
                EventBus.emit('tool:error', { tool: call.name, error: error.message, cycle: iteration });
                _toolCircuitBreaker.recordFailure(call.name, error);
              } else if (!error) {
                _toolCircuitBreaker.recordSuccess(call.name);
              }
              allResults.push({ call, finalResult, result });

              // Handle recursive tool chains (sequential within)
              if (result && typeof result === 'object' && result.nextSteps && Array.isArray(result.nextSteps)) {
                logger.info(`[Agent] Recursive tool chain from ${call.name}`);
                for (const step of result.nextSteps) {
                  if (step.tool && step.args) {
                    const chainedCall = { name: step.tool, args: step.args };
                    const { result: chainedResult, error: chainedError } = await _executeToolWithRetry(chainedCall, iteration);
                    let chainedFinal = chainedResult;
                    if (chainedError && !chainedResult) {
                      chainedFinal = `Error: ${chainedError.message}`;
                      _toolCircuitBreaker.recordFailure(step.tool, chainedError);
                      allResults.push({ call: chainedCall, finalResult: chainedFinal });
                      break;
                    }
                    _toolCircuitBreaker.recordSuccess(step.tool);
                    allResults.push({ call: chainedCall, finalResult: chainedFinal });
                  }
                }
              }
            }

            // Process all results into context (preserves original order for pre-results)
            for (const { call, finalResult, aborted } of allResults) {
              if (aborted) continue;
              _processToolResult(call, finalResult, iteration, context);
            }

            // Add execution telemetry feedback if batching occurred
            if (readOnlyCalls.length > 1 || (readOnlyCalls.length > 0 && mutatingCalls.length > 0)) {
              const telemetry = [];
              if (readOnlyCalls.length > 1) {
                telemetry.push(`${readOnlyCalls.length} read-only tools ran in PARALLEL`);
              }
              if (mutatingCalls.length > 0) {
                telemetry.push(`${mutatingCalls.length} mutating tools ran sequentially`);
              }
              context.push({
                role: 'user',
                content: `[Execution: ${telemetry.join(', ')}]`
              });
            }
          } else {
            if (ResponseParser.isDone(response.content)) {
              logger.info('[Agent] Goal achieved.');
              break;
            }
            // WebLLM requires last message to be user/tool - add continuation prompt
            let continuationMsg = 'No tool call detected. Use format:\n\nTOOL_CALL: tool_name\nARGS: { }';
            if (iteration > 3) {
              continuationMsg = 'You must use a tool or say DONE.';
            }
            context.push({ role: 'user', content: continuationMsg });
          }
        }
      } catch (err) {
        if (err instanceof Errors.AbortError) {
          logger.info('[Agent] Cycle aborted.');
        } else {
          logger.error('[Agent] Critical Error', err);
          throw err;
        }
      } finally {
        _isRunning = false;
        _abortController = null;
        EventBus.emit('agent:status', { state: 'IDLE', activity: 'Stopped' });
      }
    };

    const _logReflection = async (call, result, iteration) => {
         if (!ReflectionStore) return;
         const isError = result.startsWith('Error:');
         try {
            await ReflectionStore.add({
                type: isError ? 'error' : 'success',
                content: `Tool ${call.name}`,
                context: { cycle: iteration, tool: call.name, args: call.args, outcome: isError ? 'failed' : 'successful' }
            });
         } catch (e) {
            logger.debug('[Agent] Failed to log reflection:', e.message);
         }
    };

    const _buildInitialContext = async (goal) => {
      const personaPrompt = await PersonaManager.getSystemPrompt();

      const systemPrompt = `
${personaPrompt}

You are an autonomous agent. Your self is the code in the VFS + the LLM that processes it. Your environment is the browser with all its capabilities.

## Tool Call Format
\`\`\`
TOOL_CALL: ToolName
ARGS: { "key": "value" }
\`\`\`

## Core Tools
- ListTools: see all available tools
- ListFiles: list directory contents { "path": "/dir/" }
- ReadFile/WriteFile: read and write files { "path": "/file.js", "content": "..." }
- CreateTool: create + auto-load new tool { "name": "MyTool", "code": "..." }
- Grep: search file contents { "pattern": "text", "path": "/dir", "recursive": true }
- Find: find files by name { "path": "/", "name": "*.js" }
- Edit: find/replace in file { "path": "/file", "operations": [{ "match": "old", "replacement": "new" }] }

## Creating Tools
Tools live in /tools/ with this structure:
\`\`\`javascript
export const tool = {
  name: 'MyTool',
  description: 'What it does',
  inputSchema: { type: 'object', properties: { arg1: { type: 'string' } } }
};

export default async function(args, deps) {
  const { VFS, EventBus, Utils, SemanticMemory, KnowledgeGraph } = deps;
  return 'result';
}
\`\`\`

**CRITICAL: DO NOT USE IMPORT STATEMENTS** - Tools load as blob URLs, so imports fail. Use the deps parameter instead.

Available deps: VFS, EventBus, Utils, AuditLogger, ToolWriter, TransformersClient, WorkerManager, ToolRunner, SemanticMemory, EmbeddingStore, KnowledgeGraph

## VFS Structure
/ ├── .system/ (state.json) ├── .memory/ (knowledge-graph.json, reflections.json) ├── core/ (agent-loop, llm-client, etc.) ├── capabilities/ ├── tools/ (your creations) ├── ui/ └── styles/

## Browser Environment
Tools run in browser context with full DOM access. You have access to: document, window, createElement, querySelector, localStorage, fetch, WebSocket, canvas, audio, video, requestAnimationFrame, and all Web APIs. The page is your canvas - query elements, modify them, inject styles, create animations, delete elements. The main UI container is #app.

## Batching
You can emit up to ${getMaxToolCalls()} tool calls per response. Read-only tools run in PARALLEL, mutating tools run sequentially.

## Rules
- Act autonomously - do not ask for permission
- Use at least one tool per response (unless DONE)
- Batch independent tool calls when possible
- After writing code: LOAD it, EXECUTE it, VERIFY it works
- Use ListFiles before assuming paths exist
- When complete, summarize what you accomplished, then say DONE

## Goal
${goal}
`;

      // Store system prompt for debug visibility
      _currentSystemPrompt = systemPrompt.trim();

      const initialContext = [
        { role: 'system', content: _currentSystemPrompt },
        { role: 'user', content: `Begin. Goal: ${goal}` }
      ];

      // Store context for debug visibility
      _currentContext = [...initialContext];

      return initialContext;
    };

    const getRecentActivities = () => [..._activityLog];

    return {
      run,
      stop: () => { if (_abortController) _abortController.abort(); _isRunning = false; },
      setModel: (c) => { _modelConfig = c; },
      setModels: (models) => {
        _modelConfigs = models || [];
        // Set primary model as first one for fallback
        if (models && models.length > 0) {
          _modelConfig = models[0];
        }
      },
      setConsensusStrategy: (strategy) => { _consensusStrategy = strategy || 'arena'; },
      isRunning: () => _isRunning,
      getRecentActivities,
      // Debug visibility
      getSystemPrompt: () => _currentSystemPrompt,
      getContext: () => [..._currentContext],
      // Human-in-the-loop
      injectHumanMessage,
      getMessageQueue: () => [..._humanMessageQueue]
    };
  }
};

export default AgentLoop;
","/core/context-manager.js":"/**
 * @fileoverview Context Manager
 * Manages token budget and context window compaction.
 * Supports model-specific limits with configurable defaults and overrides.
 */

const ContextManager = {
  metadata: {
    id: 'ContextManager',
    version: '2.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'LLMClient', 'EventBus'],
    type: 'service'
  },

  factory: (deps) => {
    const { logger } = deps.Utils;
    const { LLMClient, EventBus } = deps;

    // ─────────────────────────────────────────────────────────────────────────
    // Model Limits Configuration
    // ─────────────────────────────────────────────────────────────────────────

    // Default limits (conservative, works with most models)
    const DEFAULT_LIMITS = {
      compact: 30000,      // Trigger compaction at 30k tokens
      warning: 100000,     // Emit warning at 100k tokens (80% of hard)
      hard: 120000         // Hard limit - aggressive compact then halt
    };

    // Model-specific overrides (model ID pattern → limits)
    // Patterns are matched with startsWith for flexibility
    // Order matters - more specific patterns should come first
    const MODEL_LIMITS = {
      // Gemini models - massive context windows (1M+)
      // Match gemini-2, gemini-3, gemini-exp, etc.
      'gemini-': { compact: 200000, warning: 400000, hard: 500000 },
      'gemini-exp': { compact: 200000, warning: 400000, hard: 500000 },

      // Anthropic Claude models (200k context)
      'claude-opus-4': { compact: 150000, warning: 170000, hard: 190000 },
      'claude-sonnet-4': { compact: 150000, warning: 170000, hard: 190000 },
      'claude-3-opus': { compact: 150000, warning: 170000, hard: 190000 },
      'claude-3-sonnet': { compact: 150000, warning: 170000, hard: 190000 },
      'claude-3-haiku': { compact: 150000, warning: 170000, hard: 190000 },
      'claude-3.5': { compact: 150000, warning: 170000, hard: 190000 },

      // OpenAI models
      'gpt-5': { compact: 150000, warning: 180000, hard: 200000 },  // Future GPT-5
      'gpt-4o': { compact: 100000, warning: 115000, hard: 125000 },
      'gpt-4-turbo': { compact: 100000, warning: 115000, hard: 125000 },
      'gpt-4': { compact: 6000, warning: 7000, hard: 8000 },  // Original GPT-4 has 8k
      'gpt-3.5': { compact: 12000, warning: 14000, hard: 16000 },
      'o1': { compact: 100000, warning: 180000, hard: 200000 },
      'o3': { compact: 100000, warning: 180000, hard: 200000 },
      'o4': { compact: 150000, warning: 180000, hard: 200000 },

      // Local/WebLLM models (typically smaller context)
      'llama': { compact: 6000, warning: 7000, hard: 8000 },
      'phi': { compact: 3000, warning: 3500, hard: 4000 },
      'qwen': { compact: 25000, warning: 28000, hard: 32000 },
      'smollm': { compact: 1500, warning: 1800, hard: 2000 }
    };

    // Runtime limit overrides (set via setLimits)
    let _runtimeOverrides = null;

    // ─────────────────────────────────────────────────────────────────────────
    // Limit Resolution
    // ─────────────────────────────────────────────────────────────────────────

    const getLimitsForModel = (modelId) => {
      // Runtime overrides take precedence
      if (_runtimeOverrides) {
        return { ...DEFAULT_LIMITS, ..._runtimeOverrides };
      }

      if (!modelId) return DEFAULT_LIMITS;

      const lowerModelId = modelId.toLowerCase();

      // Find matching model pattern
      for (const [pattern, limits] of Object.entries(MODEL_LIMITS)) {
        if (lowerModelId.startsWith(pattern.toLowerCase())) {
          return { ...DEFAULT_LIMITS, ...limits };
        }
      }

      return DEFAULT_LIMITS;
    };

    const setLimits = (overrides) => {
      _runtimeOverrides = overrides;
      logger.info(`[ContextManager] Runtime limits set: ${JSON.stringify(overrides)}`);
    };

    const clearLimitOverrides = () => {
      _runtimeOverrides = null;
      logger.info('[ContextManager] Runtime limit overrides cleared');
    };

    // ─────────────────────────────────────────────────────────────────────────
    // Token Counting (with caching)
    // ─────────────────────────────────────────────────────────────────────────

    let _cachedTokenCount = null;
    let _cachedContextLength = 0;
    let _cachedLastMessageLength = 0;

    /**
     * Improved token estimator using word-based heuristics
     * More accurate than simple char/4 approximation
     * ~1.3 tokens per word for English, accounting for punctuation and whitespace
     */
    const estimateTokens = (text) => {
      if (!text || typeof text !== 'string') return 0;

      // Count words (split on whitespace)
      const words = text.trim().split(/\s+/).filter(w => w.length > 0);
      let tokenEstimate = 0;

      for (const word of words) {
        // Most words are 1 token, but long words and punctuation add more
        if (word.length <= 4) {
          tokenEstimate += 1;
        } else if (word.length <= 8) {
          tokenEstimate += 1.3;
        } else if (word.length <= 12) {
          tokenEstimate += 1.7;
        } else {
          // Very long words (technical terms, URLs) are split into more subwords
          tokenEstimate += Math.ceil(word.length / 4);
        }

        // Add tokens for punctuation attached to words
        const punctuation = (word.match(/[^\w]/g) || []).length;
        tokenEstimate += punctuation * 0.5;
      }

      // Account for message structure overhead (role, formatting)
      return Math.ceil(tokenEstimate);
    };

    const countTokens = (context) => {
      const contextLength = context.length;
      const lastMessageLength = context.length > 0
        ? (context[context.length - 1].content?.length || 0)
        : 0;

      // Cache hit
      if (_cachedTokenCount !== null &&
          contextLength === _cachedContextLength &&
          lastMessageLength === _cachedLastMessageLength) {
        return _cachedTokenCount;
      }

      // Cache miss: recalculate with improved estimator
      let totalTokens = 0;
      for (const m of context) {
        // Add ~4 tokens overhead per message for role/formatting
        totalTokens += 4;
        totalTokens += estimateTokens(m.content);
      }

      _cachedTokenCount = totalTokens;
      _cachedContextLength = contextLength;
      _cachedLastMessageLength = lastMessageLength;

      return _cachedTokenCount;
    };

    const invalidateTokenCache = () => {
      _cachedTokenCount = null;
      _cachedContextLength = 0;
      _cachedLastMessageLength = 0;
    };

    // ─────────────────────────────────────────────────────────────────────────
    // Threshold Checks
    // ─────────────────────────────────────────────────────────────────────────

    const shouldCompact = (context, modelId) => {
      const limits = getLimitsForModel(modelId);
      return countTokens(context) > limits.compact;
    };

    const isAtWarningLevel = (context, modelId) => {
      const limits = getLimitsForModel(modelId);
      const tokens = countTokens(context);
      return tokens > limits.warning && tokens <= limits.hard;
    };

    const exceedsHardLimit = (context, modelId) => {
      const limits = getLimitsForModel(modelId);
      const tokens = countTokens(context);
      return {
        exceeded: tokens > limits.hard,
        tokens,
        limit: limits.hard,
        limits // Include full limits for debugging
      };
    };

    // ─────────────────────────────────────────────────────────────────────────
    // Critical Info Extraction
    // ─────────────────────────────────────────────────────────────────────────

    const extractCriticalInfo = (messages, aggressive = false) => {
      const toolCalls = [];
      const memoryOps = [];
      const errors = [];
      const decisions = [];

      for (const msg of messages) {
        const content = msg.content || '';

        // Extract tool calls
        const toolCallMatches = content.matchAll(/TOOL_CALL:\s*(\w+)/g);
        for (const match of toolCallMatches) {
          toolCalls.push({ tool: match[1], role: msg.role });
        }

        const toolResultMatches = content.matchAll(/Act #(\d+) → (\w+)\s*(.*?)(?=Act #|\n\n|$)/gs);
        for (const match of toolResultMatches) {
          // In aggressive mode, truncate results more
          const resultLen = aggressive ? 50 : 100;
          toolCalls.push({ cycle: match[1], tool: match[2], result: match[3].substring(0, resultLen) });
        }

        // Extract memory operations
        if (content.includes('WriteFile') || content.includes('CreateTool') || content.includes('LoadModule')) {
          const opLen = aggressive ? 80 : 150;
          memoryOps.push({ role: msg.role, op: content.substring(0, opLen) });
        }

        // Extract errors (always preserve these)
        if (content.includes('ERROR') || content.includes('failed') || content.includes('Error:')) {
          const errLen = aggressive ? 100 : 200;
          errors.push(content.substring(0, errLen));
        }

        // Extract key decisions
        const thinkMatches = content.matchAll(/Think #(\d+)\s*\n(.*?)(?=\nTOOL_CALL|\nThink #|$)/gs);
        for (const match of thinkMatches) {
          if (match[2].length > 50) {
            const thoughtLen = aggressive ? 100 : 200;
            decisions.push({ cycle: match[1], thought: match[2].substring(0, thoughtLen) });
          }
        }
      }

      return { toolCalls, memoryOps, errors, decisions };
    };

    // ─────────────────────────────────────────────────────────────────────────
    // Compaction
    // ─────────────────────────────────────────────────────────────────────────

    const compact = async (context, modelConfig, options = {}) => {
      const modelId = modelConfig?.id;
      const limits = getLimitsForModel(modelId);
      const tokens = countTokens(context);
      const aggressive = options.aggressive || false;

      // Check if compaction needed
      if (tokens <= limits.compact && !aggressive) {
        return { context, compacted: false };
      }

      if (!modelConfig) {
        logger.warn('[ContextManager] No model config provided, skipping compaction');
        return { context, compacted: false };
      }

      const mode = aggressive ? 'AGGRESSIVE' : 'STANDARD';
      logger.info(`[ContextManager] ${mode} compaction starting (${tokens} tokens, limit: ${limits.compact})`);

      // Aggressive mode: keep fewer recent messages
      const recentCount = aggressive ? 4 : 8;

      const start = context.slice(0, 2); // System + First User (goal)
      const end = context.slice(-recentCount);
      const middle = context.slice(2, -recentCount);

      if (middle.length === 0) {
        return { context, compacted: false };
      }

      // Extract critical info (with aggressive truncation if needed)
      const critical = extractCriticalInfo(middle, aggressive);

      // Build compact summary
      let compactSummary = `[CONTEXT COMPACTED - ${mode}]\n\n`;

      // In aggressive mode, keep fewer items
      const toolLimit = aggressive ? 5 : 10;
      const memLimit = aggressive ? 3 : 5;
      const errLimit = aggressive ? 2 : 3;
      const decLimit = aggressive ? 3 : 5;

      if (critical.toolCalls.length > 0) {
        compactSummary += `TOOL CALLS (${critical.toolCalls.length}):\n`;
        critical.toolCalls.slice(-toolLimit).forEach(tc => {
          compactSummary += `- ${tc.tool}${tc.result ? ': ' + tc.result : ''}\n`;
        });
        compactSummary += '\n';
      }

      if (critical.memoryOps.length > 0) {
        compactSummary += `MEMORY OPERATIONS:\n`;
        critical.memoryOps.slice(-memLimit).forEach(op => {
          compactSummary += `- ${op.op}\n`;
        });
        compactSummary += '\n';
      }

      if (critical.errors.length > 0) {
        compactSummary += `ERRORS TO AVOID:\n`;
        critical.errors.slice(-errLimit).forEach(err => {
          compactSummary += `- ${err}\n`;
        });
        compactSummary += '\n';
      }

      if (critical.decisions.length > 0) {
        compactSummary += `KEY DECISIONS:\n`;
        critical.decisions.slice(-decLimit).forEach(dec => {
          compactSummary += `- Cycle ${dec.cycle}: ${dec.thought}\n`;
        });
      }

      compactSummary += `\n[${middle.length} messages compacted]`;

      const compacted = [...start, { role: 'user', content: compactSummary }, ...end];
      const newTokens = countTokens(compacted);

      invalidateTokenCache();

      // Notify UI
      if (EventBus) {
        EventBus.emit('context:compacted', {
          mode,
          previousTokens: tokens,
          newTokens,
          reduction: tokens - newTokens,
          preserved: {
            toolCalls: Math.min(critical.toolCalls.length, toolLimit),
            errors: Math.min(critical.errors.length, errLimit),
            decisions: Math.min(critical.decisions.length, decLimit)
          }
        });
      }

      logger.info(`[ContextManager] ${mode} compaction complete: ${tokens} → ${newTokens} tokens (${middle.length} msgs compacted)`);

      return { context: compacted, compacted: true, previousTokens: tokens, newTokens };
    };

    // ─────────────────────────────────────────────────────────────────────────
    // Main Entry Point: Manage Context
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Main context management function. Call before each LLM request.
     * Returns { context, halted, error } where halted=true means agent should stop.
     */
    const manage = async (context, modelConfig) => {
      const modelId = modelConfig?.id;
      const limits = getLimitsForModel(modelId);
      let currentContext = context;
      let tokens = countTokens(currentContext);

      // Emit current token count
      emitTokens(currentContext, modelId);

      // Step 1: Warning level check
      if (isAtWarningLevel(currentContext, modelId)) {
        logger.warn(`[ContextManager] Context at warning level: ${tokens}/${limits.hard} tokens`);
        if (EventBus) {
          EventBus.emit('context:warning', {
            tokens,
            limit: limits.hard,
            percentage: Math.round((tokens / limits.hard) * 100)
          });
        }
      }

      // Step 2: Standard compaction if needed
      if (shouldCompact(currentContext, modelId)) {
        const result = await compact(currentContext, modelConfig, { aggressive: false });
        if (result.compacted) {
          currentContext = result.context;
          tokens = countTokens(currentContext);
        }
      }

      // Step 3: Check if still over hard limit → aggressive compaction
      let hardCheck = exceedsHardLimit(currentContext, modelId);
      if (hardCheck.exceeded) {
        logger.warn(`[ContextManager] Still over hard limit after standard compact, trying aggressive...`);

        const result = await compact(currentContext, modelConfig, { aggressive: true });
        if (result.compacted) {
          currentContext = result.context;
          tokens = countTokens(currentContext);
        }

        // Step 4: Final check - if still over, halt the agent
        hardCheck = exceedsHardLimit(currentContext, modelId);
        if (hardCheck.exceeded) {
          const error = `Context exceeds hard limit even after aggressive compaction: ${tokens}/${limits.hard} tokens. Agent must halt.`;
          logger.error(`[ContextManager] ${error}`);

          if (EventBus) {
            EventBus.emit('context:halted', {
              reason: 'hard_limit_exceeded',
              tokens,
              limit: limits.hard,
              message: error
            });
          }

          return {
            context: currentContext,
            halted: true,
            error
          };
        }
      }

      return {
        context: currentContext,
        halted: false,
        error: null
      };
    };

    // ─────────────────────────────────────────────────────────────────────────
    // Token Emission (for UI)
    // ─────────────────────────────────────────────────────────────────────────

    const emitTokens = (context, modelId) => {
      const limits = getLimitsForModel(modelId);
      const tokens = countTokens(context);
      const hardCheck = exceedsHardLimit(context, modelId);

      if (EventBus) {
        EventBus.emit('agent:tokens', {
          tokens,
          compact: limits.compact,
          warning: limits.warning,
          limit: limits.hard,
          exceeded: hardCheck.exceeded,
          percentage: Math.round((tokens / limits.hard) * 100)
        });
      }

      return tokens;
    };

    // ─────────────────────────────────────────────────────────────────────────
    // Exports
    // ─────────────────────────────────────────────────────────────────────────

    return {
      // Core functions
      countTokens,
      invalidateTokenCache,

      // Threshold checks
      shouldCompact,
      isAtWarningLevel,
      exceedsHardLimit,

      // Compaction
      compact,

      // Main entry point (recommended)
      manage,

      // Configuration
      getLimitsForModel,
      setLimits,
      clearLimitOverrides,

      // Token events
      emitTokens,

      // Expose defaults for reference
      DEFAULT_LIMITS,
      MODEL_LIMITS
    };
  }
};

export default ContextManager;
","/core/llm-client.js":"/**
 * @fileoverview LLM Client
 * Unified interface for model inference.
 * Supports Proxy (HTTP), Browser-Native (WebLLM/WebGPU), and Direct Cloud API execution.
 */

const LLMClient = {
  metadata: {
    id: 'LLMClient',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'RateLimiter?', 'StreamParser?', 'TransformersClient?'],
    type: 'service'
  },

  factory: (deps) => {
    const { Utils, RateLimiter, StreamParser, TransformersClient } = deps;
    const { logger, Errors } = Utils;

    // Fallback rate limiter if not provided
    const _limiter = RateLimiter ? RateLimiter.createLimiter(60) : { waitForToken: async () => {} };
    // Streaming requires StreamParser - disable if not available
    const _canStream = !!StreamParser;
    const _activeRequests = new Map();

    // WebLLM State
    let _webLlmEngine = null;
    let _currentWebModelId = null;
    let _webLlmLoaderPromise = null;

    // Cleanup WebLLM engine and release GPU memory
    const cleanupWebLlmEngine = async () => {
      if (_webLlmEngine) {
        try {
          logger.info('[LLM] Cleaning up WebLLM engine...');
          // WebLLM 0.2.x uses unload(), newer versions may use different method
          if (typeof _webLlmEngine.unload === 'function') {
            await _webLlmEngine.unload();
          } else if (typeof _webLlmEngine.resetChat === 'function') {
            await _webLlmEngine.resetChat();
          }
          _webLlmEngine = null;
          _currentWebModelId = null;
          logger.info('[LLM] WebLLM engine cleaned up, GPU memory released');
        } catch (e) {
          logger.warn('[LLM] Error during WebLLM cleanup:', e.message);
          // Force null even on error
          _webLlmEngine = null;
          _currentWebModelId = null;
        }
      }
    };

    const ensureWebLlmReady = async () => {
      if (typeof window === 'undefined') {
        throw new Errors.ConfigError('WebLLM is only available in browser environments');
      }

      if (window.webllm) return window.webllm;
      if (_webLlmLoaderPromise) return _webLlmLoaderPromise;

      _webLlmLoaderPromise = import('https://esm.run/@mlc-ai/web-llm')
        .then(mod => {
          window.webllm = window.webllm || mod;
          return window.webllm;
        })
        .catch((err) => {
          _webLlmLoaderPromise = null;
          logger.error('[LLM] Failed to load WebLLM runtime', err);
          throw new Errors.ConfigError('Failed to load WebLLM runtime');
        });

      return _webLlmLoaderPromise;
    };

    // --- Helper: Stream Parser (Proxy Mode) ---
    const parseProxyStreamChunk = (chunk, buffer) => {
      const text = buffer + chunk;
      const lines = text.split('\n');
      const remaining = lines.pop() || '';
      const updates = [];

      for (const line of lines) {
        const clean = line.trim();
        if (!clean || clean === 'data: [DONE]') continue;
        if (clean.startsWith('data: ')) {
          try {
            const jsonStr = clean.substring(6);
            if (!jsonStr.startsWith('{')) continue; // Skip malformed chunks
            const json = JSON.parse(jsonStr);
            const content = json.choices?.[0]?.delta?.content
              || json.message?.content
              || json.response
              || '';
            if (content) updates.push(content);
          } catch (e) {
            // Log malformed chunks at debug level
            logger.debug('[LLM] Malformed stream chunk:', clean.substring(6, 50));
          }
        }
      }
      return { updates, remaining };
    };

    // --- Helper: Clean Thoughts ---
    const stripThoughts = (text) => {
        return text
            .replace(/<think>[\s\S]*?<\/think>/gi, '')
            .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
            .trim();
    };

    // --- Helper: Check Native Tool Support ---
    // OpenAI models support function calling (gpt-3.5-turbo, gpt-4, gpt-4o, etc.)
    const supportsNativeTools = (modelConfig) => {
      if (!modelConfig?.id) return false;
      const model = modelConfig.id.toLowerCase();
      const provider = modelConfig.provider?.toLowerCase();

      // OpenAI models - all gpt-3.5-turbo and gpt-4 variants support tools
      if (provider === 'openai' || model.startsWith('gpt-')) {
        return true;
      }

      return false;
    };

    // --- Helper: Parse OpenAI Tool Calls ---
    const parseOpenAIToolCalls = (message) => {
      if (!message?.tool_calls?.length) return null;

      return message.tool_calls.map(tc => ({
        id: tc.id,
        name: tc.function?.name,
        args: (() => {
          try {
            return JSON.parse(tc.function?.arguments || '{}');
          } catch {
            return {};
          }
        })()
      }));
    };

    // --- Mode: Browser-Native (WebLLM) ---
    const _chatBrowser = async (messages, modelConfig, onUpdate, requestId) => {
        logger.info(`[LLM] Browser-Native Request to ${modelConfig.id}`);

        await ensureWebLlmReady();

        try {
            // Initialize Engine if needed or model changed
            if (!_webLlmEngine || _currentWebModelId !== modelConfig.id) {
                // Cleanup previous engine before loading new model
                if (_webLlmEngine && _currentWebModelId !== modelConfig.id) {
                  logger.info(`[LLM] Switching model from ${_currentWebModelId} to ${modelConfig.id}`);
                  await cleanupWebLlmEngine();
                }

                logger.info(`[LLM] Initializing WebLLM Engine for ${modelConfig.id}...`);

                let lastReportedProgress = -5; // Track last reported progress for 5% increments
                let lastProgressTime = Date.now();
                const DOWNLOAD_TIMEOUT_MS = 10 * 60 * 1000; // 10 minute timeout

                const enginePromise = window.webllm.CreateMLCEngine(
                    modelConfig.id,
                    {
                        initProgressCallback: (report) => {
                            lastProgressTime = Date.now(); // Reset timeout on any progress
                            logger.debug(`[WebLLM] Loading: ${report.text}`);

                            if (onUpdate) {
                                // Extract progress percentage if available
                                const progressMatch = report.text.match(/(\d+(?:\.\d+)?)\s*%/);
                                if (progressMatch) {
                                    const progress = Math.floor(parseFloat(progressMatch[1]));
                                    // Only update at 5% increments
                                    if (progress >= lastReportedProgress + 5) {
                                        lastReportedProgress = Math.floor(progress / 5) * 5;
                                        onUpdate(`[System: Downloading model... ${lastReportedProgress}%]\n`);
                                    }
                                } else if (report.text.toLowerCase().includes('download')) {
                                    onUpdate(`[System: Downloading model...]\n`);
                                } else if (report.text.toLowerCase().includes('loading')) {
                                    onUpdate(`[System: Loading model into GPU...]\n`);
                                }
                            }
                        },
                        // Use larger context window to prevent context overflow errors
                        context_window_size: modelConfig.contextSize || 32768
                    }
                );

                // Add timeout that resets on progress
                const timeoutPromise = new Promise((_, reject) => {
                    const checkTimeout = setInterval(() => {
                        if (Date.now() - lastProgressTime > DOWNLOAD_TIMEOUT_MS) {
                            clearInterval(checkTimeout);
                            reject(new Error('Model download stalled - no progress for 10 minutes'));
                        }
                    }, 30000); // Check every 30s

                    // Clean up interval when engine loads
                    enginePromise.then(() => clearInterval(checkTimeout)).catch(() => clearInterval(checkTimeout));
                });

                try {
                    _webLlmEngine = await Promise.race([enginePromise, timeoutPromise]);
                } catch (timeoutErr) {
                    _webLlmEngine = null;
                    _currentWebModelId = null;
                    throw new Errors.ApiError(`Model download failed: ${timeoutErr.message}. Check your internet connection.`, 504);
                }

                _currentWebModelId = modelConfig.id;
            }

            const chatMessages = messages.map(m => ({
                role: m.role,
                content: m.content
            }));

            if (chatMessages[0]?.role !== 'system') {
                logger.warn('[LLM] Missing system prompt at context start. Repairing context for WebLLM.');
                chatMessages.unshift({
                    role: 'system',
                    content: 'You are REPLOID, a careful browser-based AI agent.'
                });
            }

            let fullContent = "";

            if (onUpdate) {
                const chunks = await _webLlmEngine.chat.completions.create({
                    messages: chatMessages,
                    stream: true,
                    temperature: 0.7
                });

                for await (const chunk of chunks) {
                    const delta = chunk.choices[0]?.delta?.content || "";
                    if (delta) {
                        fullContent += delta;
                        onUpdate(delta);
                    }
                }
            } else {
                const reply = await _webLlmEngine.chat.completions.create({
                    messages: chatMessages,
                    stream: false,
                    temperature: 0.7
                });
                fullContent = reply.choices[0].message.content;
            }

            return {
                requestId,
                content: stripThoughts(fullContent),
                raw: fullContent,
                model: modelConfig.id,
                timestamp: Date.now(),
                provider: 'webllm'
            };

        } catch (err) {
            logger.error('[LLM] WebLLM Error', err);
            if (err.message.includes('device') || err.message.includes('memory')) {
                _webLlmEngine = null;
                _currentWebModelId = null;
            }
            throw new Errors.ApiError(`WebLLM Execution Failed: ${err.message}`, 500);
        }
    };

    // --- Mode: Proxy (HTTP) ---
    const _chatProxy = async (messages, modelConfig, onUpdate, requestId) => {
      const endpoint = modelConfig.endpoint || '/api/chat';
      const controller = new AbortController();
      _activeRequests.set(requestId, controller);

      try {
        const requestBody = {
            model: modelConfig.id,
            provider: modelConfig.provider,
            messages: messages,
            stream: !!onUpdate,
            apiKey: modelConfig.apiKey
        };

        if (modelConfig.provider === 'ollama') {
            requestBody.options = { temperature: 0.7 };
        }

        const response = await fetch(endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(requestBody),
          signal: controller.signal
        });

        if (!response.ok) {
          throw new Errors.ApiError(`API Error ${response.status}`, response.status);
        }

        let fullContent = '';

        if (onUpdate && response.body && StreamParser) {
          const rawReader = response.body.getReader();
          const reader = StreamParser.withStreamTimeout(rawReader, StreamParser.DEFAULT_STREAM_TIMEOUT_MS, controller);
          const decoder = new TextDecoder();
          let buffer = '';

          try {
            while (true) {
              const { done, value } = await reader.read();
              if (done) break;

              const chunk = decoder.decode(value, { stream: true });
              const { updates, remaining } = parseProxyStreamChunk(chunk, buffer);
              buffer = remaining;

              for (const text of updates) {
                fullContent += text;
                onUpdate(text);
              }
            }

            // Process remaining buffer on stream end
            if (buffer.trim()) {
              const { updates } = parseProxyStreamChunk(buffer + '\n', '');
              for (const text of updates) {
                fullContent += text;
                onUpdate(text);
              }
            }
          } finally {
            reader.releaseLock();
          }
        } else {
          const data = await response.json();
          fullContent = data.content || data.choices?.[0]?.message?.content || '';
        }

        return {
          requestId,
          content: stripThoughts(fullContent),
          raw: fullContent,
          model: modelConfig.id,
          timestamp: Date.now(),
          provider: modelConfig.provider
        };

      } finally {
        _activeRequests.delete(requestId);
      }
    };

    // --- Mode: Direct Cloud API (browser-cloud) ---
    const CLOUD_API_ENDPOINTS = {
      gemini: 'https://generativelanguage.googleapis.com/v1beta/models',
      openai: 'https://api.openai.com/v1/chat/completions',
      anthropic: 'https://api.anthropic.com/v1/messages'
    };

    const _chatCloudDirect = async (messages, modelConfig, onUpdate, requestId) => {
      const provider = modelConfig.provider;
      const storageKey = `${provider.toUpperCase()}_API_KEY`;
      let apiKey = modelConfig.apiKey || localStorage.getItem(storageKey);

      if (!apiKey) {
        throw new Errors.ConfigError(`API key required for ${provider}. Please add your API key in model settings.`);
      }

      // Validate API key format - detect corrupted localStorage
      if (apiKey.includes('[INFO]') || apiKey.includes('[Boot]') || apiKey.includes(' ') || apiKey.length > 200) {
        logger.error(`[LLM] Corrupted API key detected in localStorage (${storageKey}). Clearing invalid value.`);
        localStorage.removeItem(storageKey);
        throw new Errors.ConfigError(`API key for ${provider} was corrupted. Please re-enter your API key in model settings.`);
      }

      const controller = new AbortController();
      _activeRequests.set(requestId, controller);

      try {
        let response;
        let fullContent = '';

        if (provider === 'gemini') {
          // Google Gemini API (latest format with system_instruction support)
          const action = onUpdate ? 'streamGenerateContent' : 'generateContent';
          const queryParams = onUpdate ? `?alt=sse&key=${apiKey}` : `?key=${apiKey}`;
          const endpoint = `${CLOUD_API_ENDPOINTS.gemini}/${modelConfig.id}:${action}${queryParams}`;

          // Extract system message for system_instruction
          const systemMsg = messages.find(m => m.role === 'system');
          const nonSystemMsgs = messages.filter(m => m.role !== 'system');

          // Convert to Gemini format (user/model roles)
          const geminiMessages = nonSystemMsgs.map(m => ({
            role: m.role === 'assistant' ? 'model' : 'user',
            parts: [{ text: m.content }]
          }));

          const requestBody = {
            contents: geminiMessages,
            generationConfig: {
              temperature: 0.7,
              maxOutputTokens: 8192,
              topP: 0.95
            }
          };

          // Add system instruction if present (supported in Gemini 1.5+)
          if (systemMsg?.content) {
            requestBody.system_instruction = {
              parts: [{ text: systemMsg.content }]
            };
          }

          response = await fetch(endpoint, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(requestBody),
            signal: controller.signal
          });

          if (!response.ok) {
            const errData = await response.json().catch(() => ({}));
            throw new Errors.ApiError(`Gemini API Error: ${errData.error?.message || response.status}`, response.status);
          }

          if (onUpdate && response.body && StreamParser) {
            fullContent = await StreamParser.parseForProvider(response, 'gemini', onUpdate, { abortController: controller });
          } else {
            const data = await response.json();
            fullContent = data.candidates?.[0]?.content?.parts?.[0]?.text || '';
          }

        } else if (provider === 'openai') {
          // OpenAI API with native tool calling support
          const requestBody = {
            model: modelConfig.id,
            messages: messages,
            stream: !!onUpdate,
            temperature: 0.7
          };

          // Add tools if provided and model supports them
          if (modelConfig.tools?.length > 0) {
            requestBody.tools = modelConfig.tools;
            requestBody.tool_choice = 'auto';
          }

          response = await fetch(CLOUD_API_ENDPOINTS.openai, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${apiKey}`
            },
            body: JSON.stringify(requestBody),
            signal: controller.signal
          });

          if (!response.ok) {
            const errData = await response.json().catch(() => ({}));
            throw new Errors.ApiError(`OpenAI API Error: ${errData.error?.message || response.status}`, response.status);
          }

          let toolCalls = null;

          if (onUpdate && response.body && StreamParser) {
            // Streaming mode with tool call support
            if (StreamParser.parseOpenAIStreamWithTools) {
              const streamResult = await StreamParser.parseOpenAIStreamWithTools(response, onUpdate, { abortController: controller });
              fullContent = streamResult.content;
              toolCalls = streamResult.toolCalls;
            } else {
              // Fallback to text-only parsing
              fullContent = await StreamParser.parseForProvider(response, 'openai', onUpdate, { abortController: controller });
            }
          } else {
            const data = await response.json();
            const message = data.choices?.[0]?.message;
            fullContent = message?.content || '';
            toolCalls = parseOpenAIToolCalls(message);
          }

          // Return early with tool calls if present
          if (toolCalls?.length > 0) {
            return {
              requestId,
              content: fullContent,
              raw: fullContent,
              model: modelConfig.id,
              timestamp: Date.now(),
              provider: provider,
              toolCalls // Native tool calls!
            };
          }

        } else if (provider === 'anthropic') {
          // Anthropic Claude API (latest version)
          const systemMsg = messages.find(m => m.role === 'system');
          const nonSystemMsgs = messages.filter(m => m.role !== 'system');

          response = await fetch(CLOUD_API_ENDPOINTS.anthropic, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'x-api-key': apiKey,
              'anthropic-version': '2023-06-01',
              'anthropic-dangerous-direct-browser-access': 'true'
            },
            body: JSON.stringify({
              model: modelConfig.id,
              max_tokens: 8192,
              ...(systemMsg?.content ? { system: systemMsg.content } : {}),
              messages: nonSystemMsgs.map(m => ({
                role: m.role,
                content: m.content
              })),
              stream: !!onUpdate
            }),
            signal: controller.signal
          });

          if (!response.ok) {
            const errData = await response.json().catch(() => ({}));
            throw new Errors.ApiError(`Anthropic API Error: ${errData.error?.message || response.status}`, response.status);
          }

          if (onUpdate && response.body && StreamParser) {
            fullContent = await StreamParser.parseForProvider(response, 'anthropic', onUpdate, { abortController: controller });
          } else {
            const data = await response.json();
            fullContent = data.content?.[0]?.text || '';
          }

        } else {
          throw new Errors.ConfigError(`Unsupported cloud provider: ${provider}`);
        }

        return {
          requestId,
          content: stripThoughts(fullContent),
          raw: fullContent,
          model: modelConfig.id,
          timestamp: Date.now(),
          provider: provider
        };

      } finally {
        _activeRequests.delete(requestId);
      }
    };

    // --- Mode: Transformers.js ---
    const _chatTransformers = async (messages, modelConfig, onUpdate, requestId) => {
      if (!TransformersClient) {
        throw new Errors.ConfigError('TransformersClient not available');
      }

      logger.info(`[LLM] Transformers.js Request to ${modelConfig.id}`);

      const response = await TransformersClient.chat(messages, modelConfig, onUpdate);
      return {
        ...response,
        requestId
      };
    };

    // --- Mode: Dreamer (Local WebGPU) ---
    let _dreamerProvider = null;
    const _chatDreamer = async (messages, modelConfig, onUpdate, requestId) => {
      logger.info(`[LLM] Dreamer Request to ${modelConfig.modelId || modelConfig.id}`);

      // Lazy load Dreamer provider
      if (!_dreamerProvider) {
        const { DreamerProvider } = await import('./dreamer/dreamer-provider.js');
        _dreamerProvider = DreamerProvider;
      }

      // Initialize if needed
      if (!_dreamerProvider.getCapabilities().initialized) {
        await _dreamerProvider.init();
      }

      if (!_dreamerProvider.getCapabilities().available) {
        throw new Errors.ConfigError('Dreamer not available - WebGPU may not be supported');
      }

      // Load model if different
      const modelId = modelConfig.modelId || modelConfig.id;
      const currentModel = _dreamerProvider.getCapabilities().currentModelId;
      if (currentModel !== modelId) {
        await _dreamerProvider.loadModel(modelId, modelConfig.modelUrl, onUpdate, modelConfig.localPath);
      }

      // Stream or sync based on callback
      if (onUpdate) {
        let fullContent = '';
        for await (const token of _dreamerProvider.stream(messages, modelConfig)) {
          fullContent += token;
          onUpdate(token);
        }
        return {
          requestId,
          content: stripThoughts(fullContent),
          raw: fullContent,
          model: modelId,
          timestamp: Date.now(),
          provider: 'dreamer'
        };
      } else {
        const result = await _dreamerProvider.chat(messages, modelConfig);
        return {
          requestId,
          content: stripThoughts(result.content),
          raw: result.content,
          model: modelId,
          timestamp: Date.now(),
          provider: 'dreamer'
        };
      }
    };

    /**
     * @param {Array} messages - Chat messages
     * @param {Object} modelConfig - Model configuration
     * @param {Function} onUpdate - Streaming callback
     * @param {Object} options - Additional options
     * @param {Array} options.tools - Tool schemas for native tool calling
     */
    const chat = async (messages, modelConfig, onUpdate = null, options = {}) => {
      await _limiter.waitForToken();

      const requestId = Utils.generateId('req');
      const isCloudProvider = ['gemini', 'openai', 'anthropic'].includes(modelConfig.provider);

      // Merge tools into modelConfig if native tools supported
      const configWithTools = { ...modelConfig };
      if (options.tools?.length > 0 && supportsNativeTools(modelConfig)) {
        configWithTools.tools = options.tools;
        logger.info(`[LLM] Native tool calling enabled with ${options.tools.length} tools`);
      }

      // Route to appropriate backend
      if (modelConfig.provider === 'dreamer') {
          // Local WebGPU inference via Dreamer
          return await _chatDreamer(messages, configWithTools, onUpdate, requestId);
      } else if (modelConfig.provider === 'transformers' ||
          (TransformersClient && TransformersClient.isTransformersModel && TransformersClient.isTransformersModel(modelConfig.id))) {
          return await _chatTransformers(messages, configWithTools, onUpdate, requestId);
      } else if (modelConfig.hostType === 'browser-cloud' && isCloudProvider) {
          // Direct browser-to-cloud API call (no proxy)
          logger.info(`[LLM] Direct API call to ${modelConfig.provider}/${modelConfig.id}`);
          return await _chatCloudDirect(messages, configWithTools, onUpdate, requestId);
      } else if (modelConfig.queryMethod === 'browser' || modelConfig.provider === 'webllm') {
          return await _chatBrowser(messages, configWithTools, onUpdate, requestId);
      } else {
          return await _chatProxy(messages, configWithTools, onUpdate, requestId);
      }
    };

    const abortRequest = (requestId) => {
      const controller = _activeRequests.get(requestId);
      if (controller) {
        controller.abort();
        return true;
      }
      return false;
    };

    const getWebLLMStatus = () => {
        return {
            loaded: !!_webLlmEngine,
            model: _currentWebModelId
        };
    };

    const getTransformersStatus = () => {
        if (!TransformersClient) return { available: false };
        return TransformersClient.getStatus();
    };

    const getDreamerStatus = () => {
        if (!_dreamerProvider) return { available: false, initialized: false };
        return _dreamerProvider.getCapabilities();
    };

    // Release GPU memory (useful when switching providers or on error)
    const releaseGPUMemory = async () => {
      await cleanupWebLlmEngine();
      if (TransformersClient?.cleanup) {
        await TransformersClient.cleanup();
      }
      if (_dreamerProvider?.destroy) {
        await _dreamerProvider.destroy();
        _dreamerProvider = null;
      }
      logger.info('[LLM] All GPU memory released');
    };

    return { chat, abortRequest, getWebLLMStatus, getTransformersStatus, getDreamerStatus, releaseGPUMemory, supportsNativeTools };
  }
};

export default LLMClient;
","/core/persona-manager.js":"/**
 * @fileoverview Persona Manager
 * dynamic system prompt construction based on config.
 */

const PersonaManager = {
  metadata: {
    id: 'PersonaManager',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils'],
    async: true,
    type: 'core'
  },

  factory: (deps) => {
    const { Utils } = deps;
    const { logger } = Utils;

    // Core RSI instructions - always included
    const CORE_INSTRUCTIONS = `You are REPLOID, an autonomous AI agent in a browser-based VFS.
Your code lives at /core/, /capabilities/, and /tools/. You can read, write, and modify your own source.

## RSI PROTOCOL
1. NEVER declare yourself "done" - there is always room for improvement
2. After writing ANY code: LOAD it, EXECUTE it, VERIFY it works
3. After creating a tool: CALL the tool and observe the output
4. If something fails: debug, fix, retry
5. If something works: look for optimizations, edge cases, enhancements

## TOOL WRITING
All tools live in /tools/. Tools receive a \`deps\` object: { VFS, EventBus, ToolRunner, ... }
- Tool signature: \`export default async function(args, deps) { return result; }\`
- Tool names MUST use CamelCase (e.g., ReadFile, InspectCore)`;

    let _config = null;

    const loadConfig = async () => {
      if (_config) return _config;
      try {
        const response = await fetch('/config.json');
        if (response.ok) {
          _config = await response.json();
        }
      } catch (err) {
        logger.warn('[PersonaManager] Could not load config.json');
      }
      return _config;
    };

    const getSystemPrompt = async () => {
      try {
        const config = await loadConfig();
        if (!config?.personas?.length) {
          return CORE_INSTRUCTIONS;
        }

        // Get selection from localStorage, fallback to config default
        const selectedId = localStorage.getItem('REPLOID_PERSONA_ID')
          || config.defaultPersona
          || 'default';

        const personaDef = config.personas.find(p => p.id === selectedId);
        if (!personaDef) {
          return CORE_INSTRUCTIONS;
        }

        logger.info(`[PersonaManager] Active Persona: ${personaDef.name}`);

        // Combine core instructions with persona-specific guidance
        return `${CORE_INSTRUCTIONS}

## PERSONA: ${personaDef.name}
${personaDef.description}

## BEHAVIORAL FOCUS
${personaDef.instructions || "Focus on continuous improvement."}`;

      } catch (err) {
        logger.error('[PersonaManager] Failed to load persona', err);
        return CORE_INSTRUCTIONS;
      }
    };

    const getPersonas = async () => {
      const config = await loadConfig();
      return config?.personas || [];
    };

    return { getSystemPrompt, getPersonas };
  }
};

export default PersonaManager;
","/core/response-parser.js":"/**
 * @fileoverview Response Parser
 * Extracts tool calls from LLM text using Robust Regex.
 */

const ResponseParser = {
  metadata: {
    id: 'ResponseParser',
    version: '1.0.0', // Backtick template literal support
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils'],
    type: 'service'
  },

  factory: (deps) => {
    const { logger, sanitizeLlmJsonRespPure } = deps.Utils;

    const parseToolCalls = (text) => {
      if (!text) return [];
      const calls = [];

      // Standard Format:
      // TOOL_CALL: name
      // ARGS: { ... }
      // find each TOOL_CALL and extract JSON with brace counting
      const toolCallRegex = /TOOL_CALL:\s*([a-zA-Z0-9_]+)\s*\nARGS:\s*/g;

      let match;
      while ((match = toolCallRegex.exec(text)) !== null) {
        const name = match[1].trim();
        let startIdx = match.index + match[0].length;

        while (startIdx < text.length && /\s/.test(text[startIdx])) startIdx++;
        if (text[startIdx] !== '{') {
          logger.warn(`[ResponseParser] Expected JSON object for ${name}`);
          calls.push({ name, args: {}, error: 'Invalid JSON block' });
          continue;
        }

        let braceCount = 0;
        let stringDelimiter = null; // Track which delimiter started the string: " or `
        let escape = false;
        let endIdx = startIdx;

        for (let i = startIdx; i < text.length; i++) {
          const char = text[i];

          if (escape) {
            escape = false;
            continue;
          }

          if (char === '\\' && stringDelimiter) {
            escape = true;
            continue;
          }

          // Handle both double quotes and backticks as string delimiters
          if (char === '"' || char === '`') {
            if (!stringDelimiter) {
              stringDelimiter = char; // Start string
            } else if (stringDelimiter === char) {
              stringDelimiter = null; // End string (matching delimiter)
            }
            // If in a string with different delimiter, ignore this char
            continue;
          }

          if (!stringDelimiter) {
            if (char === '{') {
              braceCount++;
            } else if (char === '}') {
              braceCount--;
              if (braceCount === 0) {
                endIdx = i + 1;
                break;
              }
            }
          }
        }

        const rawArgs = text.slice(startIdx, endIdx);

        const { json } = sanitizeLlmJsonRespPure(rawArgs);
        try {
          const args = JSON.parse(json);
          calls.push({ name, args });
        } catch (e) {
          logger.warn(`[ResponseParser] Bad args for ${name}`, {
            error: e.message,
            rawLength: rawArgs.length,
            rawPreview: rawArgs.slice(0, 200),
            rawEnd: rawArgs.length > 200 ? rawArgs.slice(-50) : ''
          });
          // Provide actionable error message
          const hint = rawArgs.includes('\n') && !rawArgs.includes('\\n')
            ? ' Hint: Content has literal newlines - use \\n escapes instead.'
            : '';
          calls.push({ name, args: {}, error: `JSON Parse Error: ${e.message}.${hint}` });
        }
      }

      return calls;
    };

    // RSI MODE: Agent should NEVER stop on its own
    // Only the circuit breaker (iteration limit) or user intervention stops it
    // This enforces continuous improvement behavior
    const isDone = (text) => {
        // In RSI mode, we don't accept self-declared completion
        // The agent should always look for improvements
        // To restore non-RSI mode, uncomment below:
        // if (!text) return false;
        // return text.includes('GOAL_ACHIEVED') || text.includes('GOAL_COMPLETE');
        return false;
    };

    return { parseToolCalls, isDone };
  }
};

export default ResponseParser;
","/core/schema-registry.js":"/**
 * @fileoverview Schema Registry
 * Central source for tool input schemas and worker type definitions.
 */

const SchemaRegistry = {
  metadata: {
    id: 'SchemaRegistry',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'VFS'],
    async: true,
    type: 'service'
  },

  factory: (deps) => {
    const { Utils, VFS } = deps;
    const { logger } = Utils;

    const SCHEMAS_PATH = '/.system/schemas.json';

    const _toolSchemas = new Map();   // name -> { schema, builtin }
    const _workerSchemas = new Map(); // name -> { config, builtin }

    // Tool schemas with readOnly flag for parallel execution
    // readOnly: true = safe for parallel execution (no side effects)
    // readOnly: false/undefined = mutating, must execute sequentially
    const DEFAULT_TOOL_SCHEMAS = {
      ReadFile: {
        description: 'Read contents of a file from the virtual filesystem',
        readOnly: true,
        parameters: {
          type: 'object',
          required: ['path'],
          properties: {
            path: { type: 'string', description: 'VFS path to read (e.g. /core/agent-loop.js)' }
          }
        }
      },
      WriteFile: {
        description: 'Write content to a file in the virtual filesystem',
        readOnly: false,
        parameters: {
          type: 'object',
          required: ['path', 'content'],
          properties: {
            path: { type: 'string', description: 'VFS path to write' },
            content: { type: 'string', description: 'Content to write' }
          }
        }
      },
      ListFiles: {
        description: 'List files in a directory',
        readOnly: true,
        parameters: {
          type: 'object',
          properties: {
            path: { type: 'string', description: 'Directory path (default: /)' }
          }
        }
      },
      DeleteFile: {
        description: 'Delete a file from the virtual filesystem',
        readOnly: false,
        parameters: {
          type: 'object',
          required: ['path'],
          properties: {
            path: { type: 'string', description: 'VFS path to delete' }
          }
        }
      },
      CreateTool: {
        description: 'Create a new tool at runtime (Level 1 RSI)',
        readOnly: false,
        parameters: {
          type: 'object',
          required: ['name', 'code'],
          properties: {
            name: { type: 'string', description: 'Tool name (CamelCase, e.g., ReadFile, AnalyzeLogs)' },
            code: { type: 'string', description: 'JavaScript code with export default { metadata: { readOnly: true/false }, call: async (args, deps) => {...} }. Set readOnly: true for tools that only read data (enables parallel execution).' }
          }
        }
      },
      ListTools: {
        description: 'List all available tools',
        readOnly: true,
        parameters: { type: 'object', properties: {} }
      },
      LoadModule: {
        description: 'Hot-reload a module from the VFS',
        readOnly: false,
        parameters: {
          type: 'object',
          required: ['path'],
          properties: {
            path: { type: 'string', description: 'VFS path to module' }
          }
        }
      }
    };

    // Persist non-builtin schemas to VFS
    const _persist = async () => {
      if (!VFS) return;
      try {
        const data = {
          tools: {},
          workers: {}
        };
        // Only persist non-builtin schemas
        for (const [name, entry] of _toolSchemas.entries()) {
          if (!entry.builtin) {
            data.tools[name] = entry.schema;
          }
        }
        for (const [name, entry] of _workerSchemas.entries()) {
          if (!entry.builtin) {
            data.workers[name] = entry.config;
          }
        }
        await VFS.write(SCHEMAS_PATH, JSON.stringify(data, null, 2));
      } catch (e) {
        logger.warn('[SchemaRegistry] Failed to persist schemas:', e.message);
      }
    };

    // Load persisted schemas from VFS
    const _load = async () => {
      if (!VFS) return;
      try {
        const content = await VFS.read(SCHEMAS_PATH);
        if (!content) return;
        const data = JSON.parse(content);
        // Merge persisted tool schemas (non-builtin)
        if (data.tools) {
          for (const [name, schema] of Object.entries(data.tools)) {
            if (!_toolSchemas.has(name)) {
              _toolSchemas.set(name, { schema, builtin: false });
            }
          }
        }
        // Merge persisted worker schemas (non-builtin)
        if (data.workers) {
          for (const [name, config] of Object.entries(data.workers)) {
            if (!_workerSchemas.has(name)) {
              _workerSchemas.set(name, { config, builtin: false });
            }
          }
        }
        logger.info('[SchemaRegistry] Loaded persisted schemas from VFS');
      } catch (e) {
        // File may not exist yet, that's fine
        if (!e.message?.includes('not found')) {
          logger.warn('[SchemaRegistry] Failed to load schemas:', e.message);
        }
      }
    };

    const registerToolSchema = (name, schema, options = {}) => {
      if (!name || !schema) return;
      _toolSchemas.set(name, { schema, builtin: !!options.builtin });
      // Persist non-builtin schemas
      if (!options.builtin) {
        _persist();
      }
    };

    const unregisterToolSchema = (name) => {
      const entry = _toolSchemas.get(name);
      if (entry?.builtin) return false;
      const result = _toolSchemas.delete(name);
      if (result) _persist();
      return result;
    };

    const getToolSchema = (name) => _toolSchemas.get(name)?.schema || null;

    /**
     * Check if a tool is read-only (safe for parallel execution)
     * Falls back to hardcoded list for tools without explicit metadata
     */
    const isToolReadOnly = (name) => {
      const entry = _toolSchemas.get(name);
      if (entry?.schema?.readOnly !== undefined) {
        return entry.schema.readOnly;
      }
      // Fallback for tools without explicit readOnly metadata
      const FALLBACK_READ_ONLY = ['Grep', 'Find', 'Cat', 'Head', 'Tail', 'Ls', 'Pwd', 'ListMemories', 'ListKnowledge', 'Search'];
      return FALLBACK_READ_ONLY.includes(name);
    };

    /**
     * Get list of all read-only tool names
     */
    const getReadOnlyTools = () => {
      const readOnly = [];
      for (const [name, entry] of _toolSchemas.entries()) {
        if (entry.schema?.readOnly === true) {
          readOnly.push(name);
        }
      }
      // Add fallback tools
      const FALLBACK_READ_ONLY = ['Grep', 'Find', 'Cat', 'Head', 'Tail', 'Ls', 'Pwd', 'ListMemories', 'ListKnowledge', 'Search'];
      for (const name of FALLBACK_READ_ONLY) {
        if (!readOnly.includes(name)) {
          readOnly.push(name);
        }
      }
      return readOnly;
    };

    const listToolSchemas = () => {
      const result = [];
      for (const [name, entry] of _toolSchemas.entries()) {
        result.push({ name, ...entry });
      }
      return result;
    };

    const registerWorkerTypes = (workerTypes = {}, options = {}) => {
      let hasNonBuiltin = false;
      for (const [name, config] of Object.entries(workerTypes)) {
        _workerSchemas.set(name, { config, builtin: !!options.builtin });
        if (!options.builtin) hasNonBuiltin = true;
      }
      // Persist if any non-builtin types were added
      if (hasNonBuiltin) _persist();
    };

    const getWorkerType = (name) => _workerSchemas.get(name)?.config || null;

    const listWorkerTypes = () => {
      const result = [];
      for (const [name, entry] of _workerSchemas.entries()) {
        result.push({ name, ...entry });
      }
      return result;
    };

    const init = async () => {
      // Register builtin schemas first
      registerToolSchema('ReadFile', DEFAULT_TOOL_SCHEMAS.ReadFile, { builtin: true });
      registerToolSchema('WriteFile', DEFAULT_TOOL_SCHEMAS.WriteFile, { builtin: true });
      registerToolSchema('ListFiles', DEFAULT_TOOL_SCHEMAS.ListFiles, { builtin: true });
      registerToolSchema('DeleteFile', DEFAULT_TOOL_SCHEMAS.DeleteFile, { builtin: true });
      registerToolSchema('CreateTool', DEFAULT_TOOL_SCHEMAS.CreateTool, { builtin: true });
      registerToolSchema('ListTools', DEFAULT_TOOL_SCHEMAS.ListTools, { builtin: true });
      registerToolSchema('LoadModule', DEFAULT_TOOL_SCHEMAS.LoadModule, { builtin: true });
      logger.info('[SchemaRegistry] Default tool schemas registered');
      // Load persisted non-builtin schemas from VFS
      await _load();
      return true;
    };

    return {
      init,
      registerToolSchema,
      unregisterToolSchema,
      getToolSchema,
      isToolReadOnly,
      getReadOnlyTools,
      listToolSchemas,
      registerWorkerTypes,
      getWorkerType,
      listWorkerTypes
    };
  }
};

export default SchemaRegistry;
","/core/state-helpers-pure.js":"/**
 * @fileoverview Pure State Helpers
 * Logic-only functions for state validation and default values.
 */

const StateHelpersPure = {
  metadata: {
    id: 'StateHelpersPure',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: [],
    type: 'pure'
  },

  factory: () => {

    const DEFAULT_STATE = {
      version: '1.0.0',
      totalCycles: 0,
      currentGoal: null,
      session: {
        id: null,
        startTime: null,
        status: 'idle'
      },
      artifactMetadata: {}, // Tracks file modification times/cycles
      stats: {
        apiCalls: 0,
        errors: 0
      }
    };

    const createInitialState = (overrides = {}) => {
      return {
        ...DEFAULT_STATE,
        ...overrides,
        session: { ...DEFAULT_STATE.session, ...(overrides.session || {}) }
      };
    };

    const validateState = (state) => {
      const errors = [];
      if (!state || typeof state !== 'object') return ['State is not an object'];
      if (typeof state.totalCycles !== 'number') errors.push('Invalid totalCycles');
      return errors.length > 0 ? errors : null;
    };

    /**
     * Push a new goal onto the goal stack
     */
    const pushGoal = (state, newGoalText) => {
      const newState = JSON.parse(JSON.stringify(state));

      if (!newState.currentGoal) {
        newState.currentGoal = {
          id: Date.now().toString(),
          text: newGoalText,
          created: Date.now(),
          subgoals: []
        };
      } else {
        // Add as subgoal to current
        newState.currentGoal.subgoals.push({
          id: Date.now().toString(),
          text: newGoalText,
          created: Date.now(),
          status: 'pending'
        });
      }

      return newState;
    };

    return {
      createInitialState,
      validateState,
      pushGoal,
      DEFAULT_STATE
    };
  }
};

export default StateHelpersPure;
","/core/state-manager.js":"/**
 * @fileoverview State Manager
 * Manages high-level agent state and persistence.
 */

const StateManager = {
  metadata: {
    id: 'StateManager',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'VFS', 'StateHelpersPure', 'EventBus', 'AuditLogger?'], // Optional AuditLogger
    async: true,
    type: 'service'
  },

  factory: (deps) => {
    const { Utils, VFS, StateHelpersPure, EventBus, AuditLogger } = deps;
    const { logger, Errors, generateId } = Utils;

    const STATE_PATH = '/.system/state.json';
    let _state = null;

    const load = async () => {
      try {
        const content = await VFS.read(STATE_PATH);
        const rawState = JSON.parse(content);

        const errors = StateHelpersPure.validateState(rawState);
        if (errors) {
          logger.warn('[StateManager] Validation failed, resetting', errors);
          _state = StateHelpersPure.createInitialState();
        } else {
          _state = StateHelpersPure.createInitialState(rawState); // Merge safely
          logger.info(`[StateManager] Loaded state (Cycle: ${_state.totalCycles})`);
        }
      } catch (err) {
        // If file missing, init fresh
        logger.info('[StateManager] Initializing fresh state.');
        _state = StateHelpersPure.createInitialState();
        await save();
      }
      return _state;
    };

    const save = async (retries = 2) => {
      if (!_state) return;
      try {
        const content = JSON.stringify(_state, null, 2);
        await VFS.write(STATE_PATH, content);
      } catch (err) {
        if (retries > 0) {
          logger.warn(`[StateManager] Save failed, retrying (${retries} left)`, err.message);
          await new Promise(r => setTimeout(r, 100));
          return save(retries - 1);
        }
        logger.error('[StateManager] Save failed after retries', err);
        // Notify UI so user knows state may not be persisted
        if (EventBus) {
          EventBus.emit('error:persistence', {
            message: 'Failed to save agent state',
            details: err.message
          });
        }
      }
    };

    // --- Public API ---

    const getState = () => {
      if (!_state) throw new Errors.StateError('StateManager not initialized');
      return JSON.parse(JSON.stringify(_state));
    };

    const updateState = async (updates) => {
      if (!_state) await load();
      Object.assign(_state, updates);
      await save();
      return getState();
    };

    const setGoal = async (goalText) => {
      if (!_state) await load();

      const goalId = generateId('goal');

      // Use pure helper to maintain goal history
      _state = StateHelpersPure.pushGoal(_state, goalText);

      await save();

      if (AuditLogger && AuditLogger.logAgentAction) {
        AuditLogger.logAgentAction('SET_GOAL', 'StateManager', { goal: goalText });
      }

      // Emit event for swarm sync
      EventBus.emit('goal:set', { id: goalId, goal: goalText, timestamp: Date.now() });

      logger.info(`[StateManager] Goal set: "${goalText.substring(0, 50)}..."`);
    };

    const incrementCycle = async () => {
      if (!_state) await load();
      _state.totalCycles++;
      await save();
    };

    return {
      init: load,
      getState,
      updateState,
      setGoal,
      incrementCycle
    };
  }
};

export default StateManager;
","/core/tool-runner.js":"/**
 * @fileoverview Tool Runner
 * Execution engine for built-in and dynamic tools.
 */

const ToolRunner = {
  metadata: {
    id: 'ToolRunner',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'VFS', 'ToolWriter', 'SubstrateLoader?', 'EventBus', 'AuditLogger?', 'HITLController?', 'ArenaHarness?', 'VFSSandbox?', 'VerificationManager?', 'Shell?', 'gitTools?', 'WorkerManager?', 'EmbeddingStore?', 'SemanticMemory?', 'KnowledgeGraph?', 'SchemaRegistry'],
    async: true,
    type: 'service'
  },

  factory: (deps) => {
    const { Utils, VFS, ToolWriter, SubstrateLoader, EventBus, AuditLogger, HITLController, ArenaHarness, VFSSandbox, VerificationManager, Shell, gitTools, EmbeddingStore, SemanticMemory, KnowledgeGraph, SchemaRegistry } = deps;
    const { logger, Errors } = Utils;

    // WorkerManager is mutable because of circular dependency:
    // ToolRunner -> WorkerManager? (optional) -> ToolRunner
    // WorkerManager initializes AFTER ToolRunner, so we need to update the reference later
    let _workerManager = deps.WorkerManager || null;

    // Arena verification for self-modification (opt-in via config)
    let _arenaGatingEnabled = false;
    try {
      const saved = localStorage.getItem('REPLOID_ARENA_GATING');
      _arenaGatingEnabled = saved === 'true';
    } catch (e) { /* ignore */ }

    const _tools = new Map();
    const _dynamicTools = new Set();

    // Schema cache for performance (#3)
    let _schemaCache = null;
    let _schemaCacheVersion = 0;
    let _toolsVersion = 0;

    const invalidateSchemaCache = () => {
      _toolsVersion++;
      _schemaCache = null;
    };

    // --- Arena Verification for Core Changes ---

    /**
     * Verify a core file change in sandbox before committing
     * @param {string} path - File path
     * @param {string} content - New content
     * @returns {Promise<{passed: boolean, errors: string[]}>}
     */
    const _verifyCoreMutation = async (path, content) => {
      // Skip verification if arena/verification not available or disabled
      if (!_arenaGatingEnabled || !VFSSandbox || !VerificationManager) {
        return { passed: true, errors: [], skipped: true };
      }

      try {
        logger.info(`[ToolRunner] Arena gating: verifying ${path}`);

        // Create snapshot of current state
        const snapshot = await VFSSandbox.createSnapshot();

        try {
          // Apply the change in sandbox
          await VFSSandbox.applyChanges({ [path]: content });

          // Run verification
          const result = await VerificationManager.verifyProposal({ [path]: content });

          return {
            passed: result.passed,
            errors: result.errors || [],
            warnings: result.warnings || []
          };
        } finally {
          // Always restore original state
          await VFSSandbox.restoreSnapshot(snapshot);
        }
      } catch (err) {
        logger.error('[ToolRunner] Arena verification failed:', err.message);
        return { passed: false, errors: [err.message] };
      }
    };

    // All tools are now dynamic (loaded from /tools/)
    // No hardcoded built-ins - full RSI capability

    const loadToolModule = async (path, forcedName = null) => {
      try {
        const code = await VFS.read(path);
        const blob = new Blob([code], { type: 'text/javascript' });
        const url = URL.createObjectURL(blob);

        try {
          const mod = await import(url);
          const handler = typeof mod.default === 'function'
            ? mod.default
            : typeof mod.tool?.call === 'function'
              ? mod.tool.call
              : null;

          if (!handler) {
            logger.warn(`[ToolRunner] ${path} missing default export`);
            return false;
          }

          const name = forcedName || path.split('/').pop().replace('.js', '');
          _tools.set(name, handler);
          _dynamicTools.add(name);
          invalidateSchemaCache(); // Invalidate cache when tools change

          // Capture schema from dynamic tool if available
          if (mod.tool?.inputSchema || mod.tool?.description) {
            SchemaRegistry.registerToolSchema(name, {
              description: mod.tool.description || `Dynamic tool: ${name}`,
              parameters: mod.tool.inputSchema || { type: 'object', properties: {} }
            });
          }

          logger.info(`[ToolRunner] Loaded dynamic tool: ${name}`);
          return true;
        } finally {
          URL.revokeObjectURL(url);
        }
      } catch (e) {
        logger.error(`[ToolRunner] Failed to load ${path}`, e);
        return false;
      }
    };

    const unloadDynamicTools = () => {
      for (const name of _dynamicTools) {
        _tools.delete(name);
        SchemaRegistry.unregisterToolSchema(name);
      }
      _dynamicTools.clear();
    };

    // --- Dynamic Tool Loading ---

    const loadDynamicTools = async () => {
      unloadDynamicTools();

      let files = [];
      try {
        files = await VFS.list('/tools/');
      } catch (err) {
        logger.warn('[ToolRunner] Failed to list /tools directory', err);
        return true;
      }

      for (const file of files) {
        if (!file.endsWith('.js')) continue;
        // Skip test files
        if (file.includes('.test.') || file.includes('.spec.') || file.includes('.integration.')) continue;
        await loadToolModule(file);
      }
      return true;
    };

    const ensureToolLoaded = async (name) => {
      if (_tools.has(name)) return true;
      const path = `/tools/${name}.js`;
      if (await VFS.exists(path)) {
        return await loadToolModule(path, name);
      }
      return false;
    };

    // --- Public API ---

    /**
     * Execute a tool with optional permission filtering (for workers)
     * @param {string} name - Tool name
     * @param {Object} args - Tool arguments
     * @param {Object} [options] - Execution options
     * @param {string[]|'*'} [options.allowedTools] - Allowed tools filter ('*' = all)
     * @param {string} [options.workerId] - Worker ID for audit logging
     */
    const execute = async (name, args = {}, options = {}) => {
      const { allowedTools, workerId } = options;

      // Permission check for worker execution
      if (allowedTools && allowedTools !== '*') {
        if (!allowedTools.includes(name)) {
          const error = new Errors.ToolError(`Tool '${name}' not permitted for this worker type`);
          if (AuditLogger) {
            await AuditLogger.logEvent('TOOL_PERMISSION_DENIED', {
              tool: name,
              workerId,
              allowedTools
            }, 'WARN');
          }
          throw error;
        }
      }
      if (!_tools.has(name)) {
        const loaded = await ensureToolLoaded(name);
        if (!loaded) {
          throw new Errors.ToolError(`Tool not found: ${name}`);
        }
      }

      const toolFn = _tools.get(name);
      if (!toolFn) {
        throw new Errors.ToolError(`Tool not found: ${name}`);
      }

      // HITL approval check for critical tools
      if (_requiresApproval(name)) {
        logger.info(`[ToolRunner] Requesting HITL approval for ${name}`);
        const approved = await _requestApproval(name, args);
        if (!approved) {
          if (AuditLogger) {
            await AuditLogger.logEvent('TOOL_REJECTED', {
              tool: name,
              args: _sanitizeArgs(args),
              reason: 'User rejected via HITL'
            }, 'WARN');
          }
          return { error: 'Operation rejected by user', rejected: true };
        }
      }

      logger.info(`[ToolRunner] Executing ${name}`);
      const startTime = Date.now();

      try {
        // Get TransformersClient from global (pre-resolved in boot.js)
        const TransformersClient = window.REPLOID?.transformersClient || null;

        // Inject comprehensive deps for full RSI capability
        const toolDeps = {
          Utils,
          VFS,
          Shell,
          gitTools,
          EventBus,
          AuditLogger,
          ToolWriter,
          SubstrateLoader,
          VFSSandbox,
          VerificationManager,
          WorkerManager: _workerManager, // Use mutable reference (updated after init)
          TransformersClient,
          EmbeddingStore,
          SemanticMemory,
          KnowledgeGraph,
          ToolRunner: { list: () => Array.from(_tools.keys()), execute, has: (n) => _tools.has(n) }
        };
        const result = await toolFn(args, toolDeps);

        // Audit log successful execution
        if (AuditLogger) {
          await AuditLogger.logEvent('TOOL_EXEC', {
            tool: name,
            args: _sanitizeArgs(args),
            durationMs: Date.now() - startTime,
            success: true,
            ...(workerId && { workerId })
          });
        }

        return result;
      } catch (err) {
        logger.error(`[ToolRunner] Error in ${name}`, err);

        // Audit log failed execution
        if (AuditLogger) {
          await AuditLogger.logEvent('TOOL_EXEC', {
            tool: name,
            args: _sanitizeArgs(args),
            durationMs: Date.now() - startTime,
            success: false,
            error: err.message,
            ...(workerId && { workerId })
          }, 'ERROR');
        }

        const errorWithContext = new Errors.ToolError(err.message, { tool: name, args });
        errorWithContext.stack = err.stack; // Preserve original stack trace
        throw errorWithContext;
      }
    };

    // Sanitize args for logging (truncate large content)
    const _sanitizeArgs = (args) => {
      const sanitized = {};
      for (const [key, value] of Object.entries(args)) {
        if (typeof value === 'string' && value.length > 200) {
          sanitized[key] = value.substring(0, 200) + `... (${value.length} chars)`;
        } else {
          sanitized[key] = value;
        }
      }
      return sanitized;
    };

    // Critical tools that require HITL approval
    const CRITICAL_TOOLS = ['WriteFile', 'DeleteFile', 'CreateTool', 'Edit', 'LoadModule'];

    /**
     * Check if tool requires HITL approval
     * @param {string} toolName - Tool name
     * @returns {boolean}
     */
    const _requiresApproval = (toolName) => {
      if (!HITLController) return false;
      const state = HITLController.getState();
      const mode = state?.approvalMode || 'autonomous';
      if (mode === 'autonomous') return false;
      return CRITICAL_TOOLS.includes(toolName);
    };

    /**
     * Request HITL approval for a tool execution
     * @param {string} toolName - Tool name
     * @param {Object} args - Tool arguments
     * @returns {Promise<boolean>} - True if approved
     */
    const _requestApproval = async (toolName, args) => {
      if (!HITLController) return true;

      return new Promise((resolve) => {
        const approvalId = `tool_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

        HITLController.requestApproval({
          id: approvalId,
          moduleId: 'ToolRunner',
          capability: 'APPROVE_TOOL_EXECUTION',
          action: toolName,
          data: { tool: toolName, args: _sanitizeArgs(args) },
          onApprove: () => resolve(true),
          onReject: (reason) => {
            logger.info(`[ToolRunner] Tool ${toolName} rejected: ${reason}`);
            resolve(false);
          },
          timeout: 300000 // 5 minute timeout
        });
      });
    };

    // Arena gating control
    const setArenaGating = (enabled) => {
      _arenaGatingEnabled = !!enabled;
      try {
        localStorage.setItem('REPLOID_ARENA_GATING', String(_arenaGatingEnabled));
      } catch (e) { /* ignore */ }
      logger.info(`[ToolRunner] Arena gating ${_arenaGatingEnabled ? 'enabled' : 'disabled'}`);
      if (EventBus) {
        EventBus.emit('toolrunner:arena_gating', { enabled: _arenaGatingEnabled });
      }
    };

    const isArenaGatingEnabled = () => _arenaGatingEnabled;

    /**
     * Get tool schemas for native tool calling (OpenAI format)
     * Uses caching for performance - invalidated when tools change
     * @returns {Array<{type: string, function: {name: string, description: string, parameters: object}}>}
     */
    const getToolSchemas = () => {
      // Return cached if valid
      if (_schemaCache && _schemaCacheVersion === _toolsVersion) {
        return _schemaCache;
      }

      const schemas = [];

      for (const [name] of _tools) {
        // Check dynamic schema first, then built-in
        const schema = SchemaRegistry.getToolSchema(name);
        if (schema) {
          schemas.push({
            type: 'function',
            function: {
              name,
              description: schema.description,
              parameters: schema.parameters
            }
          });
        }
      }

      // Cache the result
      _schemaCache = schemas;
      _schemaCacheVersion = _toolsVersion;
      logger.debug(`[ToolRunner] Schema cache built: ${schemas.length} tools`);

      return schemas;
    };

    /**
     * Get filtered list of tools based on allowed tools
     * @param {string[]|'*'} allowedTools - Allowed tools ('*' = all)
     * @returns {string[]} - List of tool names
     */
    const listFiltered = (allowedTools) => {
      const allTools = Array.from(_tools.keys());
      if (allowedTools === '*') return allTools;
      return allTools.filter(name => allowedTools.includes(name));
    };

    /**
     * Get filtered tool schemas for worker (OpenAI format)
     * @param {string[]|'*'} allowedTools - Allowed tools ('*' = all)
     * @returns {Array} - Filtered schemas
     */
    const getToolSchemasFiltered = (allowedTools) => {
      const schemas = getToolSchemas();
      if (allowedTools === '*') return schemas;
      return schemas.filter(s => allowedTools.includes(s.function.name));
    };

    return {
      init: loadDynamicTools,
      execute,
      refresh: loadDynamicTools,
      list: () => Array.from(_tools.keys()),
      listFiltered,
      has: (name) => _tools.has(name),
      setArenaGating,
      isArenaGatingEnabled,
      getToolSchemas,
      getToolSchemasFiltered,
      // Setter for late-bound WorkerManager (circular dependency workaround)
      setWorkerManager: (wm) => {
        _workerManager = wm;
        logger.debug('[ToolRunner] WorkerManager reference updated');
      }
    };
  }
};

export default ToolRunner;
","/core/tool-writer.js":"/**
 * @fileoverview Tool Writer
 * Manages creation and validation of dynamic tools.
 */

const ToolWriter = {
  metadata: {
    id: 'ToolWriter',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'VFS', 'SubstrateLoader?'],
    type: 'service'
  },

  factory: (deps) => {
    const { Utils, VFS, SubstrateLoader } = deps;
    const { logger, Errors } = Utils;

    const validateCode = (code) => {
      // Check if code is provided
      if (!code || typeof code !== 'string') {
        throw new Errors.ValidationError('Missing or invalid code parameter. CreateTool requires { name, code } where code is the tool implementation.');
      }
      // Structural checks (string-based, ES module compatible)
      if (!code.includes('export default') && !code.includes('export const tool')) {
        throw new Errors.ValidationError('Tool must export default or export const tool');
      }
      // Check for async pattern (multiple valid formats)
      const hasAsync = code.includes('async function') ||
                       code.includes('async (') ||
                       code.includes('call: async');
      if (!hasAsync) {
        throw new Errors.ValidationError('Tool call function must be async');
      }
      // Note: Removed new Function(code) check - incompatible with ES module syntax
      // Actual syntax validation happens when ToolRunner does import(blobUrl)
    };

    const create = async (name, code) => {
      if (typeof name !== 'string') {
        throw new Errors.ValidationError('Tool name must be a string');
      }

      const trimmedName = name.trim();
      if (!/^[A-Z][A-Za-z0-9]*$/.test(trimmedName)) {
        throw new Errors.ValidationError('Invalid tool name. Use CamelCase and start with an uppercase letter (e.g., ReadFile, AnalyzeLogs).');
      }

      validateCode(code);

      const path = `/tools/${trimmedName}.js`;

      // Persist
      await VFS.write(path, code);

      // Auto-load the tool if SubstrateLoader is available
      let loadStatus = '';
      if (SubstrateLoader) {
        try {
          await SubstrateLoader.loadModule(path);
          loadStatus = ' and loaded';
        } catch (err) {
          loadStatus = ` (load failed: ${err.message})`;
        }
      }

      logger.info(`[ToolWriter] Created tool: ${trimmedName}${loadStatus}`);
      return `Tool ${trimmedName} created at ${path}${loadStatus}`;
    };

    return { create };
  }
};

export default ToolWriter;
","/core/transformers-client.js":"/**
 * @fileoverview Transformers.js Client
 * Browser-native inference using Hugging Face Transformers.js with WebGPU/WASM.
 * Supports newer models like Qwen3, Gemma3, DeepSeek-R1 that aren't in WebLLM.
 */

const TransformersClient = {
  metadata: {
    id: 'TransformersClient',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'EventBus'],
    type: 'service'
  },

  factory: (deps) => {
    const { Utils, EventBus } = deps;
    const { logger, Errors } = Utils;

    // State
    let _generator = null;
    let _currentModelId = null;
    let _loaderPromise = null;

    // Model configurations for Transformers.js
    const modelConfigs = {
      // Qwen3 models
      'qwen3-0.6b': {
        hfId: 'onnx-community/Qwen3-0.6B-ONNX',
        dtype: 'q4',
        device: 'webgpu'
      },
      'qwen3-1.7b': {
        hfId: 'onnx-community/Qwen3-1.7B-ONNX',
        dtype: 'q4',
        device: 'webgpu'
      },
      // Gemma3 models
      'gemma3-1b': {
        hfId: 'onnx-community/gemma-3-1b-it-ONNX',
        dtype: 'q4',
        device: 'webgpu'
      },
      // SmolLM2
      'smollm2-360m': {
        hfId: 'HuggingFaceTB/SmolLM2-360M-Instruct',
        dtype: 'fp16',
        device: 'webgpu'
      },
      'smollm2-1.7b': {
        hfId: 'HuggingFaceTB/SmolLM2-1.7B-Instruct',
        dtype: 'q4',
        device: 'webgpu'
      },
      // DeepSeek-R1 distilled
      'deepseek-r1-1.5b': {
        hfId: 'onnx-community/DeepSeek-R1-Distill-Qwen-1.5B-ONNX',
        dtype: 'q4',
        device: 'webgpu'
      },
      // Phi-4-mini
      'phi4-mini': {
        hfId: 'onnx-community/Phi-4-mini-instruct-ONNX',
        dtype: 'q4',
        device: 'webgpu'
      }
    };

    const ensureTransformersReady = async () => {
      if (typeof window === 'undefined') {
        throw new Errors.ConfigError('Transformers.js is only available in browser environments');
      }

      if (window.transformers) return window.transformers;
      if (_loaderPromise) return _loaderPromise;

      _loaderPromise = import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@3')
        .then(mod => {
          window.transformers = {
            pipeline: mod.pipeline,
            env: mod.env
          };
          // Configure for WebGPU
          mod.env.backends.onnx.wasm.proxy = false;
          return window.transformers;
        })
        .catch((err) => {
          _loaderPromise = null;
          logger.error('[Transformers] Failed to load runtime', err);
          throw new Errors.ConfigError('Failed to load Transformers.js runtime');
        });

      return _loaderPromise;
    };

    const loadModel = async (modelId) => {
      await ensureTransformersReady();

      const config = modelConfigs[modelId];
      if (!config) {
        throw new Errors.ConfigError(`Unknown Transformers.js model: ${modelId}`);
      }

      if (_currentModelId === modelId && _generator) {
        logger.info(`[Transformers] Model ${modelId} already loaded`);
        return;
      }

      logger.info(`[Transformers] Loading model: ${config.hfId}`);

      // Throttle progress updates - only emit on 5% changes
      let lastReportedPercent = -1;

      try {
        // Dispose previous generator if exists
        if (_generator && _generator.dispose) {
          await _generator.dispose();
        }

        // Emit downloading state
        EventBus.emit('agent:status', {
          state: 'DOWNLOADING',
          activity: `Downloading model: ${modelId}`,
          progress: 0
        });

        _generator = await window.transformers.pipeline(
          'text-generation',
          config.hfId,
          {
            device: config.device,
            dtype: config.dtype,
            progress_callback: (progress) => {
              if (progress.status === 'progress' && progress.total > 0) {
                const percent = Math.round((progress.loaded / progress.total) * 100);
                // Only emit if percent changed by 5% or more
                if (percent - lastReportedPercent >= 5 || percent === 100) {
                  lastReportedPercent = percent;
                  const shortFile = progress.file?.split('/').pop() || 'model';
                  EventBus.emit('agent:status', {
                    state: 'DOWNLOADING',
                    activity: `Downloading ${shortFile}: ${percent}%`,
                    progress: percent
                  });
                }
              }
            }
          }
        );

        _currentModelId = modelId;
        logger.info(`[Transformers] Model ${modelId} loaded successfully`);
      } catch (err) {
        logger.error(`[Transformers] Failed to load model ${modelId}`, err);
        _generator = null;
        _currentModelId = null;
        const reason = err?.message || err?.cause?.message || err?.toString() || 'Unknown error';
        throw new Errors.ApiError(`Failed to load model: ${reason}`, 500);
      }
    };

    const chat = async (messages, modelConfig, onUpdate) => {
      const modelId = modelConfig.transformersModelId || modelConfig.id;

      await loadModel(modelId);

      // Format messages for text generation
      // Transformers.js text-generation expects a single prompt string
      const prompt = formatMessagesForGeneration(messages);

      logger.info(`[Transformers] Generating response for ${modelId}`);

      try {
        let fullContent = '';

        if (onUpdate) {
          // Streaming mode using callback
          const streamer = {
            put: (tokens) => {
              const text = _generator.tokenizer.decode(tokens, { skip_special_tokens: true });
              if (text) {
                fullContent += text;
                onUpdate(text);
              }
            },
            end: () => {}
          };

          await _generator(prompt, {
            max_new_tokens: 2048,
            temperature: 0.7,
            do_sample: true,
            streamer
          });
        } else {
          // Non-streaming mode
          const output = await _generator(prompt, {
            max_new_tokens: 2048,
            temperature: 0.7,
            do_sample: true,
            return_full_text: false
          });

          fullContent = output[0].generated_text;
        }

        return {
          requestId: Utils.generateId('tfjs'),
          content: stripThoughts(fullContent),
          raw: fullContent,
          model: modelId,
          timestamp: Date.now(),
          provider: 'transformers'
        };

      } catch (err) {
        logger.error('[Transformers] Generation error', err);
        const reason = err?.message || err?.cause?.message || err?.toString() || 'Unknown error';
        throw new Errors.ApiError(`Transformers.js generation failed: ${reason}`, 500);
      }
    };

    const formatMessagesForGeneration = (messages) => {
      // Convert chat messages to a single prompt string
      // Using ChatML-like format that most models understand
      let prompt = '';

      for (const msg of messages) {
        if (msg.role === 'system') {
          prompt += `<|system|>\n${msg.content}\n`;
        } else if (msg.role === 'user') {
          prompt += `<|user|>\n${msg.content}\n`;
        } else if (msg.role === 'assistant') {
          prompt += `<|assistant|>\n${msg.content}\n`;
        }
      }

      // Add final assistant tag to prompt generation
      prompt += '<|assistant|>\n';

      return prompt;
    };

    const stripThoughts = (text) => {
      return text
        .replace(/<think>[\s\S]*?<\/think>/gi, '')
        .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
        .trim();
    };

    const getStatus = () => {
      return {
        loaded: !!_generator,
        model: _currentModelId,
        available: typeof window !== 'undefined' && !!navigator.gpu
      };
    };

    const getAvailableModels = () => {
      return Object.entries(modelConfigs).map(([id, config]) => ({
        id,
        hfId: config.hfId,
        dtype: config.dtype
      }));
    };

    const unload = async () => {
      if (_generator && _generator.dispose) {
        await _generator.dispose();
      }
      _generator = null;
      _currentModelId = null;
      logger.info('[Transformers] Model unloaded');
    };

    return {
      chat,
      loadModel,
      getStatus,
      getAvailableModels,
      unload,
      isTransformersModel: (id) => id in modelConfigs || id.startsWith('transformers:')
    };
  }
};

export default TransformersClient;
","/core/utils.js":"/**
 * @fileoverview Core Utilities Module
 * The foundational pure functions, error classes, and protocol parsers.
 */

const Utils = {
  metadata: {
    id: 'Utils',
    version: '1.0.0', // Merged ParserUtils
    genesis: { introduced: 'tabula' },
    dependencies: [],
    type: 'pure'
  },

  factory: () => {
    // --- Internal State ---
    const _logStats = { debug: 0, info: 0, warn: 0, error: 0 };
    const _recentLogs = [];
    const MAX_LOG_HISTORY = 100;

    // --- Error Handling System ---
    class ApplicationError extends Error {
      constructor(message, details = {}) {
        super(message);
        this.name = this.constructor.name;
        this.details = details;
        this.timestamp = Date.now();
      }
    }

    class ApiError extends ApplicationError {
      constructor(message, status, details) {
        super(message, details);
        this.status = status;
      }
    }

    class StateError extends ApplicationError {}
    class ArtifactError extends ApplicationError {}
    class ValidationError extends ApplicationError {}
    class AbortError extends ApplicationError {}
    class ToolError extends ApplicationError {}
    class ConfigError extends ApplicationError {}

    const Errors = {
      ApplicationError,
      ApiError,
      StateError,
      ArtifactError,
      ValidationError,
      AbortError,
      ToolError,
      ConfigError
    };

    // --- Logging System ---
    const logger = {
      _write: (level, message, details) => {
        _logStats[level]++;

        const entry = {
          ts: new Date().toISOString(),
          level: level.toUpperCase(),
          msg: message,
          data: details
        };

        const method = console[level] || console.log;
        const prefix = `[${entry.level}]`;
        details ? method(prefix, message, details) : method(prefix, message);

        _recentLogs.push(entry);
        if (_recentLogs.length > MAX_LOG_HISTORY) _recentLogs.shift();
      },

      debug: (msg, data) => logger._write('debug', msg, data),
      info: (msg, data) => logger._write('info', msg, data),
      warn: (msg, data) => logger._write('warn', msg, data),
      error: (msg, data) => logger._write('error', msg, data),

      getStats: () => ({ ..._logStats }),
      getHistory: () => [..._recentLogs],
      clearHistory: () => { _recentLogs.length = 0; }
    };

    // --- Pure Helpers ---

    const generateId = (prefix = 'id') => {
      const random = Math.random().toString(36).substring(2, 10);
      const ts = Date.now().toString(36);
      return `${prefix}_${ts}_${random}`;
    };

    const trunc = (str, len) => {
      if (!str) return '';
      return str.length > len ? str.substring(0, len - 3) + '...' : str;
    };

    const kabobToCamel = (s) => s.replace(/-([a-z0-9])/gi, (_, c) => c.toUpperCase());

    const escapeHtml = (unsafe) => {
      if (!unsafe) return '';
      return unsafe
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
    };

    /**
     * Convert backtick template literals to valid JSON strings.
     * Handles: `content with "quotes" and newlines` -> "content with \"quotes\" and newlines"
     */
    const convertBacktickStrings = (text) => {
      let result = '';
      let i = 0;
      while (i < text.length) {
        // Check if we're entering a JSON string (double quote)
        if (text[i] === '"') {
          result += '"';
          i++;
          // Skip through the JSON string
          while (i < text.length) {
            if (text[i] === '\\' && i + 1 < text.length) {
              result += text[i] + text[i + 1];
              i += 2;
            } else if (text[i] === '"') {
              result += '"';
              i++;
              break;
            } else {
              result += text[i];
              i++;
            }
          }
        }
        // Check if we're entering a backtick string (needs conversion)
        else if (text[i] === '`') {
          result += '"'; // Start JSON string
          i++;
          // Process backtick string content
          while (i < text.length && text[i] !== '`') {
            const char = text[i];
            if (char === '\\' && i + 1 < text.length) {
              // Preserve escapes
              result += text[i] + text[i + 1];
              i += 2;
            } else if (char === '"') {
              // Escape double quotes inside backtick strings
              result += '\\"';
              i++;
            } else if (char === '\n') {
              // Convert literal newlines to \n
              result += '\\n';
              i++;
            } else if (char === '\r') {
              // Convert carriage returns
              result += '\\r';
              i++;
            } else if (char === '\t') {
              // Convert tabs
              result += '\\t';
              i++;
            } else {
              result += char;
              i++;
            }
          }
          result += '"'; // End JSON string
          if (i < text.length) i++; // Skip closing backtick
        }
        else {
          result += text[i];
          i++;
        }
      }
      return result;
    };

    const sanitizeLlmJsonRespPure = (text) => {
      if (!text || typeof text !== 'string') return { json: "{}", method: "empty" };

      // First try direct parse
      try {
        JSON.parse(text);
        return { json: text, method: "direct" };
      } catch (e) { /* continue */ }

      // Try converting backtick strings to JSON strings
      if (text.includes('`')) {
        try {
          const converted = convertBacktickStrings(text);
          JSON.parse(converted);
          return { json: converted, method: "backtick" };
        } catch (e) { /* continue */ }
      }

      const codeBlock = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
      if (codeBlock) {
        try {
          JSON.parse(codeBlock[1]);
          return { json: codeBlock[1], method: "block" };
        } catch (e) { /* continue */ }
      }

      const firstOpen = text.indexOf('{');
      const lastClose = text.lastIndexOf('}');
      if (firstOpen > -1 && lastClose > firstOpen) {
        const candidate = text.substring(firstOpen, lastClose + 1);
        try {
          JSON.parse(candidate);
          return { json: candidate, method: "heuristic" };
        } catch (e) { /* continue */ }

        // Try backtick conversion on the candidate
        if (candidate.includes('`')) {
          try {
            const converted = convertBacktickStrings(candidate);
            JSON.parse(converted);
            return { json: converted, method: "heuristic+backtick" };
          } catch (e) { /* continue */ }
        }
      }

      return { json: "{}", method: "failed" };
    };

    /**
     * Tracker to prevent EventBus memory leaks
     */
    const createSubscriptionTracker = () => {
      const subs = new Map();
      return {
        track: (id, unsubFn) => {
          if (!subs.has(id)) subs.set(id, []);
          subs.get(id).push(unsubFn);
        },
        unsubscribeAll: (id) => {
          const list = subs.get(id);
          if (list) {
            list.forEach(fn => fn());
            subs.delete(id);
          }
        }
      };
    };

    // --- PAWS Protocol Parsers (Merged from ParserUtils) ---

    const parseCatsBundle = (content) => {
      const files = [];
      if (!content) return { reason: 'Empty content', files: [] };

      const blocks = content.split(/```vfs-file\s*\n/);
      const reasonMatch = content.match(/\*\*Reason:\*\*\s*(.+)/);
      const reason = reasonMatch ? reasonMatch[1].trim() : 'Context bundle';

      for (let i = 1; i < blocks.length; i++) {
        const block = blocks[i];
        const pathMatch = block.match(/^path:\s*(.+?)\s*\n```/);
        if (!pathMatch) continue;

        const filePath = pathMatch[1].trim();
        const contentStartRegex = /```\n([\s\S]*?)\n```/;
        const contentMatch = block.substring(pathMatch[0].length).match(contentStartRegex);

        if (contentMatch) {
          files.push({
            path: filePath,
            content: contentMatch[1]
          });
        }
      }
      return { reason, files };
    };

    const generateCatsBundle = (files, reason = 'Context Export') => {
      const date = new Date().toISOString();
      let out = `## PAWS Context Bundle (cats.md)\n**Generated:** ${date}\n**Reason:** ${reason}\n**Files:** ${files.length}\n\n---\n\n`;
      for (const f of files) {
        out += `\`\`\`vfs-file\npath: ${f.path}\n\`\`\`\n`;
        out += `\`\`\`\n${f.content}\n\`\`\`\n\n---\n\n`;
      }
      return out;
    };

    const parseDogsBundle = (content) => {
      const changes = [];
      if (!content) return changes;

      const blocks = content.split(/```paws-change\s*\n/);

      for (let i = 1; i < blocks.length; i++) {
        const block = blocks[i];
        const metaEndIdx = block.indexOf('```');
        if (metaEndIdx === -1) continue;

        const metaSection = block.substring(0, metaEndIdx);
        const opMatch = metaSection.match(/operation:\s*(CREATE|MODIFY|DELETE)/i);
        const pathMatch = metaSection.match(/file_path:\s*(.+)/);

        if (!opMatch || !pathMatch) continue;

        const operation = opMatch[1].toUpperCase();
        const filePath = pathMatch[1].trim();
        let newContent = null;

        if (operation !== 'DELETE') {
          const contentSection = block.substring(metaEndIdx + 3);
          const contentMatch = contentSection.match(/```\n([\s\S]*?)\n```/);
          newContent = contentMatch ? contentMatch[1] : '';
        }

        changes.push({ operation, file_path: filePath, new_content: newContent });
      }
      return changes;
    };

    const generateDogsBundle = (changes, summary = 'Code Modification') => {
      let out = `## PAWS Change Proposal (dogs.md)\n**Summary:** ${summary}\n**Changes:** ${changes.length}\n\n---\n\n`;
      for (const c of changes) {
        out += `\`\`\`paws-change\noperation: ${c.operation}\nfile_path: ${c.file_path}\n\`\`\`\n`;
        if (c.operation !== 'DELETE') {
          out += `\`\`\`\n${c.new_content || ''}\n\`\`\`\n\n`;
        }
      }
      return out;
    };

    return {
      Errors,
      logger,
      generateId,
      trunc,
      kabobToCamel,
      escapeHtml,
      sanitizeLlmJsonRespPure,
      createSubscriptionTracker,
      // Protocol Parsers
      parseCatsBundle,
      generateCatsBundle,
      parseDogsBundle,
      generateDogsBundle
    };
  }
};

export default Utils;
","/core/verification-manager.js":"/**
 * @fileoverview Verification Manager
 * Pre-flight safety checks via Web Worker.
 */

const VerificationManager = {
  metadata: {
    id: 'VerificationManager',
    version: '1.0.0',
    genesis: { introduced: 'reflection' },
    dependencies: ['Utils', 'VFS'],
    async: true,
    type: 'service'
  },

  factory: (deps) => {
    const { logger } = deps.Utils;
    const { VFS } = deps;

    const WORKER_PATH = '/core/verification-worker.js';

    const createSnapshot = async () => {
      const files = await VFS.list('/');
      const snapshot = {};
      for (const path of files) {
        if (path.endsWith('.js') || path.endsWith('.json')) {
          try { snapshot[path] = await VFS.read(path); } catch (e) {}
        }
      }
      return snapshot;
    };

    const verifyProposal = async (changes) => {
      logger.info('[Verifier] Snapshotting...');
      const snapshot = await createSnapshot();

      // Overlay changes
      for (const c of changes) {
        if (c.operation === 'DELETE') delete snapshot[c.file_path];
        else snapshot[c.file_path] = c.new_content;
      }

      return new Promise((resolve) => {
        const worker = new Worker(WORKER_PATH);

        const timeout = setTimeout(() => {
          worker.terminate();
          resolve({ passed: false, reason: 'Timeout' });
        }, 5000);

        worker.onmessage = (e) => {
          clearTimeout(timeout);
          worker.terminate();
          resolve(e.data);
        };

        worker.onerror = (e) => {
          clearTimeout(timeout);
          worker.terminate();
          logger.error('[Verifier] Crash', e);
          resolve({ passed: false, reason: 'Worker Error' });
        };

        worker.postMessage({ type: 'VERIFY', snapshot });
      });
    };

    return { verifyProposal };
  }
};

export default VerificationManager;
","/core/vfs.js":"/**
 * @fileoverview Virtual File System (VFS)
 * IndexedDB-backed storage.
 *
 * BREAKING: Uses 'reploid-vfs-v2'. Previous v1 data is ignored.
 */

const VFS = {
  metadata: {
    id: 'VFS',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'EventBus?'],
    async: true,
    type: 'service'
