","/tools/Edit.js":"/**
 * @fileoverview Edit - Targeted file modifications
 * Supports literal match/replace operations with optional counts.
 */

async function call(args = {}, deps = {}) {
  const { VFS } = deps;
  if (!VFS) return 'VFS unavailable';

  const { path, operations } = args;
  if (!path) throw new Error('Missing "path" argument');
  if (!Array.isArray(operations) || operations.length === 0) {
    throw new Error('Provide at least one operation in "operations" array');
  }

  let content = await VFS.read(path);
  let changed = false;
  const results = [];

  for (let i = 0; i < operations.length; i++) {
    const op = operations[i] || {};
    const match = op.match;
    const replacement = op.replacement ?? '';
    if (!match) throw new Error(`Operation #${i + 1} missing "match"`);
    if (match.length === 0) throw new Error(`Operation #${i + 1} cannot use empty match string`);

    const count = typeof op.count === 'number' ? op.count : 1;
    const maxReplacements = count <= 0 ? Infinity : count;

    let replacements = 0;
    let startIndex = 0;

    while (replacements < maxReplacements) {
      const idx = content.indexOf(match, startIndex);
      if (idx === -1) break;

      content = content.slice(0, idx) + replacement + content.slice(idx + match.length);
      replacements++;
      changed = true;
      startIndex = idx + replacement.length;
    }

    results.push({
      matchPreview: match.length > 60 ? match.slice(0, 57) + '...' : match,
      replacementPreview: replacement.length > 60 ? replacement.slice(0, 57) + '...' : replacement,
      replacements
    });
  }

  if (changed) {
    await VFS.write(path, content);
  }

  return {
    success: true,
    path,
    changed,
    operations: results
  };
}

export const tool = {
  name: "Edit",
  description: "Apply literal match/replacement edits to a file (operations array with match/replacement/count).",
  call
};

export default call;
","/tools/FileOutline.js":"/**
 * @fileoverview File Outline Tool
 * Reads file structure (imports, exports, functions) without loading full content.
 * Saves tokens during RSI analysis phases.
 */

const inputSchema = {
  type: 'object',
  required: ['path'],
  properties: {
    path: {
      type: 'string',
      description: 'The VFS path to analyze (e.g. /core/agent-loop.js)'
    }
  }
};

const validateInput = (input) => {
  if (!input || typeof input.path !== 'string') {
    return 'Parameter "path" is required';
  }
  if (!input.path.trim()) {
    return 'Parameter "path" cannot be empty';
  }
  return null;
};

async function call(input = {}, deps = {}) {
  const validationError = validateInput(input);
  if (validationError) {
    return { success: false, error: validationError };
  }

  const path = input.path.trim();
  const { VFS } = deps;
  if (!VFS) {
    return { success: false, error: 'VFS unavailable in this environment' };
  }

  if (!(await VFS.exists(path))) {
    return { success: false, error: `File not found: ${path}` };
  }

  const content = await VFS.read(path);
  const lines = content.split('\n');

  const structure = {
    imports: [],
    exports: [],
    functions: [],
    classes: [],
    todos: [],
    loc: lines.length
  };

  // Lightweight Regex Analysis (Fast, low token cost output)
  lines.forEach((line, index) => {
    const i = index + 1;
    const trim = line.trim();

    // Imports
    if (trim.startsWith('import ')) {
        structure.imports.push({ line: i, sig: trim });
    }

    // Exports
    if (trim.startsWith('export ')) {
        structure.exports.push({ line: i, sig: trim.split('{')[0].split('(')[0] });
    }

    // Functions (simple heuristic)
    const funcMatch = line.match(/(async\s+)?function\s+([a-zA-Z0-9_]+)|const\s+([a-zA-Z0-9_]+)\s*=\s*(async\s*)?(\([^)]*\)|[a-z])\s*=>/);
    if (funcMatch) {
        const name = funcMatch[2] || funcMatch[3];
        // Ignore common noise
        if (name && !['if', 'for', 'while', 'switch', 'catch'].includes(name)) {
            structure.functions.push({ line: i, name });
        }
    }

    // Classes
    const classMatch = line.match(/class\s+([a-zA-Z0-9_]+)/);
    if (classMatch) {
        structure.classes.push({ line: i, name: classMatch[1] });
    }

    // TODOs
    if (trim.includes('TODO') || trim.includes('FIXME')) {
        structure.todos.push({ line: i, comment: trim });
    }
  });

  return {
    success: true,
    path,
    summary: `Analyzed ${path} (${structure.loc} lines). Found ${structure.functions.length} functions, ${structure.classes.length} classes.`,
    structure
  };
}

export const tool = {
  name: "FileOutline",
  description: "Analyzes a file's structure (functions, exports, imports) without reading the full content. Use this first to save tokens when exploring code.",
  readOnly: true,
  inputSchema,
  call
};

export default call; // Support both export styles
","/tools/Find.js":"/**
 * @fileoverview Find - Locate files by name pattern
 */

async function call(args = {}, deps = {}) {
  const { VFS } = deps;
  if (!VFS) throw new Error('VFS not available');

  const { path = '/', name } = args;

  const files = await VFS.list(path);

  if (!name) {
    return files.join('\n');
  }

  // Convert glob pattern to regex
  // Supports * (any chars) and ? (single char)
  const regexPattern = name
    .replace(/[.+^${}()|[\]\\]/g, '\\$&')  // Escape special regex chars
    .replace(/\*/g, '.*')                   // * -> .*
    .replace(/\?/g, '.');                   // ? -> .

  const regex = new RegExp(regexPattern, 'i');

  const matches = files.filter(filePath => {
    const fileName = filePath.split('/').pop();
    return regex.test(fileName);
  });

  return matches.join('\n');
}

export const tool = {
  name: "Find",
  description: "Find files matching a name pattern (find)",
  readOnly: true,
  call
};

export default call;
