","/tools/WriteFile.js":"/**
 * @fileoverview WriteFile - Write content to VFS with audit logging and arena verification
 */

async function call(args = {}, deps = {}) {
  const { VFS, EventBus, AuditLogger, VFSSandbox, VerificationManager, SubstrateLoader } = deps;
  if (!VFS) throw new Error('VFS not available');

  const path = args.path || args.file;
  const content = args.content;
  const autoLoad = args.autoLoad === true;

  if (!path) throw new Error('Missing path argument');
  if (content === undefined) throw new Error('Missing content argument');

  const isCore = path.startsWith('/core/');
  const existed = await VFS.exists(path);
  const beforeContent = existed ? await VFS.read(path).catch(() => null) : null;

  // Arena verification for core file changes (when enabled)
  let arenaGatingEnabled = false;
  try {
    arenaGatingEnabled = localStorage.getItem('REPLOID_ARENA_GATING') === 'true';
  } catch (e) { /* ignore */ }

  if (isCore && arenaGatingEnabled && VFSSandbox && VerificationManager) {
    try {
      const snapshot = await VFSSandbox.createSnapshot();
      try {
        await VFSSandbox.applyChanges({ [path]: content });
        const result = await VerificationManager.verifyProposal({ [path]: content });

        if (!result.passed) {
          const errorMsg = `Core modification blocked: ${result.errors?.join(', ') || 'verification failed'}`;
          if (AuditLogger) {
            await AuditLogger.logEvent('CORE_WRITE_BLOCKED', { path, errors: result.errors }, 'WARN');
          }
          if (EventBus) {
            EventBus.emit('tool:core_blocked', { path, errors: result.errors });
          }
          throw new Error(errorMsg);
        }
      } finally {
        await VFSSandbox.restoreSnapshot(snapshot);
      }
    } catch (err) {
      if (err.message.startsWith('Core modification blocked')) throw err;
      // Verification system error - log but proceed
      console.warn('[WriteFile] Arena verification error:', err.message);
    }
  }

  await VFS.write(path, content);

  // Emit event for UI
  if (EventBus) {
    EventBus.emit(existed ? 'vfs:write' : 'artifact:created', { path });
  }

  // Audit log
  if (AuditLogger) {
    await AuditLogger.logEvent('FILE_WRITE', {
      path,
      existed,
      bytesWritten: content.length,
      bytesBefore: beforeContent?.length || 0,
      isCore,
      arenaVerified: isCore && arenaGatingEnabled
    }, isCore ? 'WARN' : 'INFO');
  }

  // Auto-load module if requested and file is .js
  let loadResult = '';
  if (autoLoad && path.endsWith('.js') && SubstrateLoader) {
    try {
      await SubstrateLoader.loadModule(path);
      loadResult = ' + hot-reloaded';
    } catch (err) {
      loadResult = ` (autoLoad failed: ${err.message})`;
    }
  } else if (autoLoad && !SubstrateLoader) {
    loadResult = ' (autoLoad skipped: SubstrateLoader not available)';
  }

  return `Wrote ${path} (${content.length} bytes)${loadResult}`;
}

export const tool = {
  name: "WriteFile",
  description: "Write content to a file in the virtual filesystem",
  inputSchema: {
    type: 'object',
    required: ['path', 'content'],
    properties: {
      path: { type: 'string', description: 'VFS path to write (e.g. /tools/my-tool.js)' },
      content: { type: 'string', description: 'Content to write' },
      autoLoad: { type: 'boolean', description: 'If true and path is .js, hot-reload the module after writing', default: false }
    }
  },
  call
};

export default call;
","/ui/components/confirmation-modal.js":"// Confirmation Modal Component for REPLOID

const ConfirmationModal = {
  metadata: {
    id: 'ConfirmationModal',
    version: '1.0.0',
    dependencies: ['Utils'],
    async: false,
    type: 'ui'
  },

  factory: (deps) => {
    const { Utils } = deps;
    const { logger, escapeHtml } = Utils;

    let activeModal = null;

    const attachHandlers = (overlay, handlers) => {
      overlay.querySelector('.modal-btn-confirm').addEventListener('click', handlers.confirm);
      overlay.querySelector('.modal-btn-cancel').addEventListener('click', handlers.cancel);
      overlay.querySelector('.modal-close').addEventListener('click', handlers.cancel);
      document.addEventListener('keydown', handlers.escape);
      overlay.addEventListener('click', handlers.overlayClick);
    };

    const confirm = (options = {}) => {
      const {
        title = 'Confirm Action',
        message = 'Are you sure you want to proceed?',
        confirmText = 'Confirm',
        cancelText = 'Cancel',
        danger = false,
        details = null
      } = options;

      return new Promise((resolve) => {
        closeModal();

        const overlay = document.createElement('div');
        overlay.className = 'modal-overlay';
        overlay.innerHTML = `
          <div class="modal-content ${danger ? 'modal-danger' : ''}">
            <div class="modal-header">
              <h3 class="modal-title">${escapeHtml(title)}</h3>
              <button class="modal-close" aria-label="Close">&times;</button>
            </div>
            <div class="modal-body">
              <p class="modal-message">${escapeHtml(message)}</p>
              ${details ? `<div class="modal-details">${escapeHtml(details)}</div>` : ''}
            </div>
            <div class="modal-actions">
              <button class="btn btn-secondary modal-btn-cancel">${escapeHtml(cancelText)}</button>
              <button class="btn ${danger ? 'btn-danger' : 'btn-primary'} modal-btn-confirm">${escapeHtml(confirmText)}</button>
            </div>
          </div>
        `;

        const handlers = {
          confirm: () => {
            closeModal();
            resolve(true);
          },
          cancel: () => {
            closeModal();
            resolve(false);
          },
          escape: (event) => {
            if (event.key === 'Escape') handlers.cancel();
          },
          overlayClick: (event) => {
            if (event.target === overlay) handlers.cancel();
          }
        };

        document.body.appendChild(overlay);
        attachHandlers(overlay, handlers);

        activeModal = { overlay, handlers };
        logger.info('[ConfirmationModal] Modal shown:', title);
      });
    };

    const closeModal = () => {
      if (!activeModal) return;
      const { overlay, handlers } = activeModal;

      document.removeEventListener('keydown', handlers.escape);
      overlay.removeEventListener('click', handlers.overlayClick);

      if (overlay.parentNode) {
        overlay.parentNode.removeChild(overlay);
      }

      activeModal = null;
      logger.info('[ConfirmationModal] Modal closed');
    };

    return { confirm, closeModal };
  }
};

export default ConfirmationModal;
