   * @param {number} options.duration - Auto-dismiss duration in ms (0 = no auto-dismiss)
   * @param {Array} options.actions - Array of {label, onClick, primary} objects
   * @returns {string} Toast ID for programmatic dismissal
   */
  show(options = {}) {
    this.init();

    const {
      type = 'info',
      title = '',
      message = '',
      duration = 5000,
      actions = []
    } = options;

    const id = `toast-${++this._idCounter}`;
    const icons = {
      info: '○',
      success: '✓'
    };

    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    toast.id = id;

    let actionsHtml = '';
    if (actions.length > 0) {
      actionsHtml = `
        <div class="toast-actions">
          ${actions.map((a, i) => `
            <button class="toast-btn ${a.primary ? 'primary' : ''}" data-action="${i}">
              ${a.label}
            </button>
          `).join('')}
        </div>
      `;
    }

    toast.innerHTML = `
      <span class="toast-icon">${icons[type] || '○'}</span>
