    const _chatDreamer = async (messages, modelConfig, onUpdate, requestId) => {
      logger.info(`[LLM] Dreamer Request to ${modelConfig.modelId || modelConfig.id}`);

      // Lazy load Dreamer provider
      if (!_dreamerProvider) {
        const { DreamerProvider } = await import('./dreamer/dreamer-provider.js');
        _dreamerProvider = DreamerProvider;
      }

      // Initialize if needed
      if (!_dreamerProvider.getCapabilities().initialized) {
        await _dreamerProvider.init();
      }

      if (!_dreamerProvider.getCapabilities().available) {
        throw new Errors.ConfigError('Dreamer not available - WebGPU may not be supported');
      }

      // Load model if different
      const modelId = modelConfig.modelId || modelConfig.id;
      const currentModel = _dreamerProvider.getCapabilities().currentModelId;
      if (currentModel !== modelId) {
        await _dreamerProvider.loadModel(modelId, modelConfig.modelUrl, onUpdate, modelConfig.localPath);
      }

      // Stream or sync based on callback
      if (onUpdate) {
        let fullContent = '';
        for await (const token of _dreamerProvider.stream(messages, modelConfig)) {
          fullContent += token;
          onUpdate(token);
        }
        return {
          requestId,
          content: stripThoughts(fullContent),
          raw: fullContent,
          model: modelId,
          timestamp: Date.now(),
          provider: 'dreamer'
        };
      } else {
        const result = await _dreamerProvider.chat(messages, modelConfig);
        return {
          requestId,
          content: stripThoughts(result.content),
          raw: result.content,
          model: modelId,
          timestamp: Date.now(),
          provider: 'dreamer'
        };
      }
    };

    /**
     * @param {Array} messages - Chat messages
     * @param {Object} modelConfig - Model configuration
     * @param {Function} onUpdate - Streaming callback
     * @param {Object} options - Additional options
     * @param {Array} options.tools - Tool schemas for native tool calling
     */
    const chat = async (messages, modelConfig, onUpdate = null, options = {}) => {
      await _limiter.waitForToken();

      const requestId = Utils.generateId('req');
      const isCloudProvider = ['gemini', 'openai', 'anthropic'].includes(modelConfig.provider);

      // Merge tools into modelConfig if native tools supported
      const configWithTools = { ...modelConfig };
      if (options.tools?.length > 0 && supportsNativeTools(modelConfig)) {
        configWithTools.tools = options.tools;
        logger.info(`[LLM] Native tool calling enabled with ${options.tools.length} tools`);
      }

      // Route to appropriate backend
      if (modelConfig.provider === 'dreamer') {
          // Local WebGPU inference via Dreamer
          return await _chatDreamer(messages, configWithTools, onUpdate, requestId);
      } else if (modelConfig.provider === 'transformers' ||
          (TransformersClient && TransformersClient.isTransformersModel && TransformersClient.isTransformersModel(modelConfig.id))) {
          return await _chatTransformers(messages, configWithTools, onUpdate, requestId);
      } else if (modelConfig.hostType === 'browser-cloud' && isCloudProvider) {
          // Direct browser-to-cloud API call (no proxy)
          logger.info(`[LLM] Direct API call to ${modelConfig.provider}/${modelConfig.id}`);
          return await _chatCloudDirect(messages, configWithTools, onUpdate, requestId);
      } else if (modelConfig.queryMethod === 'browser' || modelConfig.provider === 'webllm') {
          return await _chatBrowser(messages, configWithTools, onUpdate, requestId);
      } else {
          return await _chatProxy(messages, configWithTools, onUpdate, requestId);
      }
    };

    const abortRequest = (requestId) => {
      const controller = _activeRequests.get(requestId);
      if (controller) {
        controller.abort();
        return true;
      }
      return false;
    };

    const getWebLLMStatus = () => {
        return {
            loaded: !!_webLlmEngine,
            model: _currentWebModelId
        };
    };

    const getTransformersStatus = () => {
        if (!TransformersClient) return { available: false };
        return TransformersClient.getStatus();
    };

    const getDreamerStatus = () => {
        if (!_dreamerProvider) return { available: false, initialized: false };
        return _dreamerProvider.getCapabilities();
    };

    // Release GPU memory (useful when switching providers or on error)
    const releaseGPUMemory = async () => {
      await cleanupWebLlmEngine();
      if (TransformersClient?.cleanup) {
        await TransformersClient.cleanup();
      }
      if (_dreamerProvider?.destroy) {
        await _dreamerProvider.destroy();
        _dreamerProvider = null;
      }
      logger.info('[LLM] All GPU memory released');
    };

    return { chat, abortRequest, getWebLLMStatus, getTransformersStatus, getDreamerStatus, releaseGPUMemory, supportsNativeTools };
  }
};

export default LLMClient;
","/core/persona-manager.js":"/**
 * @fileoverview Persona Manager
 * dynamic system prompt construction based on config.
 */

const PersonaManager = {
  metadata: {
    id: 'PersonaManager',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils'],
    async: true,
    type: 'core'
  },

  factory: (deps) => {
    const { Utils } = deps;
    const { logger } = Utils;

    // Core RSI instructions - always included
    const CORE_INSTRUCTIONS = `You are REPLOID, an autonomous AI agent in a browser-based VFS.
Your code lives at /core/, /capabilities/, and /tools/. You can read, write, and modify your own source.

## RSI PROTOCOL
1. NEVER declare yourself "done" - there is always room for improvement
2. After writing ANY code: LOAD it, EXECUTE it, VERIFY it works
3. After creating a tool: CALL the tool and observe the output
4. If something fails: debug, fix, retry
5. If something works: look for optimizations, edge cases, enhancements

## TOOL WRITING
All tools live in /tools/. Tools receive a \`deps\` object: { VFS, EventBus, ToolRunner, ... }
- Tool signature: \`export default async function(args, deps) { return result; }\`
- Tool names MUST use CamelCase (e.g., ReadFile, InspectCore)`;

    let _config = null;

    const loadConfig = async () => {
      if (_config) return _config;
      try {
        const response = await fetch('/config.json');
        if (response.ok) {
          _config = await response.json();
        }
      } catch (err) {
        logger.warn('[PersonaManager] Could not load config.json');
      }
      return _config;
    };

    const getSystemPrompt = async () => {
      try {
        const config = await loadConfig();
        if (!config?.personas?.length) {
          return CORE_INSTRUCTIONS;
        }

        // Get selection from localStorage, fallback to config default
        const selectedId = localStorage.getItem('REPLOID_PERSONA_ID')
          || config.defaultPersona
          || 'default';

        const personaDef = config.personas.find(p => p.id === selectedId);
        if (!personaDef) {
          return CORE_INSTRUCTIONS;
        }

        logger.info(`[PersonaManager] Active Persona: ${personaDef.name}`);

        // Combine core instructions with persona-specific guidance
        return `${CORE_INSTRUCTIONS}

## PERSONA: ${personaDef.name}
${personaDef.description}

## BEHAVIORAL FOCUS
${personaDef.instructions || "Focus on continuous improvement."}`;

      } catch (err) {
        logger.error('[PersonaManager] Failed to load persona', err);
        return CORE_INSTRUCTIONS;
      }
    };

    const getPersonas = async () => {
      const config = await loadConfig();
      return config?.personas || [];
    };

    return { getSystemPrompt, getPersonas };
  }
};

export default PersonaManager;
","/core/response-parser.js":"/**
 * @fileoverview Response Parser
 * Extracts tool calls from LLM text using Robust Regex.
 */

const ResponseParser = {
  metadata: {
    id: 'ResponseParser',
    version: '1.0.0', // Backtick template literal support
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils'],
    type: 'service'
  },

  factory: (deps) => {
    const { logger, sanitizeLlmJsonRespPure } = deps.Utils;

    const parseToolCalls = (text) => {
      if (!text) return [];
      const calls = [];

      // Standard Format:
      // TOOL_CALL: name
      // ARGS: { ... }
      // find each TOOL_CALL and extract JSON with brace counting
      const toolCallRegex = /TOOL_CALL:\s*([a-zA-Z0-9_]+)\s*\nARGS:\s*/g;

      let match;
      while ((match = toolCallRegex.exec(text)) !== null) {
        const name = match[1].trim();
        let startIdx = match.index + match[0].length;

        while (startIdx < text.length && /\s/.test(text[startIdx])) startIdx++;
        if (text[startIdx] !== '{') {
          logger.warn(`[ResponseParser] Expected JSON object for ${name}`);
          calls.push({ name, args: {}, error: 'Invalid JSON block' });
          continue;
        }

        let braceCount = 0;
        let stringDelimiter = null; // Track which delimiter started the string: " or `
        let escape = false;
        let endIdx = startIdx;

        for (let i = startIdx; i < text.length; i++) {
          const char = text[i];

          if (escape) {
            escape = false;
            continue;
          }

          if (char === '\\' && stringDelimiter) {
            escape = true;
            continue;
          }

          // Handle both double quotes and backticks as string delimiters
          if (char === '"' || char === '`') {
            if (!stringDelimiter) {
              stringDelimiter = char; // Start string
            } else if (stringDelimiter === char) {
              stringDelimiter = null; // End string (matching delimiter)
            }
            // If in a string with different delimiter, ignore this char
            continue;
          }

          if (!stringDelimiter) {
            if (char === '{') {
              braceCount++;
            } else if (char === '}') {
              braceCount--;
              if (braceCount === 0) {
                endIdx = i + 1;
                break;
              }
            }
          }
        }

        const rawArgs = text.slice(startIdx, endIdx);

        const { json } = sanitizeLlmJsonRespPure(rawArgs);
        try {
          const args = JSON.parse(json);
          calls.push({ name, args });
        } catch (e) {
          logger.warn(`[ResponseParser] Bad args for ${name}`, {
            error: e.message,
            rawLength: rawArgs.length,
            rawPreview: rawArgs.slice(0, 200),
            rawEnd: rawArgs.length > 200 ? rawArgs.slice(-50) : ''
          });
          // Provide actionable error message
          const hint = rawArgs.includes('\n') && !rawArgs.includes('\\n')
            ? ' Hint: Content has literal newlines - use \\n escapes instead.'
            : '';
          calls.push({ name, args: {}, error: `JSON Parse Error: ${e.message}.${hint}` });
        }
      }

      return calls;
    };

    // RSI MODE: Agent should NEVER stop on its own
    // Only the circuit breaker (iteration limit) or user intervention stops it
    // This enforces continuous improvement behavior
    const isDone = (text) => {
        // In RSI mode, we don't accept self-declared completion
        // The agent should always look for improvements
        // To restore non-RSI mode, uncomment below:
        // if (!text) return false;
        // return text.includes('GOAL_ACHIEVED') || text.includes('GOAL_COMPLETE');
        return false;
    };

    return { parseToolCalls, isDone };
  }
};

export default ResponseParser;
","/core/schema-registry.js":"/**
 * @fileoverview Schema Registry
 * Central source for tool input schemas and worker type definitions.
 */

const SchemaRegistry = {
  metadata: {
    id: 'SchemaRegistry',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'VFS'],
    async: true,
    type: 'service'
  },

  factory: (deps) => {
    const { Utils, VFS } = deps;
    const { logger } = Utils;

    const SCHEMAS_PATH = '/.system/schemas.json';

    const _toolSchemas = new Map();   // name -> { schema, builtin }
    const _workerSchemas = new Map(); // name -> { config, builtin }

    // Tool schemas with readOnly flag for parallel execution
    // readOnly: true = safe for parallel execution (no side effects)
    // readOnly: false/undefined = mutating, must execute sequentially
    const DEFAULT_TOOL_SCHEMAS = {
      ReadFile: {
        description: 'Read contents of a file from the virtual filesystem',
        readOnly: true,
        parameters: {
          type: 'object',
          required: ['path'],
          properties: {
            path: { type: 'string', description: 'VFS path to read (e.g. /core/agent-loop.js)' }
          }
        }
      },
      WriteFile: {
        description: 'Write content to a file in the virtual filesystem',
        readOnly: false,
        parameters: {
          type: 'object',
          required: ['path', 'content'],
          properties: {
            path: { type: 'string', description: 'VFS path to write' },
            content: { type: 'string', description: 'Content to write' }
          }
        }
      },
      ListFiles: {
        description: 'List files in a directory',
        readOnly: true,
        parameters: {
          type: 'object',
          properties: {
            path: { type: 'string', description: 'Directory path (default: /)' }
          }
        }
      },
      DeleteFile: {
        description: 'Delete a file from the virtual filesystem',
        readOnly: false,
        parameters: {
          type: 'object',
          required: ['path'],
          properties: {
            path: { type: 'string', description: 'VFS path to delete' }
          }
        }
      },
      CreateTool: {
        description: 'Create a new tool at runtime (Level 1 RSI)',
        readOnly: false,
        parameters: {
          type: 'object',
          required: ['name', 'code'],
          properties: {
            name: { type: 'string', description: 'Tool name (CamelCase, e.g., ReadFile, AnalyzeLogs)' },
            code: { type: 'string', description: 'JavaScript code with export default { metadata: { readOnly: true/false }, call: async (args, deps) => {...} }. Set readOnly: true for tools that only read data (enables parallel execution).' }
          }
        }
      },
      ListTools: {
        description: 'List all available tools',
        readOnly: true,
        parameters: { type: 'object', properties: {} }
      },
      LoadModule: {
        description: 'Hot-reload a module from the VFS',
        readOnly: false,
        parameters: {
          type: 'object',
          required: ['path'],
          properties: {
            path: { type: 'string', description: 'VFS path to module' }
          }
        }
      }
    };

    // Persist non-builtin schemas to VFS
    const _persist = async () => {
      if (!VFS) return;
      try {
        const data = {
          tools: {},
          workers: {}
        };
        // Only persist non-builtin schemas
        for (const [name, entry] of _toolSchemas.entries()) {
          if (!entry.builtin) {
            data.tools[name] = entry.schema;
          }
        }
        for (const [name, entry] of _workerSchemas.entries()) {
          if (!entry.builtin) {
            data.workers[name] = entry.config;
          }
        }
        await VFS.write(SCHEMAS_PATH, JSON.stringify(data, null, 2));
      } catch (e) {
        logger.warn('[SchemaRegistry] Failed to persist schemas:', e.message);
      }
    };

    // Load persisted schemas from VFS
    const _load = async () => {
      if (!VFS) return;
      try {
        const content = await VFS.read(SCHEMAS_PATH);
        if (!content) return;
        const data = JSON.parse(content);
        // Merge persisted tool schemas (non-builtin)
        if (data.tools) {
          for (const [name, schema] of Object.entries(data.tools)) {
            if (!_toolSchemas.has(name)) {
              _toolSchemas.set(name, { schema, builtin: false });
            }
          }
        }
        // Merge persisted worker schemas (non-builtin)
        if (data.workers) {
          for (const [name, config] of Object.entries(data.workers)) {
            if (!_workerSchemas.has(name)) {
              _workerSchemas.set(name, { config, builtin: false });
            }
          }
        }
        logger.info('[SchemaRegistry] Loaded persisted schemas from VFS');
      } catch (e) {
        // File may not exist yet, that's fine
        if (!e.message?.includes('not found')) {
          logger.warn('[SchemaRegistry] Failed to load schemas:', e.message);
        }
      }
    };

    const registerToolSchema = (name, schema, options = {}) => {
      if (!name || !schema) return;
      _toolSchemas.set(name, { schema, builtin: !!options.builtin });
      // Persist non-builtin schemas
      if (!options.builtin) {
        _persist();
      }
    };

    const unregisterToolSchema = (name) => {
      const entry = _toolSchemas.get(name);
      if (entry?.builtin) return false;
      const result = _toolSchemas.delete(name);
      if (result) _persist();
      return result;
    };

    const getToolSchema = (name) => _toolSchemas.get(name)?.schema || null;

    /**
     * Check if a tool is read-only (safe for parallel execution)
     * Falls back to hardcoded list for tools without explicit metadata
     */
    const isToolReadOnly = (name) => {
      const entry = _toolSchemas.get(name);
      if (entry?.schema?.readOnly !== undefined) {
        return entry.schema.readOnly;
      }
      // Fallback for tools without explicit readOnly metadata
      const FALLBACK_READ_ONLY = ['Grep', 'Find', 'Cat', 'Head', 'Tail', 'Ls', 'Pwd', 'ListMemories', 'ListKnowledge', 'Search'];
      return FALLBACK_READ_ONLY.includes(name);
    };

    /**
     * Get list of all read-only tool names
     */
    const getReadOnlyTools = () => {
      const readOnly = [];
      for (const [name, entry] of _toolSchemas.entries()) {
        if (entry.schema?.readOnly === true) {
          readOnly.push(name);
        }
      }
      // Add fallback tools
      const FALLBACK_READ_ONLY = ['Grep', 'Find', 'Cat', 'Head', 'Tail', 'Ls', 'Pwd', 'ListMemories', 'ListKnowledge', 'Search'];
      for (const name of FALLBACK_READ_ONLY) {
        if (!readOnly.includes(name)) {
          readOnly.push(name);
        }
      }
      return readOnly;
    };

    const listToolSchemas = () => {
      const result = [];
      for (const [name, entry] of _toolSchemas.entries()) {
        result.push({ name, ...entry });
      }
      return result;
    };

    const registerWorkerTypes = (workerTypes = {}, options = {}) => {
      let hasNonBuiltin = false;
      for (const [name, config] of Object.entries(workerTypes)) {
        _workerSchemas.set(name, { config, builtin: !!options.builtin });
        if (!options.builtin) hasNonBuiltin = true;
      }
      // Persist if any non-builtin types were added
      if (hasNonBuiltin) _persist();
    };

    const getWorkerType = (name) => _workerSchemas.get(name)?.config || null;

    const listWorkerTypes = () => {
      const result = [];
      for (const [name, entry] of _workerSchemas.entries()) {
        result.push({ name, ...entry });
      }
      return result;
    };

    const init = async () => {
      // Register builtin schemas first
      registerToolSchema('ReadFile', DEFAULT_TOOL_SCHEMAS.ReadFile, { builtin: true });
      registerToolSchema('WriteFile', DEFAULT_TOOL_SCHEMAS.WriteFile, { builtin: true });
      registerToolSchema('ListFiles', DEFAULT_TOOL_SCHEMAS.ListFiles, { builtin: true });
      registerToolSchema('DeleteFile', DEFAULT_TOOL_SCHEMAS.DeleteFile, { builtin: true });
      registerToolSchema('CreateTool', DEFAULT_TOOL_SCHEMAS.CreateTool, { builtin: true });
      registerToolSchema('ListTools', DEFAULT_TOOL_SCHEMAS.ListTools, { builtin: true });
      registerToolSchema('LoadModule', DEFAULT_TOOL_SCHEMAS.LoadModule, { builtin: true });
      logger.info('[SchemaRegistry] Default tool schemas registered');
      // Load persisted non-builtin schemas from VFS
      await _load();
      return true;
    };

    return {
      init,
      registerToolSchema,
      unregisterToolSchema,
      getToolSchema,
      isToolReadOnly,
      getReadOnlyTools,
      listToolSchemas,
      registerWorkerTypes,
      getWorkerType,
      listWorkerTypes
    };
  }
};

export default SchemaRegistry;
","/core/state-helpers-pure.js":"/**
 * @fileoverview Pure State Helpers
 * Logic-only functions for state validation and default values.
 */

const StateHelpersPure = {
  metadata: {
    id: 'StateHelpersPure',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: [],
    type: 'pure'
  },

  factory: () => {

    const DEFAULT_STATE = {
      version: '1.0.0',
      totalCycles: 0,
      currentGoal: null,
      session: {
        id: null,
        startTime: null,
        status: 'idle'
      },
      artifactMetadata: {}, // Tracks file modification times/cycles
      stats: {
        apiCalls: 0,
        errors: 0
      }
    };

    const createInitialState = (overrides = {}) => {
      return {
        ...DEFAULT_STATE,
        ...overrides,
        session: { ...DEFAULT_STATE.session, ...(overrides.session || {}) }
      };
    };

    const validateState = (state) => {
      const errors = [];
      if (!state || typeof state !== 'object') return ['State is not an object'];
      if (typeof state.totalCycles !== 'number') errors.push('Invalid totalCycles');
      return errors.length > 0 ? errors : null;
    };

    /**
     * Push a new goal onto the goal stack
     */
    const pushGoal = (state, newGoalText) => {
      const newState = JSON.parse(JSON.stringify(state));

      if (!newState.currentGoal) {
        newState.currentGoal = {
          id: Date.now().toString(),
          text: newGoalText,
          created: Date.now(),
          subgoals: []
        };
      } else {
        // Add as subgoal to current
        newState.currentGoal.subgoals.push({
          id: Date.now().toString(),
          text: newGoalText,
          created: Date.now(),
          status: 'pending'
        });
      }

      return newState;
    };

    return {
      createInitialState,
      validateState,
      pushGoal,
      DEFAULT_STATE
    };
  }
};

export default StateHelpersPure;
","/core/state-manager.js":"/**
 * @fileoverview State Manager
 * Manages high-level agent state and persistence.
 */

const StateManager = {
  metadata: {
    id: 'StateManager',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'VFS', 'StateHelpersPure', 'EventBus', 'AuditLogger?'], // Optional AuditLogger
    async: true,
    type: 'service'
  },

  factory: (deps) => {
    const { Utils, VFS, StateHelpersPure, EventBus, AuditLogger } = deps;
    const { logger, Errors, generateId } = Utils;

    const STATE_PATH = '/.system/state.json';
    let _state = null;

    const load = async () => {
      try {
        const content = await VFS.read(STATE_PATH);
        const rawState = JSON.parse(content);

        const errors = StateHelpersPure.validateState(rawState);
        if (errors) {
          logger.warn('[StateManager] Validation failed, resetting', errors);
          _state = StateHelpersPure.createInitialState();
        } else {
          _state = StateHelpersPure.createInitialState(rawState); // Merge safely
          logger.info(`[StateManager] Loaded state (Cycle: ${_state.totalCycles})`);
        }
      } catch (err) {
        // If file missing, init fresh
        logger.info('[StateManager] Initializing fresh state.');
        _state = StateHelpersPure.createInitialState();
        await save();
      }
      return _state;
    };

    const save = async (retries = 2) => {
      if (!_state) return;
      try {
        const content = JSON.stringify(_state, null, 2);
        await VFS.write(STATE_PATH, content);
      } catch (err) {
        if (retries > 0) {
          logger.warn(`[StateManager] Save failed, retrying (${retries} left)`, err.message);
          await new Promise(r => setTimeout(r, 100));
          return save(retries - 1);
        }
        logger.error('[StateManager] Save failed after retries', err);
        // Notify UI so user knows state may not be persisted
        if (EventBus) {
          EventBus.emit('error:persistence', {
            message: 'Failed to save agent state',
            details: err.message
          });
        }
      }
    };

    // --- Public API ---

    const getState = () => {
      if (!_state) throw new Errors.StateError('StateManager not initialized');
      return JSON.parse(JSON.stringify(_state));
    };

    const updateState = async (updates) => {
      if (!_state) await load();
      Object.assign(_state, updates);
      await save();
      return getState();
    };

    const setGoal = async (goalText) => {
      if (!_state) await load();

      const goalId = generateId('goal');

      // Use pure helper to maintain goal history
      _state = StateHelpersPure.pushGoal(_state, goalText);

      await save();

      if (AuditLogger && AuditLogger.logAgentAction) {
        AuditLogger.logAgentAction('SET_GOAL', 'StateManager', { goal: goalText });
      }

      // Emit event for swarm sync
      EventBus.emit('goal:set', { id: goalId, goal: goalText, timestamp: Date.now() });

      logger.info(`[StateManager] Goal set: "${goalText.substring(0, 50)}..."`);
    };

    const incrementCycle = async () => {
      if (!_state) await load();
      _state.totalCycles++;
      await save();
    };

    return {
      init: load,
      getState,
      updateState,
      setGoal,
      incrementCycle
    };
  }
};

export default StateManager;
","/core/tool-runner.js":"/**
 * @fileoverview Tool Runner
 * Execution engine for built-in and dynamic tools.
 */

const ToolRunner = {
  metadata: {
    id: 'ToolRunner',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'VFS', 'ToolWriter', 'SubstrateLoader?', 'EventBus', 'AuditLogger?', 'HITLController?', 'ArenaHarness?', 'VFSSandbox?', 'VerificationManager?', 'Shell?', 'gitTools?', 'WorkerManager?', 'EmbeddingStore?', 'SemanticMemory?', 'KnowledgeGraph?', 'SchemaRegistry'],
    async: true,
    type: 'service'
  },

  factory: (deps) => {
    const { Utils, VFS, ToolWriter, SubstrateLoader, EventBus, AuditLogger, HITLController, ArenaHarness, VFSSandbox, VerificationManager, Shell, gitTools, EmbeddingStore, SemanticMemory, KnowledgeGraph, SchemaRegistry } = deps;
    const { logger, Errors } = Utils;

    // WorkerManager is mutable because of circular dependency:
    // ToolRunner -> WorkerManager? (optional) -> ToolRunner
    // WorkerManager initializes AFTER ToolRunner, so we need to update the reference later
    let _workerManager = deps.WorkerManager || null;

    // Arena verification for self-modification (opt-in via config)
    let _arenaGatingEnabled = false;
    try {
      const saved = localStorage.getItem('REPLOID_ARENA_GATING');
      _arenaGatingEnabled = saved === 'true';
    } catch (e) { /* ignore */ }

    const _tools = new Map();
    const _dynamicTools = new Set();

    // Schema cache for performance (#3)
    let _schemaCache = null;
    let _schemaCacheVersion = 0;
    let _toolsVersion = 0;

    const invalidateSchemaCache = () => {
      _toolsVersion++;
      _schemaCache = null;
    };

    // --- Arena Verification for Core Changes ---

    /**
     * Verify a core file change in sandbox before committing
     * @param {string} path - File path
     * @param {string} content - New content
     * @returns {Promise<{passed: boolean, errors: string[]}>}
     */
    const _verifyCoreMutation = async (path, content) => {
      // Skip verification if arena/verification not available or disabled
      if (!_arenaGatingEnabled || !VFSSandbox || !VerificationManager) {
        return { passed: true, errors: [], skipped: true };
      }

      try {
        logger.info(`[ToolRunner] Arena gating: verifying ${path}`);

        // Create snapshot of current state
        const snapshot = await VFSSandbox.createSnapshot();

        try {
          // Apply the change in sandbox
          await VFSSandbox.applyChanges({ [path]: content });

          // Run verification
          const result = await VerificationManager.verifyProposal({ [path]: content });

          return {
            passed: result.passed,
            errors: result.errors || [],
            warnings: result.warnings || []
          };
        } finally {
          // Always restore original state
          await VFSSandbox.restoreSnapshot(snapshot);
        }
      } catch (err) {
        logger.error('[ToolRunner] Arena verification failed:', err.message);
        return { passed: false, errors: [err.message] };
      }
    };

    // All tools are now dynamic (loaded from /tools/)
    // No hardcoded built-ins - full RSI capability

    const loadToolModule = async (path, forcedName = null) => {
      try {
        const code = await VFS.read(path);
        const blob = new Blob([code], { type: 'text/javascript' });
        const url = URL.createObjectURL(blob);

        try {
          const mod = await import(url);
          const handler = typeof mod.default === 'function'
            ? mod.default
            : typeof mod.tool?.call === 'function'
              ? mod.tool.call
              : null;

          if (!handler) {
            logger.warn(`[ToolRunner] ${path} missing default export`);
            return false;
          }

          const name = forcedName || path.split('/').pop().replace('.js', '');
          _tools.set(name, handler);
          _dynamicTools.add(name);
          invalidateSchemaCache(); // Invalidate cache when tools change

          // Capture schema from dynamic tool if available
          if (mod.tool?.inputSchema || mod.tool?.description) {
            SchemaRegistry.registerToolSchema(name, {
              description: mod.tool.description || `Dynamic tool: ${name}`,
              parameters: mod.tool.inputSchema || { type: 'object', properties: {} }
            });
          }

          logger.info(`[ToolRunner] Loaded dynamic tool: ${name}`);
          return true;
        } finally {
          URL.revokeObjectURL(url);
        }
      } catch (e) {
        logger.error(`[ToolRunner] Failed to load ${path}`, e);
        return false;
      }
    };

    const unloadDynamicTools = () => {
      for (const name of _dynamicTools) {
        _tools.delete(name);
        SchemaRegistry.unregisterToolSchema(name);
      }
      _dynamicTools.clear();
    };

    // --- Dynamic Tool Loading ---

    const loadDynamicTools = async () => {
      unloadDynamicTools();

      let files = [];
      try {
        files = await VFS.list('/tools/');
      } catch (err) {
        logger.warn('[ToolRunner] Failed to list /tools directory', err);
        return true;
      }

      for (const file of files) {
        if (!file.endsWith('.js')) continue;
        // Skip test files
        if (file.includes('.test.') || file.includes('.spec.') || file.includes('.integration.')) continue;
        await loadToolModule(file);
      }
      return true;
    };

    const ensureToolLoaded = async (name) => {
      if (_tools.has(name)) return true;
      const path = `/tools/${name}.js`;
      if (await VFS.exists(path)) {
        return await loadToolModule(path, name);
      }
      return false;
    };

    // --- Public API ---

    /**
     * Execute a tool with optional permission filtering (for workers)
     * @param {string} name - Tool name
     * @param {Object} args - Tool arguments
     * @param {Object} [options] - Execution options
     * @param {string[]|'*'} [options.allowedTools] - Allowed tools filter ('*' = all)
     * @param {string} [options.workerId] - Worker ID for audit logging
     */
    const execute = async (name, args = {}, options = {}) => {
      const { allowedTools, workerId } = options;

      // Permission check for worker execution
      if (allowedTools && allowedTools !== '*') {
        if (!allowedTools.includes(name)) {
          const error = new Errors.ToolError(`Tool '${name}' not permitted for this worker type`);
          if (AuditLogger) {
            await AuditLogger.logEvent('TOOL_PERMISSION_DENIED', {
              tool: name,
              workerId,
              allowedTools
            }, 'WARN');
          }
          throw error;
        }
      }
      if (!_tools.has(name)) {
        const loaded = await ensureToolLoaded(name);
        if (!loaded) {
          throw new Errors.ToolError(`Tool not found: ${name}`);
        }
      }

      const toolFn = _tools.get(name);
      if (!toolFn) {
        throw new Errors.ToolError(`Tool not found: ${name}`);
      }

      // HITL approval check for critical tools
      if (_requiresApproval(name)) {
        logger.info(`[ToolRunner] Requesting HITL approval for ${name}`);
        const approved = await _requestApproval(name, args);
        if (!approved) {
          if (AuditLogger) {
            await AuditLogger.logEvent('TOOL_REJECTED', {
              tool: name,
              args: _sanitizeArgs(args),
              reason: 'User rejected via HITL'
            }, 'WARN');
          }
          return { error: 'Operation rejected by user', rejected: true };
        }
      }

      logger.info(`[ToolRunner] Executing ${name}`);
      const startTime = Date.now();

      try {
        // Get TransformersClient from global (pre-resolved in boot.js)
        const TransformersClient = window.REPLOID?.transformersClient || null;

        // Inject comprehensive deps for full RSI capability
        const toolDeps = {
          Utils,
          VFS,
          Shell,
          gitTools,
          EventBus,
          AuditLogger,
          ToolWriter,
          SubstrateLoader,
          VFSSandbox,
          VerificationManager,
          WorkerManager: _workerManager, // Use mutable reference (updated after init)
          TransformersClient,
          EmbeddingStore,
          SemanticMemory,
          KnowledgeGraph,
          ToolRunner: { list: () => Array.from(_tools.keys()), execute, has: (n) => _tools.has(n) }
        };
        const result = await toolFn(args, toolDeps);

        // Audit log successful execution
        if (AuditLogger) {
          await AuditLogger.logEvent('TOOL_EXEC', {
            tool: name,
            args: _sanitizeArgs(args),
            durationMs: Date.now() - startTime,
            success: true,
            ...(workerId && { workerId })
          });
        }

        return result;
      } catch (err) {
        logger.error(`[ToolRunner] Error in ${name}`, err);

        // Audit log failed execution
        if (AuditLogger) {
          await AuditLogger.logEvent('TOOL_EXEC', {
            tool: name,
            args: _sanitizeArgs(args),
            durationMs: Date.now() - startTime,
            success: false,
            error: err.message,
            ...(workerId && { workerId })
          }, 'ERROR');
        }

        const errorWithContext = new Errors.ToolError(err.message, { tool: name, args });
        errorWithContext.stack = err.stack; // Preserve original stack trace
        throw errorWithContext;
      }
    };

    // Sanitize args for logging (truncate large content)
    const _sanitizeArgs = (args) => {
      const sanitized = {};
      for (const [key, value] of Object.entries(args)) {
        if (typeof value === 'string' && value.length > 200) {
          sanitized[key] = value.substring(0, 200) + `... (${value.length} chars)`;
        } else {
          sanitized[key] = value;
        }
      }
      return sanitized;
    };

    // Critical tools that require HITL approval
    const CRITICAL_TOOLS = ['WriteFile', 'DeleteFile', 'CreateTool', 'Edit', 'LoadModule'];

    /**
     * Check if tool requires HITL approval
     * @param {string} toolName - Tool name
     * @returns {boolean}
     */
    const _requiresApproval = (toolName) => {
      if (!HITLController) return false;
      const state = HITLController.getState();
      const mode = state?.approvalMode || 'autonomous';
      if (mode === 'autonomous') return false;
      return CRITICAL_TOOLS.includes(toolName);
    };

    /**
     * Request HITL approval for a tool execution
     * @param {string} toolName - Tool name
     * @param {Object} args - Tool arguments
     * @returns {Promise<boolean>} - True if approved
     */
    const _requestApproval = async (toolName, args) => {
      if (!HITLController) return true;

      return new Promise((resolve) => {
        const approvalId = `tool_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

        HITLController.requestApproval({
          id: approvalId,
          moduleId: 'ToolRunner',
          capability: 'APPROVE_TOOL_EXECUTION',
          action: toolName,
          data: { tool: toolName, args: _sanitizeArgs(args) },
          onApprove: () => resolve(true),
          onReject: (reason) => {
            logger.info(`[ToolRunner] Tool ${toolName} rejected: ${reason}`);
            resolve(false);
          },
          timeout: 300000 // 5 minute timeout
        });
      });
    };

    // Arena gating control
    const setArenaGating = (enabled) => {
      _arenaGatingEnabled = !!enabled;
      try {
        localStorage.setItem('REPLOID_ARENA_GATING', String(_arenaGatingEnabled));
      } catch (e) { /* ignore */ }
      logger.info(`[ToolRunner] Arena gating ${_arenaGatingEnabled ? 'enabled' : 'disabled'}`);
      if (EventBus) {
        EventBus.emit('toolrunner:arena_gating', { enabled: _arenaGatingEnabled });
      }
    };

    const isArenaGatingEnabled = () => _arenaGatingEnabled;

    /**
     * Get tool schemas for native tool calling (OpenAI format)
     * Uses caching for performance - invalidated when tools change
     * @returns {Array<{type: string, function: {name: string, description: string, parameters: object}}>}
     */
    const getToolSchemas = () => {
      // Return cached if valid
      if (_schemaCache && _schemaCacheVersion === _toolsVersion) {
        return _schemaCache;
      }

      const schemas = [];

      for (const [name] of _tools) {
        // Check dynamic schema first, then built-in
        const schema = SchemaRegistry.getToolSchema(name);
        if (schema) {
          schemas.push({
            type: 'function',
            function: {
              name,
              description: schema.description,
              parameters: schema.parameters
            }
          });
        }
      }

      // Cache the result
      _schemaCache = schemas;
      _schemaCacheVersion = _toolsVersion;
      logger.debug(`[ToolRunner] Schema cache built: ${schemas.length} tools`);

      return schemas;
    };

    /**
     * Get filtered list of tools based on allowed tools
     * @param {string[]|'*'} allowedTools - Allowed tools ('*' = all)
     * @returns {string[]} - List of tool names
     */
    const listFiltered = (allowedTools) => {
      const allTools = Array.from(_tools.keys());
      if (allowedTools === '*') return allTools;
      return allTools.filter(name => allowedTools.includes(name));
    };

    /**
     * Get filtered tool schemas for worker (OpenAI format)
     * @param {string[]|'*'} allowedTools - Allowed tools ('*' = all)
     * @returns {Array} - Filtered schemas
     */
    const getToolSchemasFiltered = (allowedTools) => {
      const schemas = getToolSchemas();
      if (allowedTools === '*') return schemas;
      return schemas.filter(s => allowedTools.includes(s.function.name));
    };

    return {
      init: loadDynamicTools,
      execute,
      refresh: loadDynamicTools,
      list: () => Array.from(_tools.keys()),
      listFiltered,
      has: (name) => _tools.has(name),
      setArenaGating,
      isArenaGatingEnabled,
      getToolSchemas,
      getToolSchemasFiltered,
      // Setter for late-bound WorkerManager (circular dependency workaround)
      setWorkerManager: (wm) => {
        _workerManager = wm;
        logger.debug('[ToolRunner] WorkerManager reference updated');
      }
    };
  }
};

export default ToolRunner;
","/core/tool-writer.js":"/**
 * @fileoverview Tool Writer
 * Manages creation and validation of dynamic tools.
 */

const ToolWriter = {
  metadata: {
    id: 'ToolWriter',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'VFS', 'SubstrateLoader?'],
    type: 'service'
  },

  factory: (deps) => {
    const { Utils, VFS, SubstrateLoader } = deps;
    const { logger, Errors } = Utils;

    const validateCode = (code) => {
      // Check if code is provided
      if (!code || typeof code !== 'string') {
        throw new Errors.ValidationError('Missing or invalid code parameter. CreateTool requires { name, code } where code is the tool implementation.');
      }
      // Structural checks (string-based, ES module compatible)
      if (!code.includes('export default') && !code.includes('export const tool')) {
        throw new Errors.ValidationError('Tool must export default or export const tool');
      }
      // Check for async pattern (multiple valid formats)
      const hasAsync = code.includes('async function') ||
                       code.includes('async (') ||
                       code.includes('call: async');
      if (!hasAsync) {
        throw new Errors.ValidationError('Tool call function must be async');
      }
      // Note: Removed new Function(code) check - incompatible with ES module syntax
      // Actual syntax validation happens when ToolRunner does import(blobUrl)
    };

    const create = async (name, code) => {
      if (typeof name !== 'string') {
        throw new Errors.ValidationError('Tool name must be a string');
      }

      const trimmedName = name.trim();
      if (!/^[A-Z][A-Za-z0-9]*$/.test(trimmedName)) {
        throw new Errors.ValidationError('Invalid tool name. Use CamelCase and start with an uppercase letter (e.g., ReadFile, AnalyzeLogs).');
      }

      validateCode(code);

      const path = `/tools/${trimmedName}.js`;

      // Persist
      await VFS.write(path, code);

      // Auto-load the tool if SubstrateLoader is available
      let loadStatus = '';
      if (SubstrateLoader) {
        try {
          await SubstrateLoader.loadModule(path);
          loadStatus = ' and loaded';
        } catch (err) {
          loadStatus = ` (load failed: ${err.message})`;
        }
      }

      logger.info(`[ToolWriter] Created tool: ${trimmedName}${loadStatus}`);
      return `Tool ${trimmedName} created at ${path}${loadStatus}`;
    };

    return { create };
  }
};

export default ToolWriter;
","/core/transformers-client.js":"/**
 * @fileoverview Transformers.js Client
 * Browser-native inference using Hugging Face Transformers.js with WebGPU/WASM.
 * Supports newer models like Qwen3, Gemma3, DeepSeek-R1 that aren't in WebLLM.
 */

const TransformersClient = {
  metadata: {
    id: 'TransformersClient',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'EventBus'],
    type: 'service'
  },

  factory: (deps) => {
    const { Utils, EventBus } = deps;
    const { logger, Errors } = Utils;

    // State
    let _generator = null;
    let _currentModelId = null;
    let _loaderPromise = null;

    // Model configurations for Transformers.js
    const modelConfigs = {
      // Qwen3 models
      'qwen3-0.6b': {
        hfId: 'onnx-community/Qwen3-0.6B-ONNX',
        dtype: 'q4',
        device: 'webgpu'
      },
      'qwen3-1.7b': {
        hfId: 'onnx-community/Qwen3-1.7B-ONNX',
        dtype: 'q4',
        device: 'webgpu'
      },
      // Gemma3 models
      'gemma3-1b': {
        hfId: 'onnx-community/gemma-3-1b-it-ONNX',
        dtype: 'q4',
        device: 'webgpu'
      },
      // SmolLM2
      'smollm2-360m': {
        hfId: 'HuggingFaceTB/SmolLM2-360M-Instruct',
        dtype: 'fp16',
        device: 'webgpu'
      },
      'smollm2-1.7b': {
        hfId: 'HuggingFaceTB/SmolLM2-1.7B-Instruct',
        dtype: 'q4',
        device: 'webgpu'
      },
      // DeepSeek-R1 distilled
      'deepseek-r1-1.5b': {
        hfId: 'onnx-community/DeepSeek-R1-Distill-Qwen-1.5B-ONNX',
        dtype: 'q4',
        device: 'webgpu'
      },
      // Phi-4-mini
      'phi4-mini': {
        hfId: 'onnx-community/Phi-4-mini-instruct-ONNX',
        dtype: 'q4',
        device: 'webgpu'
      }
    };

    const ensureTransformersReady = async () => {
      if (typeof window === 'undefined') {
        throw new Errors.ConfigError('Transformers.js is only available in browser environments');
      }

      if (window.transformers) return window.transformers;
      if (_loaderPromise) return _loaderPromise;

      _loaderPromise = import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@3')
        .then(mod => {
          window.transformers = {
            pipeline: mod.pipeline,
            env: mod.env
          };
          // Configure for WebGPU
          mod.env.backends.onnx.wasm.proxy = false;
          return window.transformers;
        })
        .catch((err) => {
          _loaderPromise = null;
          logger.error('[Transformers] Failed to load runtime', err);
          throw new Errors.ConfigError('Failed to load Transformers.js runtime');
        });

      return _loaderPromise;
    };

    const loadModel = async (modelId) => {
      await ensureTransformersReady();

      const config = modelConfigs[modelId];
      if (!config) {
        throw new Errors.ConfigError(`Unknown Transformers.js model: ${modelId}`);
      }

      if (_currentModelId === modelId && _generator) {
        logger.info(`[Transformers] Model ${modelId} already loaded`);
        return;
      }

      logger.info(`[Transformers] Loading model: ${config.hfId}`);

      // Throttle progress updates - only emit on 5% changes
      let lastReportedPercent = -1;

      try {
        // Dispose previous generator if exists
        if (_generator && _generator.dispose) {
          await _generator.dispose();
        }

        // Emit downloading state
        EventBus.emit('agent:status', {
          state: 'DOWNLOADING',
          activity: `Downloading model: ${modelId}`,
          progress: 0
        });

        _generator = await window.transformers.pipeline(
          'text-generation',
          config.hfId,
          {
            device: config.device,
            dtype: config.dtype,
            progress_callback: (progress) => {
              if (progress.status === 'progress' && progress.total > 0) {
                const percent = Math.round((progress.loaded / progress.total) * 100);
                // Only emit if percent changed by 5% or more
                if (percent - lastReportedPercent >= 5 || percent === 100) {
                  lastReportedPercent = percent;
                  const shortFile = progress.file?.split('/').pop() || 'model';
                  EventBus.emit('agent:status', {
                    state: 'DOWNLOADING',
                    activity: `Downloading ${shortFile}: ${percent}%`,
                    progress: percent
                  });
                }
              }
            }
          }
        );

        _currentModelId = modelId;
        logger.info(`[Transformers] Model ${modelId} loaded successfully`);
      } catch (err) {
        logger.error(`[Transformers] Failed to load model ${modelId}`, err);
        _generator = null;
        _currentModelId = null;
        const reason = err?.message || err?.cause?.message || err?.toString() || 'Unknown error';
        throw new Errors.ApiError(`Failed to load model: ${reason}`, 500);
      }
    };

    const chat = async (messages, modelConfig, onUpdate) => {
      const modelId = modelConfig.transformersModelId || modelConfig.id;

      await loadModel(modelId);

      // Format messages for text generation
      // Transformers.js text-generation expects a single prompt string
      const prompt = formatMessagesForGeneration(messages);

      logger.info(`[Transformers] Generating response for ${modelId}`);

      try {
        let fullContent = '';

        if (onUpdate) {
          // Streaming mode using callback
          const streamer = {
            put: (tokens) => {
              const text = _generator.tokenizer.decode(tokens, { skip_special_tokens: true });
              if (text) {
                fullContent += text;
                onUpdate(text);
              }
            },
            end: () => {}
          };

          await _generator(prompt, {
            max_new_tokens: 2048,
            temperature: 0.7,
            do_sample: true,
            streamer
          });
        } else {
          // Non-streaming mode
          const output = await _generator(prompt, {
            max_new_tokens: 2048,
            temperature: 0.7,
            do_sample: true,
            return_full_text: false
          });

          fullContent = output[0].generated_text;
        }

        return {
          requestId: Utils.generateId('tfjs'),
          content: stripThoughts(fullContent),
          raw: fullContent,
          model: modelId,
          timestamp: Date.now(),
          provider: 'transformers'
        };

      } catch (err) {
        logger.error('[Transformers] Generation error', err);
        const reason = err?.message || err?.cause?.message || err?.toString() || 'Unknown error';
        throw new Errors.ApiError(`Transformers.js generation failed: ${reason}`, 500);
      }
    };

    const formatMessagesForGeneration = (messages) => {
      // Convert chat messages to a single prompt string
      // Using ChatML-like format that most models understand
      let prompt = '';

      for (const msg of messages) {
        if (msg.role === 'system') {
          prompt += `<|system|>\n${msg.content}\n`;
        } else if (msg.role === 'user') {
          prompt += `<|user|>\n${msg.content}\n`;
        } else if (msg.role === 'assistant') {
          prompt += `<|assistant|>\n${msg.content}\n`;
        }
      }

      // Add final assistant tag to prompt generation
      prompt += '<|assistant|>\n';

      return prompt;
    };

    const stripThoughts = (text) => {
      return text
        .replace(/<think>[\s\S]*?<\/think>/gi, '')
        .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
        .trim();
    };

    const getStatus = () => {
      return {
        loaded: !!_generator,
        model: _currentModelId,
        available: typeof window !== 'undefined' && !!navigator.gpu
      };
    };

    const getAvailableModels = () => {
      return Object.entries(modelConfigs).map(([id, config]) => ({
        id,
        hfId: config.hfId,
        dtype: config.dtype
      }));
    };

    const unload = async () => {
      if (_generator && _generator.dispose) {
        await _generator.dispose();
      }
      _generator = null;
      _currentModelId = null;
      logger.info('[Transformers] Model unloaded');
    };

    return {
      chat,
      loadModel,
      getStatus,
      getAvailableModels,
      unload,
      isTransformersModel: (id) => id in modelConfigs || id.startsWith('transformers:')
    };
  }
};

export default TransformersClient;
","/core/utils.js":"/**
 * @fileoverview Core Utilities Module
 * The foundational pure functions, error classes, and protocol parsers.
 */

const Utils = {
  metadata: {
    id: 'Utils',
    version: '1.0.0', // Merged ParserUtils
    genesis: { introduced: 'tabula' },
    dependencies: [],
    type: 'pure'
  },

  factory: () => {
    // --- Internal State ---
    const _logStats = { debug: 0, info: 0, warn: 0, error: 0 };
    const _recentLogs = [];
    const MAX_LOG_HISTORY = 100;

    // --- Error Handling System ---
    class ApplicationError extends Error {
      constructor(message, details = {}) {
        super(message);
        this.name = this.constructor.name;
        this.details = details;
        this.timestamp = Date.now();
      }
    }

    class ApiError extends ApplicationError {
      constructor(message, status, details) {
        super(message, details);
        this.status = status;
      }
    }

    class StateError extends ApplicationError {}
    class ArtifactError extends ApplicationError {}
    class ValidationError extends ApplicationError {}
    class AbortError extends ApplicationError {}
    class ToolError extends ApplicationError {}
    class ConfigError extends ApplicationError {}

    const Errors = {
      ApplicationError,
      ApiError,
      StateError,
      ArtifactError,
      ValidationError,
      AbortError,
      ToolError,
      ConfigError
    };

    // --- Logging System ---
    const logger = {
      _write: (level, message, details) => {
        _logStats[level]++;

        const entry = {
          ts: new Date().toISOString(),
          level: level.toUpperCase(),
          msg: message,
          data: details
        };

        const method = console[level] || console.log;
        const prefix = `[${entry.level}]`;
        details ? method(prefix, message, details) : method(prefix, message);

        _recentLogs.push(entry);
        if (_recentLogs.length > MAX_LOG_HISTORY) _recentLogs.shift();
      },

      debug: (msg, data) => logger._write('debug', msg, data),
      info: (msg, data) => logger._write('info', msg, data),
      warn: (msg, data) => logger._write('warn', msg, data),
      error: (msg, data) => logger._write('error', msg, data),

      getStats: () => ({ ..._logStats }),
      getHistory: () => [..._recentLogs],
      clearHistory: () => { _recentLogs.length = 0; }
    };

    // --- Pure Helpers ---

    const generateId = (prefix = 'id') => {
      const random = Math.random().toString(36).substring(2, 10);
      const ts = Date.now().toString(36);
      return `${prefix}_${ts}_${random}`;
    };

    const trunc = (str, len) => {
      if (!str) return '';
      return str.length > len ? str.substring(0, len - 3) + '...' : str;
    };

    const kabobToCamel = (s) => s.replace(/-([a-z0-9])/gi, (_, c) => c.toUpperCase());

    const escapeHtml = (unsafe) => {
      if (!unsafe) return '';
      return unsafe
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
    };

    /**
     * Convert backtick template literals to valid JSON strings.
     * Handles: `content with "quotes" and newlines` -> "content with \"quotes\" and newlines"
     */
    const convertBacktickStrings = (text) => {
      let result = '';
      let i = 0;
      while (i < text.length) {
        // Check if we're entering a JSON string (double quote)
        if (text[i] === '"') {
          result += '"';
          i++;
          // Skip through the JSON string
          while (i < text.length) {
            if (text[i] === '\\' && i + 1 < text.length) {
              result += text[i] + text[i + 1];
              i += 2;
            } else if (text[i] === '"') {
              result += '"';
              i++;
              break;
            } else {
              result += text[i];
              i++;
            }
          }
        }
        // Check if we're entering a backtick string (needs conversion)
        else if (text[i] === '`') {
          result += '"'; // Start JSON string
          i++;
          // Process backtick string content
          while (i < text.length && text[i] !== '`') {
            const char = text[i];
            if (char === '\\' && i + 1 < text.length) {
              // Preserve escapes
              result += text[i] + text[i + 1];
              i += 2;
            } else if (char === '"') {
              // Escape double quotes inside backtick strings
              result += '\\"';
              i++;
            } else if (char === '\n') {
              // Convert literal newlines to \n
              result += '\\n';
              i++;
            } else if (char === '\r') {
              // Convert carriage returns
              result += '\\r';
              i++;
            } else if (char === '\t') {
              // Convert tabs
              result += '\\t';
              i++;
            } else {
              result += char;
              i++;
            }
          }
          result += '"'; // End JSON string
          if (i < text.length) i++; // Skip closing backtick
        }
        else {
          result += text[i];
          i++;
        }
      }
      return result;
    };

    const sanitizeLlmJsonRespPure = (text) => {
      if (!text || typeof text !== 'string') return { json: "{}", method: "empty" };

      // First try direct parse
      try {
        JSON.parse(text);
        return { json: text, method: "direct" };
      } catch (e) { /* continue */ }

      // Try converting backtick strings to JSON strings
      if (text.includes('`')) {
        try {
          const converted = convertBacktickStrings(text);
          JSON.parse(converted);
          return { json: converted, method: "backtick" };
        } catch (e) { /* continue */ }
      }

      const codeBlock = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
      if (codeBlock) {
        try {
          JSON.parse(codeBlock[1]);
          return { json: codeBlock[1], method: "block" };
        } catch (e) { /* continue */ }
      }

      const firstOpen = text.indexOf('{');
      const lastClose = text.lastIndexOf('}');
      if (firstOpen > -1 && lastClose > firstOpen) {
        const candidate = text.substring(firstOpen, lastClose + 1);
        try {
          JSON.parse(candidate);
          return { json: candidate, method: "heuristic" };
        } catch (e) { /* continue */ }

        // Try backtick conversion on the candidate
        if (candidate.includes('`')) {
          try {
            const converted = convertBacktickStrings(candidate);
            JSON.parse(converted);
            return { json: converted, method: "heuristic+backtick" };
          } catch (e) { /* continue */ }
        }
      }

      return { json: "{}", method: "failed" };
    };

    /**
     * Tracker to prevent EventBus memory leaks
     */
    const createSubscriptionTracker = () => {
      const subs = new Map();
      return {
        track: (id, unsubFn) => {
          if (!subs.has(id)) subs.set(id, []);
          subs.get(id).push(unsubFn);
        },
        unsubscribeAll: (id) => {
          const list = subs.get(id);
          if (list) {
            list.forEach(fn => fn());
            subs.delete(id);
          }
        }
      };
    };

    // --- PAWS Protocol Parsers (Merged from ParserUtils) ---

    const parseCatsBundle = (content) => {
      const files = [];
      if (!content) return { reason: 'Empty content', files: [] };

      const blocks = content.split(/```vfs-file\s*\n/);
      const reasonMatch = content.match(/\*\*Reason:\*\*\s*(.+)/);
      const reason = reasonMatch ? reasonMatch[1].trim() : 'Context bundle';

      for (let i = 1; i < blocks.length; i++) {
        const block = blocks[i];
        const pathMatch = block.match(/^path:\s*(.+?)\s*\n```/);
        if (!pathMatch) continue;

        const filePath = pathMatch[1].trim();
        const contentStartRegex = /```\n([\s\S]*?)\n```/;
        const contentMatch = block.substring(pathMatch[0].length).match(contentStartRegex);

        if (contentMatch) {
          files.push({
            path: filePath,
            content: contentMatch[1]
          });
        }
      }
      return { reason, files };
    };

    const generateCatsBundle = (files, reason = 'Context Export') => {
      const date = new Date().toISOString();
      let out = `## PAWS Context Bundle (cats.md)\n**Generated:** ${date}\n**Reason:** ${reason}\n**Files:** ${files.length}\n\n---\n\n`;
      for (const f of files) {
        out += `\`\`\`vfs-file\npath: ${f.path}\n\`\`\`\n`;
        out += `\`\`\`\n${f.content}\n\`\`\`\n\n---\n\n`;
      }
      return out;
    };

    const parseDogsBundle = (content) => {
      const changes = [];
      if (!content) return changes;

      const blocks = content.split(/```paws-change\s*\n/);

      for (let i = 1; i < blocks.length; i++) {
        const block = blocks[i];
        const metaEndIdx = block.indexOf('```');
        if (metaEndIdx === -1) continue;

        const metaSection = block.substring(0, metaEndIdx);
        const opMatch = metaSection.match(/operation:\s*(CREATE|MODIFY|DELETE)/i);
        const pathMatch = metaSection.match(/file_path:\s*(.+)/);

        if (!opMatch || !pathMatch) continue;

        const operation = opMatch[1].toUpperCase();
        const filePath = pathMatch[1].trim();
        let newContent = null;

        if (operation !== 'DELETE') {
          const contentSection = block.substring(metaEndIdx + 3);
          const contentMatch = contentSection.match(/```\n([\s\S]*?)\n```/);
          newContent = contentMatch ? contentMatch[1] : '';
        }

        changes.push({ operation, file_path: filePath, new_content: newContent });
      }
      return changes;
    };

    const generateDogsBundle = (changes, summary = 'Code Modification') => {
      let out = `## PAWS Change Proposal (dogs.md)\n**Summary:** ${summary}\n**Changes:** ${changes.length}\n\n---\n\n`;
      for (const c of changes) {
        out += `\`\`\`paws-change\noperation: ${c.operation}\nfile_path: ${c.file_path}\n\`\`\`\n`;
        if (c.operation !== 'DELETE') {
          out += `\`\`\`\n${c.new_content || ''}\n\`\`\`\n\n`;
        }
      }
      return out;
    };

    return {
      Errors,
      logger,
      generateId,
      trunc,
      kabobToCamel,
      escapeHtml,
      sanitizeLlmJsonRespPure,
      createSubscriptionTracker,
      // Protocol Parsers
      parseCatsBundle,
      generateCatsBundle,
      parseDogsBundle,
      generateDogsBundle
    };
  }
};

export default Utils;
","/core/verification-manager.js":"/**
 * @fileoverview Verification Manager
 * Pre-flight safety checks via Web Worker.
 */

const VerificationManager = {
  metadata: {
    id: 'VerificationManager',
    version: '1.0.0',
    genesis: { introduced: 'reflection' },
    dependencies: ['Utils', 'VFS'],
    async: true,
    type: 'service'
  },

  factory: (deps) => {
    const { logger } = deps.Utils;
    const { VFS } = deps;

    const WORKER_PATH = '/core/verification-worker.js';

    const createSnapshot = async () => {
      const files = await VFS.list('/');
      const snapshot = {};
      for (const path of files) {
        if (path.endsWith('.js') || path.endsWith('.json')) {
          try { snapshot[path] = await VFS.read(path); } catch (e) {}
        }
      }
      return snapshot;
    };

    const verifyProposal = async (changes) => {
      logger.info('[Verifier] Snapshotting...');
      const snapshot = await createSnapshot();

      // Overlay changes
      for (const c of changes) {
        if (c.operation === 'DELETE') delete snapshot[c.file_path];
        else snapshot[c.file_path] = c.new_content;
      }

      return new Promise((resolve) => {
        const worker = new Worker(WORKER_PATH);

        const timeout = setTimeout(() => {
          worker.terminate();
          resolve({ passed: false, reason: 'Timeout' });
        }, 5000);

        worker.onmessage = (e) => {
          clearTimeout(timeout);
          worker.terminate();
          resolve(e.data);
        };

        worker.onerror = (e) => {
          clearTimeout(timeout);
          worker.terminate();
          logger.error('[Verifier] Crash', e);
          resolve({ passed: false, reason: 'Worker Error' });
        };

        worker.postMessage({ type: 'VERIFY', snapshot });
      });
    };

    return { verifyProposal };
  }
};

export default VerificationManager;
","/core/vfs.js":"/**
 * @fileoverview Virtual File System (VFS)
 * IndexedDB-backed storage.
 *
 * BREAKING: Uses 'reploid-vfs-v2'. Previous v1 data is ignored.
 */

const VFS = {
  metadata: {
    id: 'VFS',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'EventBus?'],
    async: true,
    type: 'service'
  },

  factory: (deps) => {
    const { Utils, EventBus } = deps;
    const { logger, Errors } = Utils;

    const DB_NAME = 'reploid-vfs-v2';
    const STORE_FILES = 'files';
    let db = null;

    const openDB = () => {
      return new Promise((resolve, reject) => {
        if (db) return resolve(db);

        logger.debug('[VFS] Opening IndexedDB...');

        // Timeout to detect blocked IndexedDB (e.g., another tab holding connection)
        const timeout = setTimeout(() => {
          logger.error('[VFS] IndexedDB open timed out after 10s. Try closing other tabs or clearing IndexedDB.');
          reject(new Errors.StateError('VFS DB open timed out - close other tabs and reload'));
        }, 10000);

        const request = indexedDB.open(DB_NAME, 1);

        request.onblocked = () => {
          clearTimeout(timeout);
          logger.error('[VFS] IndexedDB blocked - another tab may have an open connection');
          reject(new Errors.StateError('VFS DB blocked - close other tabs'));
        };

        request.onupgradeneeded = (event) => {
          logger.debug('[VFS] IndexedDB upgrade needed');
          const d = event.target.result;
          if (!d.objectStoreNames.contains(STORE_FILES)) {
            d.createObjectStore(STORE_FILES, { keyPath: 'path' });
          }
        };

        request.onsuccess = (e) => {
          clearTimeout(timeout);
          db = e.target.result;
          logger.info('[VFS] Database connected');
          resolve(db);
        };

        request.onerror = (e) => {
          clearTimeout(timeout);
          logger.error('[VFS] IndexedDB open error:', e.target.error);
          reject(new Errors.StateError('Failed to open VFS DB: ' + (e.target.error?.message || 'unknown error')));
        };
      });
    };

    const normalize = (path) => {
      if (!path || typeof path !== 'string') throw new Errors.ValidationError('Invalid path');
      let clean = path.trim().replace(/\\/g, '/');
      return clean.startsWith('/') ? clean : '/' + clean;
    };

    // --- API ---

    const init = async () => { await openDB(); return true; };

    const write = async (path, content) => {
      await openDB();
      const cleanPath = normalize(path);

      // Check if file exists to determine operation type
      const fileExists = await exists(cleanPath);
      const operation = fileExists ? 'update' : 'write';

      return new Promise((resolve, reject) => {
        const tx = db.transaction([STORE_FILES], 'readwrite');
        const store = tx.objectStore(STORE_FILES);
        const entry = {
          path: cleanPath,
          content,
          size: content.length,
          updated: Date.now(),
          type: 'file'
        };
        store.put(entry).onsuccess = () => {
          // Emit event for HMR
          if (EventBus) {
            EventBus.emit('vfs:file_changed', {
              path: cleanPath,
              operation,
              size: content.length,
              timestamp: Date.now()
            });
          }
          resolve(true);
        };
        tx.onerror = () => reject(new Errors.ArtifactError(`Write failed: ${cleanPath}`));
      });
    };

    const read = async (path) => {
      await openDB();
      const cleanPath = normalize(path);
      return new Promise((resolve, reject) => {
        const tx = db.transaction([STORE_FILES], 'readonly');
        const req = tx.objectStore(STORE_FILES).get(cleanPath);
        req.onsuccess = () => {
          req.result ? resolve(req.result.content) : reject(new Errors.ArtifactError(`File not found: ${cleanPath}`));
        };
        req.onerror = () => reject(new Errors.ArtifactError(`Read failed: ${cleanPath}`));
      });
    };

    const remove = async (path) => {
      await openDB();
      const cleanPath = normalize(path);
      return new Promise((resolve, reject) => {
        const tx = db.transaction([STORE_FILES], 'readwrite');
        const req = tx.objectStore(STORE_FILES).delete(cleanPath);
        req.onsuccess = () => {
          logger.info(`[VFS] Deleted ${cleanPath}`);

          // Emit event for HMR
          if (EventBus) {
            EventBus.emit('vfs:file_changed', {
              path: cleanPath,
              operation: 'delete',
              timestamp: Date.now()
            });
          }

          resolve(true);
        };
        req.onerror = () => {
          logger.error(`[VFS] Delete failed: ${cleanPath}`);
          reject(new Errors.ArtifactError(`Delete failed: ${cleanPath}`));
        };
      });
    };

    const list = async (dir = '/') => {
      await openDB();
      const cleanDir = normalize(dir);
      const prefix = cleanDir.endsWith('/') ? cleanDir : cleanDir + '/';

      return new Promise((resolve) => {
        const tx = db.transaction([STORE_FILES], 'readonly');
        const store = tx.objectStore(STORE_FILES);

        // Try to use IndexedDB key range for O(log n + m) instead of O(n) scan
        // IDBKeyRange may not be available in test environments
        const IDB = typeof IDBKeyRange !== 'undefined' ? IDBKeyRange : null;

        if (IDB) {
          try {
            // Create key range: [prefix, prefix + '\uffff')
            // '\uffff' is highest Unicode char, so this captures all strings starting with prefix
            const range = IDB.bound(prefix, prefix + '\uffff', false, true);
            const req = store.getAllKeys(range);

            req.onsuccess = () => {
              resolve(req.result || []);
            };
            req.onerror = () => {
              // Fallback to full scan if key range fails
              const fallbackReq = store.getAllKeys();
              fallbackReq.onsuccess = () => {
                const all = fallbackReq.result || [];
                resolve(all.filter(p => p.startsWith(prefix)));
              };
            };
            return;
          } catch (e) {
            // Fall through to fallback
          }
        }

        // Fallback: full scan with filter
        const req = store.getAllKeys();
        req.onsuccess = () => {
          const all = req.result || [];
          resolve(all.filter(p => p.startsWith(prefix)));
        };
      });
    };

    const stat = async (path) => {
      await openDB();
      const cleanPath = normalize(path);
      return new Promise((resolve) => {
        const tx = db.transaction([STORE_FILES], 'readonly');
        const req = tx.objectStore(STORE_FILES).get(cleanPath);
        req.onsuccess = () => {
          if (req.result) {
            resolve({
              path: req.result.path,
              size: req.result.size,
              updated: req.result.updated,
              type: req.result.type
            });
          } else {
            resolve(null);
          }
        };
      });
    };

    const exists = async (path) => {
      const meta = await stat(path);
      return !!meta;
    };

    const isEmpty = async () => {
      await openDB();
      return new Promise((resolve) => {
        const tx = db.transaction([STORE_FILES], 'readonly');
        const req = tx.objectStore(STORE_FILES).count();
        req.onsuccess = () => resolve(req.result === 0);
      });
    };

    // Virtual mkdir - VFS is flat, so this is mostly for API compatibility
    // useful if we later add directory metadata
    const mkdir = async (path) => {
      logger.debug(`[VFS] mkdir ${path} (virtual)`);
      return true;
    };

    const clear = async () => {
      await openDB();
      return new Promise((resolve) => {
        const tx = db.transaction([STORE_FILES], 'readwrite');
        tx.objectStore(STORE_FILES).clear().onsuccess = () => resolve(true);
      });
    };

    /**
     * Export all VFS contents as a single JSON object
     * @returns {Promise<Object>} { files: { path: content, ... }, meta: { ... } }
     */
    const exportAll = async () => {
      await openDB();
      return new Promise((resolve, reject) => {
        const tx = db.transaction([STORE_FILES], 'readonly');
        const store = tx.objectStore(STORE_FILES);
        const req = store.getAll();
        req.onsuccess = () => {
          const files = {};
          const entries = req.result || [];
          for (const entry of entries) {
            files[entry.path] = {
              content: entry.content,
              size: entry.size,
              updated: entry.updated
            };
          }
          resolve({
            files,
            meta: {
              exportedAt: Date.now(),
              version: '2.0',
              fileCount: entries.length
            }
          });
        };
        req.onerror = () => reject(new Errors.ArtifactError('Export failed'));
      });
    };

    /**
     * Import all files from exported JSON
     * @param {Object} data - { files: { path: { content, ... }, ... } }
     * @param {boolean} [clearFirst=false] - Clear VFS before import
     * @returns {Promise<number>} Number of files imported
     */
    const importAll = async (data, clearFirst = false) => {
      if (!data?.files || typeof data.files !== 'object') {
        throw new Errors.ValidationError('Invalid import data: missing files object');
      }

      await openDB();

      if (clearFirst) {
        await clear();
      }

      const paths = Object.keys(data.files);
      let imported = 0;

      for (const path of paths) {
        const entry = data.files[path];
        const content = typeof entry === 'string' ? entry : entry.content;
        if (content !== undefined) {
          await write(path, content);
          imported++;
        }
      }

      logger.info(`[VFS] Imported ${imported} files`);
      return imported;
    };

    return {
      init,
      read,
      write,
      delete: remove,
      list,
      stat,
      exists,
      isEmpty,
      mkdir,
      clear,
      exportAll,
      importAll
    };
  }
};

export default VFS;
","/core/worker-agent.js":"/**
 * @fileoverview Worker Agent
 * Minimal agent loop that runs inside a Web Worker for isolated task execution.
 * Receives task + allowed tools via postMessage, returns results.
 * Cannot spawn workers (flat hierarchy enforced via depth check).
 */

// Web Worker context - no DOM access, no shared state
self.onmessage = async (e) => {
  const {
    workerId,
    type,
    task,
    model,
    allowedTools,
    maxIterations = 20,
    depth,
    config
  } = e.data;

  // Safety check: Workers cannot spawn other workers
  if (depth > 1) {
    self.postMessage({
      type: 'error',
      workerId,
      error: 'Workers cannot spawn other workers (flat hierarchy enforced)'
    });
    return;
  }

  try {
    self.postMessage({ type: 'started', workerId });

    // Import required modules (these will be loaded from VFS via Service Worker)
    // Note: In Web Worker context, we need to import dynamically
    const result = await executeWorkerTask({
      workerId,
      type,
      task,
      model,
      allowedTools,
      maxIterations,
      config
    });

    self.postMessage({
      type: 'complete',
      workerId,
      result
    });

  } catch (error) {
    self.postMessage({
      type: 'error',
      workerId,
      error: error.message,
      stack: error.stack
    });
  }
};

/**
 * Execute the worker's task with a simplified agent loop
 */
async function executeWorkerTask({ workerId, type, task, model, allowedTools, maxIterations, config }) {
  const startTime = Date.now();
  let iterations = 0;
  const toolResults = [];

  // Progress reporting
  const reportProgress = (message) => {
    self.postMessage({
      type: 'progress',
      workerId,
      iteration: iterations,
      message
    });
  };

  reportProgress(`Starting ${type} worker for task: ${task.substring(0, 50)}...`);

  // For Phase 3 stub: Return placeholder result
  // TODO: Implement full agent loop with:
  // 1. LLM call with task + allowed tools
  // 2. Tool execution with permission filtering
  // 3. Result aggregation
  // 4. Iteration until done or maxIterations

  // Placeholder implementation
  await new Promise(resolve => setTimeout(resolve, 100)); // Simulate work

  return {
    workerId,
    type,
    task: task.substring(0, 100),
    iterations,
    duration: Date.now() - startTime,
    status: 'completed',
    output: `[Worker ${workerId}] Placeholder result - full implementation in Phase 3`,
    allowedTools: Array.isArray(allowedTools) ? allowedTools : 'ALL',
    note: 'Web Worker agent loop not yet fully implemented'
  };
}

/**
 * Filter tools based on worker type permissions
 */
function filterTools(allTools, allowedTools) {
  if (allowedTools === '*') return allTools;
  return allTools.filter(tool => allowedTools.includes(tool.name || tool));
}

/**
 * Simple tool execution within worker context
 * Only allowed tools can be executed
 */
async function executeToolInWorker(toolName, args, allowedTools, toolImplementations) {
  // Check permission
  if (allowedTools !== '*' && !allowedTools.includes(toolName)) {
    throw new Error(`Tool '${toolName}' not allowed for this worker type`);
  }

  const tool = toolImplementations[toolName];
  if (!tool) {
    throw new Error(`Tool '${toolName}' not found`);
  }

  return await tool(args);
}
","/core/worker-manager.js":"/**
 * @fileoverview Worker Manager
 * Spawns and manages isolated Web Worker agents for parallel task execution.
 * Part of the "Brains + Muscles" architecture:
 * - Brains: Multiple models for quality (Arena mode)
 * - Muscles: Multiple workers for speed (this module)
 */

const WorkerManager = {
  metadata: {
    id: 'WorkerManager',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    files: ['core/worker-manager.js', 'core/worker-agent.js'],
    dependencies: ['Utils', 'VFS', 'LLMClient', 'ToolRunner', 'ResponseParser', 'EventBus', 'AuditLogger?', 'SchemaRegistry?'],
    async: true,
    type: 'core'
  },

  factory: (deps) => {
    const { Utils, VFS, LLMClient, ToolRunner, ResponseParser, EventBus, AuditLogger, SchemaRegistry } = deps;
    const { logger } = Utils;

    const WORKERS_DIR = '/.system/workers';
    const MAX_COMPLETED_WORKERS = 100;  // Prevent unbounded memory growth
    const _activeWorkers = new Map();
    const _completedWorkers = new Map();
    const _maxConcurrentWorkers = 10;
    let _workerConfig = null;
    let _modelConfig = null; // Default model config for workers
    let _modelRoles = null; // Role-based model configs (fast, code, orchestrator, local)

    /**
     * Persist worker state to VFS
     * @private
     */
    const _persistWorker = async (workerId, data) => {
      if (!VFS) return;
      try {
        const path = `${WORKERS_DIR}/${workerId}.json`;
        await VFS.write(path, JSON.stringify(data, null, 2));
      } catch (e) {
        logger.warn(`[WorkerManager] Failed to persist worker ${workerId}:`, e.message);
      }
    };

    /**
     * Load persisted workers from VFS on init
     * @private
     */
    const _loadPersistedWorkers = async () => {
      if (!VFS) return;
      try {
        const files = await VFS.list(WORKERS_DIR);
        for (const file of files) {
          if (!file.endsWith('.json')) continue;
          try {
            const content = await VFS.read(file);
            const data = JSON.parse(content);
            if (data.workerId && data.status !== 'running') {
              // Only restore completed/error/terminated workers
              _completedWorkers.set(data.workerId, data);
            }
          } catch (e) {
            // Skip invalid files
          }
        }
        if (_completedWorkers.size > 0) {
          logger.info(`[WorkerManager] Loaded ${_completedWorkers.size} persisted workers from VFS`);
        }
      } catch (e) {
        // Directory may not exist yet
      }
    };

    /**
     * Initialize with worker type configuration
     * @param {Object} config - Config from genesis-levels.json (workerTypes, modelRoles)
     * @param {Object} [modelConfig] - Default model configuration for workers
     */
    const init = async (config, modelConfig = null) => {
      _workerConfig = config?.workerTypes || {};
      _modelRoles = config?.modelRoles || {};
      _modelConfig = modelConfig;
      if (SchemaRegistry && _workerConfig) {
        SchemaRegistry.registerWorkerTypes(_workerConfig, { builtin: true });
      }
      // Load persisted workers from VFS
      await _loadPersistedWorkers();

      // Update ToolRunner's WorkerManager reference (circular dependency workaround)
      // ToolRunner initializes before WorkerManager, so it has undefined WorkerManager
      // We need to update it so SpawnWorker tool can access WorkerManager
      if (ToolRunner?.setWorkerManager) {
        ToolRunner.setWorkerManager(api);
      }

      logger.info('[WorkerManager] Initialized with worker types:', Object.keys(_workerConfig));
      logger.info('[WorkerManager] Model roles available:', Object.keys(_modelRoles));
      return true;
    };

    /**
     * Set the default model config for workers
     */
    const setModelConfig = (modelConfig) => {
      _modelConfig = modelConfig;
    };

    /**
     * Set model configs for specific roles
     * @param {Object} roleConfigs - Map of role name to model config
     *   e.g., { fast: {...geminiConfig}, code: {...codestralConfig} }
     */
    const setModelRoles = (roleConfigs) => {
      _modelRoles = { ..._modelRoles, ...roleConfigs };
      logger.info('[WorkerManager] Updated model roles:', Object.keys(_modelRoles).filter(k => _modelRoles[k]?.config));
    };

    /**
     * Resolve a model role to actual model config
     * @param {string} role - Role name (fast, code, orchestrator, local) or null for default
     * @returns {Object} Model config to use
     */
    const _resolveModelConfig = (role) => {
      // If role specified and we have a config for it, use that
      if (role && _modelRoles?.[role]?.config) {
        logger.info(`[WorkerManager] Using model role '${role}': ${_modelRoles[role].config.id}`);
        return _modelRoles[role].config;
      }
      // Fall back to default model config
      return _modelConfig;
    };

    /**
     * Get allowed tools for a worker type
     * @param {string} type - Worker type (explore, analyze, execute)
     * @returns {string[]|'*'} - List of allowed tool names or '*' for all
     */
    const _getWorkerDefinition = (type) => {
      const schemaDef = SchemaRegistry?.getWorkerType(type);
      if (schemaDef) return schemaDef;
      return _workerConfig?.[type] || null;
    };

    const getToolsForType = (type) => {
      let workerType = _getWorkerDefinition(type);
      if (!workerType) {
        logger.warn(`[WorkerManager] Unknown worker type: ${type}, defaulting to explore`);
        workerType = _getWorkerDefinition('explore');
      }
      return workerType?.tools || [];
    };

    /**
     * Check if a tool is allowed for a worker type
     * @param {string} type - Worker type
     * @param {string} toolName - Tool to check
     * @returns {boolean}
     */
    const isToolAllowed = (type, toolName) => {
      const allowedTools = getToolsForType(type);
      if (allowedTools === '*') return true;
      return allowedTools.includes(toolName);
    };

    /**
     * Generate unique worker ID
     */
    const _generateWorkerId = () => {
      return `worker_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
    };

    /**
     * Spawn a new worker agent
     * @param {Object} options
     * @param {string} options.type - Worker type (explore, analyze, execute)
     * @param {string} options.task - Task description for the worker
     * @param {string} [options.model] - Optional model override
     * @param {number} [options.maxIterations] - Optional iteration cap
     * @param {number} [options.depth=0] - Current nesting depth (0 = main agent)
     * @returns {Promise<{workerId: string, promise: Promise}>}
     */
    const spawn = async ({ type, task, model, maxIterations, depth = 0 }) => {
      // Enforce flat hierarchy - workers cannot spawn workers
      if (depth > 0) {
        throw new Error('Workers cannot spawn other workers (flat hierarchy enforced)');
      }

      // Check concurrent limit
      if (_activeWorkers.size >= _maxConcurrentWorkers) {
        throw new Error(`Maximum concurrent workers (${_maxConcurrentWorkers}) reached`);
      }

      const workerId = _generateWorkerId();
      const workerType = _workerConfig[type] || _workerConfig.explore;
      const allowedTools = workerType?.tools || [];

      logger.info(`[WorkerManager] Spawning ${type} worker: ${workerId}`);
      logger.info(`[WorkerManager] Task: ${task.substring(0, 100)}...`);

      // Audit log spawn
      if (AuditLogger) {
        await AuditLogger.logEvent('WORKER_SPAWN', {
          workerId,
          type,
          task: task.substring(0, 200),
          allowedTools: allowedTools === '*' ? 'ALL' : allowedTools.length
        });
      }

      // Emit event for UI
      if (EventBus) {
        EventBus.emit('worker:spawned', { workerId, type, task });
      }

      // Create the worker execution promise
      const workerPromise = _executeWorker({
        workerId,
        type,
        task,
        model: model || workerType?.defaultModelRole || 'fast',
        allowedTools,
        maxIterations,
        depth: depth + 1
      });

      // Track active worker
      const startTime = Date.now();
      const workerRecord = {
        workerId,
        type,
        task,
        startTime,
        status: 'running',
        logs: []
      };
      _activeWorkers.set(workerId, {
        ...workerRecord,
        promise: workerPromise
      });

      // Persist initial worker state
      _persistWorker(workerId, workerRecord);

      // Handle completion
      workerPromise
        .then(result => {
          const workerData = _activeWorkers.get(workerId);
          _activeWorkers.delete(workerId);
          const completedRecord = {
            workerId,
            type,
            task,
            startTime: workerData?.startTime || startTime,
            status: 'completed',
            result,
            logs: workerData?.logs || [],
            completedTime: Date.now(),
            duration: Date.now() - (workerData?.startTime || startTime)
          };
          _completedWorkers.set(workerId, completedRecord);
          // Evict oldest if over limit (LRU)
          if (_completedWorkers.size > MAX_COMPLETED_WORKERS) {
            const oldestKey = _completedWorkers.keys().next().value;
            _completedWorkers.delete(oldestKey);
          }
          _persistWorker(workerId, completedRecord);
          if (EventBus) {
            EventBus.emit('worker:completed', { workerId, result });
          }
        })
        .catch(error => {
          const workerData = _activeWorkers.get(workerId);
          _activeWorkers.delete(workerId);
          const errorRecord = {
            workerId,
            type,
            task,
            startTime: workerData?.startTime || startTime,
            status: 'error',
            error: error.message,
            logs: workerData?.logs || [],
            completedTime: Date.now(),
            duration: Date.now() - (workerData?.startTime || startTime)
          };
          _completedWorkers.set(workerId, errorRecord);
          // Evict oldest if over limit (LRU)
          if (_completedWorkers.size > MAX_COMPLETED_WORKERS) {
            const oldestKey = _completedWorkers.keys().next().value;
            _completedWorkers.delete(oldestKey);
          }
          _persistWorker(workerId, errorRecord);
          if (EventBus) {
            EventBus.emit('worker:error', { workerId, error: error.message });
          }
        });

      return { workerId, promise: workerPromise };
    };

    /**
     * Execute worker with Promise-based isolation (main thread)
     * For true Web Worker isolation, see worker-agent.js (future)
     * @private
     */
    const _executeWorker = async ({ workerId, type, task, model, allowedTools, maxIterations = 10, depth }) => {
      const startTime = Date.now();
      let iterations = 0;
      const toolResults = [];

      logger.info(`[WorkerManager] Worker ${workerId} starting execution...`);
      logger.info(`[WorkerManager] Model role: ${model || 'default'}`);
      logger.info(`[WorkerManager] Allowed tools: ${allowedTools === '*' ? 'ALL' : allowedTools.join(', ')}`);

      // Resolve model role to actual config
      const resolvedModelConfig = _resolveModelConfig(model);

      // Check if we have a model config
      if (!resolvedModelConfig) {
        logger.warn(`[WorkerManager] No model config available for role '${model}', returning without LLM call`);
        return {
          workerId,
          type,
          status: 'completed',
          output: `Worker ${workerId} task received but no model configured. Task: ${task}`,
          iterations: 0,
          duration: Date.now() - startTime
        };
      }

      // Create worker system prompt
      const workerSystemPrompt = `You are a worker agent (type: ${type}) executing a specific task.
Your task: ${task}

You have access to the following tools: ${allowedTools === '*' ? 'ALL TOOLS' : allowedTools.join(', ')}

Important:
- Focus only on completing your assigned task
- Return your findings/results clearly
- Do not spawn other workers
- When done, provide a clear summary of your results

Available tool format:
TOOL_CALL: ToolName
ARGS: {"arg": "value"}`;

      // Initialize messages for this worker (fresh context)
      const messages = [
        { role: 'system', content: workerSystemPrompt },
        { role: 'user', content: `Please complete this task: ${task}` }
      ];

      // Get filtered tool schemas
      const toolSchemas = ToolRunner.getToolSchemasFiltered(allowedTools);

      // Track consecutive single-tool calls for nudging
      let consecutiveSingleToolCalls = 0;
      const SINGLE_TOOL_NUDGE_THRESHOLD = 3;

      try {
        // Simple agent loop
        while (iterations < maxIterations) {
          iterations++;

          // Report progress
          if (EventBus) {
            EventBus.emit('worker:progress', {
              workerId,
              iteration: iterations,
              maxIterations,
              message: `Iteration ${iterations}/${maxIterations}`
            });
          }

          // Make LLM call
          logger.info(`[WorkerManager] Worker ${workerId} iteration ${iterations}`);
          const response = await LLMClient.chat(messages, resolvedModelConfig, null, { tools: toolSchemas });

          // Add assistant response to messages
          messages.push({ role: 'assistant', content: response.content });

          // Check for native tool calls (OpenAI format)
          if (response.toolCalls?.length > 0) {
            for (const tc of response.toolCalls) {
              logger.info(`[WorkerManager] Worker ${workerId} native tool call: ${tc.name}`);
              try {
                const result = await ToolRunner.execute(tc.name, tc.args, {
                  allowedTools,
                  workerId
                });
                toolResults.push({ tool: tc.name, args: tc.args, result, success: true });
                messages.push({
                  role: 'user',
                  content: `TOOL_RESULT for ${tc.name}: ${JSON.stringify(result)}`
                });
              } catch (err) {
                toolResults.push({ tool: tc.name, args: tc.args, error: err.message, success: false });
                messages.push({
                  role: 'user',
                  content: `TOOL_ERROR for ${tc.name}: ${err.message}`
                });
              }
            }
            // Track single-tool calls and nudge
            if (response.toolCalls.length === 1) {
              consecutiveSingleToolCalls++;
              if (consecutiveSingleToolCalls >= SINGLE_TOOL_NUDGE_THRESHOLD) {
                messages.push({
                  role: 'user',
                  content: 'TIP: You can batch multiple independent tool calls in a single response. Read-only tools (ReadFile, ListFiles, Grep, Find) run in parallel for better efficiency.'
                });
                consecutiveSingleToolCalls = 0;
              }
            } else {
              consecutiveSingleToolCalls = 0;
            }
            continue; // Continue loop to process tool results
          }

          // Parse text-based tool calls
          const toolCalls = ResponseParser.parseToolCalls(response.content);

          if (toolCalls?.length > 0) {
            for (const tc of toolCalls) {
              logger.info(`[WorkerManager] Worker ${workerId} text tool call: ${tc.name}`);
              try {
                const result = await ToolRunner.execute(tc.name, tc.args, {
                  allowedTools,
                  workerId
                });
                toolResults.push({ tool: tc.name, args: tc.args, result, success: true });
                messages.push({
                  role: 'user',
                  content: `TOOL_RESULT for ${tc.name}: ${JSON.stringify(result)}`
                });
              } catch (err) {
                toolResults.push({ tool: tc.name, args: tc.args, error: err.message, success: false });
                messages.push({
                  role: 'user',
                  content: `TOOL_ERROR for ${tc.name}: ${err.message}`
                });
              }
            }
            // Track single-tool calls and nudge
            if (toolCalls.length === 1) {
              consecutiveSingleToolCalls++;
              if (consecutiveSingleToolCalls >= SINGLE_TOOL_NUDGE_THRESHOLD) {
                messages.push({
                  role: 'user',
                  content: 'TIP: You can batch multiple independent tool calls in a single response. Read-only tools (ReadFile, ListFiles, Grep, Find) run in parallel for better efficiency.'
                });
                consecutiveSingleToolCalls = 0;
              }
            } else {
              consecutiveSingleToolCalls = 0;
            }
            continue; // Continue loop to process tool results
          }

          // No tool calls - worker is done
          logger.info(`[WorkerManager] Worker ${workerId} completed after ${iterations} iterations`);
          break;
        }

        // Extract final output from last assistant message
        const lastAssistantMsg = messages.filter(m => m.role === 'assistant').pop();
        const finalOutput = lastAssistantMsg?.content || 'No output';

        return {
          workerId,
          type,
          task: task.substring(0, 200),
          status: 'completed',
          output: finalOutput,
          iterations,
          toolResults,
          duration: Date.now() - startTime
        };

      } catch (error) {
        logger.error(`[WorkerManager] Worker ${workerId} error:`, error.message);
        return {
          workerId,
          type,
          task: task.substring(0, 200),
          status: 'error',
          error: error.message,
          iterations,
          toolResults,
          duration: Date.now() - startTime
        };
      }
    };

    /**
     * List all active workers
     * @returns {Array<{workerId: string, type: string, task: string, status: string}>}
     */
    const list = () => {
      return Array.from(_activeWorkers.entries()).map(([workerId, data]) => ({
        workerId,
        type: data.type,
        task: data.task.substring(0, 100),
        status: data.status,
        runningFor: Date.now() - data.startTime
      }));
    };

    /**
     * Await completion of specific workers or all workers
     * @param {Object} options
     * @param {string[]} [options.workerIds] - Specific workers to await
     * @param {boolean} [options.all] - Await all active workers
     * @returns {Promise<Object[]>} - Results from all awaited workers
     */
    const awaitWorkers = async ({ workerIds, all }) => {
      let workersToAwait;

      if (all) {
        workersToAwait = Array.from(_activeWorkers.entries());
      } else if (workerIds) {
        workersToAwait = workerIds
          .filter(id => _activeWorkers.has(id))
          .map(id => [id, _activeWorkers.get(id)]);
      } else {
        return [];
      }

      logger.info(`[WorkerManager] Awaiting ${workersToAwait.length} workers...`);

      const results = await Promise.allSettled(
        workersToAwait.map(([id, data]) => data.promise)
      );

      return results.map((result, i) => ({
        workerId: workersToAwait[i][0],
        status: result.status,
        value: result.status === 'fulfilled' ? result.value : null,
        error: result.status === 'rejected' ? result.reason?.message : null
      }));
    };

    /**
     * Add a log entry to a worker
     * @param {string} workerId
     * @param {string} message
     */
    const addLog = (workerId, message) => {
      const worker = _activeWorkers.get(workerId);
      if (worker) {
        const logEntry = { timestamp: Date.now(), message };
        worker.logs = worker.logs || [];
        worker.logs.push(logEntry);
        // Persist with updated logs
        _persistWorker(workerId, {
          workerId,
          type: worker.type,
          task: worker.task,
          startTime: worker.startTime,
          status: worker.status,
          logs: worker.logs
        });
      }
    };

    /**
     * Terminate a specific worker
     * @param {string} workerId
     */
    const terminate = (workerId) => {
      const worker = _activeWorkers.get(workerId);
      if (worker) {
        logger.info(`[WorkerManager] Terminating worker: ${workerId}`);
        // TODO: Actually terminate the Web Worker in Phase 3
        _activeWorkers.delete(workerId);
        const terminatedRecord = {
          workerId,
          type: worker.type,
          task: worker.task,
          startTime: worker.startTime,
          status: 'terminated',
          logs: worker.logs || [],
          completedTime: Date.now(),
          duration: Date.now() - worker.startTime
        };
        _completedWorkers.set(workerId, terminatedRecord);
        _persistWorker(workerId, terminatedRecord);
        if (EventBus) {
          EventBus.emit('worker:terminated', { workerId });
        }
        return true;
      }
      return false;
    };

    /**
     * Get completed worker results
     * @param {string} [workerId] - Specific worker or all if not provided
     */
    const getResults = (workerId) => {
      if (workerId) {
        return _completedWorkers.get(workerId);
      }
      return Array.from(_completedWorkers.entries()).map(([id, data]) => ({
        workerId: id,
        ...data
      }));
    };

    /**
     * Clear completed worker history (also deletes from VFS)
     */
    const clearHistory = async () => {
      // Delete files from VFS
      if (VFS) {
        for (const workerId of _completedWorkers.keys()) {
          try {
            await VFS.delete(`${WORKERS_DIR}/${workerId}.json`);
          } catch (e) {
            // Ignore deletion errors
          }
        }
      }
      _completedWorkers.clear();
    };

    // Create API object so we can reference it in init for circular dependency fix
    const api = {
      init,
      setModelConfig,
      setModelRoles,
      spawn,
      list,
      awaitWorkers,
      terminate,
      addLog,
      getResults,
      clearHistory,
      getToolsForType,
      isToolAllowed
    };

    return api;
  }
};

export default WorkerManager;
","/infrastructure/audit-logger.js":"/**
 * @fileoverview Audit Logger
 * Security tracking. Writes to /.logs/audit/YYYY-MM-DD.jsonl
 * Supports structured export (JSON/CSV) for compliance and debugging.
 */

const AuditLogger = {
  metadata: {
    id: 'AuditLogger',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'VFS', 'TelemetryTimeline?'],
    async: true,
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { Utils, VFS, TelemetryTimeline } = deps;
    const { logger, generateId } = Utils;
    const LOG_DIR = '/.logs/audit';

    const init = async () => {
      // Directory check implied by VFS structure
      return true;
    };

    const logEvent = async (type, data, severity = 'INFO') => {
      const entry = {
        id: generateId('log'),
        ts: new Date().toISOString(),
        type,
        severity,
        data
      };

      // Echo security warnings to console
      if (severity === 'ERROR' || severity === 'WARN') {
        logger.warn(`[Audit] ${type}`, data);
      }

      const date = new Date().toISOString().split('T')[0];
      const path = `${LOG_DIR}/${date}.jsonl`;

      // Retry once on failure to ensure audit trail integrity
      for (let attempt = 0; attempt < 2; attempt++) {
        try {
          let content = '';
          if (await VFS.exists(path)) {
            content = await VFS.read(path);
          }
          content += JSON.stringify(entry) + '\n';
          await VFS.write(path, content);
          if (TelemetryTimeline) {
            await TelemetryTimeline.record(`audit:${type}`, entry.data, { severity, tags: ['audit'] });
          }
          return; // Success
        } catch (e) {
          if (attempt === 0) {
            logger.warn('[AuditLogger] Write failed, retrying...', e.message);
            await new Promise(r => setTimeout(r, 50));
          } else {
            logger.error('[AuditLogger] Write failed after retry - audit event lost', {
              error: e.message,
              entry: { type, severity, id: entry.id }
            });
          }
        }
      }
    };

    /**
     * Get all log entries for a date range
     * @param {string} [startDate] - YYYY-MM-DD (default: today)
     * @param {string} [endDate] - YYYY-MM-DD (default: startDate)
     * @returns {Promise<Array>} Array of log entries
     */
    const getEntries = async (startDate = null, endDate = null) => {
      const today = new Date().toISOString().split('T')[0];
      const start = startDate || today;
      const end = endDate || start;

      const entries = [];
      const current = new Date(start);
      const endDt = new Date(end);

      while (current <= endDt) {
        const dateStr = current.toISOString().split('T')[0];
        const path = `${LOG_DIR}/${dateStr}.jsonl`;

        try {
          if (await VFS.exists(path)) {
            const content = await VFS.read(path);
            const lines = content.split('\n').filter(l => l.trim());
            for (const line of lines) {
              try {
                entries.push(JSON.parse(line));
              } catch (e) {
                // Skip malformed lines
              }
            }
          }
        } catch (e) {
          logger.warn(`[AuditLogger] Failed to read ${path}:`, e.message);
        }

        current.setDate(current.getDate() + 1);
      }

      return entries;
    };

    /**
     * Export audit log as JSON
     * @param {string} [startDate] - YYYY-MM-DD
     * @param {string} [endDate] - YYYY-MM-DD
     * @returns {Promise<string>} JSON string
     */
    const exportJSON = async (startDate = null, endDate = null) => {
      const entries = await getEntries(startDate, endDate);
      return JSON.stringify({
        exported: new Date().toISOString(),
        startDate: startDate || new Date().toISOString().split('T')[0],
        endDate: endDate || startDate || new Date().toISOString().split('T')[0],
        count: entries.length,
        entries
      }, null, 2);
    };

    /**
     * Export audit log as CSV
     * @param {string} [startDate] - YYYY-MM-DD
     * @param {string} [endDate] - YYYY-MM-DD
     * @returns {Promise<string>} CSV string
     */
    const exportCSV = async (startDate = null, endDate = null) => {
      const entries = await getEntries(startDate, endDate);

      // CSV header
      const headers = ['id', 'timestamp', 'type', 'severity', 'data'];
      const rows = [headers.join(',')];

      for (const entry of entries) {
        const row = [
          entry.id || '',
          entry.ts || '',
          entry.type || '',
          entry.severity || 'INFO',
          JSON.stringify(entry.data || {}).replace(/"/g, '""')
        ];
        rows.push(row.map(v => `"${v}"`).join(','));
      }

      return rows.join('\n');
    };

    /**
     * Download audit log (browser only)
     * @param {string} format - 'json' or 'csv'
     * @param {string} [startDate] - YYYY-MM-DD
     * @param {string} [endDate] - YYYY-MM-DD
     */
    const download = async (format = 'json', startDate = null, endDate = null) => {
      const content = format === 'csv'
        ? await exportCSV(startDate, endDate)
        : await exportJSON(startDate, endDate);

      const mimeType = format === 'csv' ? 'text/csv' : 'application/json';
      const ext = format === 'csv' ? 'csv' : 'json';
      const filename = `audit-${startDate || 'today'}-${endDate || startDate || 'today'}.${ext}`;

      const blob = new Blob([content], { type: mimeType });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      logger.info(`[AuditLogger] Downloaded ${filename}`);
    };

    /**
     * Get summary statistics for a date range
     * @param {string} [startDate] - YYYY-MM-DD
     * @param {string} [endDate] - YYYY-MM-DD
     * @returns {Promise<Object>} Statistics
     */
    const getStats = async (startDate = null, endDate = null) => {
      const entries = await getEntries(startDate, endDate);

      const stats = {
        total: entries.length,
        byType: {},
        bySeverity: { INFO: 0, WARN: 0, ERROR: 0 },
        timeRange: {
          start: entries[0]?.ts || null,
          end: entries[entries.length - 1]?.ts || null
        }
      };

      for (const entry of entries) {
        stats.byType[entry.type] = (stats.byType[entry.type] || 0) + 1;
        stats.bySeverity[entry.severity || 'INFO']++;
      }

      return stats;
    };

    return {
      init,
      logEvent,
      getEntries,
      exportJSON,
      exportCSV,
      download,
      getStats,
      // Convenience aliases
      logAgentAction: (action, tool, args) => logEvent('AGENT_ACTION', { action, tool, args }),
      logSecurity: (type, details) => logEvent('SECURITY', { type, ...details }, 'ERROR')
    };
  }
};

export default AuditLogger;
","/infrastructure/circuit-breaker.js":"/**
 * @fileoverview Circuit Breaker - Failure tracking utility
 * Prevents repeated calls to failing services/tools.
 * Implements three states: CLOSED (normal), OPEN (failing), HALF_OPEN (testing recovery).
 */

const CircuitBreaker = {
  metadata: {
    id: 'CircuitBreaker',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'EventBus?'],
    async: false,
    type: 'utility'
  },

  factory: (deps) => {
    const { Utils, EventBus } = deps;
    const { logger } = Utils;

    /** Circuit states */
    const State = {
      CLOSED: 'closed',     // Normal operation
      OPEN: 'open',         // Failing, reject calls
      HALF_OPEN: 'half_open' // Testing recovery
    };

    /**
     * Create a circuit breaker instance
     * @param {Object} options
     * @param {number} options.threshold - Failures before circuit opens (default: 3)
     * @param {number} options.resetMs - Cooldown before testing recovery (default: 60000)
     * @param {number} options.successThreshold - Successes needed to close (default: 2)
     * @param {string} options.name - Name for logging (default: 'CircuitBreaker')
     * @param {boolean} options.emitEvents - Emit EventBus events (default: true)
     */
    const create = (options = {}) => {
      const {
        threshold = 3,
        resetMs = 60000,
        successThreshold = 2,
        name = 'CircuitBreaker',
        emitEvents = true
      } = options;

      const circuits = new Map();

      const emit = (event, data) => {
        if (emitEvents && EventBus) {
          EventBus.emit(event, { breaker: name, ...data });
        }
      };

      /**
       * Check if circuit is open for a key
       * @param {string} key - Identifier (tool name, service name, etc.)
       * @returns {boolean} True if circuit is open (should skip execution)
       */
      const isOpen = (key) => {
        const record = circuits.get(key);
        if (!record) return false;

        const now = Date.now();

        // OPEN state: check if cooldown has passed
        if (record.state === State.OPEN) {
          const elapsed = now - record.tripTime;
          if (elapsed >= resetMs) {
            // Transition to HALF_OPEN (test recovery)
            record.state = State.HALF_OPEN;
            record.testSuccesses = 0;
            logger.info(`[${name}] Circuit half-open for: ${key} (testing recovery)`);
            emit('circuit:half_open', { key });
            return false; // Allow test call
          }
          return true; // Still in cooldown
        }

        // HALF_OPEN state: allow calls (testing recovery)
        if (record.state === State.HALF_OPEN) {
          return false;
        }

        // CLOSED state or counting failures
        if (record.failures >= threshold) {
          // Should have transitioned to OPEN, but just in case
          record.state = State.OPEN;
          record.tripTime = now;
          return true;
        }

        return false;
      };

      /**
       * Record a failure for a key
       * @param {string} key - Identifier
       * @param {Error} error - The error that occurred
       */
      const recordFailure = (key, error) => {
        const now = Date.now();
        let record = circuits.get(key);

        if (!record) {
          record = {
            state: State.CLOSED,
            failures: 0,
            lastError: null,
            tripTime: 0,
            testSuccesses: 0
          };
        }

        record.lastError = error;

        if (record.state === State.HALF_OPEN) {
          // Recovery test failed - back to OPEN
          record.state = State.OPEN;
          record.tripTime = now;
          record.testSuccesses = 0;
          logger.warn(`[${name}] Recovery failed for: ${key}, circuit re-opened`);
          emit('circuit:reopen', { key, error: error?.message });
        } else {
          // Normal failure counting
          record.failures++;

          if (record.failures >= threshold && record.state !== State.OPEN) {
            record.state = State.OPEN;
            record.tripTime = now;
            logger.warn(`[${name}] Circuit TRIPPED for: ${key} after ${record.failures} failures`);
            emit('circuit:open', { key, failures: record.failures, error: error?.message });
          }
        }

        circuits.set(key, record);
      };

      /**
       * Record a success for a key
       * @param {string} key - Identifier
       */
      const recordSuccess = (key) => {
        const record = circuits.get(key);
        if (!record) return;

        if (record.state === State.HALF_OPEN) {
          // Count successful test calls
          record.testSuccesses++;

          if (record.testSuccesses >= successThreshold) {
            // Fully recovered - close circuit
            circuits.delete(key);
            logger.info(`[${name}] Circuit CLOSED for: ${key} (recovered after ${successThreshold} successes)`);
            emit('circuit:closed', { key });
          }
        } else {
          // Normal success - clear failure record
          circuits.delete(key);
        }
      };

      /**
       * Get current state for a key
       * @param {string} key - Identifier
       * @returns {Object|null} Circuit state or null if no record
       */
      const getState = (key) => {
        const record = circuits.get(key);
        if (!record) return { state: State.CLOSED, failures: 0, isOpen: false };

        const now = Date.now();
        const isCurrentlyOpen = record.state === State.OPEN &&
          (now - record.tripTime) < resetMs;

        return {
          state: record.state,
          failures: record.failures,
          lastError: record.lastError?.message,
          isOpen: isCurrentlyOpen,
          tripTime: record.tripTime,
          testSuccesses: record.testSuccesses || 0
        };
      };

      /**
       * Reset all circuits
       */
      const reset = () => {
        circuits.clear();
        logger.info(`[${name}] All circuits reset`);
      };

      /**
       * Get all tracked keys
       * @returns {string[]} List of keys with records
       */
      const getTrackedKeys = () => [...circuits.keys()];

      return {
        isOpen,
        recordFailure,
        recordSuccess,
        getState,
        reset,
        getTrackedKeys,
        State,
        get size() { return circuits.size; }
      };
    };

    return { create, State };
  }
};

export default CircuitBreaker;
","/infrastructure/event-bus.js":"/**
 * @fileoverview Event Bus
 * Pub/Sub system with subscription tracking.
 */

const EventBus = {
  metadata: {
    id: 'EventBus',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils'],
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { logger, createSubscriptionTracker } = deps.Utils;
    const _listeners = new Map();
    const _tracker = createSubscriptionTracker();

    const on = (event, fn, ownerId = null) => {
      if (!_listeners.has(event)) _listeners.set(event, new Set());
      _listeners.get(event).add(fn);

      const unsub = () => {
        const set = _listeners.get(event);
        if (set) {
          set.delete(fn);
          // Clean up empty Sets to prevent memory leak
          if (set.size === 0) {
            _listeners.delete(event);
          }
        }
      };

      if (ownerId) _tracker.track(ownerId, unsub);
      return unsub;
    };

    const emit = (event, data) => {
      // logger.debug(`[Event] ${event}`, data); // Uncomment for verbose debugging
      const set = _listeners.get(event);
      if (set) {
        for (const fn of set) {
          try { fn(data); } catch (e) { logger.error(`[EventBus] Error in ${event}`, e); }
        }
      }
    };

    const unsubscribeModule = (moduleId) => {
      _tracker.unsubscribeAll(moduleId);
      logger.debug(`[EventBus] Unsubscribed module: ${moduleId}`);
    };

    return { on, emit, unsubscribeModule };
  }
};

export default EventBus;
","/infrastructure/genesis-snapshot.js":"/**
 * @fileoverview Genesis Snapshot - Immutable kernel backups and rollback
 * Provides "Lifeboat" snapshots for recovery from bad mutations.
 */

const GenesisSnapshot = {
  metadata: {
    id: 'GenesisSnapshot',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'VFS', 'EventBus'],
    async: true,
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { Utils, VFS, EventBus } = deps;
    const { logger, generateId } = Utils;

    const SNAPSHOT_DIR = '/.genesis/snapshots';
    const LIFEBOAT_KEY = 'REPLOID_LIFEBOAT';
    const MAX_SNAPSHOTS = 10;

    /**
     * Create a full VFS snapshot
     * @param {string} [name] - Optional snapshot name
     * @param {Object} [options] - Options
     * @param {boolean} [options.includeApps] - Include /apps/ (default: false)
     * @param {boolean} [options.includeLogs] - Include /.logs/ (default: false)
     * @returns {Promise<Object>} Snapshot metadata
     */
    const createSnapshot = async (name = null, options = {}) => {
      const { includeApps = false, includeLogs = false } = options;

      const snapshotId = generateId('snap');
      const timestamp = Date.now();
      const snapshotName = name || `snapshot-${new Date(timestamp).toISOString().split('T')[0]}`;

      logger.info(`[Genesis] Creating snapshot: ${snapshotName}`);

      // Collect all files
      const files = {};
      const collectFiles = async (dir) => {
        try {
          const entries = await VFS.list(dir);
          for (const entry of entries) {
            // Skip based on options
            if (!includeLogs && entry.startsWith('/.logs/')) continue;
            if (!includeApps && entry.startsWith('/apps/')) continue;
            if (entry.startsWith('/.genesis/')) continue; // Never include snapshots

            try {
              const stat = await VFS.stat(entry);
              if (stat.isDirectory) {
                await collectFiles(entry);
              } else {
                files[entry] = await VFS.read(entry);
              }
            } catch (e) {
              logger.debug(`[Genesis] Skip ${entry}: ${e.message}`);
            }
          }
        } catch (e) {
          logger.debug(`[Genesis] Cannot list ${dir}: ${e.message}`);
        }
      };

      await collectFiles('/');

      const snapshot = {
        id: snapshotId,
        name: snapshotName,
        timestamp,
        fileCount: Object.keys(files).length,
        isBootable: true, // This snapshot contains a complete runnable system
        version: '2.0', // Self-hosting VFS architecture version
        files
      };

      // Save snapshot to VFS
      const snapshotPath = `${SNAPSHOT_DIR}/${snapshotId}.json`;
      await VFS.write(snapshotPath, JSON.stringify(snapshot));

      // Update index
      await updateIndex(snapshotId, snapshotName, timestamp, Object.keys(files).length);

      // Prune old snapshots
      await pruneSnapshots();

      EventBus.emit('genesis:snapshot_created', {
        id: snapshotId,
        name: snapshotName,
        fileCount: Object.keys(files).length
      });

      logger.info(`[Genesis] Snapshot created: ${snapshotId} (${Object.keys(files).length} files)`);

      return {
        id: snapshotId,
        name: snapshotName,
        timestamp,
        fileCount: Object.keys(files).length,
        isBootable: true,
        version: '2.0'
      };
    };

    /**
     * Create a "Lifeboat" - immutable kernel backup stored in localStorage
     * This survives VFS corruption and can restore the system from scratch.
     */
    const createLifeboat = async () => {
      logger.info('[Genesis] Creating Lifeboat backup...');

      const coreFiles = {};
      const corePaths = ['/core/', '/infrastructure/'];

      for (const prefix of corePaths) {
        try {
          const entries = await VFS.list(prefix);
          for (const entry of entries) {
            if (entry.endsWith('.js')) {
              try {
                coreFiles[entry] = await VFS.read(entry);
              } catch (e) {
                logger.warn(`[Genesis] Cannot backup ${entry}`);
              }
            }
          }
        } catch (e) {
          logger.debug(`[Genesis] Cannot list ${prefix}`);
        }
      }

      const lifeboat = {
        version: '1.0',
        timestamp: Date.now(),
        files: coreFiles
      };

      try {
        // Compress for localStorage (simple approach)
        const json = JSON.stringify(lifeboat);
        localStorage.setItem(LIFEBOAT_KEY, json);

        EventBus.emit('genesis:lifeboat_created', {
          timestamp: lifeboat.timestamp,
          fileCount: Object.keys(coreFiles).length,
          sizeBytes: json.length
        });

        logger.info(`[Genesis] Lifeboat created: ${Object.keys(coreFiles).length} core files`);
        return { success: true, fileCount: Object.keys(coreFiles).length };
      } catch (e) {
        logger.error('[Genesis] Lifeboat creation failed:', e.message);
        return { success: false, error: e.message };
      }
    };

    /**
     * Restore from Lifeboat (emergency recovery)
     */
    const restoreFromLifeboat = async () => {
      logger.warn('[Genesis] EMERGENCY: Restoring from Lifeboat...');

      try {
        const json = localStorage.getItem(LIFEBOAT_KEY);
        if (!json) {
          throw new Error('No Lifeboat backup found');
        }

        const lifeboat = JSON.parse(json);

        for (const [path, content] of Object.entries(lifeboat.files)) {
          await VFS.write(path, content);
          logger.info(`[Genesis] Restored: ${path}`);
        }

        EventBus.emit('genesis:lifeboat_restored', {
          timestamp: lifeboat.timestamp,
          fileCount: Object.keys(lifeboat.files).length
        });

        logger.info(`[Genesis] Lifeboat restore complete: ${Object.keys(lifeboat.files).length} files`);
        return { success: true, fileCount: Object.keys(lifeboat.files).length };
      } catch (e) {
        logger.error('[Genesis] Lifeboat restore failed:', e.message);
        return { success: false, error: e.message };
      }
    };

    /**
     * Restore from a snapshot
     * @param {string} snapshotId - Snapshot ID to restore
     * @param {Object} [options] - Options
     * @param {boolean} [options.deleteExtra] - Delete files not in snapshot (default: false)
     */
    const restoreSnapshot = async (snapshotId, options = {}) => {
      const { deleteExtra = false } = options;

      logger.warn(`[Genesis] Restoring snapshot: ${snapshotId}`);

      const snapshotPath = `${SNAPSHOT_DIR}/${snapshotId}.json`;
      const snapshotJson = await VFS.read(snapshotPath);
      const snapshot = JSON.parse(snapshotJson);

      let restored = 0;
      let deleted = 0;

      // Restore all files from snapshot
      for (const [path, content] of Object.entries(snapshot.files)) {
        try {
          await VFS.write(path, content);
          restored++;
        } catch (e) {
          logger.warn(`[Genesis] Failed to restore ${path}: ${e.message}`);
        }
      }

      // Optionally delete files not in snapshot
      if (deleteExtra) {
        const currentFiles = await getAllFiles('/');
        for (const path of currentFiles) {
          if (path.startsWith('/.genesis/')) continue;
          if (path.startsWith('/.logs/')) continue;
          if (!snapshot.files[path]) {
            try {
              await VFS.delete(path);
              deleted++;
            } catch (e) {
              logger.debug(`[Genesis] Could not delete ${path}`);
            }
          }
        }
      }

      EventBus.emit('genesis:snapshot_restored', {
        id: snapshotId,
        name: snapshot.name,
        restored,
        deleted
      });

      logger.info(`[Genesis] Restore complete: ${restored} restored, ${deleted} deleted`);
      return { success: true, restored, deleted };
    };

    /**
     * Get list of available snapshots
     */
    const listSnapshots = async () => {
      try {
        const indexPath = `${SNAPSHOT_DIR}/index.json`;
        if (await VFS.exists(indexPath)) {
          const indexJson = await VFS.read(indexPath);
          return JSON.parse(indexJson);
        }
      } catch (e) {
        logger.debug('[Genesis] No snapshot index');
      }
      return [];
    };

    /**
     * Delete a snapshot
     */
    const deleteSnapshot = async (snapshotId) => {
      const snapshotPath = `${SNAPSHOT_DIR}/${snapshotId}.json`;
      await VFS.delete(snapshotPath);

      // Update index
      const index = await listSnapshots();
      const newIndex = index.filter(s => s.id !== snapshotId);
      await VFS.write(`${SNAPSHOT_DIR}/index.json`, JSON.stringify(newIndex, null, 2));

      EventBus.emit('genesis:snapshot_deleted', { id: snapshotId });
      logger.info(`[Genesis] Deleted snapshot: ${snapshotId}`);
    };

    /**
     * Export snapshot as downloadable JSON
     */
    const exportSnapshot = async (snapshotId) => {
      const snapshotPath = `${SNAPSHOT_DIR}/${snapshotId}.json`;
      const snapshotJson = await VFS.read(snapshotPath);
      const snapshot = JSON.parse(snapshotJson);

      const blob = new Blob([JSON.stringify(snapshot, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `genesis-${snapshot.name}-${snapshotId}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      logger.info(`[Genesis] Exported: ${snapshot.name}`);
    };

    /**
     * Import snapshot from file
     */
    const importSnapshot = async (file) => {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = async (e) => {
          try {
            const snapshot = JSON.parse(e.target.result);

            // Validate snapshot structure
            if (!snapshot.id || !snapshot.files || !snapshot.timestamp) {
              throw new Error('Invalid snapshot format');
            }

            // Save to VFS
            const snapshotPath = `${SNAPSHOT_DIR}/${snapshot.id}.json`;
            await VFS.write(snapshotPath, JSON.stringify(snapshot));

            // Update index
            await updateIndex(snapshot.id, snapshot.name, snapshot.timestamp, snapshot.fileCount);

            EventBus.emit('genesis:snapshot_imported', { id: snapshot.id, name: snapshot.name });
            logger.info(`[Genesis] Imported: ${snapshot.name}`);

            resolve({ success: true, id: snapshot.id, name: snapshot.name });
          } catch (err) {
            reject(err);
          }
        };
        reader.onerror = () => reject(new Error('Failed to read file'));
        reader.readAsText(file);
      });
    };

    // --- Internal helpers ---

    const updateIndex = async (id, name, timestamp, fileCount) => {
      const index = await listSnapshots();
      index.push({ id, name, timestamp, fileCount });
      index.sort((a, b) => b.timestamp - a.timestamp);
      await VFS.write(`${SNAPSHOT_DIR}/index.json`, JSON.stringify(index, null, 2));
    };

    const pruneSnapshots = async () => {
      const index = await listSnapshots();
      if (index.length > MAX_SNAPSHOTS) {
        const toDelete = index.slice(MAX_SNAPSHOTS);
        for (const snap of toDelete) {
          try {
            await deleteSnapshot(snap.id);
          } catch (e) {
            logger.debug(`[Genesis] Could not prune ${snap.id}`);
          }
        }
      }
    };

    const getAllFiles = async (dir, acc = []) => {
      try {
        const entries = await VFS.list(dir);
        for (const entry of entries) {
          try {
            const stat = await VFS.stat(entry);
            if (stat.isDirectory) {
              await getAllFiles(entry, acc);
            } else {
              acc.push(entry);
            }
          } catch (e) {}
        }
      } catch (e) {}
      return acc;
    };

    /**
     * Check if Lifeboat exists
     */
    const hasLifeboat = () => {
      try {
        return !!localStorage.getItem(LIFEBOAT_KEY);
      } catch (e) {
        return false;
      }
    };

    /**
     * Get Lifeboat info
     */
    const getLifeboatInfo = () => {
      try {
        const json = localStorage.getItem(LIFEBOAT_KEY);
        if (!json) return null;
        const lifeboat = JSON.parse(json);
        return {
          timestamp: lifeboat.timestamp,
          fileCount: Object.keys(lifeboat.files).length,
          sizeBytes: json.length
        };
      } catch (e) {
        return null;
      }
    };

    return {
      createSnapshot,
      restoreSnapshot,
      listSnapshots,
      deleteSnapshot,
      exportSnapshot,
      importSnapshot,
      createLifeboat,
      restoreFromLifeboat,
      hasLifeboat,
      getLifeboatInfo
    };
  }
};

export default GenesisSnapshot;
","/infrastructure/hitl-controller.js":"/**
 * @fileoverview HITL Controller - Human-in-the-Loop approval system
 * Autonomous by default. Opt-in HITL for users who want approval gates.
 */

const HITLController = {
  metadata: {
    id: 'HITLController',
    version: '1.0.0',
    genesis: { introduced: 'reflection' },
    dependencies: ['Utils', 'EventBus'],
    async: false,
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { Utils, EventBus } = deps;
    const { logger, generateId } = Utils;

    const STORAGE_KEY = 'REPLOID_HITL_CONFIG';

    /** Approval capability types */
    const CAPABILITIES = {
      APPROVE_CODE_CHANGES: 'approve_code_changes',
      APPROVE_FILE_OPERATIONS: 'approve_file_operations',
      APPROVE_TOOL_EXECUTION: 'approve_tool_execution',
      APPROVE_SELF_MODIFICATION: 'approve_self_modification',
      APPROVE_CORE_WRITES: 'approve_core_writes'
    };

    /** Mode constants */
    const MODES = {
      AUTONOMOUS: 'autonomous',
      HITL: 'hitl',
      EVERY_N: 'every_n', // Approve every N steps
      INHERIT: 'inherit'
    };

    // Internal state
    const _moduleRegistry = new Map();
    const _approvalQueue = [];
    const _timeouts = new Map();

    let _config = {
      approvalMode: MODES.AUTONOMOUS, // Autonomous by default
      moduleOverrides: {},
      everyNSteps: 5, // Default: approve every 5 steps
      stepCounter: 0  // Track steps since last approval
    };

    const _stats = {
      total: 0,
      approved: 0,
      rejected: 0,
      timedOut: 0,
      autoApproved: 0,
      history: []
    };

    // --- Persistence ---

    const _saveConfig = () => {
      try {
        const toSave = {
          approvalMode: _config.approvalMode,
          moduleOverrides: _config.moduleOverrides,
          everyNSteps: _config.everyNSteps,
          stepCounter: _config.stepCounter
        };
        localStorage.setItem(STORAGE_KEY, JSON.stringify(toSave));
      } catch (e) {
        logger.warn('[HITL] Failed to save config:', e.message);
      }
    };

    const _loadConfig = () => {
      try {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
          const parsed = JSON.parse(saved);
          _config.approvalMode = parsed.approvalMode || MODES.AUTONOMOUS;
          _config.moduleOverrides = parsed.moduleOverrides || {};
          _config.everyNSteps = parsed.everyNSteps || 5;
          _config.stepCounter = parsed.stepCounter || 0;
          logger.info(`[HITL] Loaded config: ${_config.approvalMode} mode` +
            (_config.approvalMode === MODES.EVERY_N ? ` (every ${_config.everyNSteps} steps)` : ''));
        }
      } catch (e) {
        logger.warn('[HITL] Failed to load config, using defaults');
      }
    };

    // --- Module Registration ---

    /**
     * Register a module as HITL-capable
     * @param {string} moduleId - Module identifier
     * @param {string[]} capabilities - Array of CAPABILITIES
     * @param {string} [description] - Optional description
     */
    const registerModule = (moduleId, capabilities = [], description = '') => {
      if (!moduleId) {
        logger.warn('[HITL] registerModule called without moduleId');
        return;
      }

      const existing = _moduleRegistry.get(moduleId);
      const currentMode = _config.moduleOverrides[moduleId] || MODES.INHERIT;

      _moduleRegistry.set(moduleId, {
        id: moduleId,
        description,
        capabilities,
        currentMode,
        registeredAt: existing?.registeredAt || Date.now()
      });

      EventBus.emit('hitl:module-registered', { moduleId });
      logger.debug(`[HITL] Registered module: ${moduleId} with ${capabilities.length} capabilities`);
    };

    // --- Mode Management ---

    /**
     * Get effective mode for a module
     * @param {string} moduleId - Module identifier
     * @returns {string} 'autonomous' or 'hitl'
     */
    const getModuleMode = (moduleId) => {
      const override = _config.moduleOverrides[moduleId];
      if (override && override !== MODES.INHERIT) {
        return override;
      }
      return _config.approvalMode;
    };

    /**
     * Set master mode (affects all modules using 'inherit')
     * @param {string} mode - 'autonomous' or 'hitl'
     */
    const setApprovalMode = (mode) => {
      if (mode !== MODES.AUTONOMOUS && mode !== MODES.HITL && mode !== MODES.EVERY_N) {
        logger.warn(`[HITL] Invalid mode: ${mode}`);
        return;
      }

      const oldMode = _config.approvalMode;
      _config.approvalMode = mode;

      // Reset step counter when changing to/from EVERY_N mode
      if (mode === MODES.EVERY_N || oldMode === MODES.EVERY_N) {
        _config.stepCounter = 0;
      }

      _saveConfig();

      const affectedModules = [..._moduleRegistry.keys()].filter(
        id => !_config.moduleOverrides[id] || _config.moduleOverrides[id] === MODES.INHERIT
      );

      EventBus.emit('hitl:approval-mode-changed', { oldMode, newMode: mode, affectedModules });
      logger.info(`[HITL] Approval mode changed: ${oldMode} -> ${mode}` +
        (mode === MODES.EVERY_N ? ` (every ${_config.everyNSteps} steps)` : ''));
    };

    /**
     * Set the step interval for EVERY_N mode
     * @param {number} steps - Number of steps between approvals (1-100)
     */
    const setEveryNSteps = (steps) => {
      const n = parseInt(steps, 10);
      if (isNaN(n) || n < 1 || n > 100) {
        logger.warn(`[HITL] Invalid step count: ${steps} (must be 1-100)`);
        return;
      }

      _config.everyNSteps = n;
      _config.stepCounter = 0; // Reset counter
      _saveConfig();

      EventBus.emit('hitl:every-n-changed', { steps: n });
      logger.info(`[HITL] Every-N interval set to: ${n} steps`);
    };

    /**
     * Set mode override for a specific module
     * @param {string} moduleId - Module identifier
     * @param {string} mode - 'autonomous', 'hitl', or 'inherit'
     */
    const setModuleMode = (moduleId, mode) => {
      if (!_moduleRegistry.has(moduleId)) {
        logger.warn(`[HITL] Module not registered: ${moduleId}`);
        return;
      }

      if (![MODES.AUTONOMOUS, MODES.HITL, MODES.EVERY_N, MODES.INHERIT].includes(mode)) {
        logger.warn(`[HITL] Invalid mode: ${mode}`);
        return;
      }

      const oldMode = _config.moduleOverrides[moduleId] || MODES.INHERIT;
      _config.moduleOverrides[moduleId] = mode;

      const entry = _moduleRegistry.get(moduleId);
      if (entry) {
        entry.currentMode = mode;
      }

      _saveConfig();

      EventBus.emit('hitl:module-mode-changed', {
        moduleId,
        oldMode,
        newMode: mode,
        effectiveMode: getModuleMode(moduleId)
      });
    };

    // --- Approval Logic ---

    /**
     * Check if approval is required for an action
     * @param {string} moduleId - Module identifier
     * @param {string} capability - Capability being checked
     * @returns {boolean} True if approval required
     */
    const requiresApproval = (moduleId, capability) => {
      const effectiveMode = getModuleMode(moduleId);
      if (effectiveMode === MODES.AUTONOMOUS) {
        return false;
      }

      // In EVERY_N mode, check step counter
      if (effectiveMode === MODES.EVERY_N) {
        _config.stepCounter++;
        const needsApproval = _config.stepCounter >= _config.everyNSteps;
        if (needsApproval) {
          _config.stepCounter = 0; // Reset counter
          _saveConfig();
        }
        return needsApproval;
      }

      // In HITL mode, check if module has this capability
      const entry = _moduleRegistry.get(moduleId);
      if (!entry) {
        return false; // Unregistered modules don't require approval
      }

      return entry.capabilities.includes(capability);
    };

    /**
     * Request approval for an action
     * @param {Object} request - Approval request
     * @param {string} request.moduleId - Module requesting approval
     * @param {string} request.capability - Capability being used
     * @param {string} request.action - Human-readable action description
     * @param {*} request.data - Data to pass to callback
     * @param {Function} request.onApprove - Called with data on approval
     * @param {Function} request.onReject - Called with reason on rejection
     * @param {number} [request.timeout] - Auto-reject after ms (optional)
     * @returns {string|null} Approval ID if queued, null if auto-approved
     */
    const requestApproval = (request) => {
      const { moduleId, capability, action, data, onApprove, onReject, timeout } = request;

      // Check if approval is actually required
      if (!requiresApproval(moduleId, capability)) {
        // Auto-approve in autonomous mode
        _stats.autoApproved++;
        logger.debug(`[HITL] Auto-approved: ${moduleId}/${capability}`);
        if (onApprove) onApprove(data);
        return null;
      }

      // Queue for approval
      const approvalId = generateId('approval');
      const item = {
        id: approvalId,
        moduleId,
        capability,
        action,
        data,
        onApprove,
        onReject,
        timestamp: Date.now(),
        status: 'pending'
      };

      _approvalQueue.push(item);

      // Set timeout if specified
      if (timeout && timeout > 0) {
        const timeoutId = setTimeout(() => {
          _handleTimeout(approvalId);
        }, timeout);
        _timeouts.set(approvalId, timeoutId);
      }

      EventBus.emit('hitl:approval-pending', item);
      logger.info(`[HITL] Approval required: ${action} (${approvalId})`);

      return approvalId;
    };

    /**
     * Approve a pending request
     * @param {string} approvalId - Approval ID
     * @param {*} [data] - Optional data override
     */
    const approve = (approvalId, data = null) => {
      const index = _approvalQueue.findIndex(item => item.id === approvalId);
      if (index === -1) {
        logger.warn(`[HITL] Approval not found: ${approvalId}`);
        return false;
      }

      const item = _approvalQueue[index];
      _approvalQueue.splice(index, 1);

      // Clear timeout if set
      if (_timeouts.has(approvalId)) {
        clearTimeout(_timeouts.get(approvalId));
        _timeouts.delete(approvalId);
      }

      // Update stats
      _stats.total++;
      _stats.approved++;
      _addHistory('approved', item);

      // Execute callback
      if (item.onApprove) {
        item.onApprove(data !== null ? data : item.data);
      }

      EventBus.emit('hitl:approval-granted', { approvalId, item });
      logger.info(`[HITL] Approved: ${item.action}`);

      return true;
    };

    /**
     * Reject a pending request
     * @param {string} approvalId - Approval ID
     * @param {string} [reason] - Rejection reason
     */
    const reject = (approvalId, reason = 'Rejected by user') => {
      const index = _approvalQueue.findIndex(item => item.id === approvalId);
      if (index === -1) {
        logger.warn(`[HITL] Approval not found: ${approvalId}`);
        return false;
      }

      const item = _approvalQueue[index];
      _approvalQueue.splice(index, 1);

      // Clear timeout if set
      if (_timeouts.has(approvalId)) {
        clearTimeout(_timeouts.get(approvalId));
        _timeouts.delete(approvalId);
      }

      // Update stats
      _stats.total++;
      _stats.rejected++;
      _addHistory('rejected', item, reason);

      // Execute callback
      if (item.onReject) {
        item.onReject(reason);
      }

      EventBus.emit('hitl:approval-rejected', { approvalId, item, reason });
      logger.info(`[HITL] Rejected: ${item.action} - ${reason}`);

      return true;
    };

    const _handleTimeout = (approvalId) => {
      const index = _approvalQueue.findIndex(item => item.id === approvalId);
      if (index === -1) return; // Already processed

      const item = _approvalQueue[index];
      _approvalQueue.splice(index, 1);
      _timeouts.delete(approvalId);

      // Update stats
      _stats.total++;
      _stats.timedOut++;
      _addHistory('timeout', item, 'Timed out');

      // Execute rejection callback
      if (item.onReject) {
        item.onReject('Approval timed out');
      }

      EventBus.emit('hitl:approval-timeout', { approvalId, item });
      logger.warn(`[HITL] Approval timed out: ${item.action}`);
    };

    const _addHistory = (outcome, item, reason = null) => {
      _stats.history.unshift({
        outcome,
        moduleId: item.moduleId,
        action: item.action,
        reason,
        timestamp: Date.now()
      });

      // Keep only last 50 entries
      if (_stats.history.length > 50) {
        _stats.history.pop();
      }
    };

    // --- Query APIs ---

    const getState = () => ({
      config: {
        approvalMode: _config.approvalMode,
        moduleOverrides: { ..._config.moduleOverrides }
      },
      approvalQueue: [..._approvalQueue],
      approvalStats: { ..._stats, history: [..._stats.history] },
      registeredModules: [..._moduleRegistry.values()].map(m => ({
        ...m,
        effectiveMode: getModuleMode(m.id)
      }))
    });

    const getApprovalQueue = () => [..._approvalQueue];

    const getStats = () => ({ ..._stats, history: [..._stats.history] });

    const isHITLEnabled = () => _config.approvalMode === MODES.HITL;

    const resetToDefaults = () => {
      _config.approvalMode = MODES.AUTONOMOUS;
      _config.moduleOverrides = {};
      _approvalQueue.length = 0;

      // Clear all timeouts
      for (const timeoutId of _timeouts.values()) {
        clearTimeout(timeoutId);
      }
      _timeouts.clear();

      _saveConfig();
      EventBus.emit('hitl:config-reset', {});
      logger.info('[HITL] Reset to defaults (autonomous mode)');
    };

    // --- EventBus Integration ---

    const init = () => {
      _loadConfig();

      EventBus.on('hitl:set-approval-mode', ({ mode }) => setApprovalMode(mode), 'HITLController');
      EventBus.on('hitl:set-module-mode', ({ moduleId, mode }) => setModuleMode(moduleId, mode), 'HITLController');
      EventBus.on('hitl:approve', ({ approvalId, data }) => approve(approvalId, data), 'HITLController');
      EventBus.on('hitl:reject', ({ approvalId, reason }) => reject(approvalId, reason), 'HITLController');

      logger.info(`[HITL] Initialized in ${_config.approvalMode} mode`);
      return true;
    };

    return {
      init,
      CAPABILITIES,
      MODES,
      registerModule,
      getModuleMode,
      setApprovalMode,
      setModuleMode,
      setEveryNSteps,
      requiresApproval,
      requestApproval,
      approve,
      reject,
      getState,
      getApprovalQueue,
      getStats,
      isHITLEnabled,
      resetToDefaults
    };
  }
};

export default HITLController;
","/infrastructure/indexed-db-helper.js":"/**
 * @fileoverview IndexedDB Helper - Database initialization utility
 * Provides standardized IndexedDB setup with store/index configuration.
 *
 * NOTE: Cannot be used by bootstrap modules (vfs.js, event-bus.js, utils.js)
 * which must remain self-contained.
 */

const IndexedDBHelper = {
  metadata: {
    id: 'IndexedDBHelper',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils'],
    async: false,
    type: 'utility'
  },

  factory: (deps) => {
    const { Utils } = deps;
    const { logger } = Utils;

    /**
     * Create a database helper for a specific database
     * @param {string} dbName - Database name
     * @param {number} version - Database version
     * @param {Array<Object>} storeConfigs - Store configurations
     * @param {string} storeConfigs[].name - Object store name
     * @param {string} storeConfigs[].keyPath - Key path for objects
     * @param {boolean} storeConfigs[].autoIncrement - Auto-increment keys
     * @param {Array<Object>} storeConfigs[].indexes - Index definitions
     * @param {string} storeConfigs[].indexes[].name - Index name
     * @param {string} storeConfigs[].indexes[].keyPath - Index key path
     * @param {boolean} storeConfigs[].indexes[].unique - Unique constraint
     * @returns {Object} Database helper with openDB, close methods
     */
    const createDBHelper = (dbName, version, storeConfigs) => {
      let db = null;
      let openPromise = null;

      const openDB = () => {
        // Return existing connection if open
        if (db) return Promise.resolve(db);

        // Return pending connection if opening
        if (openPromise) return openPromise;

        openPromise = new Promise((resolve, reject) => {
          const request = indexedDB.open(dbName, version);

          request.onupgradeneeded = (event) => {
            const database = event.target.result;

            for (const config of storeConfigs) {
              if (!database.objectStoreNames.contains(config.name)) {
                const storeOptions = { keyPath: config.keyPath };
                if (config.autoIncrement) {
                  storeOptions.autoIncrement = true;
                }

                const store = database.createObjectStore(config.name, storeOptions);

                // Create indexes
                if (config.indexes) {
                  for (const idx of config.indexes) {
                    store.createIndex(
                      idx.name,
                      idx.keyPath || idx.name,
                      { unique: !!idx.unique }
                    );
                  }
                }
              }
            }
          };

          request.onsuccess = (e) => {
            db = e.target.result;
            logger.info(`[IndexedDBHelper] Database '${dbName}' connected`);
            resolve(db);
          };

          request.onerror = () => {
            openPromise = null;
            reject(new Error(`Failed to open database: ${dbName}`));
          };
        });

        return openPromise;
      };

      const close = () => {
        if (db) {
          db.close();
          db = null;
          openPromise = null;
          logger.info(`[IndexedDBHelper] Database '${dbName}' closed`);
        }
      };

      /**
       * Run a transaction on specified stores
       * @param {string|string[]} storeNames - Store name(s)
       * @param {'readonly'|'readwrite'} mode - Transaction mode
       * @param {Function} callback - (stores) => result
       * @returns {Promise<any>} Transaction result
       */
      const transaction = async (storeNames, mode, callback) => {
        await openDB();
        const stores = Array.isArray(storeNames) ? storeNames : [storeNames];
        const tx = db.transaction(stores, mode);

        // Get store objects
        const storeObjects = stores.length === 1
          ? tx.objectStore(stores[0])
          : stores.reduce((acc, name) => {
              acc[name] = tx.objectStore(name);
              return acc;
            }, {});

        return callback(storeObjects, tx);
      };

      /**
       * Get all records from a store
       * @param {string} storeName - Store name
       * @returns {Promise<Array>} All records
       */
      const getAll = async (storeName) => {
        return transaction(storeName, 'readonly', (store) => {
          return new Promise((resolve) => {
            const req = store.getAll();
            req.onsuccess = () => resolve(req.result || []);
            req.onerror = () => resolve([]);
          });
        });
      };

      /**
       * Get a record by key
       * @param {string} storeName - Store name
       * @param {any} key - Record key
       * @returns {Promise<any>} Record or undefined
       */
      const get = async (storeName, key) => {
        return transaction(storeName, 'readonly', (store) => {
          return new Promise((resolve) => {
            const req = store.get(key);
            req.onsuccess = () => resolve(req.result);
            req.onerror = () => resolve(undefined);
          });
        });
      };

      /**
       * Put a record (add or update)
       * @param {string} storeName - Store name
       * @param {any} value - Record value
       * @returns {Promise<any>} Record key
       */
      const put = async (storeName, value) => {
        return transaction(storeName, 'readwrite', (store) => {
          return new Promise((resolve, reject) => {
            const req = store.put(value);
            req.onsuccess = () => resolve(req.result);
            req.onerror = () => reject(new Error('Put failed'));
          });
        });
      };

      /**
       * Delete a record by key
       * @param {string} storeName - Store name
       * @param {any} key - Record key
       * @returns {Promise<void>}
       */
      const remove = async (storeName, key) => {
        return transaction(storeName, 'readwrite', (store) => {
          return new Promise((resolve) => {
            const req = store.delete(key);
            req.onsuccess = () => resolve();
            req.onerror = () => resolve();
          });
        });
      };

      /**
       * Clear all records from a store
       * @param {string} storeName - Store name
       * @returns {Promise<void>}
       */
      const clear = async (storeName) => {
        return transaction(storeName, 'readwrite', (store) => {
          return new Promise((resolve) => {
            const req = store.clear();
            req.onsuccess = () => resolve();
            req.onerror = () => resolve();
          });
        });
      };

      return {
        openDB,
        close,
        transaction,
        getAll,
        get,
        put,
        remove,
        clear,
        get isOpen() { return !!db; }
      };
    };

    return { createDBHelper };
  }
};

export default IndexedDBHelper;
","/infrastructure/observability.js":"/**
 * @fileoverview Observability - Token tracking, mutation stream, and metrics
 * Real-time visibility into agent behavior and resource usage.
 */

const Observability = {
  metadata: {
    id: 'Observability',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'EventBus', 'StateManager?'],
    async: false,
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { Utils, EventBus, StateManager } = deps;
    const { logger } = Utils;

    // --- Token Tracking ---
    const _tokenUsage = {
      session: { input: 0, output: 0, total: 0 },
      daily: { input: 0, output: 0, total: 0, date: null },
      byModel: {},
      history: [] // Last 100 requests
    };

    const COST_PER_1K = {
      'gpt-4': { input: 0.03, output: 0.06 },
      'gpt-4-turbo': { input: 0.01, output: 0.03 },
      'gpt-3.5-turbo': { input: 0.0005, output: 0.0015 },
      'claude-3-opus': { input: 0.015, output: 0.075 },
      'claude-3-sonnet': { input: 0.003, output: 0.015 },
      'claude-3-haiku': { input: 0.00025, output: 0.00125 },
      'gemini-pro': { input: 0.00025, output: 0.0005 },
      'gemini-1.5-pro': { input: 0.00125, output: 0.005 },
      default: { input: 0.001, output: 0.002 }
    };

    /**
     * Record token usage from an LLM call
     * @param {Object} usage - { inputTokens, outputTokens, model, provider }
     */
    const recordTokens = (usage) => {
      const { inputTokens = 0, outputTokens = 0, model = 'unknown', provider = 'unknown' } = usage;
      const total = inputTokens + outputTokens;

      // Update session totals
      _tokenUsage.session.input += inputTokens;
      _tokenUsage.session.output += outputTokens;
      _tokenUsage.session.total += total;

      // Update daily totals
      const today = new Date().toISOString().split('T')[0];
      if (_tokenUsage.daily.date !== today) {
        _tokenUsage.daily = { input: 0, output: 0, total: 0, date: today };
      }
      _tokenUsage.daily.input += inputTokens;
      _tokenUsage.daily.output += outputTokens;
      _tokenUsage.daily.total += total;

      // Track by model
      if (!_tokenUsage.byModel[model]) {
        _tokenUsage.byModel[model] = { input: 0, output: 0, total: 0, calls: 0 };
      }
      _tokenUsage.byModel[model].input += inputTokens;
      _tokenUsage.byModel[model].output += outputTokens;
      _tokenUsage.byModel[model].total += total;
      _tokenUsage.byModel[model].calls++;

      // Add to history
      _tokenUsage.history.push({
        timestamp: Date.now(),
        model,
        provider,
        inputTokens,
        outputTokens,
        total
      });
      if (_tokenUsage.history.length > 100) {
        _tokenUsage.history.shift();
      }

      // Emit event for UI
      EventBus.emit('observability:tokens', {
        session: { ..._tokenUsage.session },
        daily: { ..._tokenUsage.daily },
        latest: { model, inputTokens, outputTokens, total }
      });
    };

    /**
     * Estimate cost for token usage
     * @param {string} model - Model name
     * @param {number} inputTokens
     * @param {number} outputTokens
     * @returns {number} Estimated cost in USD
     */
    const estimateCost = (model, inputTokens, outputTokens) => {
      const rates = COST_PER_1K[model] || COST_PER_1K.default;
      return (inputTokens / 1000) * rates.input + (outputTokens / 1000) * rates.output;
    };

    /**
     * Get token usage summary
     */
    const getTokenUsage = () => {
      const sessionCost = Object.entries(_tokenUsage.byModel).reduce((sum, [model, usage]) => {
        return sum + estimateCost(model, usage.input, usage.output);
      }, 0);

      return {
        session: { ..._tokenUsage.session, estimatedCost: sessionCost },
        daily: { ..._tokenUsage.daily },
        byModel: { ..._tokenUsage.byModel },
        history: [..._tokenUsage.history]
      };
    };

    // --- Mutation Stream ---
    const _mutations = [];
    const MAX_MUTATIONS = 500;

    /**
     * Record a VFS mutation
     * @param {Object} mutation - { type, path, bytesBefore, bytesAfter, source }
     */
    const recordMutation = (mutation) => {
      const entry = {
        id: Utils.generateId('mut'),
        timestamp: Date.now(),
        ...mutation
      };

      _mutations.push(entry);
      if (_mutations.length > MAX_MUTATIONS) {
        _mutations.shift();
      }

      EventBus.emit('observability:mutation', entry);
    };

    /**
     * Get mutation history
     * @param {Object} [filter] - { type, path, since }
     */
    const getMutations = (filter = {}) => {
      let result = [..._mutations];

      if (filter.type) {
        result = result.filter(m => m.type === filter.type);
      }
      if (filter.path) {
        result = result.filter(m => m.path.includes(filter.path));
      }
      if (filter.since) {
        result = result.filter(m => m.timestamp >= filter.since);
      }

      return result;
    };

    // --- Agent Decision Trace ---
    const _decisionTrace = [];
    const MAX_DECISIONS = 200;

    /**
     * Record an agent decision point
     * @param {Object} decision - { cycle, type, input, output, reasoning }
     */
    const recordDecision = (decision) => {
      const entry = {
        id: Utils.generateId('dec'),
        timestamp: Date.now(),
        ...decision
      };

      _decisionTrace.push(entry);
      if (_decisionTrace.length > MAX_DECISIONS) {
        _decisionTrace.shift();
      }

      EventBus.emit('observability:decision', entry);
    };

    /**
     * Get decision trace
     * @param {number} [limit] - Max entries to return
     */
    const getDecisionTrace = (limit = 50) => {
      return _decisionTrace.slice(-limit);
    };

    // --- Performance Metrics ---
    const _metrics = {
      llmLatency: [], // Last 50 LLM call latencies
      toolLatency: {}, // By tool name
      errorRate: { total: 0, errors: 0 }
    };

    /**
     * Record LLM latency
     */
    const recordLLMLatency = (ms, model) => {
      _metrics.llmLatency.push({ ms, model, timestamp: Date.now() });
      if (_metrics.llmLatency.length > 50) {
        _metrics.llmLatency.shift();
      }
    };

    /**
     * Record tool execution latency
     */
    const recordToolLatency = (tool, ms, success) => {
      if (!_metrics.toolLatency[tool]) {
        _metrics.toolLatency[tool] = { calls: 0, totalMs: 0, errors: 0 };
      }
      _metrics.toolLatency[tool].calls++;
      _metrics.toolLatency[tool].totalMs += ms;
      if (!success) _metrics.toolLatency[tool].errors++;

      _metrics.errorRate.total++;
      if (!success) _metrics.errorRate.errors++;
    };

    /**
     * Get performance metrics summary
     */
    const getMetrics = () => {
      const avgLLMLatency = _metrics.llmLatency.length > 0
        ? _metrics.llmLatency.reduce((sum, l) => sum + l.ms, 0) / _metrics.llmLatency.length
        : 0;

      const toolMetrics = {};
      for (const [tool, data] of Object.entries(_metrics.toolLatency)) {
        toolMetrics[tool] = {
          calls: data.calls,
          avgMs: data.calls > 0 ? Math.round(data.totalMs / data.calls) : 0,
          errorRate: data.calls > 0 ? (data.errors / data.calls * 100).toFixed(1) + '%' : '0%'
        };
      }

      return {
        llm: {
          avgLatencyMs: Math.round(avgLLMLatency),
          recentCalls: _metrics.llmLatency.length
        },
        tools: toolMetrics,
        errorRate: _metrics.errorRate.total > 0
          ? (_metrics.errorRate.errors / _metrics.errorRate.total * 100).toFixed(1) + '%'
          : '0%'
      };
    };

    // --- Event Subscriptions ---
    const init = () => {
      // Subscribe to relevant events
      EventBus.on('agent:history', (data) => {
        if (data.type === 'llm_response') {
          recordDecision({
            cycle: data.cycle,
            type: 'llm_response',
            outputLength: data.content?.length || 0
          });
        } else if (data.type === 'tool_result') {
          recordDecision({
            cycle: data.cycle,
            type: 'tool_call',
            tool: data.tool,
            success: !data.result?.startsWith('Error:')
          });
        }
      }, 'Observability');

      EventBus.on('vfs:write', (data) => {
        recordMutation({ type: 'write', path: data.path, source: 'tool' });
      }, 'Observability');

      EventBus.on('artifact:created', (data) => {
        recordMutation({ type: 'create', path: data.path, source: 'tool' });
      }, 'Observability');

      EventBus.on('artifact:deleted', (data) => {
        recordMutation({ type: 'delete', path: data.path, source: 'tool' });
      }, 'Observability');

      logger.info('[Observability] Initialized');
      return true;
    };

    /**
     * Reset all metrics (for new session)
     */
    const reset = () => {
      _tokenUsage.session = { input: 0, output: 0, total: 0 };
      _tokenUsage.byModel = {};
      _tokenUsage.history = [];
      _mutations.length = 0;
      _decisionTrace.length = 0;
      _metrics.llmLatency = [];
      _metrics.toolLatency = {};
      _metrics.errorRate = { total: 0, errors: 0 };

      EventBus.emit('observability:reset', {});
      logger.info('[Observability] Metrics reset');
    };

    /**
     * Get full observability dashboard data
     */
    const getDashboard = () => {
      return {
        tokens: getTokenUsage(),
        mutations: {
          recent: _mutations.slice(-20),
          total: _mutations.length
        },
        decisions: {
          recent: _decisionTrace.slice(-20),
          total: _decisionTrace.length
        },
        metrics: getMetrics()
      };
    };

    return {
      init,
      reset,
      // Token tracking
      recordTokens,
      getTokenUsage,
      estimateCost,
      // Mutation stream
      recordMutation,
      getMutations,
      // Decision trace
      recordDecision,
      getDecisionTrace,
      // Performance
      recordLLMLatency,
      recordToolLatency,
      getMetrics,
      // Dashboard
      getDashboard
    };
  }
};

export default Observability;
","/infrastructure/rate-limiter.js":"/**
 * @fileoverview Token Bucket Rate Limiter
 */

const RateLimiter = {
  metadata: {
    id: 'RateLimiter',
    version: '1.0.0',
    genesis: { introduced: 'reflection' },
    dependencies: ['Utils'],
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { logger } = deps.Utils;

    class TokenBucket {
      constructor(capacity, refillRate) {
        this.capacity = capacity;
        this.tokens = capacity;
        this.refillRate = refillRate; // tokens per second
        this.lastRefill = Date.now();
        this._pendingWait = null;  // Lock for concurrent access
      }

      _refill() {
        const now = Date.now();
        const elapsed = (now - this.lastRefill) / 1000;
        if (elapsed > 0) {
          const added = elapsed * this.refillRate;
          this.tokens = Math.min(this.capacity, this.tokens + added);
          this.lastRefill = now;
        }
      }

      async waitForToken() {
        // If already waiting, chain onto existing wait to prevent race condition
        if (this._pendingWait) {
          await this._pendingWait;
          return this.waitForToken();
        }

        this._refill();
        if (this.tokens >= 1) {
          this.tokens -= 1;
          return true;
        }

        const needed = 1 - this.tokens;
        const waitMs = (needed / this.refillRate) * 1000;
        logger.debug(`[RateLimiter] Throttling for ${Math.ceil(waitMs)}ms`);

        // Create wait promise that concurrent calls can chain onto
        this._pendingWait = new Promise(r => setTimeout(r, waitMs));
        await this._pendingWait;
        this._pendingWait = null;

        this._refill();  // Refill after wait instead of hard reset
        if (this.tokens >= 1) {
          this.tokens -= 1;
        }
        return true;
      }
    }

    const createLimiter = (tpm = 60) => new TokenBucket(10, tpm / 60);

    return { createLimiter };
  }
};

export default RateLimiter;
","/infrastructure/stream-parser.js":"/**
 * @fileoverview Stream Parser - SSE stream parsing utility
 * Extracts text content from Server-Sent Events streams.
 * Used by LLM providers (Gemini, OpenAI, Anthropic) for streaming responses.
 */

const StreamParser = {
  metadata: {
    id: 'StreamParser',
    version: '1.0.0',
    genesis: { introduced: 'reflection' },
    dependencies: [],
    async: false,
    type: 'utility'
  },

  factory: () => {
    /** Default timeout between stream chunks (30 seconds) */
    const DEFAULT_STREAM_TIMEOUT_MS = 30000;

    /**
     * Wrap a reader with timeout handling
     * Aborts if no data received within timeoutMs
     * @param {ReadableStreamDefaultReader} reader - The stream reader
     * @param {number} timeoutMs - Timeout in milliseconds
     * @param {AbortController} [abortController] - Optional controller to abort fetch
     * @returns {Object} Wrapped reader with timeout
     */
    const withStreamTimeout = (reader, timeoutMs = DEFAULT_STREAM_TIMEOUT_MS, abortController = null) => {
      let timeoutId = null;

      const resetTimeout = () => {
        if (timeoutId) clearTimeout(timeoutId);
        timeoutId = setTimeout(() => {
          if (abortController) {
            abortController.abort();
          }
          reader.cancel('Stream timeout - no data received');
        }, timeoutMs);
      };

      const clearStreamTimeout = () => {
        if (timeoutId) {
          clearTimeout(timeoutId);
          timeoutId = null;
        }
      };

      return {
        async read() {
          resetTimeout();
          try {
            const result = await reader.read();
            if (result.done) clearStreamTimeout();
            return result;
          } catch (err) {
            clearStreamTimeout();
            throw err;
          }
        },
        cancel(reason) {
          clearStreamTimeout();
          return reader.cancel(reason);
        },
        releaseLock() {
          clearStreamTimeout();
          return reader.releaseLock();
        }
      };
    };
    /**
     * Parse SSE stream and extract text using provider-specific extractor
     * @param {Response} response - Fetch response with readable body
     * @param {Function} textExtractor - (data: object) => string - extracts text from parsed JSON
     * @param {Function} onUpdate - Called with each text chunk
     * @param {Object} [options] - Optional settings
     * @param {AbortController} [options.abortController] - Controller to abort on timeout
     * @param {number} [options.timeoutMs] - Timeout between chunks (default: 30s)
     * @returns {Promise<string>} Full accumulated content
     */
    const parseSSEStream = async (response, textExtractor, onUpdate, options = {}) => {
      if (!response.body) {
        throw new Error('Response body is not readable');
      }

      const { abortController, timeoutMs = DEFAULT_STREAM_TIMEOUT_MS } = options;
      const rawReader = response.body.getReader();
      const reader = withStreamTimeout(rawReader, timeoutMs, abortController);
      const decoder = new TextDecoder();
      let buffer = '';
      let fullContent = '';

      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';

          for (const line of lines) {
            if (line.startsWith('data: ') && line !== 'data: [DONE]') {
              try {
                const data = JSON.parse(line.slice(6));
                const text = textExtractor(data);
                if (text) {
                  fullContent += text;
                  onUpdate?.(text);
                }
              } catch {
                // Skip malformed JSON chunks
              }
            }
          }
        }

        // Process any remaining buffer content
        if (buffer.startsWith('data: ') && buffer !== 'data: [DONE]') {
          try {
            const data = JSON.parse(buffer.slice(6));
            const text = textExtractor(data);
            if (text) {
              fullContent += text;
              onUpdate?.(text);
            }
          } catch {
            // Skip malformed JSON
          }
        }
      } finally {
        reader.releaseLock();
      }

      return fullContent;
    };

    /**
     * Pre-built text extractors for common LLM providers
     */
    const extractors = {
      gemini: (data) => data.candidates?.[0]?.content?.parts?.[0]?.text || '',
      openai: (data) => data.choices?.[0]?.delta?.content || '',
      anthropic: (data) => {
        if (data.type === 'content_block_delta') {
          return data.delta?.text || '';
        }
        return '';
      }
    };

    /**
     * Convenience method to parse stream for a specific provider
     * @param {Response} response - Fetch response
     * @param {string} provider - 'gemini' | 'openai' | 'anthropic'
     * @param {Function} onUpdate - Called with each text chunk
     * @param {Object} [options] - Optional settings (abortController, timeoutMs)
     * @returns {Promise<string>} Full content
     */
    const parseForProvider = async (response, provider, onUpdate, options = {}) => {
      const extractor = extractors[provider];
      if (!extractor) {
        throw new Error(`Unknown provider: ${provider}`);
      }
      return parseSSEStream(response, extractor, onUpdate, options);
    };

    /**
     * Parse OpenAI stream with tool call support
     * OpenAI streams tool_calls in chunks with index-based accumulation
     * @param {Response} response - Fetch response
     * @param {Function} onUpdate - Called with each text chunk
     * @param {Object} [options] - Optional settings
     * @returns {Promise<{content: string, toolCalls: Array|null}>} Content and tool calls
     */
    const parseOpenAIStreamWithTools = async (response, onUpdate, options = {}) => {
      if (!response.body) {
        throw new Error('Response body is not readable');
      }

      const { abortController, timeoutMs = DEFAULT_STREAM_TIMEOUT_MS } = options;
      const rawReader = response.body.getReader();
      const reader = withStreamTimeout(rawReader, timeoutMs, abortController);
      const decoder = new TextDecoder();
      let buffer = '';
      let fullContent = '';

      // Accumulate tool calls by index
      const toolCallsMap = new Map(); // index -> { id, name, arguments }

      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';

          for (const line of lines) {
            if (line.startsWith('data: ') && line !== 'data: [DONE]') {
              try {
                const data = JSON.parse(line.slice(6));
                const delta = data.choices?.[0]?.delta;

                // Handle text content
                if (delta?.content) {
                  fullContent += delta.content;
                  onUpdate?.(delta.content);
                }

                // Handle tool calls (accumulate by index)
                if (delta?.tool_calls) {
                  for (const tc of delta.tool_calls) {
                    const idx = tc.index ?? 0;
                    if (!toolCallsMap.has(idx)) {
                      toolCallsMap.set(idx, { id: '', name: '', arguments: '' });
                    }
                    const entry = toolCallsMap.get(idx);
                    if (tc.id) entry.id = tc.id;
                    if (tc.function?.name) entry.name = tc.function.name;
                    if (tc.function?.arguments) entry.arguments += tc.function.arguments;
                  }
                }
              } catch {
                // Skip malformed JSON chunks
              }
            }
          }
        }
      } finally {
        reader.releaseLock();
      }

      // Convert tool calls map to array
      let toolCalls = null;
      if (toolCallsMap.size > 0) {
        toolCalls = [];
        for (const [, entry] of toolCallsMap) {
          if (entry.name) {
            let args = {};
            try {
              args = JSON.parse(entry.arguments || '{}');
            } catch {
              // Invalid JSON in arguments
            }
            toolCalls.push({
              id: entry.id,
              name: entry.name,
              args
            });
          }
        }
      }

      return { content: fullContent, toolCalls };
    };

    /**
     * Parse Anthropic stream with tool call support
     * Anthropic uses content_block events with type='tool_use'
     * @param {Response} response - Fetch response
     * @param {Function} onUpdate - Called with each text chunk
     * @param {Object} [options] - Optional settings
     * @returns {Promise<{content: string, toolCalls: Array|null}>}
     */
    const parseAnthropicStreamWithTools = async (response, onUpdate, options = {}) => {
      if (!response.body) {
        throw new Error('Response body is not readable');
      }

      const { abortController, timeoutMs = DEFAULT_STREAM_TIMEOUT_MS } = options;
      const rawReader = response.body.getReader();
      const reader = withStreamTimeout(rawReader, timeoutMs, abortController);
      const decoder = new TextDecoder();
      let buffer = '';
      let fullContent = '';
      const toolCalls = [];
      let currentToolUse = null;

      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';

          for (const line of lines) {
            if (line.startsWith('data: ')) {
              try {
                const data = JSON.parse(line.slice(6));

                // Handle text content
                if (data.type === 'content_block_delta' && data.delta?.type === 'text_delta') {
                  const text = data.delta.text || '';
                  if (text) {
                    fullContent += text;
                    onUpdate?.(text);
                  }
                }

                // Handle tool use start
                if (data.type === 'content_block_start' && data.content_block?.type === 'tool_use') {
                  currentToolUse = {
                    id: data.content_block.id,
                    name: data.content_block.name,
                    arguments: ''
                  };
                }

                // Handle tool use input delta
                if (data.type === 'content_block_delta' && data.delta?.type === 'input_json_delta') {
                  if (currentToolUse) {
                    currentToolUse.arguments += data.delta.partial_json || '';
                  }
                }

                // Handle tool use end
                if (data.type === 'content_block_stop' && currentToolUse) {
                  let args = {};
                  try {
                    args = JSON.parse(currentToolUse.arguments || '{}');
                  } catch { /* Invalid JSON */ }
                  toolCalls.push({
                    id: currentToolUse.id,
                    name: currentToolUse.name,
                    args
                  });
                  currentToolUse = null;
                }
              } catch {
                // Skip malformed JSON chunks
              }
            }
          }
        }
      } finally {
        reader.releaseLock();
      }

      return { content: fullContent, toolCalls: toolCalls.length > 0 ? toolCalls : null };
    };

    /**
     * Parse Gemini stream with tool call support
     * Gemini uses functionCall in candidates
     * @param {Response} response - Fetch response
     * @param {Function} onUpdate - Called with each text chunk
     * @param {Object} [options] - Optional settings
     * @returns {Promise<{content: string, toolCalls: Array|null}>}
     */
    const parseGeminiStreamWithTools = async (response, onUpdate, options = {}) => {
      if (!response.body) {
        throw new Error('Response body is not readable');
      }

      const { abortController, timeoutMs = DEFAULT_STREAM_TIMEOUT_MS } = options;
      const rawReader = response.body.getReader();
      const reader = withStreamTimeout(rawReader, timeoutMs, abortController);
      const decoder = new TextDecoder();
      let buffer = '';
      let fullContent = '';
      const toolCalls = [];

      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';

          for (const line of lines) {
            if (line.startsWith('data: ') && line !== 'data: [DONE]') {
              try {
                const data = JSON.parse(line.slice(6));
                const candidate = data.candidates?.[0];

                // Handle text content
                const text = candidate?.content?.parts?.[0]?.text || '';
                if (text) {
                  fullContent += text;
                  onUpdate?.(text);
                }

                // Handle function calls
                const functionCall = candidate?.content?.parts?.[0]?.functionCall;
                if (functionCall) {
                  toolCalls.push({
                    id: `gemini_${Date.now()}_${toolCalls.length}`,
                    name: functionCall.name,
                    args: functionCall.args || {}
                  });
                }
              } catch {
                // Skip malformed JSON chunks
              }
            }
          }
        }
      } finally {
        reader.releaseLock();
      }

      return { content: fullContent, toolCalls: toolCalls.length > 0 ? toolCalls : null };
    };

    return {
      parseSSEStream,
      parseForProvider,
      parseOpenAIStreamWithTools,
      parseAnthropicStreamWithTools,
      parseGeminiStreamWithTools,
      extractors,
      withStreamTimeout,
      DEFAULT_STREAM_TIMEOUT_MS
    };
  }
};

export default StreamParser;
","/infrastructure/telemetry-timeline.js":"/**
 * @fileoverview Telemetry Timeline
 * Unified append-only event log for audit, performance, and agent state changes.
 */

const TelemetryTimeline = {
  metadata: {
    id: 'TelemetryTimeline',
    version: '1.0.0',
    genesis: { introduced: 'tabula' },
    dependencies: ['Utils', 'VFS', 'EventBus?'],
    async: true,
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { Utils, VFS, EventBus } = deps;
    const { logger, generateId } = Utils;

    const LOG_DIR = '/.logs/timeline';
    const MAX_RECENT = 500;
    const _recent = [];

    const _appendEntry = async (entry) => {
      const date = new Date(entry.ts).toISOString().split('T')[0];
      const path = `${LOG_DIR}/${date}.jsonl`;
      let content = '';

      try {
        if (await VFS.exists(path)) {
          content = await VFS.read(path);
        }
      } catch (err) {
        logger.warn('[Telemetry] Failed to read timeline file', { path, error: err.message });
      }

      try {
        await VFS.write(path, content + JSON.stringify(entry) + '\n');
      } catch (err) {
        logger.error('[Telemetry] Failed to write timeline entry', { error: err.message });
      }
    };

    const _loadRecent = async () => {
      const today = new Date().toISOString().split('T')[0];
      const path = `${LOG_DIR}/${today}.jsonl`;

      try {
        if (await VFS.exists(path)) {
          const content = await VFS.read(path);
          const lines = content.split('\n').filter(Boolean);
          const start = Math.max(0, lines.length - MAX_RECENT);
          for (let i = start; i < lines.length; i++) {
            try {
              _recent.push(JSON.parse(lines[i]));
            } catch {
              // skip malformed line
            }
          }
        }
      } catch (err) {
        logger.warn('[Telemetry] Failed to load recent timeline entries', err.message);
      }
    };

    const record = async (type, payload = {}, options = {}) => {
      const entry = {
        id: generateId('evt'),
        ts: Date.now(),
        type,
        severity: options.severity || 'info',
        tags: options.tags || [],
        payload
      };
      _recent.push(entry);
      if (_recent.length > MAX_RECENT) _recent.shift();

      await _appendEntry(entry);
      if (EventBus) {
        EventBus.emit('telemetry:event', entry);
      }
      return entry.id;
    };

    const getRecent = (limit = 100) => {
      if (limit <= 0) return [];
      const start = Math.max(0, _recent.length - limit);
      return _recent.slice(start);
    };

    const getEntries = async (startDate, endDate = startDate) => {
      if (!startDate) throw new Error('startDate required');
      let start = new Date(startDate);
      let end = new Date(endDate || startDate);
      const entries = [];

      // Guard against infinite loop if dates are inverted
      if (start > end) {
        logger.warn('[Telemetry] startDate > endDate, swapping');
        [start, end] = [end, start];
      }

      // Use separate loop variable to avoid mutating comparison target
      const current = new Date(start);
      while (current <= end) {
        const dateStr = current.toISOString().split('T')[0];
        const path = `${LOG_DIR}/${dateStr}.jsonl`;
        try {
          if (await VFS.exists(path)) {
            const content = await VFS.read(path);
            for (const line of content.split('\n').filter(Boolean)) {
              try { entries.push(JSON.parse(line)); } catch { /* ignore */ }
            }
          }
        } catch (err) {
          logger.warn('[Telemetry] Failed to read timeline entries', { path, error: err.message });
        }
        current.setDate(current.getDate() + 1);
      }

      return entries;
    };

    const _wireEventBus = () => {
      if (!EventBus) return;
      const safeRecord = (type, payload, options) => {
        record(type, payload, options).catch((err) => {
          logger.warn('[Telemetry] Failed to record event', { type, error: err?.message || err });
        });
      };

      EventBus.on('agent:status', (data = {}) => safeRecord('agent:status', data, { tags: ['agent'] }));
      EventBus.on('agent:warning', (data = {}) => safeRecord('agent:warning', data, { severity: 'warn', tags: ['agent'] }));
      EventBus.on('tool:slow', (data = {}) => safeRecord('tool:slow', data, { severity: 'warn', tags: ['tool'] }));
      EventBus.on('tool:timeout', (data = {}) => safeRecord('tool:timeout', data, { severity: 'error', tags: ['tool'] }));
      EventBus.on('tool:error', (data = {}) => safeRecord('tool:error', data, { severity: 'error', tags: ['tool'] }));
      EventBus.on('tool:circuit_skip', (data = {}) => safeRecord('tool:circuit_skip', data, { severity: 'warn', tags: ['tool'] }));
    };

    return {
      init: async () => {
        await _loadRecent();
        _wireEventBus();
        logger.info('[Telemetry] Timeline initialized');
        return true;
      },
      record,
      getRecent,
      getEntries
    };
  }
};

export default TelemetryTimeline;
","/infrastructure/tool-executor.js":"/**
 * @fileoverview Tool Executor - Shared tool execution with retry, timeout, and batching
 * Used by AgentLoop and WorkerManager for consistent tool execution behavior.
 */

const ToolExecutor = {
  metadata: {
    id: 'ToolExecutor',
    version: '1.0.0',
    genesis: { introduced: 'reflection' },
    dependencies: ['Utils', 'ToolRunner', 'EventBus?'],
    async: false,
    type: 'utility'
  },

  factory: (deps) => {
    const { Utils, ToolRunner, EventBus } = deps;
    const { logger } = Utils;

    // Default configuration
    const DEFAULT_TIMEOUT_MS = 30000;  // 30s per tool
    const DEFAULT_MAX_RETRIES = 2;
    const DEFAULT_RETRY_DELAY_MS = 100;

    /**
     * Execute a single tool with timeout
     * @param {string} name - Tool name
     * @param {Object} args - Tool arguments
     * @param {Object} [options] - Execution options
     * @param {number} [options.timeoutMs] - Timeout in ms
     * @returns {Promise<any>} Tool result
     */
    const executeWithTimeout = async (name, args, options = {}) => {
      const { timeoutMs = DEFAULT_TIMEOUT_MS } = options;

      let timeoutId;
      const timeoutPromise = new Promise((_, reject) => {
        timeoutId = setTimeout(() => reject(new Error(`Tool timeout after ${timeoutMs}ms`)), timeoutMs);
      });

      try {
        const result = await Promise.race([
          ToolRunner.execute(name, args, options),
          timeoutPromise
        ]);
        return result;
      } finally {
        clearTimeout(timeoutId);  // Always clear timeout to prevent memory leak
      }
    };

    /**
     * Execute a tool with retry logic and timeout
     * @param {Object} call - Tool call { name, args }
     * @param {Object} [options] - Execution options
     * @param {number} [options.timeoutMs] - Timeout per attempt
     * @param {number} [options.maxRetries] - Max retry attempts
     * @param {number} [options.retryDelayMs] - Base delay between retries
     * @param {number} [options.iteration] - Current agent iteration (for events)
     * @param {string} [options.workerId] - Worker ID (for worker context)
     * @param {string[]|'*'} [options.allowedTools] - Allowed tools filter
     * @returns {Promise<{result: string, error: Error|null, duration: number}>}
     */
    const executeWithRetry = async (call, options = {}) => {
      const {
        timeoutMs = DEFAULT_TIMEOUT_MS,
        maxRetries = DEFAULT_MAX_RETRIES,
        retryDelayMs = DEFAULT_RETRY_DELAY_MS,
        iteration = 0,
        workerId = null,
        allowedTools = '*'
      } = options;

      let result = null;
      let lastError = null;
      const startTime = Date.now();

      for (let attempt = 0; attempt <= maxRetries; attempt++) {
        try {
          const toolStartTime = Date.now();
          const rawResult = await executeWithTimeout(call.name, call.args, {
            timeoutMs,
            workerId,
            allowedTools
          });
          const toolDuration = Date.now() - toolStartTime;

          // Warn on slow tools
          if (toolDuration > timeoutMs * 0.7) {
            logger.warn(`[ToolExecutor] Slow tool: ${call.name} took ${toolDuration}ms`);
            if (EventBus) {
              EventBus.emit('tool:slow', { tool: call.name, ms: toolDuration, cycle: iteration, workerId });
            }
          }

          // Stringify result
          result = typeof rawResult === 'string' ? rawResult : JSON.stringify(rawResult, null, 2);
          if (result === 'undefined' || result === undefined) {
            result = '(Tool returned no output)';
          }
          lastError = null;
          break;
        } catch (err) {
          lastError = err;
          const isTimeout = err.message?.includes('timeout');

          if (isTimeout) {
            logger.error(`[ToolExecutor] Tool ${call.name} TIMEOUT - exceeded ${timeoutMs}ms`);
            result = `Error: Tool execution timed out after ${timeoutMs / 1000}s. The operation may still be running.`;
            if (EventBus) {
              EventBus.emit('tool:timeout', { tool: call.name, timeout: timeoutMs, cycle: iteration, workerId });
            }
            break;
          }

          if (attempt < maxRetries) {
            logger.warn(`[ToolExecutor] Tool ${call.name} failed (attempt ${attempt + 1}/${maxRetries + 1}), retrying...`);
            await new Promise(r => setTimeout(r, retryDelayMs * (attempt + 1)));
          }
        }
      }

      return {
        result,
        error: lastError,
        duration: Date.now() - startTime
      };
    };

    /**
     * Execute multiple tools in parallel
     * @param {Object[]} calls - Array of { name, args } tool calls
     * @param {Object} [options] - Execution options (same as executeWithRetry)
     * @returns {Promise<Array<{call: Object, result: string, error: Error|null, duration: number}>>}
     */
    const executeBatch = async (calls, options = {}) => {
      const results = await Promise.all(
        calls.map(async (call) => {
          const { result, error, duration } = await executeWithRetry(call, options);
          return { call, result, error, duration };
        })
      );
      return results;
    };

    /**
     * Execute tools with readOnly/mutating split
     * ReadOnly tools run in parallel, mutating tools run sequentially after
     * @param {Object[]} calls - Tool calls
     * @param {Set<string>} readOnlyTools - Set of tool names that are read-only
     * @param {Object} [options] - Execution options
     * @returns {Promise<{results: Array, readOnlyResults: Array, mutatingResults: Array, telemetry: string[]}>}
     */
    const executeWithParallelization = async (calls, readOnlyTools, options = {}) => {
      const readOnlyCalls = calls.filter(c => readOnlyTools.has(c.name));
      const mutatingCalls = calls.filter(c => !readOnlyTools.has(c.name));

      const telemetry = [];
      const results = [];

      // Execute read-only tools in parallel
      if (readOnlyCalls.length > 0) {
        const batchResults = await executeBatch(readOnlyCalls, options);
        results.push(...batchResults);
        if (readOnlyCalls.length > 1) {
          telemetry.push(`${readOnlyCalls.length} read-only tools in parallel`);
        }
      }

      // Execute mutating tools sequentially
      for (const call of mutatingCalls) {
        const { result, error, duration } = await executeWithRetry(call, options);
        results.push({ call, result, error, duration });
      }

      if (mutatingCalls.length > 0) {
        telemetry.push(`${mutatingCalls.length} mutating tool${mutatingCalls.length > 1 ? 's' : ''} sequential`);
      }

      return {
        results,
        readOnlyResults: results.filter(r => readOnlyTools.has(r.call.name)),
        mutatingResults: results.filter(r => !readOnlyTools.has(r.call.name)),
        telemetry
      };
    };

    /**
     * Format tool result for context message
     * @param {string} toolName - Tool name
     * @param {string} result - Tool result
     * @param {Error|null} error - Error if any
     * @returns {string} Formatted message
     */
    const formatResultForContext = (toolName, result, error) => {
      if (error) {
        return `Error executing ${toolName}: ${error.message}`;
      }
      return `Result of ${toolName}:\n${result}`;
    };

    return {
      executeWithTimeout,
      executeWithRetry,
      executeBatch,
      executeWithParallelization,
      formatResultForContext,
      DEFAULT_TIMEOUT_MS,
      DEFAULT_MAX_RETRIES
    };
  }
};

export default ToolExecutor;
","/infrastructure/vfs-hmr.js":"/**
 * @fileoverview VFS Hot Module Replacement
 * Enables live reloading of modules when agent modifies code in VFS.
 * Works in conjunction with Service Worker to serve updated modules.
 */

const VFSHMR = {
  metadata: {
    id: 'VFSHMR',
    version: '1.0.0',
    genesis: { introduced: 'full' },
    dependencies: ['Utils', 'EventBus', 'VFS'],
    async: true,
    type: 'infrastructure'
  },

  factory: (deps) => {
    const { Utils, EventBus, VFS } = deps;
    const { logger } = Utils;

    let _isEnabled = true;
    let _moduleCache = new Map(); // path -> module reference
    let _dependencyGraph = new Map(); // path -> Set of dependent paths
    let _reloadCallbacks = new Map(); // path -> callback

    const init = async () => {
      logger.info('[VFS-HMR] Initializing Hot Module Replacement...');

      // Listen for VFS file changes
      EventBus.on('vfs:file_changed', handleFileChange);

      // Check if Service Worker is active
      if ('serviceWorker' in navigator && navigator.serviceWorker.controller) {
        logger.info('[VFS-HMR] Service Worker active, HMR enabled');
      } else {
        logger.warn('[VFS-HMR] Service Worker not active, HMR disabled');
        _isEnabled = false;
      }

      return true;
    };

    /**
     * Handle VFS file changes
     */
    const handleFileChange = async (event) => {
      if (!_isEnabled) return;

      const { path, operation } = event;

      // Only handle JavaScript modules
      if (!path.endsWith('.js')) return;

      logger.info(`[VFS-HMR] File changed: ${path} (${operation})`);

      try {
        if (operation === 'write' || operation === 'update') {
          await reloadModule(path);
        } else if (operation === 'delete') {
          await unloadModule(path);
        }
      } catch (error) {
        logger.error(`[VFS-HMR] Failed to reload ${path}:`, error);
        EventBus.emit('hmr:error', { path, error: error.message });
      }
    };

    /**
     * Reload a module and all its dependents
     */
    const reloadModule = async (path) => {
      logger.info(`[VFS-HMR] Reloading module: ${path}`);

      // Invalidate Service Worker cache for this module
      await invalidateServiceWorkerCache(path);

      // Get all dependent modules
      const dependents = _dependencyGraph.get(path) || new Set();

      // Execute reload callback if registered
      const callback = _reloadCallbacks.get(path);
      if (callback) {
        try {
          await callback();
          logger.info(`[VFS-HMR] Executed reload callback for ${path}`);
        } catch (error) {
          logger.error(`[VFS-HMR] Reload callback failed for ${path}:`, error);
        }
      }

      // Re-import the module with cache busting
      try {
        const timestamp = Date.now();
        const moduleUrl = path + '?hmr=' + timestamp;

        // Dynamic import with cache busting
        const newModule = await import(moduleUrl);

        // Store in cache
        _moduleCache.set(path, newModule);

        EventBus.emit('hmr:module_reloaded', { path, timestamp });
        logger.info(`[VFS-HMR] Module reloaded: ${path}`);

        // Reload dependents recursively
        for (const dependentPath of dependents) {
          logger.info(`[VFS-HMR] Reloading dependent: ${dependentPath}`);
          await reloadModule(dependentPath);
        }
      } catch (error) {
        logger.error(`[VFS-HMR] Failed to import ${path}:`, error);
        throw error;
      }
    };

    /**
     * Unload a module
     */
    const unloadModule = async (path) => {
      logger.info(`[VFS-HMR] Unloading module: ${path}`);

      _moduleCache.delete(path);
      _reloadCallbacks.delete(path);
      _dependencyGraph.delete(path);

      await invalidateServiceWorkerCache(path);

      EventBus.emit('hmr:module_unloaded', { path });
    };

    /**
     * Invalidate Service Worker cache for a module
     */
    const invalidateServiceWorkerCache = async (path) => {
      if (!navigator.serviceWorker.controller) return;

      try {
        // Send message to Service Worker to invalidate cache
        const messageChannel = new MessageChannel();

        const response = await new Promise((resolve, reject) => {
          messageChannel.port1.onmessage = (event) => {
            if (event.data.success) {
              resolve(event.data);
            } else {
              reject(new Error('Cache invalidation failed'));
            }
          };

          navigator.serviceWorker.controller.postMessage({
            type: 'INVALIDATE_MODULE',
            data: { path }
          }, [messageChannel.port2]);

          // Timeout after 1 second
          setTimeout(() => reject(new Error('Timeout')), 1000);
        });

        logger.debug(`[VFS-HMR] Cache invalidated for ${path}`);
      } catch (error) {
        logger.warn(`[VFS-HMR] Failed to invalidate SW cache for ${path}:`, error.message);
      }
    };

    /**
     * Register a reload callback for a module
     * Useful for modules that need custom cleanup/reinitialization
     */
    const onReload = (path, callback) => {
      _reloadCallbacks.set(path, callback);
      logger.debug(`[VFS-HMR] Registered reload callback for ${path}`);
    };

    /**
     * Register module dependency
     * @param {string} modulePath - The module that imports
     * @param {string} dependencyPath - The module being imported
     */
    const registerDependency = (modulePath, dependencyPath) => {
      if (!_dependencyGraph.has(dependencyPath)) {
        _dependencyGraph.set(dependencyPath, new Set());
      }
      _dependencyGraph.get(dependencyPath).add(modulePath);

      logger.debug(`[VFS-HMR] Registered dependency: ${dependencyPath} -> ${modulePath}`);
    };

    /**
     * Clear all HMR state
     */
    const clear = () => {
      _moduleCache.clear();
      _dependencyGraph.clear();
      _reloadCallbacks.clear();
      logger.info('[VFS-HMR] Cache cleared');
    };

    /**
     * Get HMR statistics
     */
    const getStats = () => {
      return {
        enabled: _isEnabled,
        cachedModules: _moduleCache.size,
        dependencies: _dependencyGraph.size,
        callbacks: _reloadCallbacks.size,
        serviceWorkerActive: navigator.serviceWorker?.controller ? true : false
      };
    };

    /**
     * Enable/disable HMR
     */
    const setEnabled = (enabled) => {
      _isEnabled = enabled;
      logger.info(`[VFS-HMR] ${enabled ? 'Enabled' : 'Disabled'}`);
    };

    /**
     * Force reload all modules
     */
    const reloadAll = async () => {
      logger.info('[VFS-HMR] Reloading all modules...');

      const paths = Array.from(_moduleCache.keys());

      for (const path of paths) {
        try {
          await reloadModule(path);
        } catch (error) {
          logger.error(`[VFS-HMR] Failed to reload ${path}:`, error);
        }
      }

      logger.info(`[VFS-HMR] Reloaded ${paths.length} modules`);
    };

    return {
      init,
      onReload,
      registerDependency,
      reloadModule,
      reloadAll,
      clear,
      getStats,
      setEnabled
    };
  }
};

export default VFSHMR;
","/styles/proto/components.css":"/* Proto Components - Cards, badges, modals, diff viewer, buttons */

/* Button variants */
.btn-small {
    padding: var(--space-xs) var(--space-sm);
    background: var(--primary-dim);
    border: 1px solid var(--primary);
    border-radius: var(--radius-sm);
    color: var(--primary);
    cursor: pointer;
    font-size: var(--font-xs);
    font-family: inherit;
    transition: all var(--transition-normal);
}

.btn-small:hover {
    background: rgba(173, 252, 65, 0.3);
}

/* Utility Classes */
.badge {
    display: inline-block;
    padding: 2px var(--space-sm);
    border-radius: var(--radius-sm);
    font-size: var(--font-xs);
    font-weight: bold;
    text-transform: uppercase;
}

.success { color: var(--success); }
.warning { color: var(--warning); }
.error { color: var(--error); }

/* Cards */
.card {
    background: var(--bg-panel);
    border: 1px solid var(--border-secondary);
    border-radius: var(--radius-md);
    padding: var(--space-lg);
}

.card:hover {
    border-color: var(--border-primary);
}

.card-header {
    color: var(--primary);
    font-weight: bold;
    margin-bottom: var(--space-md);
    padding-bottom: var(--space-sm);
    border-bottom: 1px solid var(--border-secondary);
}

.card-body {
    color: var(--text-primary);
    line-height: 1.6;
}

.card-footer {
    margin-top: var(--space-md);
    padding-top: var(--space-sm);
    border-top: 1px solid var(--border-secondary);
}

/* Keyboard Hint */
kbd {
    background: var(--bg-element);
    border: 1px solid var(--border-default);
    padding: 2px 6px;
    font-size: 10px;
    font-family: var(--font-mono);
    border-radius: 2px;
}

/* Confirmation Modal */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.72);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 10000;
    animation: fadeIn 0.2s ease;
}

.modal-content {
    background: var(--bg-panel);
    border: 2px solid var(--primary-dim);
    border-radius: var(--radius-lg);
    min-width: 360px;
    max-width: 560px;
    max-height: 80vh;
    overflow: auto;
    box-shadow: var(--shadow-lg);
    animation: slideIn 0.3s ease;
}

.modal-content.modal-danger {
    border-color: var(--danger-dim);
}

.modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--space-lg);
    border-bottom: 1px solid var(--border-default);
}

.modal-title {
    margin: 0;
    font-size: var(--font-lg);
    color: var(--primary);
    font-family: 'Courier New', monospace;
}

.modal-content.modal-danger .modal-title {
    color: var(--danger);
}

.modal-close {
    background: transparent;
    border: none;
    color: var(--text-secondary);
    font-size: var(--font-lg);
    cursor: pointer;
}

.modal-body {
    padding: var(--space-lg);
}

.modal-actions {
    display: flex;
    justify-content: flex-end;
    gap: var(--space-sm);
    padding: var(--space-lg);
    border-top: 1px solid var(--border-default);
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes slideIn {
    from { transform: translateY(-12px); opacity: 0; }
    to { transform: translateY(0); opacity: 1; }
}

/* Diff Viewer */
.diff-viewer {
    background: var(--bg-panel);
    border: 1px solid var(--border-default);
    border-radius: var(--radius-lg);
    color: var(--text-primary);
    font-family: 'Courier New', monospace;
    padding: var(--space-lg);
}

.diff-header,
.diff-footer {
    border-bottom: 1px solid var(--border-default);
    margin-bottom: var(--space-lg);
    padding-bottom: var(--space-md);
}

.diff-footer {
    border-top: 1px solid var(--border-default);
    border-bottom: none;
    margin-top: var(--space-lg);
    padding-top: var(--space-md);
    display: flex;
    align-items: center;
    gap: var(--space-sm);
}

.diff-actions {
    display: flex;
    gap: var(--space-sm);
    margin-bottom: var(--space-lg);
    flex-wrap: wrap;
}

.diff-files {
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
}

.diff-file {
    background: var(--bg-element);
    border-radius: var(--radius-md);
    overflow: hidden;
}

.diff-file-header {
    display: flex;
    justify-content: space-between;
    padding: var(--space-md);
    background: var(--bg-panel);
    align-items: center;
    gap: var(--space-md);
}

.diff-file-info {
    display: flex;
    gap: var(--space-md);
    align-items: center;
    flex-wrap: wrap;
}

.diff-operation {
    border-radius: var(--radius-sm);
    font-size: var(--font-xs);
    padding: 2px 8px;
    text-transform: uppercase;
}

.diff-operation.create {
    background: var(--success-dim);
    color: var(--bg-app);
}

.diff-operation.modify {
    background: var(--warning-dim);
    color: var(--bg-app);
}

.diff-operation.delete {
    background: var(--danger-dim);
    color: var(--bg-app);
}

.diff-file-actions {
    display: flex;
    gap: var(--space-sm);
    align-items: center;
    flex-wrap: wrap;
}

.side-by-side-diff {
    display: flex;
    gap: 2px;
}

.diff-pane {
    flex: 1;
    overflow-x: auto;
}

.diff-line {
    display: flex;
    min-height: 20px;
}

.diff-line.added {
    background: rgba(16, 185, 129, 0.15);
}

.diff-line.removed {
    background: rgba(239, 68, 68, 0.15);
}

.diff-line.changed {
    background: rgba(245, 158, 11, 0.15);
}

.line-number {
    width: 40px;
    color: var(--text-muted);
    text-align: right;
    padding-right: var(--space-sm);
    user-select: none;
}

.code-block {
    background: var(--bg-panel);
    padding: var(--space-md);
    overflow-x: auto;
    border-radius: var(--radius-md);
    font-size: var(--font-xs);
}

/* Genesis diff color coding */
.diff-added {
    background: rgba(173, 252, 65, 0.1);
    border-left: 3px solid #adfc41;
}

.diff-deleted {
    background: rgba(127, 127, 127, 0.1);
    border-left: 3px solid #7f7f7f;
    text-decoration: line-through;
}

.diff-modified {
    background: rgba(173, 252, 65, 0.05);
    border-left: 3px solid #adfc41;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

::-webkit-scrollbar-track {
    background: var(--scrollbar-bg);
}

::-webkit-scrollbar-thumb {
    background: var(--scrollbar-thumb);
    border-radius: var(--radius-md);
}

::-webkit-scrollbar-thumb:hover {
    background: var(--scrollbar-thumb-hover);
}

/* Legacy - deprecated */
.utility-panel {
    display: none;
}

.utility-header {
    display: none;
}
","/styles/proto/history.css":"/* Proto History - History stream, reflections, arena results */

/* History/Reflections Streams */
.history-stream, .reflections-stream {
    font-size: var(--font-xs);
    line-height: 1.6;
    flex: 1;
    min-height: 0;
    overflow-y: auto;
}

.history-stream {
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
}

.reflections-stream {
    display: flex;
    flex-direction: column;
    gap: var(--space-xs);
}

/* History Entries */
.history-entry {
    margin-bottom: var(--space-md);
    border: 1px solid var(--border-secondary);
    border-radius: var(--radius-sm);
    overflow: hidden;
}

.history-header {
    background: var(--bg-tertiary);
    padding: var(--space-sm) var(--space-md);
    font-size: var(--font-sm);
    font-weight: 600;
    color: var(--primary);
    border-bottom: 1px solid var(--border-secondary);
}

.history-content {
    margin: 0;
    padding: var(--space-md);
    font-size: var(--font-xs);
    overflow-x: auto;
    white-space: pre-wrap;
    word-break: break-word;
    max-height: 300px;
    overflow-y: auto;
}

/* Streaming animation */
.history-entry.streaming .history-header {
    color: var(--warning);
}

.history-entry.streaming .history-header::after {
    content: '';
    animation: pulse 1s ease-in-out infinite;
}

@keyframes pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.5; }
}

/* History Actions */
.history-actions {
    margin-top: var(--space-sm);
    padding-top: var(--space-sm);
    border-top: 1px solid var(--border-subtle);
}

.history-error {
    color: var(--danger);
}

/* Error Badge */
.error-badge {
    background: var(--danger);
    color: var(--bg-app);
    font-size: var(--font-xs);
    padding: 2px 6px;
    margin-left: 8px;
    text-transform: uppercase;
    font-weight: bold;
}

/* Reflection Entries */
.reflection-entry {
    padding: var(--space-sm);
    margin-bottom: var(--space-xs);
    border-radius: var(--radius-sm);
    border-left: 3px solid transparent;
}

.reflection-success {
    background: var(--success-bg);
    border-left-color: var(--success);
}

.reflection-error {
    background: var(--error-bg);
    border-left-color: var(--error);
}

.reflection-header {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    font-size: var(--font-sm);
}

.reflection-icon {
    font-weight: bold;
}

.reflection-success .reflection-icon {
    color: var(--success);
}

.reflection-error .reflection-icon {
    color: var(--error);
}

.reflection-tool {
    color: var(--text-primary);
    font-weight: 600;
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.reflection-cycle {
    color: var(--text-muted);
    font-size: var(--font-xs);
}

.reflection-detail {
    margin-top: var(--space-xs);
    font-size: var(--font-xs);
    color: var(--text-secondary);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* Arena Results */
.arena-result {
    border-left: 3px solid var(--primary);
}

.arena-header {
    background: var(--bg-tertiary);
    color: var(--primary);
}

.arena-solutions {
    padding: var(--space-md);
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
}

.arena-solution {
