    display: flex;
    justify-content: space-between;
    align-items: center;
}

.winner-badge {
    display: inline-block;
    padding: 2px 6px;
    background: var(--primary);
    color: var(--bg-primary);
    font-size: var(--font-xs);
    font-weight: 700;
    border-radius: 3px;
    text-transform: uppercase;
