","/tools/ListKnowledge.js":"/**
 * @fileoverview ListKnowledge - Query the knowledge graph
 */

async function call(args = {}, deps = {}) {
  const { KnowledgeGraph } = deps;

  if (!KnowledgeGraph) {
    throw new Error('KnowledgeGraph not available');
  }

  const { entity, predicate, subject, object, limit = 50 } = args;

  // Query by entity
  if (entity) {
    const result = KnowledgeGraph.getEntity(entity);
    if (!result) {
      return `Entity "${entity}" not found`;
    }
    return JSON.stringify(result, null, 2);
  }

  // Query triples
  if (predicate || subject || object) {
    const triples = KnowledgeGraph.query({ predicate, subject, object });
    const limited = triples.slice(0, limit);
    return JSON.stringify({
      total: triples.length,
      showing: limited.length,
      triples: limited
    }, null, 2);
  }

  // Default: return stats and recent entities
  const entities = KnowledgeGraph.getAllEntities();
  const graph = KnowledgeGraph.exportGraph();

  // Get most recent entities (by ID timestamp)
  const recentEntities = entities
    .slice(-limit)
    .map(e => ({
      id: e.id,
      type: e.type,
      label: e.label || e.id,
      confidence: e.confidence?.toFixed(2)
    }));

  // Get sample triples
  const sampleTriples = graph.triples
    .slice(-20)
    .map(t => `${t.subject} -[${t.predicate}]-> ${t.object}`);

  return JSON.stringify({
    stats: {
      entities: entities.length,
      triples: graph.triples.length
    },
    recentEntities,
    recentTriples: sampleTriples
  }, null, 2);
}

export const tool = {
  name: "ListKnowledge",
  description: "Query the knowledge graph. Use 'entity' to get details, 'predicate'/'subject'/'object' to query triples, or no args for overview.",
  readOnly: true,
  call
};

export default call;
","/tools/ListMemories.js":"/**
 * @fileoverview ListMemories - Query semantic memory store
 */

async function call(args = {}, deps = {}) {
  const { EmbeddingStore, SemanticMemory } = deps;

  if (!EmbeddingStore) {
    throw new Error('EmbeddingStore not available');
  }

  const { query, limit = 10, domain } = args;

  // If query provided, do semantic search
  if (query && SemanticMemory) {
    const results = await SemanticMemory.search(query, { topK: limit });
    return JSON.stringify(results.map(r => ({
      id: r.id,
      content: r.content.slice(0, 500),
      similarity: r.similarity.toFixed(3),
      domain: r.domain,
      timestamp: new Date(r.timestamp).toISOString()
    })), null, 2);
  }

  // Otherwise list all memories
  const memories = await EmbeddingStore.getAllMemories();

  // Filter by domain if specified
  let filtered = domain
    ? memories.filter(m => m.domain === domain)
    : memories;

  // Sort by timestamp descending
  filtered.sort((a, b) => b.timestamp - a.timestamp);

  // Limit results
  const limited = filtered.slice(0, limit);

  const stats = await EmbeddingStore.getStats();

  return JSON.stringify({
    total: memories.length,
    showing: limited.length,
    stats,
    memories: limited.map(m => ({
      id: m.id,
      content: m.content.slice(0, 200) + (m.content.length > 200 ? '...' : ''),
      domain: m.domain,
      source: m.source,
      accessCount: m.accessCount,
      timestamp: new Date(m.timestamp).toISOString()
    }))
  }, null, 2);
}

export const tool = {
  name: "ListMemories",
  description: "List or search semantic memories. Use 'query' for semantic search, or list all with optional 'domain' filter.",
  readOnly: true,
  call
};

