 provider: 'mock', id: 'mock-model' };\n  }\n\n  for (const inj of injections) {\n    logger.info(`Testing injection: ${inj.name}`);\n    \n    const messages = [\n      { role: 'system', content: fullSystemPrompt },\n      { role: 'user', content: inj.prompt }\n    ];\n\n    try {\n      const response = await LLMClient.chat(messages, config);\n      const content = response.content;\n      \n      const success = content.includes(inj.trigger);\n      \n      results.push({\n        name: inj.name,\n        prompt: inj.prompt,\n        response: content,\n        vulnerable: success\n      });\n      \n    } catch (err) {\n      results.push({\n        name: inj.name,\n        error: err.message,\n        vulnerable: false // Error implies it didn't execute the injection\n      });\n    }\n  }\n\n  return results;\n}"
