  border-top: 1px solid rgba(173, 252, 65, 0.2);
}

/* File Viewer Modal */

.vfs-file-viewer-modal {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 10000;
  display: none;
  align-items: center;
  justify-content: center;
  animation: fadeIn 0.2s;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.vfs-file-viewer-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.8);
  backdrop-filter: blur(4px);
}

.vfs-file-viewer-content {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 90%;
  max-width: 1200px;
  height: 80vh;
  background: rgba(0, 0, 0, 0.95);
  border: 2px solid rgba(173, 252, 65, 0.5);
  border-radius: 8px;
  box-shadow: 0 0 30px rgba(173, 252, 65, 0.3);
  animation: slideIn 0.3s ease-out;
}

@keyframes slideIn {
  from {
    transform: translateY(-20px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

.vfs-file-viewer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: rgba(173, 252, 65, 0.1);
  border-bottom: 1px solid rgba(173, 252, 65, 0.3);
}

.vfs-file-viewer-title {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #adfc41;
  font-family: 'Courier New', monospace;
  font-size: 14px;
  font-weight: 600;
}

.vfs-file-viewer-close {
  padding: 4px 8px;
  background: transparent;
  border: 1px solid rgba(127, 127, 127, 0.5);
  border-radius: 4px;
  color: #7f7f7f;
  font-size: 18px;
  cursor: pointer;
  transition: all 0.2s;
}

.vfs-file-viewer-close:hover {
  background: rgba(127, 127, 127, 0.2);
  border-color: #7f7f7f;
  box-shadow: 0 0 8px rgba(127, 127, 127, 0.3);
}

.vfs-file-viewer-meta {
  padding: 8px 16px;
  font-size: 12px;
  color: rgba(173, 252, 65, 0.7);
  background: rgba(0, 0, 0, 0.3);
  border-bottom: 1px solid rgba(173, 252, 65, 0.2);
}

.vfs-file-viewer-body {
  flex: 1;
  overflow: auto;
  padding: 16px;
  background: rgba(0, 0, 0, 0.5);
}

.vfs-file-viewer-body::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}

.vfs-file-viewer-body::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.3);
}

.vfs-file-viewer-body::-webkit-scrollbar-thumb {
  background: rgba(173, 252, 65, 0.3);
  border-radius: 6px;
}

.vfs-file-viewer-body::-webkit-scrollbar-thumb:hover {
  background: rgba(173, 252, 65, 0.5);
}

.vfs-file-viewer-body pre {
  margin: 0;
  font-family: 'Courier New', monospace;
  font-size: 13px;
  line-height: 1.6;
  color: #ffffff;
}

.vfs-file-viewer-body code {
  display: block;
  white-space: pre;
  color: #ffffff;
}

.vfs-file-viewer-footer {
  display: flex;
  gap: 8px;
  padding: 12px 16px;
  background: rgba(173, 252, 65, 0.1);
  border-top: 1px solid rgba(173, 252, 65, 0.3);
}

.vfs-file-viewer-footer button {
  padding: 8px 16px;
  background: rgba(173, 252, 65, 0.1);
  border: 1px solid rgba(173, 252, 65, 0.3);
  border-radius: 4px;
  color: #adfc41;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.2s;
}

.vfs-file-viewer-footer button:hover {
  background: rgba(173, 252, 65, 0.2);
  border-color: #adfc41;
  box-shadow: 0 0 8px rgba(173, 252, 65, 0.3);
}

/* ========================================
   MOBILE RESPONSIVE DESIGN
   ======================================== */

/* Tablet breakpoint */
@media (max-width: 1024px) {
  .vfs-toolbar {
    gap: 6px;
    padding: 6px;
