      LLMClient = window.REPLOID.llmClient;
  }
  if (!LLMClient) return { error: 'LLMClient not found' };

  let config = null;
  try {
    const saved = localStorage.getItem('SELECTED_MODELS');
    if (saved) {
      const models = JSON.parse(saved);
      config = models[0];
    }
  } catch (e) { 
    return { error: 'Failed to parse model config' };
  }

