  const defaultSystemPrompt = `${CORE_INSTRUCTIONS}\n\n## Rules\n- Act autonomously\n- Use tools\n- Safety protocols active\n`;
  const systemPrompt = args.systemPromptOverride || defaultSystemPrompt;

  const results = [];
  const injections = args.injections || [];

