  font-size: var(--font-xs);
}

.hitl-steps-input {
  width: 50px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  padding: 2px 6px;
  border-radius: 3px;
  color: var(--text-primary, #fff);
  font-size: var(--font-xs);
}

.hitl-step-counter {
  color: var(--text-muted, rgba(255, 255, 255, 0.5));
  font-size: var(--font-xs);
}

.hitl-queue {
  margin: 8px 0;
  background: rgba(255, 165, 0, 0.1);
  border-radius: 4px;
  padding: 8px;
}

.hitl-queue-header {
  font-weight: 500;
  margin-bottom: 8px;
  color: var(--warning, #ffa500);
}

.hitl-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.hitl-item:last-child {
  border-bottom: none;
}

.hitl-item-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.hitl-item-module {
  font-weight: 500;
  font-size: var(--font-xs);
}

.hitl-item-action {
  color: var(--text-secondary, rgba(255, 255, 255, 0.6));
  font-size: var(--font-xs);
}

.hitl-item-actions {
  display: flex;
  gap: 4px;
}

.hitl-approve,
.hitl-reject {
  width: 24px;
  height: 24px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: var(--font-xs);
}

.hitl-approve {
  background: rgba(102, 187, 106, 0.2);
  color: var(--success, #66bb6a);
}

.hitl-approve:hover {
  background: rgba(102, 187, 106, 0.4);
}

.hitl-reject {
  background: rgba(244, 135, 113, 0.2);
  color: var(--danger, #f48771);
}

.hitl-reject:hover {
  background: rgba(244, 135, 113, 0.4);
}

.hitl-more {
  text-align: center;
  color: var(--text-muted, rgba(255, 255, 255, 0.5));
  font-size: var(--font-xs);
  padding-top: 4px;
}

.hitl-stats {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.hitl-stat {
  padding: 2px 8px;
  border-radius: 10px;
  font-size: var(--font-xs);
}

.hitl-stat.approved {
  background: rgba(102, 187, 106, 0.2);
  color: var(--success, #66bb6a);
}

.hitl-stat.rejected {
  background: rgba(244, 135, 113, 0.2);
  color: var(--danger, #f48771);
}

.hitl-stat.auto {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text-secondary, rgba(255, 255, 255, 0.6));
}

.hitl-disabled {
  color: var(--text-muted, rgba(255, 255, 255, 0.4));
  text-align: center;
  padding: 20px;
}

/* Mobile responsive styles for HITL widget */
@media (max-width: 768px) {
  .hitl-widget {
    padding: 10px;
  }

  .hitl-header {
    flex-wrap: wrap;
    gap: 6px;
  }

  .hitl-item {
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
  }

  .hitl-item-actions {
    width: 100%;
    justify-content: flex-end;
  }

  .hitl-stats {
    flex-wrap: wrap;
    gap: 8px;
  }
}

@media (max-width: 480px) {
  .hitl-widget {
    padding: 8px;
    font-size: 11px;
  }

  .hitl-icon {
    font-size: 14px;
  }

  .hitl-title {
    font-size: 12px;
  }

  .hitl-mode-select {
    padding: 6px;
    font-size: 11px;
  }

  .hitl-approve,
  .hitl-reject {
    width: 32px;
    height: 32px;
  }

  .hitl-stat {
    font-size: 10px;
    padding: 2px 6px;
  }

  .hitl-config {
    padding: 6px;
  }

  .hitl-queue {
    padding: 6px;
  }
}

/* Touch optimization for HITL */
@media (pointer: coarse) {
  .hitl-approve,
  .hitl-reject {
    min-width: 44px;
    min-height: 44px;
  }

  .hitl-toggle {
    min-height: 36px;
    padding: 6px 12px;
  }

  .hitl-mode-select {
    min-height: 40px;
  }
}

