/* ========================================
   REPLOID Design System - NEON CORE
   styles/theme.css
   ======================================== */

:root {
  /* ---- Core Palette (Monochrome + Green) ---- */
  --bg-app: #000000;       /* Pure Black */
  --bg-panel: #000000;     /* Pure Black */
  --bg-element: #000000;   /* Pure Black */
  --bg-hover: #000000;     /* Pure Black */
  --bg-active: rgba(173, 252, 65, 0.1);

  /* ---- Borders ---- */
  --border-subtle: #7f7f7f;
  --border-default: #999999;
  --border-active: #adfc41;

  /* ---- Text ---- */
  --text-primary: #ffffff;
  --text-secondary: #b8b8b8;
  --text-muted: #a0a0a0;
  --text-inverse: #000000;

  /* ---- Accents (Green) ---- */
  --primary: #adfc41;
  --primary-dim: rgba(173, 252, 65, 0.15);
  --primary-glow: 0 0 10px rgba(173, 252, 65, 0.4);

  --secondary: #adfc41;
  --secondary-dim: rgba(173, 252, 65, 0.15);

  --success: #adfc41;
  --warning: #adfc41;
  --danger: #adfc41;

  /* ---- Typography ---- */
  --font-mono: 'Courier New', 'Consolas', monospace;
  --font-sans: 'Inter', system-ui, sans-serif;
  --font-base: 15px;
  --font-xs: 13px;
  --font-sm: 14px;
  --font-md: var(--font-base);
  --font-lg: 16px;
  --font-xl: 18px;

  /* ---- Spacing & Radius ---- */
  --space-sm: 8px;
  --space-md: 12px;
  --space-lg: 20px;
  --radius-none: 0px;
  --radius-sm: 2px;
}

/* ========================================
   RESET & BASE
   ======================================== */
* { box-sizing: border-box; }

body {
  margin: 0; padding: 0;
  background: var(--bg-app);
  color: var(--text-primary);
  font-family: var(--font-mono); /* Default to code font */
  font-size: var(--font-base);
  overflow-x: hidden;
}

/* Scanline Overlay (Optional - adds CRT feel) */
body::before {
  content: " ";
  display: block;
  position: fixed; top: 0; left: 0; bottom: 0; right: 0;
  background: linear-gradient(rgba(0, 0, 0, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(173, 252, 65, 0.02), rgba(173, 252, 65, 0.02), rgba(173, 252, 65, 0.02));
  z-index: 2;
  background-size: 100% 2px, 3px 100%;
  pointer-events: none;
}

/* ========================================
   COMPONENTS
   ======================================== */

/* 1. Buttons (Holographic) */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 10px 20px;
  font-family: var(--font-mono);
  font-size: 12px; text-transform: uppercase; letter-spacing: 1px;
  background: transparent;
  border: 1px solid var(--border-default);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn:hover:not(:disabled) {
  border-color: var(--text-primary);
  color: var(--text-primary);
  background: var(--bg-hover);
}

.btn.primary {
  border-color: var(--primary);
  color: var(--primary);
  box-shadow: 0 0 5px rgba(173,252,65,0.1);
}

.btn.primary:hover:not(:disabled) {
  background: var(--primary-dim);
  box-shadow: var(--primary-glow);
}

.btn.secondary {
  border-color: var(--border-default);
  color: var(--text-muted);
}

.btn:disabled { opacity: 0.5; cursor: not-allowed; }

/* 2. Cards (HUD Panels) */
.card, .panel, .advanced-panel {
  background: var(--bg-panel);
  border: 1px solid var(--border-default);
  padding: var(--space-lg);
  position: relative;
}

/* Corner accents for panels */
.card::after, .panel::after {
  content: ''; position: absolute;
  top: -1px; right: -1px;
  width: 10px; height: 10px;
  border-top: 2px solid var(--primary);
  border-right: 2px solid var(--primary);
}

/* 3. Inputs (Terminal Entry) */
input, select, textarea {
  background: var(--bg-element);
  border: 1px solid var(--border-default);
  color: var(--text-primary);
  font-family: var(--font-mono);
  padding: 10px;
  width: 100%;
}

input:focus, select:focus, textarea:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: inset 0 0 10px rgba(173, 252, 65, 0.1);
}

/* ========================================
   UTILITIES
   ======================================== */
.hidden { display: none !important; }
.text-cyan { color: var(--primary); }
.text-magenta { color: var(--secondary); }
.text-muted { color: var(--text-muted); }

/* ========================================
   PROGRESS BAR
   ======================================== */
.progress-bar {
  width: 100%;
  height: 4px;
  background: var(--bg-element);
  border: 1px solid var(--border-default);
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--primary), var(--secondary));
  transition: width 0.3s ease;
  box-shadow: 0 0 10px var(--primary);
}

.progress-bar-indeterminate .progress-bar-fill {
  width: 30%;
  animation: indeterminate 1.5s ease-in-out infinite;
}

@keyframes indeterminate {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(400%); }
}

/* ========================================
   TOAST NOTIFICATIONS
   ======================================== */
.toast-container {
  position: fixed;
  top: 20px;
  right: 20px;
  z-index: 10000;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-width: 400px;
}

.toast {
  background: var(--bg-panel);
  border: 1px solid var(--border-default);
  padding: 12px 16px;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  animation: slideIn 0.3s ease;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
}

.toast-icon {
  font-size: 16px;
  flex-shrink: 0;
}

.toast-content {
  flex: 1;
  min-width: 0;
}

.toast-title {
  font-weight: bold;
  margin-bottom: 4px;
  font-size: 12px;
}

.toast-message {
  font-size: 11px;
  color: var(--text-secondary);
  word-break: break-word;
}

.toast-actions {
  display: flex;
  gap: 8px;
  margin-top: 8px;
}

.toast-btn {
  padding: 4px 10px;
  font-size: 10px;
  background: transparent;
  border: 1px solid var(--border-default);
  color: var(--text-secondary);
  cursor: pointer;
  transition: 0.2s;
}

.toast-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.toast-btn.primary {
  border-color: var(--primary);
  color: var(--primary);
}

.toast-close {
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 0;
  font-size: 16px;
  line-height: 1;
}

.toast-close:hover {
  color: var(--text-primary);
}

.toast.toast-error {
  border-color: var(--danger);
}

.toast.toast-error .toast-icon {
  color: var(--danger);
}

.toast.toast-success {
  border-color: var(--success);
}

.toast.toast-success .toast-icon {
  color: var(--success);
}

.toast.toast-warning {
  border-color: var(--warning);
}

.toast.toast-warning .toast-icon {
  color: var(--warning);
}

.toast.toast-info {
  border-color: var(--primary);
}

.toast.toast-info .toast-icon {
  color: var(--primary);
}

/* ========================================
   TOKEN BUDGET INDICATOR
   ======================================== */
.token-budget {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--text-primary);
}

.token-budget-bar {
  width: 60px;
  height: 6px;
  background: var(--bg-element);
  border: 1px solid var(--border-subtle);
  overflow: hidden;
}

.token-budget-fill {
  height: 100%;
  transition: width 0.3s ease, background 0.3s ease;
}

.token-budget-fill.low {
  background: var(--success);
}

.token-budget-fill.medium {
  background: var(--warning);
}

.token-budget-fill.high {
  background: var(--danger);
}

.token-budget-text {
  min-width: 80px;
}

/* ========================================
   GOAL HISTORY DROPDOWN
   ======================================== */
.goal-history-container {
  position: relative;
  width: 100%;
}

.goal-history-dropdown {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--bg-panel);
  border: 1px solid var(--border-default);
  border-top: none;
  max-height: 200px;
  overflow-y: auto;
  z-index: 100;
}

.goal-history-item {
  padding: 10px 12px;
  cursor: pointer;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.goal-history-item:hover {
  background: var(--bg-hover);
}

.goal-history-text {
  font-size: 12px;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.goal-history-time {
  font-size: 10px;
  color: var(--text-muted);
}

.goal-history-empty {
  padding: 12px;
  text-align: center;
  color: var(--text-muted);
  font-size: 11px;
}

/* ========================================
   ERROR MODAL
   ======================================== */
.error-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.85);
  z-index: 10002;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: fadeIn 0.15s ease;
}

.error-modal {
  width: 600px;
  max-width: 90vw;
  max-height: 80vh;
  background: var(--bg-panel);
  border: 1px solid var(--danger);
  box-shadow: 0 0 30px rgba(173, 252, 65, 0.2);
  display: flex;
  flex-direction: column;
  animation: slideDown 0.2s ease;
}

.error-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px;
  border-bottom: 1px solid var(--border-default);
  background: rgba(173, 252, 65, 0.1);
}

.error-modal-title {
  font-weight: bold;
  color: var(--danger);
  font-size: 14px;
}

.error-modal-close {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 20px;
  cursor: pointer;
  padding: 0;
  line-height: 1;
}

.error-modal-close:hover {
  color: var(--text-primary);
}

.error-modal-meta {
  display: flex;
  gap: 16px;
  padding: 8px 16px;
  font-size: 10px;
  color: var(--text-muted);
  border-bottom: 1px solid var(--border-subtle);
  flex-wrap: wrap;
}

.error-modal-context {
  color: var(--primary);
}

.error-modal-content {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
  background: var(--bg-element);
}

.error-modal-content pre {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 11px;
  line-height: 1.6;
  color: var(--text-primary);
  font-family: 'Courier New', monospace;
}

.error-modal-actions {
  display: flex;
  gap: 8px;
  padding: 12px 16px;
  border-top: 1px solid var(--border-default);
  justify-content: flex-end;
}

/* ========================================
   CLI MODE
   ======================================== */

/* Mode Toggle Button Group */
.mode-toggle {
  position: fixed;
  top: 12px;
  right: 12px;
  z-index: 9000;
  display: flex;
  gap: 0;
  background: var(--bg-panel);
  border: 1px solid var(--border-default);
}

.mode-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 11px;
  cursor: pointer;
  transition: all 0.2s ease;
  border-right: 1px solid var(--border-default);
}

.mode-btn:last-child {
  border-right: none;
}

.mode-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.mode-btn.active {
  background: var(--primary-dim);
  color: var(--primary);
}

.mode-icon {
  font-size: 14px;
}

.mode-label {
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* ========================================
   CHECKBOX OPTION
   ======================================== */
.checkbox-option {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  cursor: pointer;
  padding: 10px 12px;
  background: var(--bg-element);
  border: 1px solid var(--border-default);
  transition: all 0.2s ease;
}

.checkbox-option:hover {
  border-color: var(--border-subtle);
  background: var(--bg-hover);
}

.checkbox-option input[type="checkbox"] {
  width: 16px;
  height: 16px;
  margin: 2px 0 0 0;
  accent-color: var(--primary);
  cursor: pointer;
  flex-shrink: 0;
}

.checkbox-label {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.checkbox-title {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-primary);
}

.checkbox-desc {
  font-size: 11px;
  color: var(--text-muted);
}

