/* VFS Explorer Styles */

.vfs-explorer {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: rgba(0, 0, 0, 0.8);
  border: 1px solid rgba(173, 252, 65, 0.3);
  border-radius: 4px;
  overflow: hidden;
}

.vfs-toolbar {
  display: flex;
  gap: 8px;
  padding: 8px;
  background: rgba(173, 252, 65, 0.1);
  border-bottom: 1px solid rgba(173, 252, 65, 0.3);
}

.vfs-search {
  flex: 1;
  padding: 6px 12px;
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(173, 252, 65, 0.3);
  border-radius: 4px;
  color: #adfc41;
  font-family: 'Courier New', monospace;
  font-size: 13px;
}

.vfs-search:focus {
  outline: none;
  border-color: #adfc41;
  box-shadow: 0 0 8px rgba(173, 252, 65, 0.3);
}

.vfs-search::placeholder {
  color: rgba(173, 252, 65, 0.5);
}

.vfs-toolbar button {
  padding: 6px 12px;
  background: rgba(173, 252, 65, 0.1);
  border: 1px solid rgba(173, 252, 65, 0.3);
  border-radius: 4px;
  color: #adfc41;
  cursor: pointer;
  font-size: 16px;
  transition: all 0.2s;
}

.vfs-toolbar button:hover {
  background: rgba(173, 252, 65, 0.2);
  border-color: #adfc41;
  box-shadow: 0 0 8px rgba(173, 252, 65, 0.3);
}

.vfs-tree {
  flex: 1;
  overflow-y: auto;
  padding: 4px;
  font-family: 'Courier New', monospace;
  font-size: 13px;
}

.vfs-tree::-webkit-scrollbar {
  width: 8px;
}

.vfs-tree::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.3);
}

.vfs-tree::-webkit-scrollbar-thumb {
  background: rgba(173, 252, 65, 0.3);
  border-radius: 4px;
}

.vfs-tree::-webkit-scrollbar-thumb:hover {
  background: rgba(173, 252, 65, 0.5);
}

.vfs-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  cursor: pointer;
  border-radius: 3px;
  transition: background 0.15s;
  user-select: none;
  white-space: nowrap;
}

.vfs-item:hover {
  background: rgba(173, 252, 65, 0.15);
}

.vfs-item.selected {
  background: rgba(173, 252, 65, 0.25);
  border-left: 2px solid #adfc41;
}

.vfs-item.highlight .vfs-name {
  background: rgba(173, 252, 65, 0.3);
  color: #adfc41;
  padding: 2px 4px;
  border-radius: 2px;
}

.vfs-folder-header {
  font-weight: 600;
  color: #adfc41;
}

.vfs-file {
  color: rgba(255, 255, 255, 0.9);
}

.vfs-expand {
  display: inline-block;
  width: 16px;
  text-align: center;
  font-size: 10px;
