// Version 4.1.0: Removed legacy visualizer dependencies

const UIManager = {
  metadata: {
    id: 'UIManager',
    version: '1.0.0',
    description: 'Orchestrates UI panels via DI Container',
    dependencies: [
      'Utils', 'EventBus', 'StateManager',
      'PythonReplPanel', 'LLMConfigPanel', 'VFSPanel',
